model_answers:
# KMS key for encrypting the EFS file system
resource "aws_kms_key" "efs" {
  description             = "KMS key for EFS encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = {
    Name        = "efs-encryption-key"
    Environment = "production"
    ManagedBy   = "terraform"
  }
}

resource "aws_kms_alias" "efs" {
  name          = "alias/efs-encryption-key"
  target_key_id = aws_kms_key.efs.key_id
}

# EFS File System with encryption at rest and tags
resource "aws_efs_file_system" "this" {
  creation_token = "my-efs-file-system"

  # Enable encryption at rest using the customer-managed KMS key
  encrypted  = true
  kms_key_id = aws_kms_key.efs.arn

  # Performance and throughput configuration
  performance_mode = "generalPurpose"
  throughput_mode  = "bursting"

  # Automatically transition files to Infrequent Access storage to save cost
  lifecycle_policy {
    transition_to_ia = "AFTER_30_DAYS"
  }

  lifecycle_policy {
    transition_to_primary_storage_class = "AFTER_1_ACCESS"
  }

  tags = {
    Name        = "my-efs-file-system"
    Environment = "production"
    ManagedBy   = "terraform"
    Application = "shared-storage"
  }
}

# Enforce encryption in transit via a file system policy
resource "aws_efs_file_system_policy" "this" {
  file_system_id                     = aws_efs_file_system.this.id
  bypass_policy_lockout_safety_check = false

  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "efs-secure-transport-policy"
    Statement = [
      {
        Sid       = "EnforceInTransitEncryption"
        Effect    = "Deny"
        Principal = { AWS = "*" }
        Action    = "*"
        Resource  = aws_efs_file_system.this.arn
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })
}

# Enable automatic backups for the EFS file system
resource "aws_efs_backup_policy" "this" {
  file_system_id = aws_efs_file_system.this.id

  backup_policy {
    status = "ENABLED"
  }
}

output "efs_file_system_id" {
  description = "The ID of the EFS file system"
  value       = aws_efs_file_system.this.id
}

output "efs_file_system_arn" {
  description = "The ARN of the EFS file system"
  value       = aws_efs_file_system.this.arn
}

output "efs_dns_name" {
  description = "The DNS name of the EFS file system"
  value       = aws_efs_file_system.this.dns_name
}

