# ---------------------------------------------------------------------------
# KMS keys for encryption at rest (one per region, best practice)
# ---------------------------------------------------------------------------
resource "aws_kms_key" "us_east_1" {
  provider                = aws.us_east_1
  description             = "KMS key for DynamoDB encryption (us-east-1)"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = {
    Name        = "dynamodb-kms-us-east-1"
    Environment = "production"
    ManagedBy   = "terraform"
