}

# ---------------------------------------------------------------------------
# Local values
# ---------------------------------------------------------------------------
locals {
  table_name = "app-data"

  common_tags = {
    Environment = "production"
    ManagedBy   = "terraform"
    Application = "app-data"
  }
}

# ---------------------------------------------------------------------------
# DynamoDB Tables (one per region)
# ---------------------------------------------------------------------------
resource "aws_dynamodb_table" "us_east_1" {
  provider = aws.us_east_1

  name         = local.table_name
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "id"

  attribute {
    name = "id"
    type = "S"
  }

  # Encryption at rest with customer-managed KMS key
  server_side_encryption {
    enabled     = true
    kms_key_arn = aws_kms_key.us_east_1.arn
  }

  # Point-in-time recovery for data protection
  point_in_time_recovery {
    enabled = true
  }

  # Protect against accidental deletion
  deletion_protection_enabled = true

  tags = merge(local.common_tags, {
    Name   = "${local.table_name}-us-east-1"
    Region = "us-east-1"
  })
}

resource "aws_dynamodb_table" "us_west_1" {
  provider = aws.us_west_1

  name         = local.table_name
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "id"

  attribute {
    name = "id"
    type = "S"
  }

  server_side_encryption {
    enabled     = true
    kms_key_arn = aws_kms_key.us_west_1.arn
  }

  point_in_time_recovery {
    enabled = true
  }

  deletion_protection_enabled = true

  tags = merge(local.common_tags, {
    Name   = "${local.table_name}-us-west-1"
    Region = "us-west-1"
  })
}

resource "aws_dynamodb_table" "us_west_2" {
  provider = aws.us_west_2

  name         = local.table_name
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "id"

  attribute {
    name = "id"
    type = "S"
  }

  server_side_encryption {
    enabled     = true
    kms_key_arn = aws_kms_key.us_west_2.arn
  }

  point_in_time_recovery {
    enabled = true
  }

  deletion_protection_enabled = true

  tags = merge(local.common_tags, {
    Name   = "${local.table_name}-us-west-2"
    Region = "us-west-2"
  })
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------
output "dynamodb_table_arns" {
  description = "ARNs of the DynamoDB tables per region"
  value = {
    us_east_1 = aws_dynamodb_table.us_east_1.arn
    us_west_1 = aws_dynamodb_table.us_west_1.arn
    us_west_2 = aws_dynamodb_table.us_west_2.arn
