model_answers:
terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region to deploy resources"
  type        = string
  default     = "us-east-1"
}

variable "app_name" {
  description = "Name of the Kinesis Analytics Application"
  type        = string
  default     = "basic-kinesis-analytics-app"
}

variable "log_retention_days" {
  description = "CloudWatch log retention in days"
  type        = number
  default     = 90
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

# ---------------------------------------------------------------------------
# KMS key for encrypting CloudWatch Logs
# ---------------------------------------------------------------------------
resource "aws_kms_key" "logs" {
  description             = "KMS key for Kinesis Analytics CloudWatch logs"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootPermissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowCloudWatchLogs"
        Effect = "Allow"
        Principal = {
          Service = "logs.${data.aws_region.current.name}.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:Describe*"
        ]
        Resource = "*"
        Condition = {
          ArnLike = {
            "kms:EncryptionContext:aws:logs:arn" = "arn:aws:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:/aws/kinesisanalytics/${var.app_name}"
          }
        }
      }
    ]
  })
}

resource "aws_kms_alias" "logs" {
  name          = "alias/${var.app_name}-logs"
  target_key_id = aws_kms_key.logs.key_id
}

# ---------------------------------------------------------------------------
# CloudWatch Log Group and Log Stream
# ---------------------------------------------------------------------------
resource "aws_cloudwatch_log_group" "kinesis_analytics" {
  name              = "/aws/kinesisanalytics/${var.app_name}"
  retention_in_days = var.log_retention_days
  kms_key_id        = aws_kms_key.logs.arn

  tags = {
    Application = var.app_name
    ManagedBy   = "terraform"
  }
}

resource "aws_cloudwatch_log_stream" "kinesis_analytics" {
  name           = "${var.app_name}-log-stream"
  log_group_name = aws_cloudwatch_log_group.kinesis_analytics.name
}

# ---------------------------------------------------------------------------
# IAM Role for Kinesis Analytics Application
# ---------------------------------------------------------------------------
data "aws_iam_policy_document" "assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["kinesisanalytics.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }
}

resource "aws_iam_role" "kinesis_analytics" {
  name               = "${var.app_name}-role"
  assume_role_policy = data.aws_iam_policy_document.assume_role.json

  tags = {
    Application = var.app_name
    ManagedBy   = "terraform"
  }
}

data "aws_iam_policy_document" "logging" {
  statement {
    sid    = "AllowCloudWatchLogging"
    effect = "Allow"
    actions = [
      "logs:PutLogEvents",
      "logs:DescribeLogGroups",
      "logs:DescribeLogStreams"
    ]
    resources = [
      aws_cloudwatch_log_group.kinesis_analytics.arn,
      "${aws_cloudwatch_log_group.kinesis_analytics.arn}:*"
    ]
  }
}

resource "aws_iam_role_policy" "logging" {
  name   = "${var.app_name}-logging-policy"
  role   = aws_iam_role.kinesis_analytics.id
  policy = data.aws_iam_policy_document.logging.json
}

# ---------------------------------------------------------------------------
# Kinesis Analytics Application
# ---------------------------------------------------------------------------
resource "aws_kinesis_analytics_application" "this" {
  name = var.app_name

  cloudwatch_logging_options {
    log_stream_arn = aws_cloudwatch_log_stream.kinesis_analytics.arn
    role_arn       = aws_iam_role.kinesis_analytics.arn
  }

  code = <<-EOF
    CREATE OR REPLACE STREAM "DESTINATION_SQL_STREAM" (
      "column1" VARCHAR(16),
      "column2" INTEGER
    );

    CREATE OR REPLACE PUMP "STREAM_PUMP" AS
      INSERT INTO "DESTINATION_SQL_STREAM"
      SELECT STREAM "column1", "column2"
      FROM "SOURCE_SQL_STREAM_001";
  EOF

  tags = {
    Application = var.app_name
    ManagedBy   = "terraform"
  }
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------
output "kinesis_analytics_application_arn" {
  description = "ARN of the Kinesis Analytics Application"
  value       = aws_kinesis_analytics_application.this.arn
}

output "cloudwatch_log_group_name" {
  description = "Name of the CloudWatch Log Group"
  value       = aws_cloudwatch_log_group.kinesis_analytics.name
}

output "cloudwatch_log_stream_name" {
  description = "Name of the CloudWatch Log Stream"
  value       = aws_cloudwatch_log_stream.kinesis_analytics.name
}

