model_answers:
resource "aws_lex_intent" "order_pizza" {
  name           = "OrderPizza"
  description    = "Intent to order a pizza"
  create_version = true

  sample_utterances = [
    "I want to order a pizza",
    "I would like to order a pizza",
    "Can I get a pizza",
    "Order me a pizza",
  ]

  slot {
    name          = "PizzaSize"
    description   = "The size of the pizza"
    priority      = 1
    slot_constraint = "Required"
    slot_type       = "AMAZON.AlphaNumeric"

    value_elicitation_prompt {
      max_attempts = 2

      message {
        content      = "What size pizza would you like? Small, medium, or large?"
        content_type = "PlainText"
      }
    }

    sample_utterances = [
      "I want a {PizzaSize} pizza",
    ]
  }

  slot {
    name            = "PizzaType"
    description     = "The type of pizza"
    priority        = 2
    slot_constraint = "Required"
    slot_type       = "AMAZON.AlphaNumeric"

    value_elicitation_prompt {
      max_attempts = 2

      message {
        content      = "What type of pizza would you like? For example, cheese, pepperoni, or veggie."
        content_type = "PlainText"
      }
    }

    sample_utterances = [
      "I want a {PizzaType} pizza",
    ]
  }

  confirmation_prompt {
    max_attempts = 2

    message {
      content      = "You want a {PizzaSize} {PizzaType} pizza. Is that correct?"
      content_type = "PlainText"
    }
  }

  rejection_statement {
    message {
      content      = "Okay, your order has been cancelled."
      content_type = "PlainText"
    }
  }

  fulfillment_activity {
    type = "ReturnIntent"
  }

  conclusion_statement {
    message {
      content      = "Great! Your {PizzaSize} {PizzaType} pizza is on its way. Thank you for your order!"
      content_type = "PlainText"
    }

    response_card = "{\"version\":1,\"contentType\":\"application/vnd.amazonaws.card.generic\",\"genericAttachments\":[{\"title\":\"Order Confirmed\",\"subTitle\":\"Your pizza is being prepared\"}]}"
  }
}

resource "aws_lex_bot" "pizza_ordering_bot" {
  name             = "PizzaOrderingBot"
  description      = "A bot to order pizzas"
  create_version   = true
  child_directed   = false
  idle_session_ttl_in_seconds = 300
  process_behavior = "BUILD"
  locale           = "en-US"

  intent {
    intent_name    = aws_lex_intent.order_pizza.name
    intent_version = aws_lex_intent.order_pizza.version
  }

  abort_statement {
    message {
      content      = "Sorry, I could not understand your order. Please try again later."
      content_type = "PlainText"
    }
  }

  clarification_prompt {
    max_attempts = 2

    message {
      content      = "I didn't understand that. Could you please repeat?"
      content_type = "PlainText"
    }
  }
}

