}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region for the Lightsail instance"
  type        = string
  default     = "us-east-1"
}

variable "availability_zone" {
  description = "Availability zone for the Lightsail instance"
  type        = string
  default     = "us-east-1a"
}

variable "instance_name" {
  description = "Name of the Lightsail instance"
  type        = string
  default     = "wordpress-instance"
}

variable "bundle_id" {
  description = "Lightsail bundle (instance plan) ID"
  type        = string
  default     = "nano_3_0"
}

variable "allowed_ssh_cidrs" {
  description = "CIDR blocks allowed to access SSH (port 22). Restrict to trusted IPs."
  type        = list(string)
  default     = []
}

variable "tags" {
  description = "Tags to apply to resources"
  type        = map(string)
  default = {
    Environment = "production"
    Application = "wordpress"
    ManagedBy   = "terraform"
  }
}

# WordPress blueprint for Lightsail
data "aws_lightsail_bundle" "wordpress" {
  # Placeholder to validate region availability; not strictly required.
  # Uses the default provider region.
}

resource "aws_lightsail_instance" "wordpress" {
  name              = var.instance_name
  availability_zone = var.availability_zone
  blueprint_id      = "wordpress"
  bundle_id         = var.bundle_id

  tags = var.tags
}

# Restrict public ports. Only allow HTTP/HTTPS to the world,
# and SSH only from explicitly trusted CIDRs.
resource "aws_lightsail_instance_public_ports" "wordpress" {
  instance_name = aws_lightsail_instance.wordpress.name

  port_info {
    protocol  = "tcp"
    from_port = 80
    to_port   = 80
    cidrs     = ["0.0.0.0/0"]
  }

  port_info {
    protocol  = "tcp"
    from_port = 443
    to_port   = 443
    cidrs     = ["0.0.0.0/0"]
  }

  dynamic "port_info" {
    for_each = length(var.allowed_ssh_cidrs) > 0 ? [1] : []
    content {
      protocol  = "tcp"
      from_port = 22
      to_port   = 22
      cidrs     = var.allowed_ssh_cidrs
    }
  }
}

# Allocate and attach a static public IP for stable addressing
resource "aws_lightsail_static_ip" "wordpress" {
  name = "${var.instance_name}-static-ip"
}

resource "aws_lightsail_static_ip_attachment" "wordpress" {
  static_ip_name = aws_lightsail_static_ip.wordpress.name
  instance_name  = aws_lightsail_instance.wordpress.name
}

output "instance_name" {
  description = "Name of the Lightsail WordPress instance"
  value       = aws_lightsail_instance.wordpress.name
}

output "static_ip_address" {
  description = "Static public IP address of the WordPress instance"
  value       = aws_lightsail_static_ip.wordpress.ip_address
}

output "wordpress_url" {
  description = "URL to access the WordPress site"
  value       = "http://${aws_lightsail_static_ip.wordpress.ip_address}"
}

