model_answers:
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region to deploy resources"
  type        = string
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "redshift_master_username" {
  description = "Master username for the Redshift cluster"
  type        = string
  default     = "adminuser"
}

data "aws_availability_zones" "available" {
  state = "available"
}

# ---------------------------------------------------------------------------
# VPC
# ---------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "redshift-vpc"
  }
}

# ---------------------------------------------------------------------------
# Subnets (two, in different AZs)
# ---------------------------------------------------------------------------
resource "aws_subnet" "subnet_a" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(var.vpc_cidr, 8, 0)
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = {
    Name = "redshift-subnet-a"
  }
}

resource "aws_subnet" "subnet_b" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(var.vpc_cidr, 8, 1)
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = {
    Name = "redshift-subnet-b"
  }
}

# ---------------------------------------------------------------------------
# Redshift Subnet Group
# ---------------------------------------------------------------------------
resource "aws_redshift_subnet_group" "main" {
  name       = "redshift-subnet-group"
  subnet_ids = [aws_subnet.subnet_a.id, aws_subnet.subnet_b.id]

  tags = {
    Name = "redshift-subnet-group"
  }
}

# ---------------------------------------------------------------------------
# Security Group for Redshift (no ingress from 0.0.0.0/0)
# ---------------------------------------------------------------------------
resource "aws_security_group" "redshift" {
  name        = "redshift-sg"
  description = "Security group for Redshift cluster"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Redshift access from within VPC"
    from_port   = 5439
    to_port     = 5439
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    description = "Allow all outbound"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "redshift-sg"
  }
}

# ---------------------------------------------------------------------------
# KMS key for Redshift encryption at rest
# ---------------------------------------------------------------------------
resource "aws_kms_key" "redshift" {
  description             = "KMS key for Redshift cluster encryption"
  deletion_window_in_days = 10
  enable_key_rotation     = true

  tags = {
    Name = "redshift-kms-key"
  }
}

# ---------------------------------------------------------------------------
# Random master password (stored in Secrets Manager)
# ---------------------------------------------------------------------------
resource "random_password" "redshift_master" {
  length           = 24
  special          = true
  override_special = "!#$%^&*()-_=+[]{}<>:?"
}

resource "aws_secretsmanager_secret" "redshift_master" {
  name                    = "redshift-master-credentials"
  kms_key_id              = aws_kms_key.redshift.arn
  recovery_window_in_days = 7
}

resource "aws_secretsmanager_secret_version" "redshift_master" {
  secret_id = aws_secretsmanager_secret.redshift_master.id
  secret_string = jsonencode({
    username = var.redshift_master_username
    password = random_password.redshift_master.result
  })
}

# ---------------------------------------------------------------------------
# Redshift Cluster
# ---------------------------------------------------------------------------
resource "aws_redshift_cluster" "main" {
  cluster_identifier        = "example-redshift-cluster"
  database_name             = "exampledb"
  master_username           = var.redshift_master_username
  master_password           = random_password.redshift_master.result
  node_type                 = "ra3.xlplus"
  cluster_type              = "single-node"
  number_of_nodes           = 1
  cluster_subnet_group_name = aws_redshift_subnet_group.main.name
  vpc_security_group_ids    = [aws_security_group.redshift.id]

  # Security best practices
  publicly_accessible = false
  encrypted           = true
  kms_key_id          = aws_kms_key.redshift.arn

  enhanced_vpc_routing                = true
  automated_snapshot_retention_period = 7
  skip_final_snapshot                 = false
  final_snapshot_identifier           = "example-redshift-final-snapshot"

  logging {
    enable = true
  }

  tags = {
    Name = "example-redshift-cluster"
  }
}

# ---------------------------------------------------------------------------
# Redshift Endpoint Access (uses the subnet group attached to the cluster)
# ---------------------------------------------------------------------------
resource "aws_redshift_endpoint_access" "main" {
  endpoint_name          = "example-redshift-endpoint"
  cluster_identifier     = aws_redshift_cluster.main.cluster_identifier
  subnet_group_name      = aws_redshift_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.redshift.id]
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------
output "vpc_id" {
  value = aws_vpc.main.id
}

output "redshift_cluster_endpoint" {
  value = aws_redshift_cluster.main.endpoint
}

output "redshift_endpoint_access_address" {
  value = aws_redshift_endpoint_access.main.address
}

output "redshift_master_secret_arn" {
  value = aws_secretsmanager_secret.redshift_master.arn
}

