provider "aws" {
  region = var.aws_region
}

##############################
# Variables
##############################
variable "aws_region" {
  description = "AWS region to deploy resources"
  type        = string
  default     = "us-east-1"
}

variable "domain_name" {
  description = "The domain name to manage in Route 53 (e.g. example.com)"
  type        = string
}

variable "subdomain" {
  description = "Subdomain that points to the Elastic Beanstalk environment"
  type        = string
  default     = "app"
}

variable "solution_stack_name" {
  description = "Elastic Beanstalk solution stack"
  type        = string
  default     = "64bit Amazon Linux 2023 v4.1.1 running Docker"
}

variable "instance_type" {
  description = "EC2 instance type for the Elastic Beanstalk environment"
  type        = string
  default     = "t3.small"
}

variable "vpc_id" {
  description = "VPC ID where resources are deployed"
  type        = string
}

variable "public_subnet_ids" {
  description = "Public subnets for the Elastic Beanstalk load balancer"
  type        = list(string)
}

variable "private_subnet_ids" {
  description = "Private subnets for EC2 instances and RDS"
  type        = list(string)
}

variable "db_username" {
  description = "Master username for the RDS database"
  type        = string
  default     = "dbadmin"
}

##############################
# Data sources
##############################
data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}

##############################
# Random password for RDS
##############################
resource "random_password" "db_password" {
  length           = 24
  special          = true
  override_special = "!#$%^&*()-_=+"
}

##############################
# Secrets Manager for DB credentials
##############################
resource "aws_secretsmanager_secret" "db_credentials" {
  name                    = "myapp_db-credentials"
  description             = "Master credentials for myapp_db RDS instance"
  recovery_window_in_days = 7
}

resource "aws_secretsmanager_secret_version" "db_credentials" {
  secret_id = aws_secretsmanager_secret.db_credentials.id
  secret_string = jsonencode({
    username = var.db_username
    password = random_password.db_password.result
    dbname   = aws_db_instance.myapp_db.db_name
    host     = aws_db_instance.myapp_db.address
    port     = aws_db_instance.myapp_db.port
  })
}

##############################
# IAM Roles for Elastic Beanstalk
##############################

# Service role for Elastic Beanstalk
data "aws_iam_policy_document" "eb_service_assume" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["elasticbeanstalk.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "eb_service_role" {
  name               = "eb_service_role1"
  assume_role_policy = data.aws_iam_policy_document.eb_service_assume.json
}

resource "aws_iam_role_policy_attachment" "eb_service_health" {
  role       = aws_iam_role.eb_service_role.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSElasticBeanstalkEnhancedHealth"
}

resource "aws_iam_role_policy_attachment" "eb_service_managed" {
  role       = aws_iam_role.eb_service_role.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AWSElasticBeanstalkManagedUpdatesCustomerRolePolicy"
}

# EC2 instance role and profile
data "aws_iam_policy_document" "eb_ec2_assume" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "eb_ec2_role" {
  name               = "eb_ec2_role1"
  assume_role_policy = data.aws_iam_policy_document.eb_ec2_assume.json
}

resource "aws_iam_role_policy_attachment" "eb_ec2_web" {
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AWSElasticBeanstalkWebTier"
}

resource "aws_iam_role_policy_attachment" "eb_ec2_worker" {
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AWSElasticBeanstalkWorkerTier"
}

resource "aws_iam_role_policy_attachment" "eb_ec2_ssm" {
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

# Allow instances to read the DB secret
data "aws_iam_policy_document" "eb_ec2_secret_read" {
  statement {
    effect    = "Allow"
    actions   = ["secretsmanager:GetSecretValue"]
    resources = [aws_secretsmanager_secret.db_credentials.arn]
  }
}

resource "aws_iam_role_policy" "eb_ec2_secret_read" {
  name   = "eb-ec2-read-db-secret"
  role   = aws_iam_role.eb_ec2_role.id
  policy = data.aws_iam_policy_document.eb_ec2_secret_read.json
}

resource "aws_iam_instance_profile" "eb_ec2_profile1" {
  name = "eb_ec2_profile1"
  role = aws_iam_role.eb_ec2_role.name
}

##############################
# Security Groups
##############################
resource "aws_security_group" "eb_instances" {
  name        = "eb-instances-sg"
  description = "Security group for Elastic Beanstalk EC2 instances"
  vpc_id      = var.vpc_id

  egress {
    description = "Allow all outbound"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "eb-instances-sg"
  }
}

resource "aws_security_group" "rds" {
  name        = "myapp-db-sg"
  description = "Security group for myapp_db RDS instance"
  vpc_id      = var.vpc_id

  ingress {
    description     = "PostgreSQL from EB instances"
    from_port       = 5432
    to_port         = 5432
    protocol        = "tcp"
    security_groups = [aws_security_group.eb_instances.id]
  }

  egress {
    description = "Allow all outbound"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "myapp-db-sg"
  }
}

##############################
# RDS Database
##############################
resource "aws_db_subnet_group" "myapp_db" {
  name       = "myapp-db-subnet-group"
  subnet_ids = var.private_subnet_ids

  tags = {
    Name = "myapp-db-subnet-group"
  }
}

resource "aws_db_instance" "myapp_db" {
  identifier     = "myapp-db"
  db_name        = "myapp_db"
  engine         = "postgres"
  engine_version = "15"
  instance_class = "db.t3.micro"

  allocated_storage     = 20
  max_allocated_storage = 100
  storage_type          = "gp3"
  storage_encrypted     = true

  username = var.db_username
  password = random_password.db_password.result

  db_subnet_group_name   = aws_db_subnet_group.myapp_db.name
  vpc_security_group_ids = [aws_security_group.rds.id]

  multi_az                    = true
  publicly_accessible         = false
  backup_retention_period     = 7
  deletion_protection         = true
  auto_minor_version_upgrade  = true
  copy_tags_to_snapshot       = true
  iam_database_authentication_enabled = true

  performance_insights_enabled = true
  skip_final_snapshot          = false
  final_snapshot_identifier    = "myapp-db-final-snapshot"

  tags = {
    Name = "myapp_db"
  }
}

##############################
# Elastic Beanstalk
##############################
resource "aws_elastic_beanstalk_application" "app" {
  name        = "myapp"
  description = "myapp Elastic Beanstalk application"
}

resource "aws_elastic_beanstalk_environment" "myenv" {
  name                = "myenv"
  application         = aws_elastic_beanstalk_application.app.name
  solution_stack_name = var.solution_stack_name
  tier                = "WebServer"

  # VPC configuration
  setting {
    namespace = "aws:ec2:vpc"
    name      = "VPCId"
    value     = var.vpc_id
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "Subnets"
    value     = join(",", var.private_subnet_ids)
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "ELBSubnets"
    value     = join(",", var.public_subnet_ids)
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "AssociatePublicIpAddress"
    value     = "false"
  }

  # Instance profile
  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "IamInstanceProfile"
    value     = aws_iam_instance_profile.eb_ec2_profile1.name
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "InstanceType"
    value     = var.instance_type
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "SecurityGroups"
    value     = aws_security_group.eb_instances.id
  }

  # Require IMDSv2
  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "DisableIMDSv1"
    value     = "true"
  }

  # Service role
  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "ServiceRole"
    value     = aws_iam_role.eb_service_role.arn
  }

  # Application load balancer
  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "LoadBalancerType"
    value     = "application"
  }

  # Enhanced health
  setting {
    namespace = "aws:elasticbeanstalk:healthreporting:system"
    name      = "SystemType"
    value     = "enhanced"
  }

  # Managed platform updates
  setting {
    namespace = "aws:elasticbeanstalk:managedactions"
    name      = "ManagedActionsEnabled"
    value     = "true"
  }

  setting {
    namespace = "aws:elasticbeanstalk:managedactions"
    name      = "PreferredStartTime"
    value     = "Sun:10:00"
  }

  setting {
    namespace = "aws:elasticbeanstalk:managedactions:platformupdate"
    name      = "UpdateLevel"
    value     = "minor"
  }

  # Environment variables for DB connectivity (from Secrets Manager)
  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "DB_HOST"
    value     = aws_db_instance.myapp_db.address
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "DB_PORT"
    value     = aws_db_instance.myapp_db.port
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "DB_NAME"
    value     = aws_db_instance.myapp_db.db_name
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "DB_SECRET_ARN"
    value     = aws_secretsmanager_secret.db_credentials.arn
  }

  depends_on = [
    aws_iam_role_policy_attachment.eb_service_health,
    aws_iam_role_policy_attachment.eb_service_managed
  ]
}

##############################
# Route 53
##############################
resource "aws_route53_zone" "main" {
  name = var.domain_name

  tags = {
    Name = var.domain_name
  }
}

# Alias record pointing to the Elastic Beanstalk environment's load balancer.
# Retrieve the ELB details created by Elastic Beanstalk.
data "aws_elastic_beanstalk_hosted_zone" "current" {}

# Look up the load balancer created for the environment.
data "aws_lb" "eb_alb" {
  tags = {
    "elasticbeanstalk:environment-name" = aws_elastic_beanstalk_environment.myenv.name
  }

  depends_on = [aws_elastic_beanstalk_environment.myenv]
}

resource "aws_route53_record" "app" {
  zone_id = aws_route53_zone.main.zone_id
  name    = "${var.subdomain}.${var.domain_name}"
