model_answers:
terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region to deploy resources"
  type        = string
  default     = "us-east-1"
}

variable "vpc_id" {
  description = "VPC ID where the RDS instance will be created"
  type        = string
}

variable "public_subnet_ids" {
  description = "List of public subnet IDs for the DB subnet group"
  type        = list(string)
}

variable "allowed_cidr_blocks" {
  description = "CIDR blocks allowed to access the PostgreSQL instance"
  type        = list(string)
  default     = []
}

variable "db_name" {
  description = "Name of the initial database"
  type        = string
  default     = "airbyte_test"
}

variable "db_username" {
  description = "Master username for the database"
  type        = string
  default     = "airbyte_admin"
}

variable "db_instance_class" {
  description = "RDS instance class"
  type        = string
  default     = "db.t3.medium"
}

variable "environment" {
  description = "Environment tag"
  type        = string
  default     = "test"
}

# Generate a strong random master password
resource "random_password" "db_master" {
  length           = 24
  special          = true
  override_special = "!#$%&*()-_=+[]{}<>:?"
}

# Store credentials securely in Secrets Manager
resource "aws_secretsmanager_secret" "db_credentials" {
  name        = "airbyte-connector-test-rds-credentials"
  description = "Master credentials for Airbyte connector test PostgreSQL RDS instance"

  tags = {
    Name        = "airbyte-connector-test-rds-credentials"
    Environment = var.environment
    Purpose     = "airbyte-connector-tests"
  }
}

resource "aws_secretsmanager_secret_version" "db_credentials" {
  secret_id = aws_secretsmanager_secret.db_credentials.id
  secret_string = jsonencode({
    username = var.db_username
    password = random_password.db_master.result
    engine   = "postgres"
    dbname   = var.db_name
  })
}

# KMS key for RDS storage encryption
resource "aws_kms_key" "rds" {
  description             = "KMS key for Airbyte connector test RDS encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = {
    Name        = "airbyte-connector-test-rds-kms"
    Environment = var.environment
  }
}

resource "aws_kms_alias" "rds" {
  name          = "alias/airbyte-connector-test-rds"
  target_key_id = aws_kms_key.rds.key_id
}

# DB subnet group across the provided public subnets
resource "aws_db_subnet_group" "this" {
  name       = "airbyte-connector-test-subnet-group"
  subnet_ids = var.public_subnet_ids

  tags = {
    Name        = "airbyte-connector-test-subnet-group"
    Environment = var.environment
  }
}

# Security group restricting access to PostgreSQL
resource "aws_security_group" "rds" {
  name        = "airbyte-connector-test-rds-sg"
  description = "Security group for Airbyte connector test PostgreSQL RDS"
  vpc_id      = var.vpc_id

  ingress {
    description = "PostgreSQL access from allowed CIDR blocks"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = var.allowed_cidr_blocks
  }

  egress {
    description = "Allow all outbound"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name        = "airbyte-connector-test-rds-sg"
    Environment = var.environment
  }
}

# IAM role for enhanced monitoring
resource "aws_iam_role" "rds_monitoring" {
  name = "airbyte-connector-test-rds-monitoring"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "monitoring.rds.amazonaws.com"
        }
      }
    ]
  })

  tags = {
    Environment = var.environment
  }
}

resource "aws_iam_role_policy_attachment" "rds_monitoring" {
  role       = aws_iam_role.rds_monitoring.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonRDSEnhancedMonitoringRole"
}

# PostgreSQL 15 RDS instance
resource "aws_db_instance" "airbyte_test" {
  identifier     = "airbyte-connector-test-pg"
  engine         = "postgres"
  engine_version = "15"
  instance_class = var.db_instance_class

  db_name  = var.db_name
  username = var.db_username
  password = random_password.db_master.result

  allocated_storage     = 20
  max_allocated_storage = 100
  storage_type          = "gp3"
  storage_encrypted     = true
  kms_key_id            = aws_kms_key.rds.arn

  db_subnet_group_name   = aws_db_subnet_group.this.name
  vpc_security_group_ids = [aws_security_group.rds.id]
  publicly_accessible    = true

  # Managed / low maintenance settings
  auto_minor_version_upgrade = true
  maintenance_window         = "sun:04:00-sun:05:00"
  backup_window              = "03:00-04:00"
  backup_retention_period    = 7

  # Requested behaviors
  skip_final_snapshot = true
  apply_immediately   = true

  # Security best practices
  iam_database_authentication_enabled = true
  deletion_protection                 = false
  copy_tags_to_snapshot               = true
  performance_insights_enabled        = true
  performance_insights_kms_key_id     = aws_kms_key.rds.arn
  monitoring_interval                 = 60
  monitoring_role_arn                 = aws_iam_role.rds_monitoring.arn

  enabled_cloudwatch_logs_exports = ["postgresql", "upgrade"]

  tags = {
    Name        = "airbyte-connector-test-pg"
    Environment = var.environment
    Purpose     = "airbyte-connector-tests"
  }
}

output "rds_endpoint" {
  description = "Endpoint of the PostgreSQL RDS instance"
  value       = aws_db_instance.airbyte_test.endpoint
}

output "rds_port" {
  description = "Port of the PostgreSQL RDS instance"
  value       = aws_db_instance.airbyte_test.port
}

output "rds_database_name" {
  description = "Name of the initial database"
  value       = aws_db_instance.airbyte_test.db_name
}

output "db_credentials_secret_arn" {
  description = "ARN of the Secrets Manager secret holding DB credentials"
  value       = aws_secretsmanager_secret.db_credentials.arn
}

