###############################################################################
# Data sources
###############################################################################
data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}

###############################################################################
# KMS key for SageMaker Domain EFS encryption (security best practice)
###############################################################################
resource "aws_kms_key" "sagemaker" {
  description             = "KMS key for SageMaker Domain EFS encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootAccount"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "sagemaker" {
  name          = "alias/sagemaker-domain"
  target_key_id = aws_kms_key.sagemaker.key_id
}

###############################################################################
# Networking (assumes existing VPC / subnets are provided via variables)
###############################################################################
variable "vpc_id" {
  description = "VPC ID for the SageMaker Domain"
  type        = string
}

variable "subnet_ids" {
  description = "Private subnet IDs for the SageMaker Domain"
  type        = list(string)
}

###############################################################################
# IAM execution role for SageMaker
###############################################################################
data "aws_iam_policy_document" "sagemaker_assume" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["sagemaker.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "sagemaker_execution" {
  name               = "sagemaker-jupyter-execution-role"
  assume_role_policy = data.aws_iam_policy_document.sagemaker_assume.json
}

# Scoped-down managed policy (avoid full-access policies where possible)
resource "aws_iam_role_policy_attachment" "sagemaker_execution" {
  role       = aws_iam_role.sagemaker_execution.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonSageMakerFullAccess"
}

