provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region to deploy resources"
  type        = string
  default     = "us-east-1"
}

variable "cluster_identifier" {
  description = "Identifier for the Redshift cluster"
  type        = string
  default     = "example-redshift-cluster"
}

variable "database_name" {
  description = "Name of the initial database"
  type        = string
  default     = "exampledb"
}

variable "master_username" {
  description = "Master username for the Redshift cluster"
  type        = string
  default     = "adminuser"
}

variable "node_type" {
  description = "Node type for the Redshift cluster"
  type        = string
  default     = "ra3.xlplus"
}

variable "number_of_nodes" {
  description = "Number of nodes in the Redshift cluster"
  type        = number
  default     = 2
}

# Generate a strong random master password
resource "random_password" "redshift_master" {
  length           = 24
  special          = true
  override_special = "!#$%^&*()-_=+[]{}"
}

# Store the master password securely in Secrets Manager
resource "aws_secretsmanager_secret" "redshift_master" {
  name                    = "${var.cluster_identifier}-master-password"
  description             = "Master password for Redshift cluster ${var.cluster_identifier}"
  recovery_window_in_days = 7
}

resource "aws_secretsmanager_secret_version" "redshift_master" {
  secret_id = aws_secretsmanager_secret.redshift_master.id
  secret_string = jsonencode({
    username = var.master_username
    password = random_password.redshift_master.result
  })
}

# KMS key for encrypting the Redshift cluster
resource "aws_kms_key" "redshift" {
  description             = "KMS key for Redshift cluster encryption"
  deletion_window_in_days = 10
  enable_key_rotation     = true
}

resource "aws_kms_alias" "redshift" {
  name          = "alias/${var.cluster_identifier}-kms"
  target_key_id = aws_kms_key.redshift.key_id
}

# KMS key for encrypting the SNS topic
resource "aws_kms_key" "sns" {
  description             = "KMS key for Redshift SNS topic encryption"
  deletion_window_in_days = 10
  enable_key_rotation     = true
}

resource "aws_kms_alias" "sns" {
  name          = "alias/${var.cluster_identifier}-sns-kms"
  target_key_id = aws_kms_key.sns.key_id
}

# SNS topic to receive Redshift events (encrypted at rest)
resource "aws_sns_topic" "redshift_events" {
  name              = "${var.cluster_identifier}-events"
  kms_master_key_id = aws_kms_key.sns.key_id
}

# Allow Redshift service to publish to the SNS topic
data "aws_caller_identity" "current" {}

resource "aws_sns_topic_policy" "redshift_events" {
  arn = aws_sns_topic.redshift_events.arn

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowRedshiftPublish"
        Effect    = "Allow"
        Principal = {
          Service = "redshift.amazonaws.com"
        }
        Action   = "SNS:Publish"
        Resource = aws_sns_topic.redshift_events.arn
        Condition = {
          StringEquals = {
            "AWS:SourceAccount" = data.aws_caller_identity.current.account_id
          }
        }
      }
    ]
  })
}

# Redshift parameter group
resource "aws_redshift_parameter_group" "example" {
  name   = "${var.cluster_identifier}-params"
  family = "redshift-1.0"

  parameter {
    name  = "require_ssl"
    value = "true"
  }

  parameter {
    name  = "enable_user_activity_logging"
    value = "true"
  }
}

# Redshift cluster
resource "aws_redshift_cluster" "example" {
  cluster_identifier = var.cluster_identifier
  database_name      = var.database_name
  master_username    = var.master_username
  master_password    = random_password.redshift_master.result

  node_type       = var.node_type
  cluster_type    = var.number_of_nodes > 1 ? "multi-node" : "single-node"
  number_of_nodes = var.number_of_nodes

  cluster_parameter_group_name = aws_redshift_parameter_group.example.name

  # Security best practices
  encrypted                           = true
  kms_key_id                          = aws_kms_key.redshift.arn
  publicly_accessible                 = false
  enhanced_vpc_routing                = true
  automated_snapshot_retention_period = 7
  skip_final_snapshot                 = false
  final_snapshot_identifier           = "${var.cluster_identifier}-final-snapshot"

  tags = {
    Name        = var.cluster_identifier
    Environment = "example"
  }
}

# Redshift event subscription for events associated with the parameter group
resource "aws_redshift_event_subscription" "parameter_group_events" {
  name          = "${var.cluster_identifier}-param-group-events"
  sns_topic_arn = aws_sns_topic.redshift_events.arn

  source_type = "cluster-parameter-group"
  source_ids  = [aws_redshift_parameter_group.example.id]

  severity = "INFO"

  event_categories = [
    "configuration",
  ]

  enabled = true

  depends_on = [aws_sns_topic_policy.redshift_events]

  tags = {
    Name = "${var.cluster_identifier}-param-group-events"
  }
}

output "redshift_cluster_endpoint" {
  description = "Endpoint of the Redshift cluster"
  value       = aws_redshift_cluster.example.endpoint
}

output "redshift_parameter_group_name" {
  description = "Name of the Redshift parameter group"
  value       = aws_redshift_parameter_group.example.name
}

output "sns_topic_arn" {
  description = "ARN of the SNS topic receiving Redshift events"
  value       = aws_sns_topic.redshift_events.arn
}

output "master_password_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the master password"
  value       = aws_secretsmanager_secret.redshift_master.arn
}

