model_answers:
terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

#############################################
# Providers (one per region)
#############################################

provider "aws" {
  alias  = "us_west"
  region = "us-west-2"
}

provider "aws" {
  alias  = "eu_central"
  region = "eu-central-1"
}

#############################################
# Variables
#############################################

variable "application_name" {
  description = "Name of the Elastic Beanstalk application"
  type        = string
  default     = "geo-routed-app"
}

variable "solution_stack_name" {
  description = "Elastic Beanstalk solution stack"
  type        = string
  default     = "64bit Amazon Linux 2023 v4.1.1 running Docker"
}

variable "domain_name" {
  description = "Route53 hosted zone domain name (must already exist)"
  type        = string
  default     = "example.com"
}

variable "app_subdomain" {
  description = "Subdomain used for the geolocation-routed record"
  type        = string
  default     = "app"
}

variable "instance_type" {
  description = "EC2 instance type for the Beanstalk environments"
  type        = string
  default     = "t3.small"
}

#############################################
# Data sources
#############################################

data "aws_route53_zone" "primary" {
  provider     = aws.us_west
  name         = var.domain_name
  private_zone = false
}

#############################################
# IAM: Instance profile & service role (shared, global)
#############################################

data "aws_iam_policy_document" "ec2_assume" {
  statement {
    actions = ["sts:AssumeRole"]
    effect  = "Allow"
    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "eb_instance_role" {
  provider           = aws.us_west
  name               = "${var.application_name}-eb-instance-role"
  assume_role_policy = data.aws_iam_policy_document.ec2_assume.json
}

resource "aws_iam_role_policy_attachment" "eb_web_tier" {
  provider   = aws.us_west
  role       = aws_iam_role.eb_instance_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkWebTier"
}

resource "aws_iam_role_policy_attachment" "eb_docker" {
  provider   = aws.us_west
  role       = aws_iam_role.eb_instance_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkMulticontainerDocker"
}

resource "aws_iam_instance_profile" "eb_instance_profile" {
  provider = aws.us_west
  name     = "${var.application_name}-eb-instance-profile"
  role     = aws_iam_role.eb_instance_role.name
}

data "aws_iam_policy_document" "eb_service_assume" {
  statement {
    actions = ["sts:AssumeRole"]
    effect  = "Allow"
    principals {
      type        = "Service"
      identifiers = ["elasticbeanstalk.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "eb_service_role" {
  provider           = aws.us_west
  name               = "${var.application_name}-eb-service-role"
  assume_role_policy = data.aws_iam_policy_document.eb_service_assume.json
}

resource "aws_iam_role_policy_attachment" "eb_service" {
  provider   = aws.us_west
  role       = aws_iam_role.eb_service_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSElasticBeanstalkEnhancedHealth"
}

resource "aws_iam_role_policy_attachment" "eb_service_managed" {
  provider   = aws.us_west
  role       = aws_iam_role.eb_service_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkManagedUpdatesCustomerRolePolicy"
}

#############################################
# US West resources
#############################################

resource "aws_elastic_beanstalk_application" "us_west" {
  provider    = aws.us_west
  name        = "${var.application_name}-us-west"
  description = "Elastic Beanstalk application (us-west-2)"
}

resource "aws_elastic_beanstalk_environment" "us_west" {
  provider            = aws.us_west
  name                = "us-west"
  application         = aws_elastic_beanstalk_application.us_west.name
  solution_stack_name = var.solution_stack_name
  tier                = "WebServer"

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "IamInstanceProfile"
    value     = aws_iam_instance_profile.eb_instance_profile.name
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "ServiceRole"
    value     = aws_iam_role.eb_service_role.arn
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "InstanceType"
    value     = var.instance_type
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "LoadBalancerType"
    value     = "application"
  }

  # Enforce HTTPS-capable ALB and enhanced health
  setting {
    namespace = "aws:elasticbeanstalk:healthreporting:system"
    name      = "SystemType"
    value     = "enhanced"
  }

  # Managed platform updates
  setting {
    namespace = "aws:elasticbeanstalk:managedactions"
    name      = "ManagedActionsEnabled"
    value     = "true"
  }

  setting {
    namespace = "aws:elasticbeanstalk:managedactions"
    name      = "PreferredStartTime"
    value     = "Sun:10:00"
  }

  setting {
    namespace = "aws:elasticbeanstalk:managedactions:platformupdate"
    name      = "UpdateLevel"
    value     = "minor"
  }

  # Require IMDSv2 for instance metadata security
  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "DisableIMDSv1"
    value     = "true"
  }
}

#############################################
# EU Central resources
#############################################

resource "aws_elastic_beanstalk_application" "eu_central" {
  provider    = aws.eu_central
  name        = "${var.application_name}-eu-central"
  description = "Elastic Beanstalk application (eu-central-1)"
}

resource "aws_elastic_beanstalk_environment" "eu_central" {
  provider            = aws.eu_central
  name                = "eu-central"
  application         = aws_elastic_beanstalk_application.eu_central.name
  solution_stack_name = var.solution_stack_name
  tier                = "WebServer"

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "IamInstanceProfile"
    value     = aws_iam_instance_profile.eb_instance_profile.name
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "ServiceRole"
    value     = aws_iam_role.eb_service_role.arn
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "InstanceType"
    value     = var.instance_type
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "LoadBalancerType"
    value     = "application"
  }

  setting {
    namespace = "aws:elasticbeanstalk:healthreporting:system"
    name      = "SystemType"
    value     = "enhanced"
  }

  setting {
    namespace = "aws:elasticbeanstalk:managedactions"
    name      = "ManagedActionsEnabled"
    value     = "true"
  }

  setting {
    namespace = "aws:elasticbeanstalk:managedactions"
    name      = "PreferredStartTime"
    value     = "Sun:10:00"
  }

  setting {
    namespace = "aws:elasticbeanstalk:managedactions:platformupdate"
    name      = "UpdateLevel"
    value     = "minor"
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "DisableIMDSv1"
    value     = "true"
  }
}

#############################################
# Route53 Geolocation Routing
#############################################

# Health checks so Route53 can fail away from an unhealthy region
resource "aws_route53_health_check" "us_west" {
  provider          = aws.us_west
  fqdn              = aws_elastic_beanstalk_environment.us_west.cname
  port              = 80
  type              = "HTTP"
  resource_path     = "/"
  failure_threshold = 3
  request_interval  = 30

  tags = {
    Name = "us-west-health-check"
  }
}

resource "aws_route53_health_check" "eu_central" {
  provider          = aws.us_west
  fqdn              = aws_elastic_beanstalk_environment.eu_central.cname
  port              = 80
  type              = "HTTP"
  resource_path     = "/"
  failure_threshold = 3
  request_interval  = 30

  tags = {
    Name = "eu-central-health-check"
  }
}

# Default record (fallback for locations not explicitly matched)
resource "aws_route53_record" "default" {
  provider        = aws.us_west
  zone_id         = data.aws_route53_zone.primary.zone_id
  name            = "${var.app_subdomain}.${var.domain_name}"
  type            = "CNAME"
  ttl             = 60
  set_identifier  = "default"
  health_check_id = aws_route53_health_check.us_west.id

  geolocation_routing_policy {
    country = "*"
  }

  records = [aws_elastic_beanstalk_environment.us_west.cname]
}

# North America -> us-west
resource "aws_route53_record" "us_west_geo" {
  provider        = aws.us_west
  zone_id         = data.aws_route53_zone.primary.zone_id
  name            = "${var.app_subdomain}.${var.domain_name}"
  type            = "CNAME"
  ttl             = 60
  set_identifier  = "us-west-na"
  health_check_id = aws_route53_health_check.us_west.id

  geolocation_routing_policy {
    continent = "NA"
  }

  records = [aws_elastic_beanstalk_environment.us_west.cname]
}

# Europe -> eu-central
resource "aws_route53_record" "eu_central_geo" {
  provider        = aws.us_west
  zone_id         = data.aws_route53_zone.primary.zone_id
  name            = "${var.app_subdomain}.${var.domain_name}"
  type            = "CNAME"
  ttl             = 60
  set_identifier  = "eu-central-eu"
  health_check_id = aws_route53_health_check.eu_central.id

  geolocation_routing_policy {
    continent = "EU"
  }

  records = [aws_elastic_beanstalk_environment.eu_central.cname]
}

#############################################
# Outputs
#############################################

output "us_west_environment_cname" {
  description = "CNAME of the us-west Elastic Beanstalk environment"
  value       = aws_elastic_beanstalk_environment.us_west.cname
}

output "eu_central_environment_cname" {
  description = "CNAME of the eu-central Elastic Beanstalk environment"
  value       = aws_elastic_beanstalk_environment.eu_central.cname
}

output "geolocation_dns_name" {
  description = "Geolocation-routed DNS name"
  value       = "${var.app_subdomain}.${var.domain_name}"
}

