model_answers:
terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region to deploy resources"
  type        = string
  default     = "us-east-1"
}

variable "db_name" {
  description = "Name of the initial database"
  type        = string
  default     = "appdb"
}

variable "db_username" {
  description = "Master username for the MySQL instance"
  type        = string
  default     = "admin"
}

variable "allowed_cidr_blocks" {
  description = "CIDR blocks allowed to access the database (private ranges recommended)"
  type        = list(string)
  default     = ["10.0.0.0/16"]
}

variable "vpc_id" {
  description = "VPC ID where the DB subnet group and security group live"
  type        = string
}

variable "subnet_ids" {
  description = "List of private subnet IDs for the DB subnet group"
  type        = list(string)
}

# ------------------------------------------------------------------
# Generate a strong random master password (avoid hardcoding secrets)
# ------------------------------------------------------------------
resource "random_password" "db_master" {
  length           = 24
  special          = true
  override_special = "!#$%&*()-_=+[]{}<>:?"
}

# ------------------------------------------------------------------
# Store the master credentials securely in Secrets Manager
# ------------------------------------------------------------------
resource "aws_secretsmanager_secret" "db_master" {
  name        = "mysql/master-credentials"
  description = "Master credentials for the MySQL RDS instance"
}

resource "aws_secretsmanager_secret_version" "db_master" {
  secret_id = aws_secretsmanager_secret.db_master.id
  secret_string = jsonencode({
    username = var.db_username
    password = random_password.db_master.result
  })
}

# ------------------------------------------------------------------
# KMS key for RDS storage encryption
# ------------------------------------------------------------------
resource "aws_kms_key" "rds" {
  description             = "KMS key for RDS MySQL encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true
}

resource "aws_kms_alias" "rds" {
  name          = "alias/rds-mysql"
  target_key_id = aws_kms_key.rds.key_id
}

# ------------------------------------------------------------------
# Networking: subnet group and security group
# ------------------------------------------------------------------
resource "aws_db_subnet_group" "mysql" {
  name       = "mysql-subnet-group"
  subnet_ids = var.subnet_ids

  tags = {
    Name = "mysql-subnet-group"
  }
}

resource "aws_security_group" "mysql" {
  name        = "mysql-sg"
  description = "Security group for MySQL RDS instance"
  vpc_id      = var.vpc_id

  ingress {
    description = "MySQL access from allowed CIDR blocks"
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = var.allowed_cidr_blocks
  }

  egress {
    description = "Allow all outbound"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "mysql-sg"
  }
}

# ------------------------------------------------------------------
# IAM role for enhanced monitoring
# ------------------------------------------------------------------
data "aws_iam_policy_document" "rds_monitoring_assume" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["monitoring.rds.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "rds_monitoring" {
  name               = "rds-enhanced-monitoring-role"
  assume_role_policy = data.aws_iam_policy_document.rds_monitoring_assume.json
}

resource "aws_iam_role_policy_attachment" "rds_monitoring" {
  role       = aws_iam_role.rds_monitoring.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonRDSEnhancedMonitoringRole"
}

# ------------------------------------------------------------------
# MySQL RDS instance
# ------------------------------------------------------------------
resource "aws_db_instance" "mysql" {
  identifier     = "mysql-instance"
  engine         = "mysql"
  engine_version = "8.0"
  instance_class = "db.t3.micro"

  allocated_storage     = 20
  max_allocated_storage = 100
  storage_type          = "gp3"

  db_name  = var.db_name
  username = var.db_username
  password = random_password.db_master.result

  db_subnet_group_name   = aws_db_subnet_group.mysql.name
  vpc_security_group_ids = [aws_security_group.mysql.id]

  # Security best practices
  storage_encrypted               = true
  kms_key_id                      = aws_kms_key.rds.arn
  publicly_accessible             = false
  iam_database_authentication_enabled = true
  deletion_protection             = true
  copy_tags_to_snapshot           = true
  auto_minor_version_upgrade      = true

  # Backups and maintenance
  backup_retention_period = 7
  backup_window           = "03:00-04:00"
  maintenance_window      = "Mon:04:00-Mon:05:00"

  # Monitoring
  monitoring_interval             = 60
  monitoring_role_arn             = aws_iam_role.rds_monitoring.arn
  performance_insights_enabled    = true
  performance_insights_kms_key_id = aws_kms_key.rds.arn
  enabled_cloudwatch_logs_exports = ["error", "general", "slowquery"]

  # Ensure a final snapshot is taken on deletion
  skip_final_snapshot       = false
  final_snapshot_identifier = "mysql-instance-final-snapshot"

  tags = {
    Name = "mysql-instance"
  }
}

# ------------------------------------------------------------------
# Manual snapshot of the MySQL instance
# ------------------------------------------------------------------
resource "aws_db_snapshot" "mysql" {
  db_instance_identifier = aws_db_instance.mysql.identifier
  db_snapshot_identifier = "mysql-instance-snapshot"

  tags = {
    Name = "mysql-instance-snapshot"
  }
}

# ------------------------------------------------------------------
# Outputs
# ------------------------------------------------------------------
output "db_endpoint" {
  description = "The connection endpoint of the MySQL instance"
  value       = aws_db_instance.mysql.endpoint
}

output "db_secret_arn" {
  description = "ARN of the Secrets Manager secret storing DB credentials"
  value       = aws_secretsmanager_secret.db_master.arn
}

output "db_snapshot_id" {
  description = "Identifier of the created DB snapshot"
  value       = aws_db_snapshot.mysql.db_snapshot_identifier
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

##############################
# Variables
##############################
variable "aws_region" {
  description = "AWS region to deploy resources"
  type        = string
  default     = "us-east-1"
}

variable "vpc_id" {
  description = "VPC ID where the RDS instance will be deployed"
  type        = string
}

variable "db_subnet_ids" {
  description = "List of private subnet IDs for the DB subnet group (min 2 in different AZs)"
  type        = list(string)
}

variable "allowed_cidr_blocks" {
  description = "CIDR blocks allowed to access the database (should be private/internal ranges)"
  type        = list(string)
  default     = []
}

variable "allowed_security_group_ids" {
  description = "Security group IDs allowed to access the database"
  type        = list(string)
  default     = []
}

variable "db_name" {
  description = "Name of the initial database"
  type        = string
  default     = "appdb"
}

variable "db_username" {
  description = "Master username for the database"
  type        = string
  default     = "dbadmin"
}

variable "environment" {
  description = "Environment name"
  type        = string
  default     = "production"
}

##############################
# Master Password (managed via Secrets Manager)
##############################
resource "random_password" "master" {
  length           = 32
  special          = true
  override_special = "!#$%^&*()-_=+[]{}<>:?"
}

resource "aws_secretsmanager_secret" "db_credentials" {
  name        = "${var.environment}-postgres-master-credentials"
  description = "Master credentials for the PostgreSQL RDS instance"

  # Rotate KMS key encryption for the secret
  kms_key_id = aws_kms_key.rds.arn
}

resource "aws_secretsmanager_secret_version" "db_credentials" {
  secret_id = aws_secretsmanager_secret.db_credentials.id
  secret_string = jsonencode({
    username = var.db_username
    password = random_password.master.result
    engine   = "postgres"
    dbname   = var.db_name
  })
}

##############################
# KMS Key for encryption
##############################
resource "aws_kms_key" "rds" {
  description             = "KMS key for RDS PostgreSQL encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = {
    Name        = "${var.environment}-rds-kms"
    Environment = var.environment
  }
}

resource "aws_kms_alias" "rds" {
  name          = "alias/${var.environment}-rds-postgres"
  target_key_id = aws_kms_key.rds.key_id
}

##############################
# Security Group
##############################
resource "aws_security_group" "rds" {
  name_prefix = "${var.environment}-postgres-sg-"
  description = "Security group for PostgreSQL RDS instance"
  vpc_id      = var.vpc_id

  tags = {
    Name        = "${var.environment}-postgres-sg"
    Environment = var.environment
  }

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_security_group_rule" "ingress_cidr" {
  count             = length(var.allowed_cidr_blocks) > 0 ? 1 : 0
  type              = "ingress"
  from_port         = 5432
  to_port           = 5432
  protocol          = "tcp"
  cidr_blocks       = var.allowed_cidr_blocks
  security_group_id = aws_security_group.rds.id
  description       = "Allow PostgreSQL access from approved CIDR blocks"
}

resource "aws_security_group_rule" "ingress_sg" {
  count                    = length(var.allowed_security_group_ids)
  type                     = "ingress"
  from_port                = 5432
  to_port                  = 5432
  protocol                 = "tcp"
  source_security_group_id = var.allowed_security_group_ids[count.index]
  security_group_id        = aws_security_group.rds.id
  description              = "Allow PostgreSQL access from approved security group"
}

##############################
# DB Subnet Group
##############################
resource "aws_db_subnet_group" "this" {
  name       = "${var.environment}-postgres-subnet-group"
  subnet_ids = var.db_subnet_ids

  tags = {
    Name        = "${var.environment}-postgres-subnet-group"
    Environment = var.environment
  }
}

##############################
# DB Parameter Group (enforce SSL)
##############################
resource "aws_db_parameter_group" "this" {
  name_prefix = "${var.environment}-postgres-"
  family      = "postgres16"

  parameter {
    name  = "rds.force_ssl"
    value = "1"
  }

  parameter {
    name  = "log_connections"
    value = "1"
  }

  parameter {
    name  = "log_disconnections"
    value = "1"
  }

  lifecycle {
    create_before_destroy = true
  }
}

##############################
# IAM Role for Enhanced Monitoring
##############################
data "aws_iam_policy_document" "monitoring_assume" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["monitoring.rds.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "rds_monitoring" {
  name               = "${var.environment}-rds-monitoring-role"
  assume_role_policy = data.aws_iam_policy_document.monitoring_assume.json
}

resource "aws_iam_role_policy_attachment" "rds_monitoring" {
  role       = aws_iam_role.rds_monitoring.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonRDSEnhancedMonitoringRole"
}

##############################
# RDS PostgreSQL Instance
##############################
resource "aws_db_instance" "postgres" {
  identifier     = "${var.environment}-postgres"
  engine         = "postgres"
  engine_version = "16.4"
  instance_class = "db.t4g.large"

  allocated_storage     = 50
  max_allocated_storage = 200
  storage_type          = "gp3"
  storage_encrypted     = true
  kms_key_id            = aws_kms_key.rds.arn

  db_name  = var.db_name
  username = var.db_username
  password = random_password.master.result
  port     = 5432

  # Networking - not publicly accessible
  db_subnet_group_name   = aws_db_subnet_group.this.name
  vpc_security_group_ids = [aws_security_group.rds.id]
  publicly_accessible    = false

  # High availability
  multi_az = true

  # Parameter group enforcing SSL
  parameter_group_name = aws_db_parameter_group.this.name

  # Backups
  backup_retention_period   = 30
  backup_window             = "03:00-04:00"
  maintenance_window        = "mon:04:00-mon:05:00"
  copy_tags_to_snapshot     = true
  delete_automated_backups  = false
  final_snapshot_identifier = "${var.environment}-postgres-final-snapshot"
  skip_final_snapshot       = false

  # Monitoring & logging
  monitoring_interval             = 60
  monitoring_role_arn             = aws_iam_role.rds_monitoring.arn
  performance_insights_enabled    = true
  performance_insights_kms_key_id = aws_kms_key.rds.arn
  performance_insights_retention_period = 7
  enabled_cloudwatch_logs_exports = ["postgresql", "upgrade"]

  # Security & maintenance
  auto_minor_version_upgrade  = true
  deletion_protection         = true
  iam_database_authentication_enabled = true
  apply_immediately           = false

  tags = {
    Name        = "${var.environment}-postgres"
    Environment = var.environment
  }
}

##############################
# Outputs
##############################
output "db_endpoint" {
  description = "The RDS instance connection endpoint"
  value       = aws_db_instance.postgres.endpoint
}

output "db_address" {
  description = "The RDS instance hostname"
  value       = aws_db_instance.postgres.address
}

output "db_port" {
  description = "The RDS instance port"
  value       = aws_db_instance.postgres.port
}

output "db_secret_arn" {
  description = "ARN of the Secrets Manager secret holding DB credentials"
  value       = aws_secretsmanager_secret.db_credentials.arn
}

output "db_security_group_id" {
  description = "Security group ID attached to the RDS instance"
  value       = aws_security_group.rds.id
}

