  length           = 20
  special          = true
  override_special = "!#$%^&*()-_=+[]{}<>:?"
}

# Store the generated password in AWS Secrets Manager (best practice).
resource "aws_secretsmanager_secret" "db_master" {
  name        = "primary-db-master-password"
  description = "Master password for the primary RDS instance"
}

resource "aws_secretsmanager_secret_version" "db_master" {
  secret_id = aws_secretsmanager_secret.db_master.id
  secret_string = jsonencode({
    username = var.db_username
    password = random_password.db_master.result
  })
}

# KMS key for encrypting RDS storage at rest.
resource "aws_kms_key" "rds" {
  description             = "KMS key for RDS encryption"
  deletion_window_in_days = 10
  enable_key_rotation     = true
}

resource "aws_kms_alias" "rds" {
  name          = "alias/rds-primary-replicas"
  target_key_id = aws_kms_key.rds.key_id
}

# ---------------------------------------------------------------------------
# Primary database instance
# ---------------------------------------------------------------------------
resource "aws_db_instance" "primary" {
  identifier     = "primary"
  engine         = var.db_engine
  engine_version = var.db_engine_version
  instance_class = var.db_instance_class

  allocated_storage     = 20
  max_allocated_storage = 100
  storage_type          = "gp3"
  storage_encrypted     = true
  kms_key_id            = aws_kms_key.rds.arn

  username = var.db_username
  password = random_password.db_master.result

  db_subnet_group_name   = var.db_subnet_group_name
  vpc_security_group_ids = var.db_security_group_ids
  publicly_accessible    = false
  multi_az               = true

  # Required so that read replicas can be created from this instance.
  backup_retention_period = 7

  # Security best practices
  iam_database_authentication_enabled = true
  deletion_protection                 = true
  copy_tags_to_snapshot               = true
  auto_minor_version_upgrade          = true

  performance_insights_enabled          = true
  performance_insights_kms_key_id       = aws_kms_key.rds.arn
  enabled_cloudwatch_logs_exports       = ["error", "general", "slowquery"]

  skip_final_snapshot       = false
  final_snapshot_identifier = "primary-final-snapshot"

  tags = {
    Name = "primary"
    Role = "primary"
  }
}

# ---------------------------------------------------------------------------
# Read replica 1
# ---------------------------------------------------------------------------
resource "aws_db_instance" "replica_1" {
  identifier          = "replica-1"
  replicate_source_db = aws_db_instance.primary.identifier
  instance_class      = var.db_instance_class

  storage_encrypted = true
  kms_key_id        = aws_kms_key.rds.arn

  vpc_security_group_ids = var.db_security_group_ids
  publicly_accessible    = false

  iam_database_authentication_enabled = true
  auto_minor_version_upgrade          = true
  copy_tags_to_snapshot               = true

  performance_insights_enabled    = true
  performance_insights_kms_key_id = aws_kms_key.rds.arn

  skip_final_snapshot = true

  tags = {
    Name = "replica-1"
    Role = "replica"
  }
}

# ---------------------------------------------------------------------------
# Read replica 2
# ---------------------------------------------------------------------------
resource "aws_db_instance" "replica_2" {
  identifier          = "replica-2"
  replicate_source_db = aws_db_instance.primary.identifier
  instance_class      = var.db_instance_class

  storage_encrypted = true
  kms_key_id        = aws_kms_key.rds.arn

  vpc_security_group_ids = var.db_security_group_ids
  publicly_accessible    = false

  iam_database_authentication_enabled = true
  auto_minor_version_upgrade          = true
  copy_tags_to_snapshot               = true

  performance_insights_enabled    = true
  performance_insights_kms_key_id = aws_kms_key.rds.arn

  skip_final_snapshot = true

  tags = {
    Name = "replica-2"
    Role = "replica"
  }
}

# ---------------------------------------------------------------------------
# Route 53 private hosted zone "main"
# ---------------------------------------------------------------------------
resource "aws_route53_zone" "main" {
  name    = var.domain_name
  comment = "Private hosted zone for DB read replica weighted routing"

  vpc {
    vpc_id = var.vpc_id
  }

  tags = {
    Name = "main"
  }
}

# ---------------------------------------------------------------------------
# Weighted routing records splitting traffic between the two replicas.
# Each record points to the replica endpoint via a CNAME; equal weights
# split users 50/50 between replica-1 and replica-2.
# ---------------------------------------------------------------------------
resource "aws_route53_record" "replica_1" {
  zone_id = aws_route53_zone.main.zone_id
  name    = "db.${var.domain_name}"
  type    = "CNAME"
  ttl     = 60

  set_identifier = "replica-1"

  weighted_routing_policy {
    weight = 50
  }

  records = [aws_db_instance.replica_1.address]
}

resource "aws_route53_record" "replica_2" {
  zone_id = aws_route53_zone.main.zone_id
  name    = "db.${var.domain_name}"
  type    = "CNAME"
  ttl     = 60

  set_identifier = "replica-2"

  weighted_routing_policy {
    weight = 50
  }

  records = [aws_db_instance.replica_2.address]
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------
output "primary_endpoint" {
  description = "Endpoint of the primary DB instance"
  value       = aws_db_instance.primary.endpoint
}

output "replica_1_endpoint" {
  description = "Endpoint of replica-1"
  value       = aws_db_instance.replica_1.endpoint
}

output "replica_2_endpoint" {
  description = "Endpoint of replica-2"
  value       = aws_db_instance.replica_2.endpoint
}

output "weighted_dns_name" {
  description = "Weighted routing DNS name for the read replicas"
  value       = "db.${var.domain_name}"
}

