resource "aws_lex_intent" "book_trip" {
  name        = "BookTrip"
  description = "Intent to book a trip"

  fulfillment_activity {
    type = "ReturnIntent"
  }

  sample_utterances = [
    "I want to book a trip",
    "Book a trip for me",
    "I would like to book a trip to {Destination}",
    "Book me a trip",
  ]

  slot {
    name            = "Destination"
    description     = "The destination city for the trip"
    slot_constraint = "Required"
    slot_type       = "AMAZON.City"

    value_elicitation_prompt {
      max_attempts = 2

      message {
        content      = "What city would you like to travel to?"
        content_type = "PlainText"
      }
    }

    priority = 1
  }

  slot {
    name            = "OriginCity"
    description     = "The origin city for the trip"
    slot_constraint = "Required"
    slot_type       = "AMAZON.City"

    value_elicitation_prompt {
      max_attempts = 2

      message {
        content      = "Which city are you departing from?"
        content_type = "PlainText"
      }
    }

    priority = 2
  }

  slot {
    name            = "TravelDate"
    description     = "The date of travel"
    slot_constraint = "Required"
    slot_type       = "AMAZON.DATE"

    value_elicitation_prompt {
      max_attempts = 2

      message {
        content      = "What date would you like to travel?"
        content_type = "PlainText"
      }
    }

    priority = 3
  }

  slot {
    name            = "NumberOfTravelers"
    description     = "The number of travelers"
    slot_constraint = "Optional"
    slot_type       = "AMAZON.NUMBER"

    value_elicitation_prompt {
      max_attempts = 2

      message {
        content      = "How many people are traveling?"
        content_type = "PlainText"
      }
    }

    priority = 4
  }

  confirmation_prompt {
    max_attempts = 2

    message {
      content      = "You want to book a trip from {OriginCity} to {Destination} on {TravelDate} for {NumberOfTravelers} travelers. Is that correct?"
      content_type = "PlainText"
    }
  }

  rejection_statement {
    message {
      content      = "Okay, I will not book the trip."
      content_type = "PlainText"
    }
  }
}

resource "aws_lex_bot" "book_trip_bot" {
  name             = "BookTripBot"
  description      = "Bot for booking a trip"
  child_directed   = false
  create_version   = false
  idle_session_ttl_in_seconds = 600
  process_behavior = "BUILD"
  locale           = "en-US"

  # Enforce logging/compliance where applicable
  detect_sentiment                = false
  enable_model_improvements       = true
  nlu_intent_confidence_threshold = 0.4

  abort_statement {
    message {
      content      = "Sorry, I could not understand your request. Please try again later."
      content_type = "PlainText"
    }
  }

