    max_attempts = 2

    message {
      content      = "I did not understand you. Can you please repeat that?"
      content_type = "PlainText"
    }
  }

  intent {
    intent_name    = aws_lex_intent.book_trip.name
    intent_version = aws_lex_intent.book_trip.version
  }

  voice_id = "Salli"
}

