provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region for the primary database"
  type        = string
  default     = "us-east-1"
}

variable "db_name" {
  description = "The name of the database"
  type        = string
  default     = "appdb"
}

variable "db_username" {
  description = "Master username for the database"
  type        = string
  default     = "dbadmin"
}

variable "allowed_cidr_blocks" {
  description = "CIDR blocks allowed to access the database"
  type        = list(string)
  default     = ["10.0.0.0/16"]
}

variable "vpc_id" {
  description = "VPC ID where the DB will be deployed"
  type        = string
}

variable "subnet_ids" {
  description = "List of subnet IDs for the DB subnet group"
  type        = list(string)
}

# -----------------------------------------------------------------------------
# Random password for master user (stored in Secrets Manager)
# -----------------------------------------------------------------------------
resource "random_password" "db_master" {
  length           = 24
  special          = true
  override_special = "!#$%&*()-_=+[]{}<>:?"
}

resource "aws_secretsmanager_secret" "db_master" {
  name                    = "${var.db_name}-master-credentials"
  description             = "Master credentials for ${var.db_name} RDS instance"
  recovery_window_in_days = 7
  kms_key_id              = aws_kms_key.db.arn
}

resource "aws_secretsmanager_secret_version" "db_master" {
  secret_id = aws_secretsmanager_secret.db_master.id
  secret_string = jsonencode({
    username = var.db_username
    password = random_password.db_master.result
  })
}

# -----------------------------------------------------------------------------
# KMS key for encryption at rest
# -----------------------------------------------------------------------------
resource "aws_kms_key" "db" {
  description             = "KMS key for ${var.db_name} RDS encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true
}

resource "aws_kms_alias" "db" {
  name          = "alias/${var.db_name}-rds"
  target_key_id = aws_kms_key.db.key_id
}

# -----------------------------------------------------------------------------
# Networking: subnet group and security group
# -----------------------------------------------------------------------------
resource "aws_db_subnet_group" "this" {
  name       = "${var.db_name}-subnet-group"
  subnet_ids = var.subnet_ids

  tags = {
    Name = "${var.db_name}-subnet-group"
  }
}

resource "aws_security_group" "db" {
  name        = "${var.db_name}-sg"
  description = "Security group for ${var.db_name} RDS instance"
  vpc_id      = var.vpc_id

  ingress {
    description = "Allow SQL Server access from allowed CIDRs"
    from_port   = 1433
    to_port     = 1433
    protocol    = "tcp"
    cidr_blocks = var.allowed_cidr_blocks
  }

  egress {
    description = "Allow all outbound"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "${var.db_name}-sg"
  }
}

# -----------------------------------------------------------------------------
# IAM role for enhanced monitoring
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "rds_monitoring_assume" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["monitoring.rds.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "rds_monitoring" {
  name               = "${var.db_name}-rds-monitoring-role"
  assume_role_policy = data.aws_iam_policy_document.rds_monitoring_assume.json
}

resource "aws_iam_role_policy_attachment" "rds_monitoring" {
  role       = aws_iam_role.rds_monitoring.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonRDSEnhancedMonitoringRole"
}

# -----------------------------------------------------------------------------
# Primary SQL Server RDS instance
# -----------------------------------------------------------------------------
resource "aws_db_instance" "primary" {
  identifier     = "${var.db_name}-primary"
  engine         = "sqlserver-se"
  engine_version = "15.00.4335.1.v1"
  instance_class = "db.m5.large"

  allocated_storage     = 50
  max_allocated_storage = 200
  storage_type          = "gp3"
  storage_encrypted     = true
  kms_key_id            = aws_kms_key.db.arn

  username = var.db_username
  password = random_password.db_master.result

  db_subnet_group_name   = aws_db_subnet_group.this.name
  vpc_security_group_ids = [aws_security_group.db.id]
  multi_az               = true
  publicly_accessible    = false

  backup_retention_period = 14
  backup_window           = "03:00-04:00"
  maintenance_window      = "sun:04:30-sun:05:30"
  copy_tags_to_snapshot   = true

  # Security & observability
  deletion_protection             = true
  iam_database_authentication_enabled = false
  performance_insights_enabled    = true
  performance_insights_kms_key_id = aws_kms_key.db.arn
  monitoring_interval             = 60
  monitoring_role_arn             = aws_iam_role.rds_monitoring.arn
  enabled_cloudwatch_logs_exports = ["error", "agent"]
  auto_minor_version_upgrade      = true

  skip_final_snapshot       = false
  final_snapshot_identifier = "${var.db_name}-primary-final"

  license_model = "license-included"

  tags = {
    Name = "${var.db_name}-primary"
    Role = "primary"
  }
}

# -----------------------------------------------------------------------------
# Read replica of the primary instance
# -----------------------------------------------------------------------------
resource "aws_db_instance" "replica" {
  identifier          = "${var.db_name}-replica"
  replicate_source_db = aws_db_instance.primary.identifier
  instance_class      = "db.m5.large"

  storage_encrypted = true
  kms_key_id        = aws_kms_key.db.arn

  vpc_security_group_ids = [aws_security_group.db.id]
  publicly_accessible    = false

  performance_insights_enabled    = true
  performance_insights_kms_key_id = aws_kms_key.db.arn
  monitoring_interval             = 60
  monitoring_role_arn             = aws_iam_role.rds_monitoring.arn
  auto_minor_version_upgrade      = true

  skip_final_snapshot = true

  tags = {
    Name = "${var.db_name}-replica"
    Role = "replica"
  }
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "primary_endpoint" {
  description = "Endpoint of the primary RDS instance"
  value       = aws_db_instance.primary.endpoint
}

output "replica_endpoint" {
  description = "Endpoint of the read replica RDS instance"
  value       = aws_db_instance.replica.endpoint
}

output "secrets_manager_secret_arn" {
  description = "ARN of the Secrets Manager secret holding master credentials"
  value       = aws_secretsmanager_secret.db_master.arn
}

