    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region to deploy resources"
  type        = string
  default     = "us-east-1"
}

variable "db_name" {
  description = "Name of the Lightsail managed database"
  type        = string
  default     = "app-managed-db"
}

variable "master_username" {
  description = "Master username for the database"
  type        = string
  default     = "dbadmin"
}

variable "availability_zone" {
  description = "Availability zone for the database"
  type        = string
  default     = "us-east-1a"
}

variable "bundle_id" {
  description = "Lightsail database bundle (size/performance tier)"
  type        = string
  default     = "micro_2_0"
}

variable "blueprint_id" {
  description = "Lightsail database blueprint (engine + version)"
  type        = string
  default     = "postgres_15"
}

variable "allowed_source_networks" {
  description = "CIDR blocks allowed to access the database publicly (only used if public access is enabled)"
  type        = list(string)
  default     = []
}

# Generate a strong random master password
resource "random_password" "master" {
  length           = 24
  special          = true
  override_special = "!#$%&*()-_=+[]{}<>:?"
  min_lower        = 2
  min_upper        = 2
  min_numeric      = 2
  min_special      = 2
}

resource "aws_lightsail_database" "this" {
  relational_database_name = var.db_name
  availability_zone        = var.availability_zone
  master_database_name     = "appdb"
  master_username          = var.master_username
  master_password          = random_password.master.result

  blueprint_id = var.blueprint_id
  bundle_id    = var.bundle_id

  # Security best practices:
  # Keep the database private (no public access from the internet)
  publicly_accessible = false

  # Backups & maintenance
  preferred_backup_window      = "02:00-03:00"
  preferred_maintenance_window = "sun:04:00-sun:05:00"
  backup_retention_enabled     = true

  # Do not skip final snapshot for production safety
  skip_final_snapshot       = false
  final_snapshot_name       = "${var.db_name}-final-snapshot"

  # Apply changes only during maintenance window to avoid unexpected downtime
  apply_immediately = false

  tags = {
    Name        = var.db_name
    Environment = "production"
    ManagedBy   = "terraform"
  }
}

# Store the generated master password securely in AWS Secrets Manager
resource "aws_secretsmanager_secret" "db_master_password" {
  name        = "${var.db_name}-master-password"
  description = "Master password for Lightsail managed database ${var.db_name}"

  recovery_window_in_days = 7
}

resource "aws_secretsmanager_secret_version" "db_master_password" {
  secret_id = aws_secretsmanager_secret.db_master_password.id
  secret_string = jsonencode({
    username = var.master_username
    password = random_password.master.result
    engine   = var.blueprint_id
    host     = aws_lightsail_database.this.master_endpoint_address
    port     = aws_lightsail_database.this.master_endpoint_port
    dbname   = aws_lightsail_database.this.master_database_name
  })
}

output "database_name" {
  description = "The name of the Lightsail managed database"
  value       = aws_lightsail_database.this.relational_database_name
}

output "database_endpoint" {
  description = "The database connection endpoint"
  value       = aws_lightsail_database.this.master_endpoint_address
}

output "database_port" {
  description = "The database connection port"
  value       = aws_lightsail_database.this.master_endpoint_port
}

output "secret_arn" {
  description = "ARN of the Secrets Manager secret holding DB credentials"
  value       = aws_secretsmanager_secret.db_master_password.arn
}

output "master_password" {
  description = "Master password (sensitive)"
  value       = random_password.master.result
  sensitive   = true
}

