model_answers:
terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# -----------------------------------------------------------------------------
# Variables
# -----------------------------------------------------------------------------
variable "aws_region" {
  description = "AWS region to deploy resources"
  type        = string
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "db_subnet_cidrs" {
  description = "CIDR blocks for the private DB subnets"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24", "10.0.3.0/24"]
}

variable "db_name" {
  description = "Name of the initial database"
  type        = string
  default     = "appdb"
}

variable "db_username" {
  description = "Master username for the Aurora cluster"
  type        = string
  default     = "admin"
}

variable "engine_version" {
  description = "Aurora MySQL engine version"
  type        = string
  default     = "8.0.mysql_aurora.3.05.2"
}

variable "instance_class" {
  description = "Instance class for Aurora instances"
  type        = string
  default     = "db.r6g.large"
}

variable "instance_count" {
  description = "Number of Aurora instances in the cluster"
  type        = number
  default     = 2
}

variable "tags" {
  description = "Common tags applied to all resources"
  type        = map(string)
  default = {
    Project     = "aurora-proxy"
    Environment = "prod"
    ManagedBy   = "terraform"
  }
}

# -----------------------------------------------------------------------------
# Data sources
# -----------------------------------------------------------------------------
data "aws_availability_zones" "available" {
  state = "available"
}

# -----------------------------------------------------------------------------
# Networking - VPC & Subnets
# -----------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(var.tags, {
    Name = "aurora-vpc"
  })
}

resource "aws_subnet" "db" {
  count             = length(var.db_subnet_cidrs)
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.db_subnet_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]

  # Private subnets - no public IPs
  map_public_ip_on_launch = false

  tags = merge(var.tags, {
    Name = "aurora-db-subnet-${count.index + 1}"
  })
}

resource "aws_db_subnet_group" "aurora" {
  name       = "aurora-subnet-group"
  subnet_ids = aws_subnet.db[*].id

  tags = merge(var.tags, {
    Name = "aurora-subnet-group"
  })
}

# -----------------------------------------------------------------------------
# Security Groups
# -----------------------------------------------------------------------------
resource "aws_security_group" "aurora" {
  name_prefix = "aurora-cluster-"
  description = "Security group for Aurora MySQL cluster"
  vpc_id      = aws_vpc.main.id

  tags = merge(var.tags, {
    Name = "aurora-cluster-sg"
  })

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_security_group" "proxy" {
  name_prefix = "aurora-proxy-"
  description = "Security group for RDS Proxy"
  vpc_id      = aws_vpc.main.id

  tags = merge(var.tags, {
    Name = "aurora-proxy-sg"
  })

  lifecycle {
    create_before_destroy = true
  }
}

# Proxy can reach Aurora on MySQL port
resource "aws_security_group_rule" "aurora_ingress_from_proxy" {
  type                     = "ingress"
  from_port                = 3306
  to_port                  = 3306
  protocol                 = "tcp"
  security_group_id        = aws_security_group.aurora.id
  source_security_group_id = aws_security_group.proxy.id
  description              = "Allow MySQL traffic from RDS Proxy"
}

# Proxy egress to Aurora
resource "aws_security_group_rule" "proxy_egress_to_aurora" {
  type                     = "egress"
  from_port                = 3306
  to_port                  = 3306
  protocol                 = "tcp"
  security_group_id        = aws_security_group.proxy.id
  source_security_group_id = aws_security_group.aurora.id
  description              = "Allow outbound MySQL traffic to Aurora"
}

# Allow applications inside the VPC to reach the proxy
resource "aws_security_group_rule" "proxy_ingress_from_vpc" {
  type              = "ingress"
  from_port         = 3306
  to_port           = 3306
  protocol          = "tcp"
  security_group_id = aws_security_group.proxy.id
  cidr_blocks       = [var.vpc_cidr]
  description       = "Allow MySQL traffic from within the VPC to the proxy"
}

# -----------------------------------------------------------------------------
# KMS key for encryption (Secrets Manager + RDS storage)
# -----------------------------------------------------------------------------
resource "aws_kms_key" "aurora" {
  description             = "KMS key for Aurora cluster and secrets encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = merge(var.tags, {
    Name = "aurora-kms-key"
  })
}

resource "aws_kms_alias" "aurora" {
  name          = "alias/aurora-proxy-key"
  target_key_id = aws_kms_key.aurora.key_id
}

# -----------------------------------------------------------------------------
# Secrets Manager - Credential storage
# -----------------------------------------------------------------------------
resource "random_password" "db" {
  length           = 32
  special          = true
  override_special = "!#$%^&*()-_=+[]{}<>:?"
}

resource "aws_secretsmanager_secret" "db_credentials" {
  name        = "aurora/master-credentials"
  description = "Master credentials for Aurora MySQL cluster"
  kms_key_id  = aws_kms_key.aurora.arn

  recovery_window_in_days = 7

  tags = merge(var.tags, {
    Name = "aurora-master-credentials"
  })
}

resource "aws_secretsmanager_secret_version" "db_credentials" {
  secret_id = aws_secretsmanager_secret.db_credentials.id
  secret_string = jsonencode({
    username = var.db_username
    password = random_password.db.result
    engine   = "mysql"
    host     = aws_rds_cluster.aurora.endpoint
    port     = 3306
    dbname   = var.db_name
  })
}

# -----------------------------------------------------------------------------
# IAM Role for RDS Proxy
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "proxy_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["rds.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "proxy" {
  name               = "aurora-rds-proxy-role"
  assume_role_policy = data.aws_iam_policy_document.proxy_assume_role.json

  tags = merge(var.tags, {
    Name = "aurora-rds-proxy-role"
  })
}

data "aws_iam_policy_document" "proxy_secrets" {
  statement {
    sid    = "AllowGetSecretValue"
    effect = "Allow"
    actions = [
      "secretsmanager:GetSecretValue",
      "secretsmanager:DescribeSecret"
    ]
    resources = [aws_secretsmanager_secret.db_credentials.arn]
  }

  statement {
    sid    = "AllowKMSDecrypt"
    effect = "Allow"
    actions = [
      "kms:Decrypt"
    ]
    resources = [aws_kms_key.aurora.arn]

    condition {
      test     = "StringEquals"
      variable = "kms:ViaService"
      values   = ["secretsmanager.${var.aws_region}.amazonaws.com"]
    }
  }
}

resource "aws_iam_role_policy" "proxy_secrets" {
  name   = "aurora-proxy-secrets-access"
  role   = aws_iam_role.proxy.id
  policy = data.aws_iam_policy_document.proxy_secrets.json
}

# -----------------------------------------------------------------------------
# IAM Role for RDS Enhanced Monitoring
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "monitoring_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["monitoring.rds.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "monitoring" {
  name               = "aurora-rds-monitoring-role"
  assume_role_policy = data.aws_iam_policy_document.monitoring_assume_role.json

  tags = merge(var.tags, {
    Name = "aurora-rds-monitoring-role"
  })
}

resource "aws_iam_role_policy_attachment" "monitoring" {
  role       = aws_iam_role.monitoring.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonRDSEnhancedMonitoringRole"
}

# -----------------------------------------------------------------------------
# Aurora MySQL Cluster
# -----------------------------------------------------------------------------
resource "aws_rds_cluster" "aurora" {
  cluster_identifier     = "aurora-mysql-cluster"
  engine                 = "aurora-mysql"
  engine_version         = var.engine_version
  database_name          = var.db_name
  master_username        = var.db_username
  master_password        = random_password.db.result
  port                   = 3306

  db_subnet_group_name   = aws_db_subnet_group.aurora.name
  vpc_security_group_ids = [aws_security_group.aurora.id]

  # Encryption at rest
  storage_encrypted = true
  kms_key_id        = aws_kms_key.aurora.arn

  # IAM database authentication
  iam_database_authentication_enabled = true

  # Backups
  backup_retention_period      = 14
  preferred_backup_window      = "03:00-04:00"
  preferred_maintenance_window = "sun:04:30-sun:05:30"
  copy_tags_to_snapshot        = true

  # Final snapshot configuration
  skip_final_snapshot       = false
  final_snapshot_identifier = "snapshot"

  deletion_protection = true

  enabled_cloudwatch_logs_exports = ["audit", "error", "general", "slowquery"]

  tags = merge(var.tags, {
    Name = "aurora-mysql-cluster"
  })
}

resource "aws_rds_cluster_instance" "aurora" {
  count              = var.instance_count
  identifier         = "aurora-mysql-instance-${count.index + 1}"
  cluster_identifier = aws_rds_cluster.aurora.id
  instance_class     = var.instance_class
  engine             = aws_rds_cluster.aurora.engine
  engine_version     = aws_rds_cluster.aurora.engine_version

  db_subnet_group_name = aws_db_subnet_group.aurora.name

  # Not publicly accessible
  publicly_accessible = false

  # Enhanced monitoring
  monitoring_interval = 60
  monitoring_role_arn = aws_iam_role.monitoring.arn

  # Performance Insights with encryption
  performance_insights_enabled    = true
  performance_insights_kms_key_id = aws_kms_key.aurora.arn

  auto_minor_version_upgrade = true

  tags = merge(var.tags, {
    Name = "aurora-mysql-instance-${count.index + 1}"
  })
}

# -----------------------------------------------------------------------------
# RDS Proxy
# -----------------------------------------------------------------------------
resource "aws_db_proxy" "aurora" {
  name                   = "aurora-mysql-proxy"
  engine_family          = "MYSQL"
  role_arn               = aws_iam_role.proxy.arn
  vpc_subnet_ids         = aws_subnet.db[*].id
  vpc_security_group_ids = [aws_security_group.proxy.id]

  # Require TLS for connections to the proxy
  require_tls = true

  idle_client_timeout = 1800
  debug_logging       = false

  auth {
    auth_scheme = "SECRETS"
    description = "Aurora master credentials"
    iam_auth    = "REQUIRED"
    secret_arn  = aws_secretsmanager_secret.db_credentials.arn
  }

  tags = merge(var.tags, {
    Name = "aurora-mysql-proxy"
  })

  depends_on = [aws_secretsmanager_secret_version.db_credentials]
}

resource "aws_db_proxy_default_target_group" "aurora" {
  db_proxy_name = aws_db_proxy.aurora.name

  connection_pool_config {
    connection_borrow_timeout    = 120
    max_connections_percent      = 100
    max_idle_connections_percent = 50
  }
}

resource "aws_db_proxy_target" "aurora" {
  db_proxy_name         = aws_db_proxy.aurora.name
  target_group_name     = aws_db_proxy_default_target_group.aurora.name
  db_cluster_identifier = aws_rds_cluster.aurora.id
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "cluster_endpoint" {
  description = "Aurora cluster writer endpoint"
  value       = aws_rds_cluster.aurora.endpoint
}

