provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region to deploy resources"
  type        = string
  default     = "us-east-1"
}

variable "availability_zone" {
  description = "Availability zone for the Lightsail resources"
  type        = string
  default     = "us-east-1a"
}

variable "instance_name" {
  description = "Name of the Lightsail instance"
  type        = string
  default     = "app-instance"
}

variable "db_name" {
  description = "Name of the Lightsail managed database"
  type        = string
  default     = "app-mysql-db"
}

variable "db_master_username" {
  description = "Master username for the MySQL database"
  type        = string
  default     = "dbadmin"
}

variable "allowed_ssh_cidr" {
  description = "CIDR block allowed to SSH into the instance (restrict to your IP)"
  type        = string
  # Replace with your own IP/CIDR; do NOT leave open to the world in production.
  default = "10.0.0.0/8"
}

# --------------------------------------------------------------------
# Random strong password for the database master user
# --------------------------------------------------------------------
resource "random_password" "db_master_password" {
  length           = 24
  special          = true
  override_special = "!#$%&*()-_=+[]{}<>:?"
}

# --------------------------------------------------------------------
# Lightsail Instance
# --------------------------------------------------------------------
resource "aws_lightsail_instance" "app" {
  name              = var.instance_name
  availability_zone = var.availability_zone
  blueprint_id      = "ubuntu_22_04"
  bundle_id         = "nano_3_0"

  tags = {
    Environment = "production"
    ManagedBy   = "terraform"
  }
}

# --------------------------------------------------------------------
# Restrict instance networking / firewall (only allow SSH from a
# trusted CIDR, and HTTPS from anywhere for a web app).
# --------------------------------------------------------------------
resource "aws_lightsail_instance_public_ports" "app" {
  instance_name = aws_lightsail_instance.app.name

  port_info {
    protocol   = "tcp"
    from_port  = 22
    to_port    = 22
    cidrs      = [var.allowed_ssh_cidr]
  }

  port_info {
    protocol  = "tcp"
    from_port = 443
    to_port   = 443
    cidrs     = ["0.0.0.0/0"]
  }
}

# --------------------------------------------------------------------
# Lightsail Managed MySQL Database
# --------------------------------------------------------------------
resource "aws_lightsail_database" "mysql" {
  relational_database_name = var.db_name
  availability_zone        = var.availability_zone

  # MySQL blueprint and a small bundle
  blueprint_id = "mysql_8_0"
  bundle_id    = "micro_2_0"

  master_database_name = "appdb"
  master_username      = var.db_master_username
  master_password      = random_password.db_master_password.result

  # Security best practices
  publicly_accessible                   = false
  backup_retention_enabled              = true
  preferred_backup_window               = "02:00-03:00"
  preferred_maintenance_window          = "sun:04:00-sun:05:00"
  skip_final_snapshot                   = false
  final_snapshot_name                   = "${var.db_name}-final-snapshot"

  apply_immediately = false

  tags = {
    Environment = "production"
    ManagedBy   = "terraform"
  }
}

# --------------------------------------------------------------------
# Outputs
# --------------------------------------------------------------------
output "instance_public_ip" {
  description = "Public IP of the Lightsail instance"
  value       = aws_lightsail_instance.app.public_ip_address
}

output "database_endpoint" {
  description = "Endpoint address of the MySQL database"
  value       = aws_lightsail_database.mysql.master_endpoint_address
}

output "database_port" {
  description = "Port of the MySQL database"
  value       = aws_lightsail_database.mysql.master_endpoint_port
}

output "database_master_username" {
  description = "Master username for the database"
  value       = aws_lightsail_database.mysql.master_username
}

output "database_master_password" {
  description = "Master password for the database (sensitive)"
  value       = random_password.db_master_password.result
  sensitive   = true
}

