provider "aws" {
  region = "us-east-1"
}

#######################################
# Data Sources
#######################################
data "aws_availability_zones" "available" {
  state = "available"
}

#######################################
# Networking (VPC + private subnets)
#######################################
resource "aws_vpc" "msk" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "msk-vpc"
  }
}

resource "aws_subnet" "private" {
  count             = 3
  vpc_id            = aws_vpc.msk.id
  cidr_block        = cidrsubnet(aws_vpc.msk.cidr_block, 8, count.index)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "msk-private-subnet-${count.index}"
  }
}

#######################################
# Security Group (least privilege)
#######################################
resource "aws_security_group" "msk" {
  name        = "msk-cluster-sg"
  description = "Security group for MSK cluster"
  vpc_id      = aws_vpc.msk.id

  # TLS broker access restricted to the VPC CIDR
  ingress {
    description = "Kafka TLS from within VPC"
    from_port   = 9094
    to_port     = 9094
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.msk.cidr_block]
  }

  # IAM authenticated access restricted to the VPC CIDR
  ingress {
    description = "Kafka IAM auth from within VPC"
    from_port   = 9098
    to_port     = 9098
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.msk.cidr_block]
  }

  egress {
    description = "Allow all outbound"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "msk-cluster-sg"
  }
}

#######################################
# KMS key for encryption at rest
#######################################
resource "aws_kms_key" "msk" {
  description             = "KMS key for MSK cluster encryption at rest"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = {
    Name = "msk-kms-key"
  }
}

resource "aws_kms_alias" "msk" {
  name          = "alias/msk-cluster"
  target_key_id = aws_kms_key.msk.key_id
}

#######################################
# CloudWatch Logs for broker logging
#######################################
resource "aws_cloudwatch_log_group" "msk" {
  name              = "/aws/msk/cluster"
  retention_in_days = 30
  kms_key_id        = aws_kms_key.msk.arn
}

#######################################
# MSK Configuration
#######################################
resource "aws_msk_configuration" "this" {
  name           = "msk-cluster-config"
  kafka_versions = ["3.6.0"]

  server_properties = <<-PROPERTIES
    auto.create.topics.enable=false
    default.replication.factor=3
    min.insync.replicas=2
    num.partitions=3
  PROPERTIES
}

#######################################
# MSK Cluster (3 brokers)
#######################################
resource "aws_msk_cluster" "this" {
  cluster_name           = "msk-cluster"
  kafka_version          = "3.6.0"
  number_of_broker_nodes = 3

  configuration_info {
    arn      = aws_msk_configuration.this.arn
    revision = aws_msk_configuration.this.latest_revision
  }

  broker_node_group_info {
    instance_type   = "kafka.m5.large"
    client_subnets  = aws_subnet.private[*].id
    security_groups = [aws_security_group.msk.id]

    storage_info {
      ebs_storage_info {
        volume_size = 100
      }
    }
  }

  # Encryption at rest with customer managed KMS key
  # and in-transit encryption enforced
  encryption_info {
    encryption_at_rest_kms_key_arn = aws_kms_key.msk.arn

    encryption_in_transit {
      client_broker = "TLS"
      in_cluster    = true
    }
  }

  # Authentication: IAM + TLS
  client_authentication {
    sasl {
      iam = true
    }
    tls {}
  }

  # Enhanced monitoring
  enhanced_monitoring = "PER_TOPIC_PER_BROKER"

  open_monitoring {
    prometheus {
      jmx_exporter {
        enabled_in_broker = true
      }
      node_exporter {
        enabled_in_broker = true
      }
    }
  }

  logging_info {
    broker_logs {
      cloudwatch_logs {
        enabled   = true
        log_group = aws_cloudwatch_log_group.msk.name
      }
    }
  }

  tags = {
    Name        = "msk-cluster"
    Environment = "production"
  }
}

#######################################
# Outputs
#######################################
output "cluster_arn" {
  description = "ARN of the MSK cluster"
  value       = aws_msk_cluster.this.arn
}

output "bootstrap_brokers_tls" {
  description = "TLS connection host:port pairs"
  value       = aws_msk_cluster.this.bootstrap_brokers_tls
}

output "bootstrap_brokers_sasl_iam" {
  description = "SASL/IAM connection host:port pairs"
  value       = aws_msk_cluster.this.bootstrap_brokers_sasl_iam
}

output "zookeeper_connect_string" {
  description = "Zookeeper connection string"
  value       = aws_msk_cluster.this.zookeeper_connect_string
}

