  kms_key_id        = aws_kms_key.cloudwatch_logs.arn

  tags = local.tags
}

resource "aws_cloudwatch_log_stream" "kinesis_analytics" {
  name           = local.log_stream_name
  log_group_name = aws_cloudwatch_log_group.kinesis_analytics.name
}

resource "aws_kinesis_stream" "input" {
  name             = "${local.name}-input"
  shard_count      = 1
  retention_period = 24

  encryption_type = "KMS"
  kms_key_id      = "alias/aws/kinesis"

  stream_mode_details {
    stream_mode = "PROVISIONED"
  }

  tags = local.tags
}

resource "aws_kinesis_stream" "output" {
  name             = "${local.name}-output"
  shard_count      = 1
  retention_period = 24

  encryption_type = "KMS"
  kms_key_id      = "alias/aws/kinesis"

  stream_mode_details {
    stream_mode = "PROVISIONED"
  }

  tags = local.tags
}

data "aws_iam_policy_document" "kinesis_analytics_assume_role" {
  statement {
    sid    = "AllowKinesisAnalyticsAssumeRole"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["kinesisanalytics.${data.aws_partition.current.dns_suffix}"]
    }

    actions = ["sts:AssumeRole"]
  }
}

resource "aws_iam_role" "kinesis_analytics" {
  name               = "${local.name}-role"
  assume_role_policy = data.aws_iam_policy_document.kinesis_analytics_assume_role.json

  tags = local.tags
}

data "aws_iam_policy_document" "kinesis_analytics_permissions" {
  statement {
    sid    = "ReadInputStream"
    effect = "Allow"

    actions = [
      "kinesis:DescribeStream",
      "kinesis:GetRecords",
      "kinesis:GetShardIterator",
      "kinesis:ListShards"
    ]

    resources = [aws_kinesis_stream.input.arn]
  }

  statement {
    sid    = "WriteOutputStream"
    effect = "Allow"

    actions = [
      "kinesis:DescribeStream",
      "kinesis:PutRecord",
      "kinesis:PutRecords"
    ]

    resources = [aws_kinesis_stream.output.arn]
  }

  statement {
    sid    = "WriteApplicationLogs"
    effect = "Allow"

    actions = [
      "logs:DescribeLogStreams",
      "logs:PutLogEvents"
    ]

    resources = [
      "${local.log_group_arn}:*"
    ]
  }
}

resource "aws_iam_role_policy" "kinesis_analytics" {
  name   = "${local.name}-policy"
  role   = aws_iam_role.kinesis_analytics.id
  policy = data.aws_iam_policy_document.kinesis_analytics_permissions.json
}

resource "aws_kinesis_analytics_application" "basic" {
  name        = local.name
  description = "Basic Kinesis Analytics SQL application with CloudWatch logging"

  code = <<-SQL
    CREATE OR REPLACE STREAM "DESTINATION_SQL_STREAM" (
      ticker_symbol VARCHAR(8),
      sector        VARCHAR(32),
      price         DOUBLE
    );

    CREATE OR REPLACE PUMP "STREAM_PUMP" AS
      INSERT INTO "DESTINATION_SQL_STREAM"
      SELECT STREAM
        "ticker_symbol",
        "sector",
        "price"
      FROM "SOURCE_SQL_STREAM_001";
  SQL

  cloudwatch_logging_options {
    log_stream_arn = aws_cloudwatch_log_stream.kinesis_analytics.arn
    role_arn       = aws_iam_role.kinesis_analytics.arn
  }

  inputs {
    name_prefix = "SOURCE_SQL_STREAM"

    kinesis_stream {
      resource_arn = aws_kinesis_stream.input.arn
      role_arn     = aws_iam_role.kinesis_analytics.arn
    }

    schema {
      record_encoding = "UTF-8"

      record_columns {
        name     = "ticker_symbol"
        mapping  = "$.ticker_symbol"
        sql_type = "VARCHAR(8)"
      }

      record_columns {
        name     = "sector"
        mapping  = "$.sector"
        sql_type = "VARCHAR(32)"
      }

      record_columns {
        name     = "price"
        mapping  = "$.price"
        sql_type = "DOUBLE"
      }

      record_format {
        mapping_parameters {
          json {
            record_row_path = "$"
          }
        }
      }
    }
  }

  outputs {
    name = "DESTINATION_SQL_STREAM"

    kinesis_stream {
      resource_arn = aws_kinesis_stream.output.arn
      role_arn     = aws_iam_role.kinesis_analytics.arn
    }

    schema {
      record_format_type = "JSON"
    }
  }

  tags = local.tags

  depends_on = [
    aws_iam_role_policy.kinesis_analytics
  ]
}

