resource "aws_lex_intent" "order_pizza" {
  name           = "OrderPizza"
  description    = "Intent for ordering pizzas."
  create_version = true

  sample_utterances = [
    "I want to order a pizza",
    "Order a pizza",
    "I would like a pizza",
    "Get me a {PizzaSize} pizza",
    "I want a {PizzaSize} {PizzaType} pizza",
    "Order {Quantity} {PizzaSize} {PizzaType} pizzas",
    "I would like {Quantity} {PizzaSize} {PizzaCrust} crust {PizzaType} pizzas"
  ]

  slot {
    name              = "Quantity"
    description       = "Number of pizzas to order."
    priority          = 1
    slot_constraint   = "Required"
    slot_type         = "AMAZON.Number"

    value_elicitation_prompt {
      max_attempts = 2

      message {
        content      = "How many pizzas would you like to order?"
        content_type = "PlainText"
      }
    }
  }

  slot {
    name                = "PizzaSize"
    description         = "Requested pizza size."
    priority            = 2
    slot_constraint     = "Required"
    slot_type           = aws_lex_slot_type.pizza_size.name
    slot_type_version   = aws_lex_slot_type.pizza_size.version

    value_elicitation_prompt {
      max_attempts = 2

      message {
        content      = "What size pizza would you like: small, medium, large, or extra large?"
        content_type = "PlainText"
      }
    }
  }

  slot {
    name                = "PizzaCrust"
    description         = "Requested pizza crust."
    priority            = 3
    slot_constraint     = "Required"
    slot_type           = aws_lex_slot_type.pizza_crust.name
    slot_type_version   = aws_lex_slot_type.pizza_crust.version

    value_elicitation_prompt {
      max_attempts = 2

      message {
        content      = "What kind of crust would you like: thin, regular, deep dish, or stuffed?"
        content_type = "PlainText"
      }
    }
  }

  slot {
    name                = "PizzaType"
    description         = "Requested pizza type."
    priority            = 4
    slot_constraint     = "Required"
    slot_type           = aws_lex_slot_type.pizza_type.name
    slot_type_version   = aws_lex_slot_type.pizza_type.version

    value_elicitation_prompt {
      max_attempts = 2

      message {
        content      = "What type of pizza would you like: cheese, pepperoni, vegetarian, hawaiian, or supreme?"
        content_type = "PlainText"
      }
    }
  }

  confirmation_prompt {
    max_attempts = 2

    message {
      content      = "Please confirm: you want {Quantity} {PizzaSize} {PizzaCrust} crust {PizzaType} pizza or pizzas. Is that correct?"
      content_type = "PlainText"
    }
  }

  rejection_statement {
    message {
      content      = "Okay, I have cancelled the pizza order."
      content_type = "PlainText"
    }
  }

  conclusion_statement {
    message {
      content      = "Thank you. Your pizza order has been received."
      content_type = "PlainText"
    }
  }

  fulfillment_activity {
    type = "ReturnIntent"
  }
}

resource "aws_lex_bot" "pizza_order_bot" {
  name                        = "PizzaOrderBot"
  description                 = "Amazon Lex bot for ordering pizzas."
  child_directed              = false
  locale                      = "en-US"
  voice_id                    = "Salli"
  process_behavior            = "BUILD"
  idle_session_ttl_in_seconds = 300
  create_version              = true
  detect_sentiment            = false

  abort_statement {
    message {
      content      = "Sorry, I am unable to complete your pizza order right now."
      content_type = "PlainText"
    }
  }

  clarification_prompt {
    max_attempts = 2

    message {
      content      = "I did not understand. You can say, I want to order a pizza."
      content_type = "PlainText"
    }
  }

  intent {
    intent_name    = aws_lex_intent.order_pizza.name
    intent_version = aws_lex_intent.order_pizza.version
  }
}

