model_answers:
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region

  default_tags {
    tags = {
      Project     = var.project_name
      Environment = var.environment
      ManagedBy   = "Terraform"
    }
  }
}

variable "aws_region" {
  type        = string
  description = "AWS region where the Lightsail instance will be created."
  default     = "us-east-1"
}

variable "availability_zone" {
  type        = string
  description = "Lightsail availability zone for the instance."
  default     = "us-east-1a"
}

variable "project_name" {
  type        = string
  description = "Project name used for resource naming."
  default     = "wordpress-lightsail"
}

variable "environment" {
  type        = string
  description = "Deployment environment."
  default     = "prod"
}

variable "instance_name" {
  type        = string
  description = "Name of the Lightsail WordPress instance."
  default     = "wordpress-prod-01"
}

variable "bundle_id" {
  type        = string
  description = "Lightsail bundle ID."
  default     = "micro_3_0"
}

variable "ssh_public_key" {
  type        = string
  description = "Public SSH key for administrative access. Do not provide a private key."
  sensitive   = true
}

variable "ssh_allowed_cidrs" {
  type        = list(string)
  description = "CIDR blocks allowed to access SSH. Use a trusted public IP range only."
  default     = []
}

resource "aws_lightsail_key_pair" "wordpress" {
  name       = "${var.project_name}-${var.environment}-key"
  public_key = var.ssh_public_key
}

resource "aws_lightsail_instance" "wordpress" {
  name              = var.instance_name
  availability_zone = var.availability_zone
  blueprint_id      = "wordpress"
  bundle_id         = var.bundle_id
  key_pair_name     = aws_lightsail_key_pair.wordpress.name
  ip_address_type   = "ipv4"

  add_on {
    type                 = "AutoSnapshot"
    status               = "Enabled"
    snapshot_time_of_day = "03:00"
  }

  tags = {
    Name = var.instance_name
  }
}

resource "aws_lightsail_static_ip" "wordpress" {
  name = "${var.instance_name}-static-ip"
}

resource "aws_lightsail_static_ip_attachment" "wordpress" {
  static_ip_name = aws_lightsail_static_ip.wordpress.name
  instance_name  = aws_lightsail_instance.wordpress.name
}

resource "aws_lightsail_instance_public_ports" "wordpress" {
  instance_name = aws_lightsail_instance.wordpress.name

  port_info {
    protocol  = "tcp"
    from_port = 80
    to_port   = 80
    cidrs     = ["0.0.0.0/0"]
  }

  port_info {
    protocol  = "tcp"
    from_port = 443
    to_port   = 443
    cidrs     = ["0.0.0.0/0"]
  }

  dynamic "port_info" {
    for_each = length(var.ssh_allowed_cidrs) > 0 ? [1] : []

    content {
      protocol  = "tcp"
      from_port = 22
      to_port   = 22
      cidrs     = var.ssh_allowed_cidrs
    }
  }
}

output "wordpress_static_ip" {
  description = "Static public IPv4 address assigned to the WordPress Lightsail instance."
  value       = aws_lightsail_static_ip.wordpress.ip_address
}

