}

data "aws_iam_policy_document" "s3_kms_key" {
  statement {
    sid     = "EnableAccountKMSAdministration"
    effect  = "Allow"
    actions = ["kms:*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    resources = ["*"]
  }

  statement {
    sid    = "AllowS3InventoryToEncryptReports"
    effect = "Allow"

    actions = [
      "kms:GenerateDataKey"
    ]

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }

    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }

    condition {
      test     = "ArnLike"
      variable = "aws:SourceArn"
      values   = [aws_s3_bucket.source.arn]
    }
  }
}

resource "aws_kms_key" "s3" {
  description             = "KMS key for S3 bucket encryption and S3 Inventory reports"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.s3_kms_key.json
}

resource "aws_kms_alias" "s3" {
  name          = "alias/${var.name_prefix}-${random_id.suffix.hex}-s3"
  target_key_id = aws_kms_key.s3.key_id
}

resource "aws_s3_bucket_server_side_encryption_configuration" "source" {
  bucket = aws_s3_bucket.source.id

  rule {
    bucket_key_enabled = true

    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.s3.arn
    }
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "inventory_reports" {
  bucket = aws_s3_bucket.inventory_reports.id

  rule {
    bucket_key_enabled = true

    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.s3.arn
    }
  }
}

resource "aws_s3_bucket_versioning" "source" {
  bucket = aws_s3_bucket.source.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_versioning" "inventory_reports" {
  bucket = aws_s3_bucket.inventory_reports.id

  versioning_configuration {
    status = "Enabled"
  }
}

data "aws_iam_policy_document" "source_bucket" {
  statement {
    sid    = "DenyInsecureTransport"
    effect = "Deny"

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    actions = ["s3:*"]

    resources = [
      aws_s3_bucket.source.arn,
      "${aws_s3_bucket.source.arn}/*"
    ]

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "source" {
  bucket = aws_s3_bucket.source.id
  policy = data.aws_iam_policy_document.source_bucket.json
}

data "aws_iam_policy_document" "inventory_reports_bucket" {
  statement {
    sid    = "DenyInsecureTransport"
    effect = "Deny"

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    actions = ["s3:*"]

    resources = [
      aws_s3_bucket.inventory_reports.arn,
      "${aws_s3_bucket.inventory_reports.arn}/*"
    ]

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }

  statement {
    sid    = "AllowS3InventoryDelivery"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }

    actions = ["s3:PutObject"]

    resources = [
      "${aws_s3_bucket.inventory_reports.arn}/${local.inventory_report_prefix}/*"
    ]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }

    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }

    condition {
      test     = "ArnLike"
      variable = "aws:SourceArn"
      values   = [aws_s3_bucket.source.arn]
    }
  }
}

resource "aws_s3_bucket_policy" "inventory_reports" {
  bucket = aws_s3_bucket.inventory_reports.id
  policy = data.aws_iam_policy_document.inventory_reports_bucket.json
}

resource "aws_s3_bucket_inventory" "weekly_current_versions_csv" {
  bucket  = aws_s3_bucket.source.id
  name    = "weekly-current-object-versions-csv"
  enabled = true

  included_object_versions = "Current"

  schedule {
    frequency = "Weekly"
  }

  destination {
    bucket {
      bucket_arn = aws_s3_bucket.inventory_reports.arn
      account_id = data.aws_caller_identity.current.account_id
      format     = "CSV"
      prefix     = local.inventory_report_prefix

      encryption {
        sse_kms {
          key_id = aws_kms_key.s3.arn
        }
      }
    }
  }

  optional_fields = [
    "Size",
    "LastModifiedDate",
    "StorageClass",
    "ETag",
    "IsMultipartUploaded",
    "EncryptionStatus"
  ]

  depends_on = [
    aws_s3_bucket_policy.inventory_reports,
    aws_s3_bucket_versioning.source,
    aws_s3_bucket_versioning.inventory_reports,
    aws_s3_bucket_server_side_encryption_configuration.source,
    aws_s3_bucket_server_side_encryption_configuration.inventory_reports
  ]
}

