terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  type    = string
  default = "us-east-1"
}

variable "project_name" {
  type    = string
  default = "redshift-example"
}

variable "vpc_cidr" {
  type    = string
  default = "10.0.0.0/16"
}

variable "redshift_port" {
  type    = number
  default = 5439
}

variable "redshift_client_cidr_blocks" {
  type        = list(string)
  description = "CIDR blocks allowed to connect to the Redshift endpoint. Restrict this to trusted client networks."
  default     = ["10.0.0.0/16"]
}

locals {
  name = var.project_name

  common_tags = {
    Project   = var.project_name
    ManagedBy = "Terraform"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "this" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name}-vpc"
  })
}

resource "aws_subnet" "private_a" {
  vpc_id                  = aws_vpc.this.id
  cidr_block              = cidrsubnet(var.vpc_cidr, 8, 1)
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name}-private-a"
  })
}

resource "aws_subnet" "private_b" {
  vpc_id                  = aws_vpc.this.id
  cidr_block              = cidrsubnet(var.vpc_cidr, 8, 2)
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name}-private-b"
  })
}

resource "aws_redshift_subnet_group" "this" {
  name       = "${local.name}-subnet-group"
  subnet_ids = [aws_subnet.private_a.id, aws_subnet.private_b.id]

  tags = merge(local.common_tags, {
    Name = "${local.name}-subnet-group"
  })
}

resource "aws_kms_key" "redshift" {
  description             = "KMS key for ${local.name} Redshift encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = merge(local.common_tags, {
    Name = "${local.name}-redshift-kms"
  })
}

resource "aws_kms_alias" "redshift" {
  name          = "alias/${local.name}-redshift"
  target_key_id = aws_kms_key.redshift.key_id
}

resource "aws_security_group" "redshift_cluster" {
  name        = "${local.name}-redshift-cluster-sg"
  description = "Security group for the Redshift cluster"
  vpc_id      = aws_vpc.this.id

  tags = merge(local.common_tags, {
    Name = "${local.name}-redshift-cluster-sg"
  })
}

resource "aws_security_group" "redshift_endpoint" {
  name        = "${local.name}-redshift-endpoint-sg"
  description = "Security group for Redshift endpoint access"
  vpc_id      = aws_vpc.this.id

  tags = merge(local.common_tags, {
    Name = "${local.name}-redshift-endpoint-sg"
  })
}

resource "aws_vpc_security_group_ingress_rule" "redshift_endpoint_from_clients" {
  for_each = toset(var.redshift_client_cidr_blocks)

  security_group_id = aws_security_group.redshift_endpoint.id
  description       = "Allow trusted clients to access Redshift endpoint"
  cidr_ipv4         = each.value
  ip_protocol       = "tcp"
  from_port         = var.redshift_port
  to_port           = var.redshift_port
}

resource "aws_vpc_security_group_egress_rule" "redshift_endpoint_to_cluster" {
  security_group_id            = aws_security_group.redshift_endpoint.id
  description                  = "Allow endpoint to connect to Redshift cluster"
  referenced_security_group_id = aws_security_group.redshift_cluster.id
  ip_protocol                  = "tcp"
  from_port                    = var.redshift_port
  to_port                      = var.redshift_port
}

resource "aws_vpc_security_group_ingress_rule" "redshift_cluster_from_endpoint" {
  security_group_id            = aws_security_group.redshift_cluster.id
  description                  = "Allow Redshift endpoint to connect to cluster"
  referenced_security_group_id = aws_security_group.redshift_endpoint.id
  ip_protocol                  = "tcp"
  from_port                    = var.redshift_port
  to_port                      = var.redshift_port
}

resource "aws_redshift_parameter_group" "this" {
  name   = "${local.name}-params"
  family = "redshift-1.0"

  parameter {
    name  = "require_ssl"
    value = "true"
  }

  parameter {
    name  = "enable_user_activity_logging"
    value = "true"
  }

  tags = merge(local.common_tags, {
    Name = "${local.name}-params"
  })
}

resource "aws_redshift_cluster" "this" {
  cluster_identifier                  = local.name
  database_name                       = "exampledb"
  master_username                     = "rsadmin"
  manage_master_password              = true
  master_password_secret_kms_key_id   = aws_kms_key.redshift.arn
  node_type                           = "dc2.large"
  cluster_type                        = "single-node"
  port                                = var.redshift_port
  cluster_subnet_group_name           = aws_redshift_subnet_group.this.name
  vpc_security_group_ids              = [aws_security_group.redshift_cluster.id]
  cluster_parameter_group_name        = aws_redshift_parameter_group.this.name
  encrypted                           = true
  kms_key_id                          = aws_kms_key.redshift.arn
  publicly_accessible                 = false
  enhanced_vpc_routing                = true
  automated_snapshot_retention_period = 7
  preferred_maintenance_window        = "sun:10:00-sun:10:30"
  allow_version_upgrade               = true
  skip_final_snapshot                 = false
  final_snapshot_identifier           = "${local.name}-final-snapshot"

  logging {
    enable               = true
    log_destination_type = "cloudwatch"
    log_exports          = ["connectionlog", "userlog", "useractivitylog"]
  }

  tags = merge(local.common_tags, {
    Name = local.name
  })
}

resource "aws_redshift_endpoint_access" "this" {
  endpoint_name          = "${local.name}-endpoint"
  cluster_identifier    = aws_redshift_cluster.this.cluster_identifier
  subnet_group_name     = aws_redshift_subnet_group.this.name
  vpc_security_group_ids = [aws_security_group.redshift_endpoint.id]

  depends_on = [
    aws_vpc_security_group_ingress_rule.redshift_endpoint_from_clients,
    aws_vpc_security_group_egress_rule.redshift_endpoint_to_cluster,
    aws_vpc_security_group_ingress_rule.redshift_cluster_from_endpoint
  ]
}

