resource "aws_chimesdkvoice_voice_connector_group" "encrypted_group" {
  name = "encrypted-voice-connector-group"

  connector {
    voice_connector_id = aws_chimesdkvoice_voice_connector.primary.id
    priority           = 1
  }

  connector {
    voice_connector_id = aws_chimesdkvoice_voice_connector.secondary.id
    priority           = 2
  }
}

