resource "aws_instance" "web" {
  ami                         = data.aws_ami.amazon_linux_2023.id
  instance_type               = "t2.micro"
  subnet_id                   = aws_subnet.private_a.id
  vpc_security_group_ids      = [aws_security_group.ec2.id]
  associate_public_ip_address = false
  user_data_replace_on_change = true

  metadata_options {
    http_endpoint               = "enabled"
    http_tokens                 = "required"
    http_put_response_hop_limit = 1
    instance_metadata_tags      = "disabled"
  }

  root_block_device {
    encrypted             = true
    volume_type           = "gp3"
    volume_size           = 8
    delete_on_termination = true
  }

  user_data = <<-EOF
    #!/bin/bash
    set -euo pipefail

    mkdir -p /opt/nlb-demo
    cat > /opt/nlb-demo/index.html <<'HTML'
    <!doctype html>
    <html>
      <head><title>NLB EC2 Target</title></head>
      <body><h1>Hello from a t2.micro EC2 instance behind a Network Load Balancer</h1></body>
    </html>
    HTML

    cat > /etc/systemd/system/nlb-demo-http.service <<'SERVICE'
    [Unit]
    Description=Simple HTTP service for NLB target
    After=network-online.target
    Wants=network-online.target

    [Service]
    Type=simple
    User=root
    WorkingDirectory=/opt/nlb-demo
    ExecStart=/usr/bin/python3 -m http.server 80 --bind 0.0.0.0
    Restart=always
    RestartSec=5

    [Install]
    WantedBy=multi-user.target
    SERVICE

    systemctl daemon-reload
    systemctl enable --now nlb-demo-http.service
  EOF

  tags = {
    Name = "nlb-target-t2-micro"
  }
}

