locals {
  common_tags = merge(var.tags, {
    Application = "Airbyte"
    Purpose     = "connector-tests"
    Engine      = "postgresql-15"
    ManagedBy   = "terraform"
  })

  enabled_cloudwatch_logs_exports = toset(["postgresql", "upgrade"])
}

resource "aws_db_subnet_group" "airbyte_postgres" {
  name        = "${var.db_identifier}-subnet-group"
  description = "Public subnet group for Airbyte connector test PostgreSQL 15 RDS instance"
  subnet_ids  = var.public_subnet_ids

  tags = local.common_tags
}

resource "aws_security_group" "airbyte_postgres" {
  name        = "${var.db_identifier}-sg"
  description = "Restricts PostgreSQL access for Airbyte connector tests"
  vpc_id      = var.vpc_id

  revoke_rules_on_delete = true

  tags = local.common_tags
}

resource "aws_vpc_security_group_ingress_rule" "postgres_ipv4" {
  for_each = var.allowed_ipv4_cidr_blocks

  security_group_id = aws_security_group.airbyte_postgres.id
  description       = "PostgreSQL access from approved IPv4 CIDR ${each.value}"
  cidr_ipv4         = each.value
  from_port         = 5432
  to_port           = 5432
  ip_protocol       = "tcp"
}

resource "aws_vpc_security_group_ingress_rule" "postgres_ipv6" {
  for_each = var.allowed_ipv6_cidr_blocks

  security_group_id = aws_security_group.airbyte_postgres.id
  description       = "PostgreSQL access from approved IPv6 CIDR ${each.value}"
  cidr_ipv6         = each.value
  from_port         = 5432
  to_port           = 5432
  ip_protocol       = "tcp"
}

resource "aws_vpc_security_group_ingress_rule" "postgres_sg" {
  for_each = var.allowed_security_group_ids

  security_group_id            = aws_security_group.airbyte_postgres.id
  description                  = "PostgreSQL access from approved security group ${each.value}"
  referenced_security_group_id = each.value
  from_port                    = 5432
  to_port                      = 5432
  ip_protocol                  = "tcp"
}

resource "aws_vpc_security_group_egress_rule" "all_ipv4" {
  security_group_id = aws_security_group.airbyte_postgres.id
  description       = "Allow outbound IPv4 traffic"
  cidr_ipv4         = "0.0.0.0/0"
  ip_protocol       = "-1"
}

resource "aws_vpc_security_group_egress_rule" "all_ipv6" {
  security_group_id = aws_security_group.airbyte_postgres.id
  description       = "Allow outbound IPv6 traffic"
  cidr_ipv6         = "::/0"
  ip_protocol       = "-1"
}

resource "aws_db_parameter_group" "airbyte_postgres15" {
  name        = "${var.db_identifier}-pg15"
  family      = "postgres15"
  description = "PostgreSQL 15 parameters for Airbyte connector tests"

  parameter {
    name         = "rds.force_ssl"
    value        = "1"
    apply_method = "pending-reboot"
  }

  tags = local.common_tags
}

resource "aws_cloudwatch_log_group" "rds" {
  for_each = local.enabled_cloudwatch_logs_exports

  name              = "/aws/rds/instance/${var.db_identifier}/${each.value}"
  retention_in_days = var.cloudwatch_log_retention_days

  tags = local.common_tags
}

resource "aws_db_instance" "airbyte_postgres" {
  identifier = var.db_identifier

  engine         = "postgres"
  engine_version = "15"
  instance_class = var.instance_class

  db_name  = var.initial_database_name
  username = var.master_username

  manage_master_user_password = true

  port = 5432

  allocated_storage     = var.allocated_storage_gib
  max_allocated_storage = var.max_allocated_storage_gib
  storage_type          = "gp3"
  storage_encrypted     = true

  db_subnet_group_name   = aws_db_subnet_group.airbyte_postgres.name
  vpc_security_group_ids = [aws_security_group.airbyte_postgres.id]
  publicly_accessible    = var.publicly_accessible

  parameter_group_name = aws_db_parameter_group.airbyte_postgres15.name

  backup_retention_period = var.backup_retention_days
  backup_window           = "03:00-04:00"
  maintenance_window      = "sun:05:00-sun:06:00"

  auto_minor_version_upgrade            = true
  allow_major_version_upgrade           = false
  apply_immediately                     = true
  skip_final_snapshot                   = true
  delete_automated_backups              = true
  deletion_protection                   = false
  copy_tags_to_snapshot                 = true
  iam_database_authentication_enabled   = true
  enabled_cloudwatch_logs_exports       = sort(tolist(local.enabled_cloudwatch_logs_exports))
  performance_insights_enabled          = true
  performance_insights_retention_period = 7

  tags = local.common_tags

  depends_on = [
    aws_cloudwatch_log_group.rds
  ]

  lifecycle {
    precondition {
      condition = !var.publicly_accessible || (
        length(var.allowed_ipv4_cidr_blocks) +
        length(var.allowed_ipv6_cidr_blocks) +
        length(var.allowed_security_group_ids)
      ) > 0
      error_message = "A publicly accessible RDS instance must restrict PostgreSQL access using at least one allowed CIDR block or security group."
    }
  }
}

output "rds_endpoint" {
  description = "RDS PostgreSQL endpoint."
  value       = aws_db_instance.airbyte_postgres.endpoint
}

output "rds_port" {
  description = "RDS PostgreSQL port."
  value       = aws_db_instance.airbyte_postgres.port
}

output "rds_master_user_secret_arn" {
  description = "AWS Secrets Manager secret ARN containing the managed master user password."
  value       = aws_db_instance.airbyte_postgres.master_user_secret[0].secret_arn
  sensitive   = true
}

