  tags = {
    Name = "mysql-rds-sg"
  }
}

resource "aws_vpc_security_group_ingress_rule" "mysql" {
  for_each = toset(var.allowed_db_ingress_cidr_blocks)

  security_group_id = aws_security_group.mysql.id
  description       = "Allow MySQL access from approved CIDR"
  cidr_ipv4         = each.value
  from_port         = 3306
  to_port           = 3306
  ip_protocol       = "tcp"
}

resource "aws_vpc_security_group_egress_rule" "mysql" {
  security_group_id = aws_security_group.mysql.id
  description       = "Allow outbound traffic"
  cidr_ipv4         = "0.0.0.0/0"
  ip_protocol       = "-1"
}

resource "aws_db_parameter_group" "mysql" {
  name        = "mysql-secure-parameters"
  family      = "mysql8.0"
  description = "Secure MySQL parameters"

  parameter {
    name  = "require_secure_transport"
    value = "ON"
  }

  tags = {
    Name = "mysql-secure-parameters"
  }
}

resource "aws_db_instance" "mysql" {
  identifier = "secure-mysql"

  engine         = "mysql"
  engine_version = var.db_engine_version
  instance_class = var.db_instance_class

  db_name  = var.db_name
  username = var.db_username

  manage_master_user_password   = true
  master_user_secret_kms_key_id  = aws_kms_key.rds.arn
  iam_database_authentication_enabled = true

  allocated_storage     = var.db_allocated_storage
  max_allocated_storage = var.db_max_allocated_storage
  storage_type          = "gp3"
  storage_encrypted     = true
  kms_key_id            = aws_kms_key.rds.arn

  db_subnet_group_name   = aws_db_subnet_group.mysql.name
  vpc_security_group_ids = [aws_security_group.mysql.id]
  publicly_accessible    = false

  multi_az               = true
  backup_retention_period = 7
  backup_window           = "03:00-04:00"
  maintenance_window      = "sun:04:00-sun:05:00"

  auto_minor_version_upgrade = true
  apply_immediately          = false

  deletion_protection       = true
  skip_final_snapshot       = false
  final_snapshot_identifier = "secure-mysql-final-snapshot"

  copy_tags_to_snapshot = true

  enabled_cloudwatch_logs_exports = [
    "error",
    "general",
    "slowquery"
  ]

  parameter_group_name = aws_db_parameter_group.mysql.name

  performance_insights_enabled          = true
  performance_insights_kms_key_id       = aws_kms_key.rds.arn
  performance_insights_retention_period = 7

  monitoring_interval = 0

  tags = {
    Name = "secure-mysql"
  }
}

output "mysql_endpoint" {
  description = "RDS MySQL endpoint."
  value       = aws_db_instance.mysql.endpoint
}

output "mysql_port" {
  description = "RDS MySQL port."
  value       = aws_db_instance.mysql.port
}

