}

variable "private_subnet_ids" {
  description = "Private subnet IDs for the ElastiCache subnet group. Use at least two subnets in different Availability Zones."
  type        = set(string)

  validation {
    condition     = length(var.private_subnet_ids) >= 2
    error_message = "At least two private subnet IDs are required."
  }
}

variable "allowed_security_group_ids" {
  description = "Security group IDs allowed to connect to Redis."
  type        = set(string)

  validation {
    condition     = length(var.allowed_security_group_ids) > 0
    error_message = "At least one allowed security group ID is required."
  }
}

variable "node_type" {
  description = "ElastiCache node type."
  type        = string
  default     = "cache.t4g.small"
}

variable "engine_version" {
  description = "Redis OSS engine version."
  type        = string
  default     = "7.1"
}

variable "parameter_group_name" {
  description = "Redis parameter group name."
  type        = string
  default     = "default.redis7"
}

variable "replica_count" {
  description = "Number of read replicas. Set to 0 for a single-node Redis instance."
  type        = number
  default     = 1

  validation {
    condition     = var.replica_count >= 0 && var.replica_count <= 5
    error_message = "replica_count must be between 0 and 5."
  }
}

variable "port" {
  description = "Redis port."
  type        = number
  default     = 6379
}

variable "snapshot_retention_limit" {
  description = "Number of days to retain automatic Redis snapshots."
  type        = number
  default     = 7

  validation {
    condition     = var.snapshot_retention_limit >= 1 && var.snapshot_retention_limit <= 35
    error_message = "snapshot_retention_limit must be between 1 and 35."
  }
}

variable "snapshot_window" {
  description = "Daily time range during which automated backups are created, in UTC."
  type        = string
  default     = "03:00-04:00"
}

variable "maintenance_window" {
  description = "Weekly time range during which maintenance can occur, in UTC."
  type        = string
  default     = "sun:05:00-sun:06:00"
}

variable "apply_immediately" {
  description = "Whether changes should be applied immediately."
  type        = bool
  default     = false
}

variable "log_retention_days" {
  description = "CloudWatch Logs retention in days."
  type        = number
  default     = 30
}

variable "tags" {
  description = "Tags to apply to resources."
  type        = map(string)
  default     = {}
}

locals {
  common_tags = merge(var.tags, {
    ManagedBy = "Terraform"
    Service   = "Redis"
  })
}

data "aws_iam_policy_document" "redis_kms" {
  statement {
    sid     = "EnableIAMPermissions"
    effect  = "Allow"
    actions = ["kms:*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    resources = ["*"]
  }

  statement {
    sid    = "AllowCloudWatchLogsUseOfKey"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["logs.${data.aws_region.current.name}.amazonaws.com"]
    }

    actions = [
      "kms:Decrypt",
      "kms:DescribeKey",
      "kms:Encrypt",
      "kms:GenerateDataKey",
      "kms:GenerateDataKeyPair",
      "kms:GenerateDataKeyPairWithoutPlaintext",
      "kms:GenerateDataKeyWithoutPlaintext",
      "kms:ReEncryptFrom",
      "kms:ReEncryptTo"
    ]

    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "kms:ViaService"
      values   = ["logs.${data.aws_region.current.name}.amazonaws.com"]
    }

    condition {
      test     = "StringLike"
      variable = "kms:EncryptionContext:aws:logs:arn"
      values   = ["arn:aws:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:/aws/elasticache/${var.name}/*"]
    }
  }
}

resource "aws_kms_key" "redis" {
  description             = "KMS key for ${var.name} Redis encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.redis_kms.json

  tags = merge(local.common_tags, {
    Name = "${var.name}-kms"
  })
}

resource "aws_kms_alias" "redis" {
  name          = "alias/${var.name}-redis"
  target_key_id = aws_kms_key.redis.key_id
}

resource "random_password" "redis_auth_token" {
  length  = 40
  special = false
}

resource "aws_security_group" "redis" {
  name        = "${var.name}-sg"
  description = "Security group for Redis ElastiCache ${var.name}"
  vpc_id      = var.vpc_id

  tags = merge(local.common_tags, {
    Name = "${var.name}-sg"
  })
}

resource "aws_vpc_security_group_ingress_rule" "redis_from_allowed_sgs" {
  for_each = var.allowed_security_group_ids

  security_group_id            = aws_security_group.redis.id
  referenced_security_group_id = each.value
  ip_protocol                  = "tcp"
  from_port                    = var.port
  to_port                      = var.port
  description                  = "Allow Redis access from approved security group"
}

resource "aws_vpc_security_group_ingress_rule" "redis_self" {
  security_group_id            = aws_security_group.redis.id
  referenced_security_group_id = aws_security_group.redis.id
  ip_protocol                  = "tcp"
  from_port                    = var.port
  to_port                      = var.port
  description                  = "Allow Redis node-to-node traffic"
}

resource "aws_vpc_security_group_egress_rule" "redis_self" {
  security_group_id            = aws_security_group.redis.id
  referenced_security_group_id = aws_security_group.redis.id
  ip_protocol                  = "tcp"
  from_port                    = var.port
  to_port                      = var.port
  description                  = "Allow Redis node-to-node egress traffic"
}

resource "aws_elasticache_subnet_group" "redis" {
  name        = "${var.name}-subnet-group"
  description = "Private subnet group for Redis ${var.name}"
  subnet_ids  = sort(tolist(var.private_subnet_ids))

  tags = merge(local.common_tags, {
    Name = "${var.name}-subnet-group"
  })
}

resource "aws_cloudwatch_log_group" "redis_slow" {
  name              = "/aws/elasticache/${var.name}/slow-log"
  retention_in_days = var.log_retention_days
  kms_key_id        = aws_kms_key.redis.arn

  tags = merge(local.common_tags, {
    Name = "${var.name}-slow-log"
  })
}

resource "aws_cloudwatch_log_group" "redis_engine" {
  name              = "/aws/elasticache/${var.name}/engine-log"
  retention_in_days = var.log_retention_days
  kms_key_id        = aws_kms_key.redis.arn

  tags = merge(local.common_tags, {
    Name = "${var.name}-engine-log"
  })
}

resource "aws_elasticache_replication_group" "redis" {
  replication_group_id = var.name
  description          = "Redis replication group for ${var.name}"

  engine               = "redis"
  engine_version       = var.engine_version
  node_type            = var.node_type
  port                 = var.port
  parameter_group_name = var.parameter_group_name

  num_cache_clusters         = var.replica_count + 1
  automatic_failover_enabled = var.replica_count > 0
  multi_az_enabled           = var.replica_count > 0

  subnet_group_name  = aws_elasticache_subnet_group.redis.name
  security_group_ids = [aws_security_group.redis.id]

  at_rest_encryption_enabled = true
  transit_encryption_enabled = true
  auth_token                 = random_password.redis_auth_token.result
  kms_key_id                 = aws_kms_key.redis.arn

  snapshot_retention_limit = var.snapshot_retention_limit
  snapshot_window          = var.snapshot_window
  maintenance_window       = var.maintenance_window

  auto_minor_version_upgrade = true
  apply_immediately          = var.apply_immediately

  log_delivery_configuration {
    destination      = aws_cloudwatch_log_group.redis_slow.name
    destination_type = "cloudwatch-logs"
    log_format      = "json"
    log_type        = "slow-log"
  }

  log_delivery_configuration {
    destination      = aws_cloudwatch_log_group.redis_engine.name
    destination_type = "cloudwatch-logs"
    log_format      = "json"
    log_type        = "engine-log"
  }

  tags = merge(local.common_tags, {
    Name = var.name
  })
}

resource "aws_secretsmanager_secret" "redis" {
  name                    = "${var.name}/credentials"
  description             = "Connection details and auth token for Redis ${var.name}"
  kms_key_id              = aws_kms_key.redis.arn
  recovery_window_in_days = 30

  tags = merge(local.common_tags, {
    Name = "${var.name}-credentials"
  })
}

resource "aws_secretsmanager_secret_version" "redis" {
  secret_id = aws_secretsmanager_secret.redis.id

  secret_string = jsonencode({
    engine                   = "redis"
    host                     = aws_elasticache_replication_group.redis.primary_endpoint_address
    port                     = var.port
    transit_encryption       = true
    auth_token               = random_password.redis_auth_token.result
    replication_group_id     = aws_elasticache_replication_group.redis.replication_group_id
    reader_endpoint_address  = aws_elasticache_replication_group.redis.reader_endpoint_address
  })
}

output "redis_primary_endpoint_address" {
  description = "Primary endpoint address for Redis."
  value       = aws_elasticache_replication_group.redis.primary_endpoint_address
}

output "redis_reader_endpoint_address" {
  description = "Reader endpoint address for Redis."
  value       = aws_elasticache_replication_group.redis.reader_endpoint_address
}

output "redis_port" {
  description = "Redis port."
  value       = var.port
}

output "redis_security_group_id" {
  description = "Security group ID attached to Redis."
  value       = aws_security_group.redis.id
}

output "redis_credentials_secret_arn" {
  description = "Secrets Manager secret ARN containing Redis connection details and auth token."
  value       = aws_secretsmanager_secret.redis.arn
}

