model_answers:
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.40.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.6.0"
    }
  }
}

variable "delivery_stream_name" {
  description = "Name of the Kinesis Data Firehose delivery stream."
  type        = string
  default     = "firehose-to-aoss"
}

variable "collection_name" {
  description = "Name of the OpenSearch Serverless collection."
  type        = string
  default     = "firehose-logs"
}

variable "index_name" {
  description = "OpenSearch Serverless index name."
  type        = string
  default     = "firehose-index"
}

data "aws_caller_identity" "current" {}
data "aws_region" "current" {}
data "aws_partition" "current" {}

resource "random_id" "suffix" {
  byte_length = 4
}

locals {
  account_id          = data.aws_caller_identity.current.account_id
  region              = data.aws_region.current.name
  partition           = data.aws_partition.current.partition
  backup_bucket_name  = "${var.delivery_stream_name}-backup-${local.account_id}-${random_id.suffix.hex}"
  firehose_stream_arn = "arn:${local.partition}:firehose:${local.region}:${local.account_id}:deliverystream/${var.delivery_stream_name}"
  log_group_name      = "/aws/kinesisfirehose/${var.delivery_stream_name}"
}

data "aws_iam_policy_document" "s3_kms_key" {
  statement {
    sid     = "EnableRootAccountPermissions"
    effect  = "Allow"
    actions = ["kms:*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }

    resources = ["*"]
  }

  statement {
    sid    = "AllowFirehoseRoleUseForS3Backup"
    effect = "Allow"

    actions = [
      "kms:Decrypt",
      "kms:DescribeKey",
      "kms:GenerateDataKey",
      "kms:GenerateDataKeyWithoutPlaintext",
      "kms:ReEncryptFrom",
      "kms:ReEncryptTo"
    ]

    principals {
      type        = "AWS"
      identifiers = [aws_iam_role.firehose.arn]
    }

    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "kms:ViaService"
      values   = ["s3.${local.region}.amazonaws.com"]
    }
  }
}

resource "aws_kms_key" "s3_backup" {
  description             = "KMS key for Firehose S3 backup bucket encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.s3_kms_key.json
}

resource "aws_kms_alias" "s3_backup" {
  name          = "alias/${var.delivery_stream_name}-s3-backup"
  target_key_id = aws_kms_key.s3_backup.key_id
}

data "aws_iam_policy_document" "firehose_kms_key" {
  statement {
    sid     = "EnableRootAccountPermissions"
    effect  = "Allow"
    actions = ["kms:*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }

    resources = ["*"]
  }

  statement {
    sid    = "AllowFirehoseServiceUse"
    effect = "Allow"

    actions = [
      "kms:Decrypt",
      "kms:DescribeKey",
      "kms:GenerateDataKey",
      "kms:GenerateDataKeyWithoutPlaintext"
    ]

    principals {
      type        = "Service"
      identifiers = ["firehose.amazonaws.com"]
    }

    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }

    condition {
      test     = "ArnLike"
      variable = "aws:SourceArn"
      values   = [local.firehose_stream_arn]
    }
  }
}

resource "aws_kms_key" "firehose" {
  description             = "KMS key for Kinesis Data Firehose server-side encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.firehose_kms_key.json
}

resource "aws_kms_alias" "firehose" {
  name          = "alias/${var.delivery_stream_name}-firehose"
  target_key_id = aws_kms_key.firehose.key_id
}

data "aws_iam_policy_document" "aoss_kms_key" {
  statement {
    sid     = "EnableRootAccountPermissions"
    effect  = "Allow"
    actions = ["kms:*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }

    resources = ["*"]
  }

  statement {
    sid    = "AllowOpenSearchServerlessUse"
    effect = "Allow"

    actions = [
      "kms:CreateGrant",
      "kms:Decrypt",
      "kms:DescribeKey",
      "kms:GenerateDataKey",
      "kms:GenerateDataKeyWithoutPlaintext"
    ]

    principals {
      type        = "Service"
      identifiers = ["aoss.amazonaws.com"]
    }

    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }
}

resource "aws_kms_key" "aoss" {
  description             = "KMS key for OpenSearch Serverless collection encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.aoss_kms_key.json
}

resource "aws_kms_alias" "aoss" {
  name          = "alias/${var.collection_name}-aoss"
  target_key_id = aws_kms_key.aoss.key_id
}

resource "aws_s3_bucket" "backup" {
  bucket        = local.backup_bucket_name
  force_destroy = false
}

resource "aws_s3_bucket_public_access_block" "backup" {
  bucket = aws_s3_bucket.backup.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "backup" {
  bucket = aws_s3_bucket.backup.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_versioning" "backup" {
  bucket = aws_s3_bucket.backup.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "backup" {
  bucket = aws_s3_bucket.backup.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.s3_backup.arn
      sse_algorithm     = "aws:kms"
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "backup" {
  bucket = aws_s3_bucket.backup.id

  rule {
    id     = "abort-incomplete-multipart-uploads"
    status = "Enabled"

    abort_incomplete_multipart_upload {
      days_after_initiation = 7
    }
  }
}

data "aws_iam_policy_document" "backup_bucket" {
  statement {
    sid    = "DenyInsecureTransport"
    effect = "Deny"

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    actions = ["s3:*"]

    resources = [
      aws_s3_bucket.backup.arn,
      "${aws_s3_bucket.backup.arn}/*"
    ]

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "backup" {
  bucket = aws_s3_bucket.backup.id
  policy = data.aws_iam_policy_document.backup_bucket.json
}

resource "aws_cloudwatch_log_group" "firehose" {
  name              = local.log_group_name
  retention_in_days = 30
}

resource "aws_cloudwatch_log_stream" "aoss_delivery" {
  name           = "OpenSearchServerlessDelivery"
  log_group_name = aws_cloudwatch_log_group.firehose.name
}

resource "aws_cloudwatch_log_stream" "s3_backup" {
  name           = "S3BackupDelivery"
  log_group_name = aws_cloudwatch_log_group.firehose.name
}

data "aws_iam_policy_document" "firehose_assume_role" {
  statement {
    sid     = "AllowFirehoseAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["firehose.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }

    condition {
      test     = "ArnLike"
      variable = "aws:SourceArn"
      values   = [local.firehose_stream_arn]
    }
  }
}

resource "aws_iam_role" "firehose" {
  name               = "${var.delivery_stream_name}-role"
  assume_role_policy = data.aws_iam_policy_document.firehose_assume_role.json
}

data "aws_iam_policy_document" "firehose_permissions" {
  statement {
    sid    = "AllowS3BackupWrites"
    effect = "Allow"

    actions = [
      "s3:AbortMultipartUpload",
      "s3:GetBucketLocation",
      "s3:ListBucket",
      "s3:ListBucketMultipartUploads"
    ]

    resources = [aws_s3_bucket.backup.arn]
  }

  statement {
    sid    = "AllowS3BackupObjectWrites"
    effect = "Allow"

    actions = [
      "s3:PutObject"
    ]

    resources = ["${aws_s3_bucket.backup.arn}/*"]
  }

  statement {
    sid    = "AllowS3BackupKmsUse"
    effect = "Allow"

    actions = [
      "kms:Decrypt",
      "kms:DescribeKey",
      "kms:GenerateDataKey",
      "kms:GenerateDataKeyWithoutPlaintext",
      "kms:ReEncryptFrom",
      "kms:ReEncryptTo"
    ]

    resources = [aws_kms_key.s3_backup.arn]

    condition {
      test     = "StringEquals"
      variable = "kms:ViaService"
      values   = ["s3.${local.region}.amazonaws.com"]
    }
  }

  statement {
    sid    = "AllowOpenSearchServerlessApiAccess"
    effect = "Allow"

    actions = [
      "aoss:APIAccessAll"
    ]

    resources = [
      aws_opensearchserverless_collection.this.arn
    ]
  }

  statement {
    sid    = "AllowCloudWatchLogging"
    effect = "Allow"

    actions = [
      "logs:PutLogEvents"
    ]

    resources = [
      "arn:${local.partition}:logs:${local.region}:${local.account_id}:log-group:${local.log_group_name}:log-stream:*"
    ]
  }
}

resource "aws_iam_role_policy" "firehose" {
  name   = "${var.delivery_stream_name}-permissions"
  role   = aws_iam_role.firehose.id
  policy = data.aws_iam_policy_document.firehose_permissions.json
}

resource "aws_opensearchserverless_security_policy" "encryption" {
  name = "firehose-aoss-encryption"
  type = "encryption"

  policy = jsonencode({
    Rules = [
      {
        ResourceType = "collection"
        Resource     = ["collection/${var.collection_name}"]
      }
    ]
    KmsARN = aws_kms_key.aoss.arn
  })
}

resource "aws_opensearchserverless_security_policy" "network" {
  name = "firehose-aoss-network"
  type = "network"

  policy = jsonencode([
    {
      Description     = "Allow Kinesis Data Firehose to access the collection endpoint"
      AllowFromPublic = false
      SourceServices  = ["firehose.amazonaws.com"]

      Rules = [
        {
          ResourceType = "collection"
          Resource     = ["collection/${var.collection_name}"]
        }
      ]
    }
  ])
}

resource "aws_opensearchserverless_collection" "this" {
  name             = var.collection_name
  type             = "TIMESERIES"
  standby_replicas = "ENABLED"

  depends_on = [
    aws_opensearchserverless_security_policy.encryption,
    aws_opensearchserverless_security_policy.network
  ]
}

resource "aws_opensearchserverless_access_policy" "firehose" {
  name = "firehose-aoss-data-access"
  type = "data"

  policy = jsonencode([
    {
      Description = "Allow Firehose to write documents to the configured index"
      Principal   = [aws_iam_role.firehose.arn]

      Rules = [
        {
          ResourceType = "collection"
          Resource     = ["collection/${var.collection_name}"]
          Permission   = ["aoss:DescribeCollectionItems"]
        },
        {
          ResourceType = "index"
          Resource     = ["index/${var.collection_name}/${var.index_name}"]
          Permission = [
            "aoss:CreateIndex",
            "aoss:DescribeIndex",
            "aoss:UpdateIndex",
            "aoss:WriteDocument"
          ]
        }
      ]
    }
  ])
}

resource "aws_kinesis_firehose_delivery_stream" "this" {
  name        = var.delivery_stream_name
  destination = "opensearchserverless"

  server_side_encryption {
    enabled  = true
    key_type = "CUSTOMER_MANAGED_CMK"
    key_arn  = aws_kms_key.firehose.arn
  }

  opensearchserverless_configuration {
    role_arn            = aws_iam_role.firehose.arn
    collection_endpoint = aws_opensearchserverless_collection.this.collection_endpoint
    index_name          = var.index_name

    buffering_interval = 60
    buffering_size     = 5
    retry_duration     = 300
    s3_backup_mode     = "FailedDocumentsOnly"

    cloudwatch_logging_options {
      enabled         = true
      log_group_name  = aws_cloudwatch_log_group.firehose.name
      log_stream_name = aws_cloudwatch_log_stream.aoss_delivery.name
    }

    s3_configuration {
      role_arn           = aws_iam_role.firehose.arn
      bucket_arn         = aws_s3_bucket.backup.arn
      buffering_interval = 300
      buffering_size     = 5
      compression_format = "GZIP"
      kms_key_arn        = aws_kms_key.s3_backup.arn

      prefix              = "firehose-backup/year=!{timestamp:yyyy}/month=!{timestamp:MM}/day=!{timestamp:dd}/hour=!{timestamp:HH}/"
      error_output_prefix = "firehose-errors/!{firehose:error-output-type}/year=!{timestamp:yyyy}/month=!{timestamp:MM}/day=!{timestamp:dd}/hour=!{timestamp:HH}/"

      cloudwatch_logging_options {
        enabled         = true
        log_group_name  = aws_cloudwatch_log_group.firehose.name
        log_stream_name = aws_cloudwatch_log_stream.s3_backup.name
      }
    }
  }

  depends_on = [
    aws_iam_role_policy.firehose,
    aws_opensearchserverless_access_policy.firehose,
    aws_opensearchserverless_security_policy.network
  ]
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  type        = string
  description = "AWS region to deploy the RDS PostgreSQL instance."
  default     = "us-east-1"
}

variable "name" {
  type        = string
  description = "Name prefix for the PostgreSQL RDS resources."
  default     = "postgres"
}

variable "vpc_id" {
  type        = string
  description = "VPC ID where the RDS instance will be deployed."
}

variable "private_subnet_ids" {
  type        = list(string)
  description = "Private subnet IDs for the RDS subnet group. Use subnets in at least two Availability Zones."
}

variable "allowed_security_group_ids" {
  type        = list(string)
  description = "Security group IDs allowed to connect to PostgreSQL on port 5432."
}

variable "db_name" {
  type        = string
  description = "Initial PostgreSQL database name."
  default     = "appdb"
}

variable "master_username" {
  type        = string
  description = "Master username for PostgreSQL."
  default     = "dbadmin"
  sensitive   = true
}

variable "postgres_major_version" {
  type        = string
  description = "PostgreSQL major version for the DB parameter group family."
  default     = "16"
}

variable "engine_version" {
  type        = string
  description = "Optional exact PostgreSQL engine version."
  default     = null
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

resource "aws_kms_key" "rds" {
  description             = "KMS key for ${var.name} RDS PostgreSQL encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootAccountAdministration"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowRDSServiceUse"
        Effect = "Allow"
        Principal = {
          Service = "rds.${data.aws_region.current.name}.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey",
          "kms:CreateGrant",
          "kms:ListGrants",
          "kms:RevokeGrant"
        ]
        Resource = "*"
      }
    ]
  })

  tags = {
    Name = "${var.name}-rds-kms"
  }
}

resource "aws_kms_alias" "rds" {
  name          = "alias/${var.name}-rds"
  target_key_id = aws_kms_key.rds.key_id
}

resource "aws_db_subnet_group" "postgres" {
  name       = "${var.name}-subnet-group"
  subnet_ids = var.private_subnet_ids

  tags = {
    Name = "${var.name}-subnet-group"
  }
}

resource "aws_security_group" "postgres" {
  name        = "${var.name}-postgres-sg"
  description = "Security group for ${var.name} PostgreSQL RDS"
  vpc_id      = var.vpc_id

  tags = {
    Name = "${var.name}-postgres-sg"
  }
}

resource "aws_vpc_security_group_ingress_rule" "postgres_from_allowed_sgs" {
  for_each = toset(var.allowed_security_group_ids)

  security_group_id            = aws_security_group.postgres.id
  referenced_security_group_id = each.value
  ip_protocol                  = "tcp"
  from_port                    = 5432
  to_port                      = 5432
  description                  = "Allow PostgreSQL from approved application security group"
}

resource "aws_cloudwatch_log_group" "postgresql" {
  name              = "/aws/rds/instance/${var.name}/postgresql"
  retention_in_days = 365
  kms_key_id        = aws_kms_key.rds.arn

  tags = {
    Name = "${var.name}-postgresql-logs"
  }
}

resource "aws_cloudwatch_log_group" "upgrade" {
  name              = "/aws/rds/instance/${var.name}/upgrade"
  retention_in_days = 365
  kms_key_id        = aws_kms_key.rds.arn

  tags = {
    Name = "${var.name}-upgrade-logs"
  }
}

resource "aws_iam_role" "rds_enhanced_monitoring" {
  name = "${var.name}-rds-enhanced-monitoring-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "monitoring.rds.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name = "${var.name}-rds-enhanced-monitoring-role"
  }
}

resource "aws_iam_role_policy_attachment" "rds_enhanced_monitoring" {
  role       = aws_iam_role.rds_enhanced_monitoring.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonRDSEnhancedMonitoringRole"
}

resource "aws_db_parameter_group" "postgres" {
  name        = "${var.name}-postgres${var.postgres_major_version}"
  family      = "postgres${var.postgres_major_version}"
  description = "Secure PostgreSQL parameter group for ${var.name}"

  parameter {
    name  = "rds.force_ssl"
    value = "1"
  }

  tags = {
    Name = "${var.name}-postgres-parameter-group"
  }
}

resource "aws_db_instance" "postgres" {
  identifier = var.name

  engine         = "postgres"
  engine_version = var.engine_version
  instance_class = "db.t4g.large"

  db_name  = var.db_name
  username = var.master_username

  manage_master_user_password   = true
  master_user_secret_kms_key_id  = aws_kms_key.rds.arn

  allocated_storage     = 100
  max_allocated_storage = 1000
  storage_type          = "gp3"
  storage_encrypted     = true
  kms_key_id            = aws_kms_key.rds.arn

  db_subnet_group_name   = aws_db_subnet_group.postgres.name
  vpc_security_group_ids = [aws_security_group.postgres.id]
  publicly_accessible    = false
  port                   = 5432

  multi_az               = true
  backup_retention_period = 7
  backup_window           = "03:00-04:00"
  maintenance_window      = "sun:04:00-sun:05:00"
  copy_tags_to_snapshot   = true
  delete_automated_backups = false
  deletion_protection     = true
  skip_final_snapshot     = false
  final_snapshot_identifier = "${var.name}-final-snapshot"

  auto_minor_version_upgrade = true
  allow_major_version_upgrade = false
  apply_immediately           = false

  parameter_group_name = aws_db_parameter_group.postgres.name

  enabled_cloudwatch_logs_exports = [
    "postgresql",
    "upgrade"
  ]

  monitoring_interval = 60
  monitoring_role_arn = aws_iam_role.rds_enhanced_monitoring.arn

  performance_insights_enabled          = true
  performance_insights_kms_key_id       = aws_kms_key.rds.arn
  performance_insights_retention_period = 7

  ca_cert_identifier = "rds-ca-rsa2048-g1"

  depends_on = [
    aws_cloudwatch_log_group.postgresql,
    aws_cloudwatch_log_group.upgrade,
    aws_iam_role_policy_attachment.rds_enhanced_monitoring
  ]

  tags = {
    Name = var.name
  }
}

output "db_instance_endpoint" {
  description = "RDS PostgreSQL endpoint."
  value       = aws_db_instance.postgres.endpoint
}

output "db_instance_port" {
  description = "RDS PostgreSQL port."
  value       = aws_db_instance.postgres.port
}

output "master_user_secret_arn" {
  description = "ARN of the Secrets Manager secret containing the managed master user password."
  value       = aws_db_instance.postgres.master_user_secret[0].secret_arn
  sensitive   = true
}

