variable "db_name" {
  description = "Initial PostgreSQL database name."
  type        = string
  default     = "appdb"
}

variable "db_username" {
  description = "Master username for PostgreSQL."
  type        = string
  default     = "dbadmin"
  sensitive   = true
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = "${var.project_name}-main-vpc"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.project_name}-igw"
  }
}

resource "aws_subnet" "public" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(var.vpc_cidr, 8, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = true

  tags = {
    Name = "${var.project_name}-public-subnet-${count.index + 1}"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.project_name}-public-rt"
  }
}

resource "aws_route" "public_internet_access" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route_table_association" "public" {
  count = 2

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "postgres" {
  name        = "${var.project_name}-postgres-sg"
  description = "Allow trusted PostgreSQL access"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "PostgreSQL access from trusted CIDR blocks"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = var.allowed_db_cidr_blocks
  }

  tags = {
    Name = "${var.project_name}-postgres-sg"
  }
}

resource "aws_db_subnet_group" "postgres" {
  name       = "${var.project_name}-db-subnet-group"
  subnet_ids = aws_subnet.public[*].id

  tags = {
    Name = "${var.project_name}-db-subnet-group"
  }
}

resource "aws_db_instance" "postgres" {
  identifier = "${var.project_name}-postgres"

  engine         = "postgres"
  engine_version = "15.3"
  instance_class = "db.t4g.micro"

  allocated_storage = 200
  storage_type      = "gp2"
  storage_encrypted = true

  db_name  = var.db_name
  username = var.db_username

  manage_master_user_password = true

  db_subnet_group_name   = aws_db_subnet_group.postgres.name
  vpc_security_group_ids = [aws_security_group.postgres.id]
  publicly_accessible    = true

  port = 5432

  backup_retention_period = 7
  backup_window           = "03:00-04:00"
  maintenance_window      = "sun:04:00-sun:05:00"

  auto_minor_version_upgrade = true
  deletion_protection        = true
  skip_final_snapshot        = false
  final_snapshot_identifier  = "${var.project_name}-postgres-final-snapshot"

  enabled_cloudwatch_logs_exports = ["postgresql", "upgrade"]

  copy_tags_to_snapshot = true

  tags = {
    Name = "${var.project_name}-postgres"
  }
}

output "database_endpoint" {
  description = "PostgreSQL RDS endpoint for connectivity."
  value       = aws_db_instance.postgres.endpoint
}

correct_options:
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.75"

      configuration_aliases = [ aws.default, aws.west, aws.europe ]
    }
  }

  required_version = "~> 1.9.8"
}

provider "aws" {
  region = "us-east-1" # Default region
  alias  = "default"

  profile = "admin-1"

  assume_role {
    role_arn = "arn:aws:iam::590184057477:role/yicun-iac"
  }
}

provider "aws" {
  region = "us-west-1"
  alias  = "west"

  profile = "admin-1"

  assume_role {
    role_arn = "arn:aws:iam::590184057477:role/yicun-iac"
  }
}

provider "aws" {
  region = "eu-central-1"
  alias  = "europe"

  profile = "admin-1"

  assume_role {
    role_arn = "arn:aws:iam::590184057477:role/yicun-iac"
  }
}

resource "aws_iam_role" "eb_ec2_role" {
  provider = aws.default
  name = "elastic_beanstalk_ec2_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Action = "sts:AssumeRole",
        Effect = "Allow",
        Principal = {
          Service = "ec2.amazonaws.com"
        },
      },
    ]
  })
}

# Attach the AWS managed policy for Elastic Beanstalk to the role
resource "aws_iam_role_policy_attachment" "eb_managed_policy" {
  provider = aws.default
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkWebTier"
}

# Create an instance profile tied to the role
resource "aws_iam_instance_profile" "eb_ec2_profile" {
  provider = aws.default
  name = "elastic_beanstalk_ec2_profile"
  role = aws_iam_role.eb_ec2_role.name
}

resource "aws_s3_bucket" "us_west_sample_bucket" {
  provider = aws.west
  bucket_prefix = "sample-"
}

resource "aws_s3_object" "us_west_examplebucket_object" {
  provider = aws.west
  key    = "app"
  bucket = aws_s3_bucket.us_west_sample_bucket.id
  source = "./supplement/app.zip"
}

# Elastic Beanstalk application
resource "aws_elastic_beanstalk_application" "us_west" {
  provider = aws.west
  name        = "my-global-app"
  description = "A global application deployed in US-West."
}

resource "aws_elastic_beanstalk_application_version" "us_west_version" {
  provider = aws.west
  name        = "v1"
  application = aws_elastic_beanstalk_application.us_west.name
  bucket = aws_s3_object.us_west_examplebucket_object.bucket
  key    = aws_s3_object.us_west_examplebucket_object.key
}

# US-West Elastic Beanstalk Environment
resource "aws_elastic_beanstalk_environment" "us_west" {
  provider            = aws.west
  name                = "my-global-app-us-west"
  application         = aws_elastic_beanstalk_application.us_west.name
  solution_stack_name = "64bit Amazon Linux 2023 v4.3.0 running Python 3.9"

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "IamInstanceProfile"
    value     = aws_iam_instance_profile.eb_ec2_profile.name
  }
}

resource "aws_s3_bucket" "eu_sample_bucket" {
  provider = aws.europe
  bucket_prefix = "sample-"
}

resource "aws_s3_object" "eu_examplebucket_object" {
  provider = aws.europe
  key    = "app"
  bucket = aws_s3_bucket.eu_sample_bucket.id
  source = "./supplement/app.zip"
}

# Elastic Beanstalk Application (EU-Central Region)
resource "aws_elastic_beanstalk_application" "eu_central" {
  provider = aws.europe
  name        = "my-global-app"
  description = "A global application deployed in EU-Central."
}

resource "aws_elastic_beanstalk_application_version" "europe_version" {
  provider = aws.europe
  name        = "v1"
  application = aws_elastic_beanstalk_application.eu_central.name
  bucket = aws_s3_object.eu_examplebucket_object.bucket
  key    = aws_s3_object.eu_examplebucket_object.key
}

# EU-Central Elastic Beanstalk Environment
resource "aws_elastic_beanstalk_environment" "eu_central" {
  provider            = aws.europe
  name                = "my-global-app-eu-central"
  application         = aws_elastic_beanstalk_application.eu_central.name
  solution_stack_name = "64bit Amazon Linux 2023 v4.3.0 running Python 3.9"

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "IamInstanceProfile"
    value     = aws_iam_instance_profile.eb_ec2_profile.name
  }
}

# Route53 Hosted Zone for the domain
resource "aws_route53_zone" "main" {
  provider = aws.default
  name     = "myglobalapp.com"
}

# Geolocation Routing Policy Records for Route 53 to direct traffic based on location
resource "aws_route53_record" "us_west" {
  provider    = aws.default
  zone_id     = aws_route53_zone.main.zone_id
  name        = "west.myglobalapp.com"
  type        = "CNAME"
  ttl         = "60"
  set_identifier = "us-west"
  geolocation_routing_policy {
    continent = "NA"
  }
  records = [
    aws_elastic_beanstalk_environment.us_west.name
  ]
}

resource "aws_route53_record" "eu_central" {
  provider    = aws.default
  zone_id     = aws_route53_zone.main.zone_id
  name        = "central.myglobalapp.com"
  type        = "CNAME"
  ttl         = "60"
  set_identifier = "eu-central"
  geolocation_routing_policy {
    continent = "EU"
  }
  records = [
    aws_elastic_beanstalk_environment.eu_central.name
  ]
}

model_answers:
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

variable "route53_region" {
  type    = string
  default = "us-east-1"
}

variable "us_west_region" {
  type    = string
  default = "us-west-2"
}

variable "eu_central_region" {
  type    = string
  default = "eu-central-1"
}

variable "domain_name" {
  type = string
}

variable "record_name" {
  type    = string
  default = "app"
}

variable "project_name" {
  type    = string
  default = "geo-eb"
}

provider "aws" {
  region = var.route53_region
}

provider "aws" {
  alias  = "us_west"
  region = var.us_west_region
}

provider "aws" {
  alias  = "eu_central"
  region = var.eu_central_region
}

locals {
  fqdn = "${var.record_name}.${var.domain_name}"

  common_tags = {
    Project   = var.project_name
    ManagedBy = "Terraform"
  }

  geo_records = {
    us_west_north_america = {
      continent = "NA"
      target    = "us_west"
    }
    us_west_south_america = {
      continent = "SA"
      target    = "us_west"
    }
    us_west_oceania = {
      continent = "OC"
      target    = "us_west"
    }
    us_west_asia = {
      continent = "AS"
      target    = "us_west"
    }
    eu_central_europe = {
      continent = "EU"
      target    = "eu_central"
    }
    eu_central_africa = {
      continent = "AF"
      target    = "eu_central"
    }
  }
}

data "aws_availability_zones" "us_west" {
  provider = aws.us_west
  state    = "available"
}

data "aws_availability_zones" "eu_central" {
  provider = aws.eu_central
  state    = "available"
}

data "aws_elastic_beanstalk_solution_stack" "us_west" {
  provider    = aws.us_west
  most_recent = true
  name_regex  = "^64bit Amazon Linux 2023 .* running Corretto 17$"
}

data "aws_elastic_beanstalk_solution_stack" "eu_central" {
  provider    = aws.eu_central
  most_recent = true
  name_regex  = "^64bit Amazon Linux 2023 .* running Corretto 17$"
}

data "aws_elastic_beanstalk_hosted_zone" "us_west" {
  provider = aws.us_west
}

data "aws_elastic_beanstalk_hosted_zone" "eu_central" {
  provider = aws.eu_central
}

resource "aws_route53_zone" "primary" {
  name = var.domain_name

  tags = local.common_tags
}

resource "aws_iam_role" "eb_service_role" {
  name = "${var.project_name}-elastic-beanstalk-service-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "elasticbeanstalk.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "eb_enhanced_health" {
  role       = aws_iam_role.eb_service_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSElasticBeanstalkEnhancedHealth"
}

resource "aws_iam_role_policy_attachment" "eb_managed_updates" {
  role       = aws_iam_role.eb_service_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkManagedUpdatesCustomerRolePolicy"
}

resource "aws_iam_role" "eb_instance_role" {
  name = "${var.project_name}-elastic-beanstalk-ec2-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "eb_web_tier" {
  role       = aws_iam_role.eb_instance_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkWebTier"
}

resource "aws_iam_role_policy_attachment" "eb_cloudwatch_agent" {
  role       = aws_iam_role.eb_instance_role.name
  policy_arn = "arn:aws:iam::aws:policy/CloudWatchAgentServerPolicy"
}

resource "aws_iam_instance_profile" "eb_instance_profile" {
  name = "${var.project_name}-elastic-beanstalk-instance-profile"
  role = aws_iam_role.eb_instance_role.name

  tags = local.common_tags
}

resource "aws_vpc" "us_west" {
  provider             = aws.us_west
  cidr_block           = "10.10.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name        = "${var.project_name}-us-west-vpc"
    Environment = "us_west"
  })
}

resource "aws_internet_gateway" "us_west" {
  provider = aws.us_west
  vpc_id   = aws_vpc.us_west.id

  tags = merge(local.common_tags, {
    Name        = "${var.project_name}-us-west-igw"
    Environment = "us_west"
  })
}

resource "aws_subnet" "us_west_public" {
  provider                = aws.us_west
  count                   = 2
  vpc_id                  = aws_vpc.us_west.id
  cidr_block              = cidrsubnet(aws_vpc.us_west.cidr_block, 8, count.index)
  availability_zone       = data.aws_availability_zones.us_west.names[count.index]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name        = "${var.project_name}-us-west-public-${count.index + 1}"
    Environment = "us_west"
    Tier        = "public"
  })
}

resource "aws_subnet" "us_west_private" {
  provider                = aws.us_west
  count                   = 2
  vpc_id                  = aws_vpc.us_west.id
  cidr_block              = cidrsubnet(aws_vpc.us_west.cidr_block, 8, count.index + 10)
  availability_zone       = data.aws_availability_zones.us_west.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name        = "${var.project_name}-us-west-private-${count.index + 1}"
    Environment = "us_west"
    Tier        = "private"
  })
}

resource "aws_eip" "us_west_nat" {
  provider = aws.us_west
  domain   = "vpc"

  tags = merge(local.common_tags, {
    Name        = "${var.project_name}-us-west-nat-eip"
    Environment = "us_west"
  })
}

resource "aws_nat_gateway" "us_west" {
  provider      = aws.us_west
  allocation_id = aws_eip.us_west_nat.id
  subnet_id     = aws_subnet.us_west_public[0].id

  tags = merge(local.common_tags, {
    Name        = "${var.project_name}-us-west-nat"
    Environment = "us_west"
  })

  depends_on = [aws_internet_gateway.us_west]
}

resource "aws_route_table" "us_west_public" {
  provider = aws.us_west
  vpc_id   = aws_vpc.us_west.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.us_west.id
  }

  tags = merge(local.common_tags, {
    Name        = "${var.project_name}-us-west-public-rt"
    Environment = "us_west"
  })
}

resource "aws_route_table" "us_west_private" {
  provider = aws.us_west
  vpc_id   = aws_vpc.us_west.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.us_west.id
  }

  tags = merge(local.common_tags, {
    Name        = "${var.project_name}-us-west-private-rt"
    Environment = "us_west"
  })
}

resource "aws_route_table_association" "us_west_public" {
  provider       = aws.us_west
  count          = 2
  subnet_id      = aws_subnet.us_west_public[count.index].id
  route_table_id = aws_route_table.us_west_public.id
}

resource "aws_route_table_association" "us_west_private" {
  provider       = aws.us_west
  count          = 2
  subnet_id      = aws_subnet.us_west_private[count.index].id
  route_table_id = aws_route_table.us_west_private.id
}

resource "aws_security_group" "us_west_alb" {
  provider    = aws.us_west
  name        = "${var.project_name}-us-west-alb-sg"
  description = "Allow inbound HTTP traffic to Elastic Beanstalk ALB"
  vpc_id      = aws_vpc.us_west.id

  ingress {
    description = "HTTP from the internet"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description      = "HTTP from the internet over IPv6"
    from_port        = 80
    to_port          = 80
    protocol         = "tcp"
    ipv6_cidr_blocks = ["::/0"]
  }

  egress {
    description     = "HTTP to application instances"
    from_port       = 80
    to_port         = 80
    protocol        = "tcp"
    security_groups = [aws_security_group.us_west_instances.id]
  }

  tags = merge(local.common_tags, {
    Name        = "${var.project_name}-us-west-alb-sg"
    Environment = "us_west"
  })
}

resource "aws_security_group" "us_west_instances" {
  provider    = aws.us_west
  name        = "${var.project_name}-us-west-instance-sg"
  description = "Allow traffic only from the Elastic Beanstalk ALB"
  vpc_id      = aws_vpc.us_west.id

  ingress {
    description     = "Application traffic from ALB"
    from_port       = 80
    to_port         = 80
    protocol        = "tcp"
    security_groups = [aws_security_group.us_west_alb.id]
  }

  egress {
    description = "HTTPS egress for OS and platform updates"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name        = "${var.project_name}-us-west-instance-sg"
    Environment = "us_west"
  })
}

resource "aws_vpc" "eu_central" {
  provider             = aws.eu_central
  cidr_block           = "10.20.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
