resource "aws_subnet" "eu_central_private" {
  provider                = aws.eu_central
  count                   = 2
  vpc_id                  = aws_vpc.eu_central.id
  cidr_block              = cidrsubnet(aws_vpc.eu_central.cidr_block, 8, count.index + 10)
  availability_zone       = data.aws_availability_zones.eu_central.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name        = "${var.project_name}-eu-central-private-${count.index + 1}"
    Environment = "eu_central"
    Tier        = "private"
  })
}

resource "aws_eip" "eu_central_nat" {
  provider = aws.eu_central
  domain   = "vpc"

  tags = merge(local.common_tags, {
    Name        = "${var.project_name}-eu-central-nat-eip"
    Environment = "eu_central"
  })
