resource "aws_nat_gateway" "eu_central" {
  provider      = aws.eu_central
  allocation_id = aws_eip.eu_central_nat.id
  subnet_id     = aws_subnet.eu_central_public[0].id

  tags = merge(local.common_tags, {
    Name        = "${var.project_name}-eu-central-nat"
    Environment = "eu_central"
  })

  depends_on = [aws_internet_gateway.eu_central]
}

resource "aws_route_table" "eu_central_public" {
  provider = aws.eu_central
  vpc_id   = aws_vpc.eu_central.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.eu_central.id
  }

  tags = merge(local.common_tags, {
    Name        = "${var.project_name}-eu-central-public-rt"
