resource "aws_route_table_association" "eu_central_public" {
  provider       = aws.eu_central
  count          = 2
  subnet_id      = aws_subnet.eu_central_public[count.index].id
  route_table_id = aws_route_table.eu_central_public.id
}

resource "aws_route_table_association" "eu_central_private" {
