resource "aws_route53_record" "app_geo" {
  for_each = local.geo_records

  zone_id        = aws_route53_zone.primary.zone_id
  name           = local.fqdn
  type           = "A"
  set_identifier = each.key

  geolocation_routing_policy {
    continent = each.value.continent
  }

  alias {
    name = each.value.target == "us_west" ? aws_elastic_beanstalk_environment.us_west.cname : aws_elastic_beanstalk_environment.eu_central.cname
    zone_id = each.value.target == "us_west" ? data.aws_elastic_beanstalk_hosted_zone.us_west.id : data.aws_elastic_beanstalk_hosted_zone.eu_central.id
    evaluate_target_health = true
  }
}

resource "aws_route53_record" "app_default" {
  zone_id        = aws_route53_zone.primary.zone_id
  name           = local.fqdn
  type           = "A"
  set_identifier = "default-us-west"

  geolocation_routing_policy {
    country = "*"
  }

  alias {
    name                   = aws_elastic_beanstalk_environment.us_west.cname
    zone_id                = data.aws_elastic_beanstalk_hosted_zone.us_west.id
    evaluate_target_health = true
  }
}

