data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_region" "current" {}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  name_prefix          = "example-redshift"
  cluster_identifier   = "${local.name_prefix}-cluster"
  parameter_group_name = "${local.name_prefix}-pg"
  sns_topic_name       = "${local.name_prefix}-pg-events"
  sns_topic_arn        = "arn:${data.aws_partition.current.partition}:sns:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:${local.sns_topic_name}"
}

resource "random_id" "final_snapshot" {
  byte_length = 4
}

data "aws_iam_policy_document" "redshift_kms" {
  statement {
    sid    = "EnableAccountKeyAdministration"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }
}

resource "aws_kms_key" "redshift" {
  description             = "KMS key for Redshift cluster encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.redshift_kms.json
}

resource "aws_kms_alias" "redshift" {
  name          = "alias/${local.name_prefix}-cluster"
  target_key_id = aws_kms_key.redshift.key_id
}

data "aws_iam_policy_document" "sns_kms" {
  statement {
    sid    = "EnableAccountKeyAdministration"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowSNSAndRedshiftToUseKeyForTopic"
    effect = "Allow"

    principals {
      type = "Service"
      identifiers = [
        "sns.amazonaws.com",
        "redshift.amazonaws.com"
      ]
    }

    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey*"
    ]

    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "kms:EncryptionContext:aws:sns:topicArn"
      values   = [local.sns_topic_arn]
    }
  }

  statement {
    sid    = "AllowSNSAndRedshiftToDescribeKey"
    effect = "Allow"

    principals {
      type = "Service"
      identifiers = [
        "sns.amazonaws.com",
        "redshift.amazonaws.com"
      ]
    }

    actions   = ["kms:DescribeKey"]
    resources = ["*"]
  }
}

resource "aws_kms_key" "sns" {
  description             = "KMS key for encrypted SNS topic receiving Redshift events"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.sns_kms.json
}

resource "aws_kms_alias" "sns" {
  name          = "alias/${local.name_prefix}-sns-events"
  target_key_id = aws_kms_key.sns.key_id
}

resource "aws_vpc" "redshift" {
  cidr_block           = var.vpc_cidr_block
  enable_dns_hostnames = true
  enable_dns_support   = true
}

resource "aws_subnet" "private" {
  count = 2

  vpc_id                  = aws_vpc.redshift.id
  cidr_block              = cidrsubnet(var.vpc_cidr_block, 8, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false
}

resource "aws_redshift_subnet_group" "example" {
  name        = "${local.name_prefix}-subnet-group"
  description = "Private subnet group for the example Redshift cluster"
  subnet_ids  = aws_subnet.private[*].id
}

resource "aws_security_group" "redshift" {
  name        = "${local.name_prefix}-sg"
  description = "Security group for the private Redshift cluster"
  vpc_id      = aws_vpc.redshift.id

  dynamic "ingress" {
    for_each = length(var.redshift_client_cidr_blocks) > 0 ? [1] : []

    content {
      description = "Restricted Redshift client access"
      from_port   = 5439
      to_port     = 5439
      protocol    = "tcp"
      cidr_blocks = var.redshift_client_cidr_blocks
    }
  }

  egress {
    description = "Allow outbound traffic within the VPC only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr_block]
  }
}

resource "aws_redshift_parameter_group" "example" {
  name        = local.parameter_group_name
  family      = "redshift-1.0"
  description = "Example Redshift parameter group requiring SSL and user activity logging"

  parameter {
    name  = "require_ssl"
    value = "true"
  }

  parameter {
    name  = "enable_user_activity_logging"
    value = "true"
  }
}

resource "aws_redshift_cluster" "example" {
  cluster_identifier = local.cluster_identifier
  database_name      = "exampledb"
  master_username    = "redshiftadmin"

  manage_master_password = true

  node_type    = var.redshift_node_type
  cluster_type = "single-node"
  port         = 5439

  cluster_subnet_group_name = aws_redshift_subnet_group.example.name
  vpc_security_group_ids    = [aws_security_group.redshift.id]
  parameter_group_name      = aws_redshift_parameter_group.example.name

  encrypted            = true
  kms_key_id           = aws_kms_key.redshift.arn
  publicly_accessible  = false
  enhanced_vpc_routing = true

  automated_snapshot_retention_period = 7
  skip_final_snapshot                 = false
  final_snapshot_identifier           = "${local.cluster_identifier}-final-${random_id.final_snapshot.hex}"

  allow_version_upgrade       = true
  apply_immediately           = false
  preferred_maintenance_window = "sun:05:00-sun:06:00"

  logging {
    enable               = true
    log_destination_type = "cloudwatch"
    log_exports = [
      "connectionlog",
      "userlog",
      "useractivitylog"
    ]
  }
}

resource "aws_sns_topic" "redshift_parameter_group_events" {
  name              = local.sns_topic_name
  kms_master_key_id = aws_kms_key.sns.arn
}

data "aws_iam_policy_document" "sns_topic" {
  statement {
    sid    = "AllowRedshiftEventNotificationsToPublish"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["redshift.amazonaws.com"]
    }

    actions   = ["sns:Publish"]
    resources = [aws_sns_topic.redshift_parameter_group_events.arn]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }
}

resource "aws_sns_topic_policy" "redshift_events" {
  arn    = aws_sns_topic.redshift_parameter_group_events.arn
  policy = data.aws_iam_policy_document.sns_topic.json
}

resource "aws_redshift_event_subscription" "parameter_group" {
  name          = "${local.name_prefix}-pg-event-subscription"
  sns_topic_arn = aws_sns_topic.redshift_parameter_group_events.arn

  source_type = "cluster-parameter-group"
  source_ids  = [aws_redshift_parameter_group.example.name]

  enabled = true

  depends_on = [
    aws_sns_topic_policy.redshift_events
  ]
}

