variable "aws_region" {
  type        = string
  description = "AWS region to deploy the database."
  default     = "us-east-1"
}

variable "vpc_id" {
  type        = string
  description = "VPC ID where the database will be deployed."
}

variable "private_subnet_ids" {
  type        = list(string)
  description = "Private subnet IDs for the database subnet group."
}

variable "allowed_security_group_ids" {
  type        = list(string)
  description = "Security group IDs allowed to connect to the database."
  default     = []
}

variable "db_name" {
  type        = string
  description = "Initial database name."
  default     = "appdb"
}

variable "db_identifier" {
  type        = string
  description = "RDS DB instance identifier."
  default     = "app-postgres"
}

variable "db_username" {
  type        = string
  description = "Database master username. Password is managed by AWS Secrets Manager."
  default     = "dbadmin"
}

variable "db_instance_class" {
  type        = string
  description = "RDS instance class."
  default     = "db.t4g.micro"
}

locals {
  db_port = 5432

  common_tags = {
    ManagedBy = "Terraform"
    Service   = "RDS"
  }
}

resource "aws_db_subnet_group" "this" {
  name        = "${var.db_identifier}-subnet-group"
  description = "Private subnet group for ${var.db_identifier}"
  subnet_ids  = var.private_subnet_ids

  tags = local.common_tags
}

resource "aws_security_group" "db" {
  name        = "${var.db_identifier}-sg"
  description = "Security group for ${var.db_identifier}"
  vpc_id      = var.vpc_id

  dynamic "ingress" {
    for_each = toset(var.allowed_security_group_ids)

    content {
      description     = "PostgreSQL access from approved security group"
      from_port       = local.db_port
      to_port         = local.db_port
      protocol        = "tcp"
      security_groups = [ingress.value]
    }
  }

  egress {
    description = "Allow outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = local.common_tags
}

resource "aws_db_instance" "this" {
  identifier = var.db_identifier

  engine         = "postgres"
  engine_version = "16"
  instance_class = var.db_instance_class

  db_name  = var.db_name
  username = var.db_username
  port     = local.db_port

  manage_master_user_password = true

  allocated_storage     = 20
  max_allocated_storage = 100
  storage_type          = "gp3"
  storage_encrypted     = true

  db_subnet_group_name   = aws_db_subnet_group.this.name
  vpc_security_group_ids = [aws_security_group.db.id]
  publicly_accessible    = false

  backup_retention_period = 7
  backup_window           = "03:00-04:00"
  maintenance_window      = "sun:04:00-sun:05:00"
  copy_tags_to_snapshot   = true
  deletion_protection     = true
  skip_final_snapshot     = false
  final_snapshot_identifier = "${var.db_identifier}-final-snapshot"

  auto_minor_version_upgrade = true

  enabled_cloudwatch_logs_exports = [
    "postgresql",
    "upgrade"
  ]

  iam_database_authentication_enabled = true

  tags = local.common_tags
}

output "db_instance_endpoint" {
  description = "RDS database endpoint."
  value       = aws_db_instance.this.endpoint
}

output "db_instance_port" {
  description = "RDS database port."
  value       = aws_db_instance.this.port
}

output "master_user_secret_arn" {
  description = "ARN of the AWS Secrets Manager secret managed by RDS for the master user password."
  value       = aws_db_instance.this.master_user_secret[0].secret_arn
  sensitive   = true
}

