terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "aws_region" {
  description = "AWS Region used by the AWS provider."
  type        = string
  default     = "us-east-1"
}

variable "private_hosted_zone_name" {
  description = "Name of the existing Route 53 private hosted zone to associate with the VPC."
  type        = string
}

variable "vpc_id" {
  description = "ID of the VPC to associate with the private hosted zone."
  type        = string

  validation {
    condition     = can(regex("^vpc-[0-9a-f]{8,17}$", var.vpc_id))
    error_message = "The VPC ID must be a valid AWS VPC ID."
  }
}

variable "vpc_region" {
  description = "Region of the VPC to associate. Defaults to the provider region when null."
  type        = string
  default     = null
}

provider "aws" {
  region = var.aws_region
}

data "aws_route53_zone" "private" {
  name         = var.private_hosted_zone_name
  private_zone = true
}

resource "aws_route53_zone_association" "this" {
  zone_id    = data.aws_route53_zone.private.zone_id
  vpc_id     = var.vpc_id
  vpc_region = coalesce(var.vpc_region, var.aws_region)
}

