}

variable "vpc_id" {
  type = string
}

variable "private_subnet_ids" {
  type = list(string)
}

variable "allowed_client_security_group_ids" {
  type    = set(string)
  default = []
}

variable "database_name" {
  type    = string
  default = "appdb"
}

variable "db_instance_class" {
  type    = string
  default = "db.t4g.micro"
}

variable "db_engine_version" {
  type    = string
  default = "16.3"
}

variable "db_parameter_group_family" {
  type    = string
  default = "postgres16"
}

variable "db_allocated_storage" {
  type    = number
  default = 20
}

variable "db_max_allocated_storage" {
  type    = number
  default = 100
}

variable "db_port" {
  type    = number
  default = 5432
}

locals {
  common_tags = {
    ManagedBy   = "Terraform"
    Environment = "main"
  }
}

resource "aws_kms_key" "rds" {
  description             = "KMS key for main RDS encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = local.common_tags
}

resource "aws_kms_alias" "rds" {
  name          = "alias/main-rds"
  target_key_id = aws_kms_key.rds.key_id
}

resource "aws_security_group" "db" {
  name_prefix = "main-db-"
  description = "Security group for primary and replica database instances"
  vpc_id      = var.vpc_id

  tags = merge(local.common_tags, {
    Name = "main-db"
  })
}

resource "aws_vpc_security_group_ingress_rule" "db_clients" {
  for_each = var.allowed_client_security_group_ids

  security_group_id            = aws_security_group.db.id
  referenced_security_group_id = each.value
  ip_protocol                  = "tcp"
  from_port                    = var.db_port
  to_port                      = var.db_port
  description                  = "Allow database access from approved client security group"
}

resource "aws_vpc_security_group_ingress_rule" "db_self" {
  security_group_id            = aws_security_group.db.id
  referenced_security_group_id = aws_security_group.db.id
  ip_protocol                  = "tcp"
  from_port                    = var.db_port
  to_port                      = var.db_port
  description                  = "Allow database traffic between primary and replicas"
}

resource "aws_vpc_security_group_egress_rule" "db_self" {
  security_group_id            = aws_security_group.db.id
  referenced_security_group_id = aws_security_group.db.id
  ip_protocol                  = "tcp"
  from_port                    = var.db_port
  to_port                      = var.db_port
  description                  = "Allow database replication traffic between primary and replicas"
}

resource "aws_db_subnet_group" "main" {
  name       = "main-db-private"
  subnet_ids = var.private_subnet_ids

  tags = merge(local.common_tags, {
    Name = "main-db-private"
  })
}

resource "aws_db_parameter_group" "main" {
  name   = "main-postgres-ssl"
  family = var.db_parameter_group_family

  parameter {
    name         = "rds.force_ssl"
    value        = "1"
    apply_method = "pending-reboot"
  }

  tags = local.common_tags
}

resource "aws_db_instance" "primary" {
  identifier = "primary"

  engine         = "postgres"
  engine_version = var.db_engine_version
  instance_class = var.db_instance_class

  db_name  = var.database_name
  username = "dbadmin"
  port     = var.db_port

  allocated_storage     = var.db_allocated_storage
  max_allocated_storage = var.db_max_allocated_storage
  storage_type          = "gp3"
  storage_encrypted     = true
  kms_key_id            = aws_kms_key.rds.arn

  manage_master_user_password   = true
  master_user_secret_kms_key_id = aws_kms_key.rds.arn

  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.db.id]
  parameter_group_name   = aws_db_parameter_group.main.name
  publicly_accessible    = false

  backup_retention_period = 7
  backup_window           = "03:00-04:00"
  maintenance_window      = "sun:04:00-sun:05:00"

  multi_az                        = true
  deletion_protection             = true
  skip_final_snapshot             = false
