model_answers:
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  type        = string
  description = "AWS region to deploy into."
  default     = "us-east-1"
}

variable "project_name" {
  type        = string
  description = "Name prefix for resources."
  default     = "secure-sql"
}

variable "vpc_cidr" {
  type        = string
  description = "CIDR block for the database VPC."
  default     = "10.20.0.0/16"
}

variable "private_subnet_cidrs" {
  type        = list(string)
  description = "At least two private subnet CIDR blocks in different AZs."
  default     = ["10.20.1.0/24", "10.20.2.0/24"]

  validation {
    condition     = length(var.private_subnet_cidrs) >= 2
    error_message = "At least two private subnet CIDR blocks are required."
  }
}

variable "database_name" {
  type        = string
  description = "Initial PostgreSQL database name."
  default     = "appdb"
}

variable "master_username" {
  type        = string
  description = "Primary database master username."
  default     = "dbadmin"
  sensitive   = true
}

variable "db_instance_class" {
  type        = string
  description = "RDS instance class for both primary and replica."
  default     = "db.t4g.medium"
}

variable "postgres_engine_version" {
  type        = string
  description = "PostgreSQL engine version."
  default     = "16.3"
}

locals {
  name = substr(replace(lower(var.project_name), "/[^a-z0-9-]/", "-"), 0, 32)

  tags = {
    Project     = var.project_name
    ManagedBy   = "Terraform"
    Environment = "production"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "database" {
  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = merge(local.tags, {
    Name = "${local.name}-vpc"
  })
}

resource "aws_subnet" "private" {
  count = 2

  vpc_id                  = aws_vpc.database.id
  cidr_block              = var.private_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.tags, {
    Name = "${local.name}-private-${count.index + 1}"
    Tier = "private"
  })
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.database.id

  tags = merge(local.tags, {
    Name = "${local.name}-private-rt"
  })
}

resource "aws_route_table_association" "private" {
  count = 2

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

resource "aws_db_subnet_group" "database" {
  name       = "${local.name}-db-subnet-group"
  subnet_ids = aws_subnet.private[*].id

  tags = merge(local.tags, {
    Name = "${local.name}-db-subnet-group"
  })
}

resource "aws_kms_key" "rds" {
  description             = "KMS key for encrypting ${local.name} RDS storage, secrets, and performance insights"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = merge(local.tags, {
    Name = "${local.name}-rds-kms"
  })
}

resource "aws_kms_alias" "rds" {
  name          = "alias/${local.name}-rds"
  target_key_id = aws_kms_key.rds.key_id
}

resource "aws_security_group" "application" {
  name                   = "${local.name}-app-sg"
  description            = "Attach this security group to application resources that need database access"
  vpc_id                 = aws_vpc.database.id
  revoke_rules_on_delete = true

  tags = merge(local.tags, {
    Name = "${local.name}-app-sg"
  })
}

resource "aws_security_group" "database" {
  name                   = "${local.name}-db-sg"
  description            = "Restricts database access to approved application security group only"
  vpc_id                 = aws_vpc.database.id
  revoke_rules_on_delete = true

  tags = merge(local.tags, {
    Name = "${local.name}-db-sg"
  })
}

resource "aws_vpc_security_group_egress_rule" "application_to_database" {
  security_group_id            = aws_security_group.application.id
  referenced_security_group_id = aws_security_group.database.id
  ip_protocol                  = "tcp"
  from_port                    = 5432
  to_port                      = 5432
  description                  = "Allow application resources to connect to PostgreSQL"
}

resource "aws_vpc_security_group_ingress_rule" "database_from_application" {
  security_group_id            = aws_security_group.database.id
  referenced_security_group_id = aws_security_group.application.id
  ip_protocol                  = "tcp"
  from_port                    = 5432
  to_port                      = 5432
  description                  = "Allow PostgreSQL access only from application security group"
}

data "aws_iam_policy_document" "rds_enhanced_monitoring_assume_role" {
  statement {
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["monitoring.rds.amazonaws.com"]
    }

    actions = ["sts:AssumeRole"]
  }
}

resource "aws_iam_role" "rds_enhanced_monitoring" {
  name               = "${local.name}-rds-monitoring-role"
  assume_role_policy = data.aws_iam_policy_document.rds_enhanced_monitoring_assume_role.json

  tags = merge(local.tags, {
    Name = "${local.name}-rds-monitoring-role"
  })
}

resource "aws_iam_role_policy_attachment" "rds_enhanced_monitoring" {
  role       = aws_iam_role.rds_enhanced_monitoring.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonRDSEnhancedMonitoringRole"
}

resource "aws_db_parameter_group" "postgres" {
  name        = "${local.name}-postgres16"
  family      = "postgres16"
  description = "Security-focused PostgreSQL parameters for ${local.name}"

  parameter {
    name         = "rds.force_ssl"
    value        = "1"
    apply_method = "pending-reboot"
  }

  tags = merge(local.tags, {
    Name = "${local.name}-postgres16"
  })
}

resource "aws_db_instance" "primary" {
  identifier = "${local.name}-primary"

  engine         = "postgres"
  engine_version = var.postgres_engine_version
  instance_class = var.db_instance_class

  db_name  = var.database_name
  username = var.master_username

  manage_master_user_password   = true
  master_user_secret_kms_key_id  = aws_kms_key.rds.arn
  iam_database_authentication_enabled = true

  allocated_storage     = 20
  max_allocated_storage = 100
  storage_type          = "gp3"
  storage_encrypted     = true
  kms_key_id            = aws_kms_key.rds.arn

  db_subnet_group_name   = aws_db_subnet_group.database.name
  vpc_security_group_ids = [aws_security_group.database.id]
  parameter_group_name   = aws_db_parameter_group.postgres.name
  port                   = 5432
  publicly_accessible    = false

  multi_az               = true
  backup_retention_period = 7
  backup_window           = "03:00-04:00"
  maintenance_window      = "sun:04:00-sun:05:00"
  copy_tags_to_snapshot   = true
  deletion_protection     = true
  skip_final_snapshot     = false
  final_snapshot_identifier = "${local.name}-primary-final-snapshot"

  auto_minor_version_upgrade = true

  enabled_cloudwatch_logs_exports = [
    "postgresql",
    "upgrade"
  ]

  monitoring_interval = 60
  monitoring_role_arn = aws_iam_role.rds_enhanced_monitoring.arn

  performance_insights_enabled    = true
  performance_insights_kms_key_id = aws_kms_key.rds.arn

  tags = merge(local.tags, {
    Name = "${local.name}-primary"
    Role = "primary"
  })

  depends_on = [
    aws_iam_role_policy_attachment.rds_enhanced_monitoring
  ]
}

resource "aws_db_instance" "replica" {
  identifier          = "${local.name}-replica-1"
  replicate_source_db = aws_db_instance.primary.identifier
  instance_class      = var.db_instance_class

  db_subnet_group_name   = aws_db_subnet_group.database.name
  vpc_security_group_ids = [aws_security_group.database.id]
  parameter_group_name   = aws_db_parameter_group.postgres.name
  port                   = 5432
  publicly_accessible    = false

  copy_tags_to_snapshot     = true
  deletion_protection       = true
  skip_final_snapshot       = false
  final_snapshot_identifier = "${local.name}-replica-1-final-snapshot"

  auto_minor_version_upgrade = true

  enabled_cloudwatch_logs_exports = [
    "postgresql",
    "upgrade"
  ]

  monitoring_interval = 60
  monitoring_role_arn = aws_iam_role.rds_enhanced_monitoring.arn

  performance_insights_enabled    = true
  performance_insights_kms_key_id = aws_kms_key.rds.arn

  tags = merge(local.tags, {
    Name = "${local.name}-replica-1"
    Role = "read-replica"
  })

  depends_on = [
    aws_db_instance.primary,
    aws_iam_role_policy_attachment.rds_enhanced_monitoring
  ]
}

output "application_security_group_id" {
  description = "Attach this security group to application resources that require database access."
  value       = aws_security_group.application.id
}

output "primary_endpoint" {
  description = "Primary PostgreSQL endpoint."
  value       = aws_db_instance.primary.endpoint
}

output "replica_endpoint" {
  description = "Read replica PostgreSQL endpoint."
  value       = aws_db_instance.replica.endpoint
}

output "master_user_secret_arn" {
  description = "AWS Secrets Manager ARN containing the managed master user credentials."
  value       = aws_db_instance.primary.master_user_secret[0].secret_arn
  sensitive   = true
}

