}

variable "aws_region" {
  description = "AWS Region where the Lightsail managed database will be created."
  type        = string
  default     = "us-east-1"
}

variable "availability_zone" {
  description = "Availability Zone for the Lightsail managed database."
  type        = string
  default     = "us-east-1a"
}

variable "database_name" {
  description = "Name of the Lightsail managed database resource."
  type        = string
  default     = "secure-lightsail-db"
}

variable "master_database_name" {
  description = "Initial database name."
  type        = string
  default     = "appdb"
}

variable "master_username" {
  description = "Master username for the database."
  type        = string
  default     = "dbadmin"

  validation {
    condition     = can(regex("^[A-Za-z][A-Za-z0-9_]{0,15}$", var.master_username))
    error_message = "The master username must start with a letter, contain only letters, numbers, and underscores, and be 1-16 characters long."
  }
}

variable "database_blueprint_id" {
  description = "Lightsail database blueprint ID."
  type        = string
  default     = "mysql_8_0"
}

variable "database_bundle_id" {
  description = "Lightsail database bundle ID."
  type        = string
  default     = "micro_2_0"
}

resource "random_password" "master_password" {
  length           = 32
  special          = true
  override_special = "!#$%&*()-_=+[]{}<>:?"
  min_lower        = 4
  min_upper        = 4
  min_numeric      = 4
  min_special      = 4
}

resource "aws_lightsail_database" "managed" {
  relational_database_name        = var.database_name
  availability_zone               = var.availability_zone
  master_database_name            = var.master_database_name
  master_username                 = var.master_username
  master_password                 = random_password.master_password.result
  relational_database_blueprint_id = var.database_blueprint_id
  relational_database_bundle_id    = var.database_bundle_id

  publicly_accessible        = false
  backup_retention_enabled   = true
  preferred_backup_window    = "03:00-04:00"
  preferred_maintenance_window = "sun:04:00-sun:05:00"
  apply_immediately          = true

  tags = {
    Name        = var.database_name
    ManagedBy   = "Terraform"
    Environment = "production"
  }
}

resource "aws_secretsmanager_secret" "database_credentials" {
  name                    = "lightsail/${var.database_name}/credentials"
  description             = "Credentials for the Lightsail managed database ${var.database_name}"
  recovery_window_in_days = 30

  tags = {
    Name        = "lightsail-${var.database_name}-credentials"
    ManagedBy   = "Terraform"
    Environment = "production"
  }
}

resource "aws_secretsmanager_secret_version" "database_credentials" {
  secret_id = aws_secretsmanager_secret.database_credentials.id

  secret_string = jsonencode({
    engine   = aws_lightsail_database.managed.engine
    host     = aws_lightsail_database.managed.master_endpoint_address
    port     = aws_lightsail_database.managed.master_endpoint_port
    dbname   = var.master_database_name
    username = var.master_username
    password = random_password.master_password.result
  })
}

output "lightsail_database_name" {
  description = "Lightsail managed database name."
  value       = aws_lightsail_database.managed.relational_database_name
}

output "lightsail_database_endpoint" {
  description = "Lightsail managed database endpoint."
  value       = aws_lightsail_database.managed.master_endpoint_address
}

output "database_credentials_secret_arn" {
  description = "ARN of the Secrets Manager secret containing database credentials."
  value       = aws_secretsmanager_secret.database_credentials.arn
}

