resource "aws_kms_key" "rds" {
  description             = "KMS key for ${var.project_name} RDS encryption and managed secret"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = merge(local.tags, {
    Name = "${var.project_name}-rds-kms-key"
  })
}

resource "aws_kms_alias" "rds" {
  name          = "alias/${var.project_name}-rds"
  target_key_id = aws_kms_key.rds.key_id
}

resource "aws_db_subnet_group" "database" {
  name        = "${var.project_name}-db-subnet-group"
  description = "Private subnets for relational database"
  subnet_ids  = [aws_subnet.private_app.id, aws_subnet.private_db.id]

  tags = merge(local.tags, {
    Name = "${var.project_name}-db-subnet-group"
  })
}

resource "aws_db_instance" "database" {
  identifier                          = "${var.project_name}-postgres"
  engine                              = "postgres"
  instance_class                      = var.db_instance_class
  allocated_storage                   = 20
  max_allocated_storage               = 100
  storage_type                        = "gp3"
  storage_encrypted                   = true
  kms_key_id                          = aws_kms_key.rds.arn
  db_name                             = local.database_name
  username                            = local.database_username
  manage_master_user_password         = true
  master_user_secret_kms_key_id       = aws_kms_key.rds.arn
  db_subnet_group_name                = aws_db_subnet_group.database.name
  vpc_security_group_ids              = [aws_security_group.database.id]
  availability_zone                   = data.aws_availability_zones.available.names[1]
  publicly_accessible                 = false
  multi_az                            = false
  backup_retention_period             = 7
  backup_window                       = "03:00-04:00"
  maintenance_window                  = "sun:04:00-sun:05:00"
  auto_minor_version_upgrade          = true
  deletion_protection                 = true
  skip_final_snapshot                 = false
  final_snapshot_identifier           = "${var.project_name}-postgres-final-${random_id.snapshot.hex}"
  copy_tags_to_snapshot               = true
  iam_database_authentication_enabled = true

  tags = merge(local.tags, {
    Name = "${var.project_name}-postgres"
    Role = "relational-database"
  })
}

resource "aws_instance" "app" {
  ami                         = data.aws_ami.amazon_linux_2023.id
  instance_type               = var.app_instance_type
  subnet_id                   = aws_subnet.private_app.id
  private_ip                  = local.app_private_ip
  associate_public_ip_address = false
  vpc_security_group_ids      = [aws_security_group.app.id]
  iam_instance_profile        = aws_iam_instance_profile.app.name
  monitoring                  = true

  metadata_options {
    http_endpoint               = "enabled"
    http_tokens                 = "required"
    http_put_response_hop_limit = 1
  }

  root_block_device {
    encrypted   = true
    volume_type = "gp3"
  }

  user_data_replace_on_change = true

  user_data = <<-EOF
    #!/bin/bash
    set -euo pipefail

    systemctl enable --now amazon-ssm-agent || true

    mkdir -p /opt/app

    cat > /opt/app/server.py <<'PY'
    from http.server import BaseHTTPRequestHandler, HTTPServer
    import os

    DB_ENDPOINT = os.environ.get("DB_ENDPOINT", "not-configured")
    DB_SECRET_ARN = os.environ.get("DB_SECRET_ARN", "not-configured")

    class Handler(BaseHTTPRequestHandler):
        def do_GET(self):
            body = (
                "Application server is running.\\n"
                f"Database endpoint: {DB_ENDPOINT}\\n"
                f"Database secret ARN: {DB_SECRET_ARN}\\n"
            ).encode()
            self.send_response(200)
            self.send_header("Content-Type", "text/plain")
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)

    HTTPServer(("0.0.0.0", 8080), Handler).serve_forever()
    PY

    cat > /etc/systemd/system/app-server.service <<'SERVICE'
    [Unit]
    Description=Private Application Server
    After=network-online.target
    Wants=network-online.target

    [Service]
    Type=simple
    User=ec2-user
    Environment="DB_ENDPOINT=${aws_db_instance.database.address}"
    Environment="DB_SECRET_ARN=${aws_db_instance.database.master_user_secret[0].secret_arn}"
    ExecStart=/usr/bin/python3 /opt/app/server.py
    Restart=always
    RestartSec=5

    [Install]
    WantedBy=multi-user.target
    SERVICE

    systemctl daemon-reload
    systemctl enable --now app-server
  EOF

  depends_on = [
    aws_iam_role_policy_attachment.app_ssm,
    aws_iam_role_policy_attachment.app_secrets,
    aws_vpc_endpoint.ssm,
    aws_vpc_endpoint.ssmmessages,
    aws_vpc_endpoint.ec2messages,
    aws_vpc_endpoint.secretsmanager
  ]

  tags = merge(local.tags, {
    Name = "${var.project_name}-app-server"
    Role = "application-server"
    Tier = "private"
  })
}

resource "aws_instance" "web" {
  ami                         = data.aws_ami.amazon_linux_2023.id
  instance_type               = var.web_instance_type
  subnet_id                   = aws_subnet.public_web.id
  private_ip                  = local.web_private_ip
  associate_public_ip_address = true
  vpc_security_group_ids      = [aws_security_group.web.id]
  iam_instance_profile        = aws_iam_instance_profile.web.name
  monitoring                  = true

  metadata_options {
    http_endpoint               = "enabled"
    http_tokens                 = "required"
    http_put_response_hop_limit = 1
  }

  root_block_device {
    encrypted   = true
    volume_type = "gp3"
  }

  user_data_replace_on_change = true

  user_data = <<-EOF
    #!/bin/bash
    set -euo pipefail

    dnf -y update
    dnf -y install nginx

    cat > /etc/nginx/conf.d/app.conf <<'NGINX'
    server {
        listen 80 default_server;
        server_name _;

        location / {
            proxy_pass http://${local.app_private_ip}:8080;
            proxy_http_version 1.1;
            proxy_set_header Host $host;
            proxy_set_header X-Real-IP $remote_addr;
            proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        }
    }
    NGINX

    rm -f /etc/nginx/conf.d/default.conf
    systemctl enable --now nginx
    systemctl enable --now amazon-ssm-agent || true
  EOF

  depends_on = [
    aws_instance.app,
    aws_iam_role_policy_attachment.web_ssm
  ]

  tags = merge(local.tags, {
    Name = "${var.project_name}-webserver"
    Role = "webserver"
    Tier = "public"
  })
}

output "webserver_url" {
  value = "http://${aws_instance.web.public_dns}"
}

