    "book travel",
    "reserve a flight",
    "I want to book a trip",
    "I want to book travel",
    "I need to travel to {DestinationCity}",
    "book a {TripType} trip",
    "book a {TripType} trip to {DestinationCity}",
    "reserve a flight from {OriginCity} to {DestinationCity}",
    "fly from {OriginCity} to {DestinationCity} on {DepartureDate}",
    "I need a {CabinClass} ticket to {DestinationCity}"
  ]

  confirmation_prompt {
    max_attempts  = 2
    response_card = local.confirmation_response_card

    message {
      content_type = "PlainText"
      content      = "Please confirm that you want to book a {TripType} trip from {OriginCity} to {DestinationCity} departing on {DepartureDate} in {CabinClass}."
    }

