      content      = "<speak>Please confirm that you want to book a <say-as interpret-as=\"characters\">{TripType}</say-as> trip from {OriginCity} to {DestinationCity} departing on {DepartureDate} in {CabinClass}.</speak>"
    }
  }

  rejection_statement {
    response_card = local.abort_response_card

    message {
      content_type = "PlainText"
      content      = "Okay, I will not book this trip."
    }

