      content_type = "SSML"
      content      = "<speak>Okay, I will not book this trip.</speak>"
    }
  }

  conclusion_statement {
    response_card = local.trip_help_response_card

    message {
      content_type = "PlainText"
      content      = "Thanks. Your trip booking request has been captured and is ready for processing."
    }

