    value_elicitation_prompt {
      max_attempts  = 2
      response_card = local.trip_help_response_card

      message {
        content_type = "PlainText"
        content      = "Is this a one way or round trip?"
      }

      message {
        content_type = "SSML"
        content      = "<speak>Is this a one way or round trip?</speak>"
      }
    }
  }

  slot {
    name                = "OriginCity"
