    ]

    value_elicitation_prompt {
      max_attempts  = 2
      response_card = local.trip_help_response_card

      message {
        content_type = "PlainText"
        content      = "What city are you leaving from?"
      }

      message {
        content_type = "SSML"
        content      = "<speak>What city are you leaving from?</speak>"
      }
    }
  }

  slot {
    name                = "DestinationCity"
    description         = "Destination city for the trip."
    priority            = 3
    slot_constraint     = "Required"
    slot_type           = aws_lex_slot_type.trip_city.name
    slot_type_version   = aws_lex_slot_type.trip_city.version
    response_card       = local.trip_help_response_card
    obfuscation_setting = "DEFAULT_OBFUSCATION"

    sample_utterances = [
      "{DestinationCity}",
      "I am going to {DestinationCity}",
      "traveling to {DestinationCity}"
    ]

    value_elicitation_prompt {
      max_attempts  = 2
      response_card = local.trip_help_response_card

      message {
        content_type = "PlainText"
        content      = "What city are you traveling to?"
      }

      message {
        content_type = "SSML"
        content      = "<speak>What city are you traveling to?</speak>"
      }
    }
  }

  slot {
    name                = "DepartureDate"
    description         = "Departure date for the trip."
    priority            = 4
    slot_constraint     = "Required"
    slot_type           = "AMAZON.DATE"
    response_card       = local.trip_help_response_card
    obfuscation_setting = "DEFAULT_OBFUSCATION"

    sample_utterances = [
      "{DepartureDate}",
