      "leaving {DepartureDate}"
    ]

    value_elicitation_prompt {
      max_attempts  = 2
      response_card = local.trip_help_response_card

      message {
        content_type = "PlainText"
        content      = "What date do you want to depart?"
      }

      message {
        content_type = "SSML"
        content      = "<speak>What date do you want to depart?</speak>"
      }
    }
  }

  slot {
    name                = "ReturnDate"
    description         = "Return date for round trip travel."
    priority            = 5
    slot_constraint     = "Optional"
    slot_type           = "AMAZON.DATE"
    response_card       = local.trip_help_response_card
    obfuscation_setting = "DEFAULT_OBFUSCATION"

