      response_card = local.trip_help_response_card

      message {
        content_type = "PlainText"
        content      = "If this is a round trip, what date do you want to return?"
      }

      message {
        content_type = "SSML"
        content      = "<speak>If this is a round trip, what date do you want to return?</speak>"
      }
    }
  }

  slot {
    name                = "CabinClass"
    description         = "Cabin class for the trip."
