terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  type        = string
  description = "AWS Region in which to create the VPC."
  default     = "us-east-1"
}

variable "vpc_cidr_block" {
  type        = string
  description = "CIDR block for the VPC."
  default     = "10.0.0.0/16"

  validation {
    condition     = can(cidrhost(var.vpc_cidr_block, 0))
    error_message = "vpc_cidr_block must be a valid IPv4 CIDR block."
  }
}

variable "route_destination_cidr_block" {
  type        = string
  description = "Specific destination CIDR block to route through the Internet Gateway."
  default     = "198.51.100.0/24"

  validation {
    condition     = can(cidrhost(var.route_destination_cidr_block, 0)) && var.route_destination_cidr_block != "0.0.0.0/0"
    error_message = "route_destination_cidr_block must be a valid IPv4 CIDR block and should not be 0.0.0.0/0."
  }
}

variable "tags" {
  type        = map(string)
  description = "Tags to apply to created resources."
  default = {
    Environment = "production"
    ManagedBy   = "terraform"
  }
}

resource "aws_vpc" "this" {
  cidr_block           = var.vpc_cidr_block
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(var.tags, {
    Name = "secure-vpc"
  })
}

resource "aws_internet_gateway" "this" {
  vpc_id = aws_vpc.this.id

  tags = merge(var.tags, {
    Name = "secure-vpc-igw"
  })
}

resource "aws_route_table" "custom" {
  vpc_id = aws_vpc.this.id

  tags = merge(var.tags, {
    Name = "secure-vpc-custom-route-table"
  })
}

resource "aws_route" "specific_cidr_via_igw" {
  route_table_id         = aws_route_table.custom.id
  destination_cidr_block = var.route_destination_cidr_block
  gateway_id             = aws_internet_gateway.this.id
}

