model_answers:
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region for resources"
  type        = string
  default     = "us-east-1"
}

variable "redshift_master_username" {
  description = "Master username for the Redshift cluster"
  type        = string
  default     = "admin"
}

variable "redshift_master_password" {
  description = "Master password for the Redshift cluster (must be 8-64 chars, include lowercase, uppercase, number, symbol)"
  type        = string
  sensitive   = true
}

data "aws_caller_identity" "current" {}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = "redshift-vpc"
  }
}

# Subnets (in different AZs for high availability)
resource "aws_subnet" "subnet_a" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "${var.aws_region}a"

  tags = {
    Name = "redshift-subnet-a"
  }
}

resource "aws_subnet" "subnet_b" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "${var.aws_region}b"

  tags = {
    Name = "redshift-subnet-b"
  }
}

# Redshift Subnet Group
resource "aws_redshift_subnet_group" "main" {
  name       = "redshift-subnet-group"
  subnet_ids = [aws_subnet.subnet_a.id, aws_subnet.subnet_b.id]

  tags = {
    Name = "redshift-subnet-group"
  }
}

# Security Group for Redshift (least privilege)
resource "aws_security_group" "redshift" {
  name        = "redshift-sg"
  description = "Security group for Redshift cluster"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Redshift port from VPC"
    from_port   = 5439
    to_port     = 5439
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/16"]
  }

  egress {
    description = "Allow all outbound"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "redshift-sg"
  }
}

# Redshift Cluster
resource "aws_redshift_cluster" "main" {
  cluster_identifier         = "redshift-cluster-example"
  database_name              = "mydatabase"
  master_username            = var.redshift_master_username
  master_password            = var.redshift_master_password
  node_type                  = "dc2.large"
  number_of_nodes             = 2
  cluster_subnet_group_name  = aws_redshift_subnet_group.main.name
  vpc_security_group_ids     = [aws_security_group.redshift.id]
  port                       = 5439

  publicly_accessible        = false
  encrypted                  = true
  apply_immediately          = false
  skip_final_snapshot        = true
  enhanced_vpc_routing       = true

  logging {
    enable        = true
    s3_key_prefix = "redshift-logs"
  }

  tags = {
    Name = "redshift-cluster-example"
  }
}

# Redshift Endpoint Access
resource "aws_redshift_endpoint_access" "main" {
  cluster_identifier     = aws_redshift_cluster.main.id
  resource_owner        = data.aws_caller_identity.current.account_id
  subnet_group_name     = aws_redshift_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.redshift.id]
}

