terraform {
  required_version = ">= 1.6.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.5"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  type    = string
  default = "us-east-1"
}

variable "availability_zone_suffix" {
  type    = string
  default = "a"
}

variable "project_name" {
  type    = string
  default = "lightsail-mysql"

  validation {
    condition     = can(regex("^[a-z][a-z0-9-]{2,30}$", var.project_name))
    error_message = "project_name must be 3-31 characters, start with a lowercase letter, and contain only lowercase letters, numbers, and hyphens."
  }
}

variable "ssh_public_key" {
  type      = string
  sensitive = true

  validation {
    condition     = can(regex("^ssh-(rsa|ed25519) ", trimspace(var.ssh_public_key)))
    error_message = "ssh_public_key must be a valid OpenSSH public key."
  }
}

variable "allowed_ssh_ipv4_cidrs" {
  type = list(string)

  validation {
    condition = alltrue([
      for cidr in var.allowed_ssh_ipv4_cidrs :
      can(cidrhost(cidr, 0)) && cidr != "0.0.0.0/0"
    ])
    error_message = "allowed_ssh_ipv4_cidrs must contain valid CIDR blocks and must not include 0.0.0.0/0."
  }
}

variable "instance_bundle_id" {
  type    = string
  default = "nano_3_0"
}

variable "instance_blueprint_id" {
  type    = string
  default = "ubuntu_22_04"
}

variable "database_bundle_id" {
  type    = string
  default = "micro_2_0"
}

variable "database_blueprint_id" {
  type    = string
  default = "mysql_8_0"
}

variable "mysql_database_name" {
  type    = string
  default = "appdb"

  validation {
    condition     = can(regex("^[A-Za-z][A-Za-z0-9_]{0,63}$", var.mysql_database_name))
    error_message = "mysql_database_name must start with a letter and contain only letters, numbers, and underscores."
  }
}

variable "mysql_master_username" {
  type    = string
  default = "dbadmin"

  validation {
    condition     = can(regex("^[A-Za-z][A-Za-z0-9]{0,15}$", var.mysql_master_username)) && !contains(["root", "admin"], lower(var.mysql_master_username))
    error_message = "mysql_master_username must start with a letter, contain only letters and numbers, be 1-16 characters, and must not be root or admin."
  }
}

locals {
  availability_zone = "${var.aws_region}${var.availability_zone_suffix}"
  name_prefix       = var.project_name

  tags = {
    Project     = var.project_name
    ManagedBy   = "Terraform"
    Environment = "production"
  }
}

resource "random_password" "mysql_master" {
  length  = 32
  special = false
}

resource "aws_kms_key" "secrets" {
  description             = "KMS key for ${local.name_prefix} MySQL credentials"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = local.tags
}

resource "aws_kms_alias" "secrets" {
  name          = "alias/${local.name_prefix}-secrets"
  target_key_id = aws_kms_key.secrets.key_id
}

resource "aws_secretsmanager_secret" "mysql_credentials" {
  name                    = "${local.name_prefix}/mysql/master-credentials"
  description             = "Master credentials for the Lightsail MySQL database"
  kms_key_id              = aws_kms_key.secrets.arn
  recovery_window_in_days = 30

  tags = local.tags
}

resource "aws_lightsail_database" "mysql" {
  relational_database_name = "${local.name_prefix}-mysql"
  availability_zone        = local.availability_zone
  blueprint_id             = var.database_blueprint_id
  bundle_id                = var.database_bundle_id

  master_database_name = var.mysql_database_name
  master_username      = var.mysql_master_username
  master_password      = random_password.mysql_master.result

  publicly_accessible      = false
  backup_retention_enabled = true
  apply_immediately        = true

  skip_final_snapshot = false
  final_snapshot_name = "${local.name_prefix}-mysql-final-snapshot"

  preferred_backup_window      = "03:00-04:00"
  preferred_maintenance_window = "sun:04:00-sun:05:00"

  tags = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "mysql_credentials" {
  secret_id = aws_secretsmanager_secret.mysql_credentials.id

  secret_string = jsonencode({
    engine   = "mysql"
    host     = aws_lightsail_database.mysql.master_endpoint_address
    port     = aws_lightsail_database.mysql.master_endpoint_port
    dbname   = var.mysql_database_name
    username = var.mysql_master_username
    password = random_password.mysql_master.result
  })
}

resource "aws_lightsail_key_pair" "instance" {
  name       = "${local.name_prefix}-ssh-key"
  public_key = trimspace(var.ssh_public_key)
}

resource "aws_lightsail_instance" "app" {
  name              = "${local.name_prefix}-instance"
  availability_zone = local.availability_zone
  blueprint_id      = var.instance_blueprint_id
  bundle_id         = var.instance_bundle_id
  key_pair_name     = aws_lightsail_key_pair.instance.name

  user_data = <<-CLOUD_INIT
    #cloud-config
    package_update: true
    package_upgrade: true
    packages:
      - mysql-client
      - ca-certificates
    write_files:
      - path: /etc/lightsail-mysql/connection.env
        owner: root:root
        permissions: "0640"
        content: |
          MYSQL_HOST="${aws_lightsail_database.mysql.master_endpoint_address}"
          MYSQL_PORT="${aws_lightsail_database.mysql.master_endpoint_port}"
          MYSQL_DATABASE="${var.mysql_database_name}"
          MYSQL_USERNAME="${var.mysql_master_username}"
          MYSQL_SECRET_ARN="${aws_secretsmanager_secret.mysql_credentials.arn}"
    runcmd:
      - chmod 0750 /etc/lightsail-mysql
  CLOUD_INIT

  tags = local.tags

  depends_on = [
    aws_secretsmanager_secret_version.mysql_credentials
  ]
}

resource "aws_lightsail_instance_public_ports" "app" {
  instance_name = aws_lightsail_instance.app.name

  port_info {
    protocol  = "tcp"
    from_port = 22
    to_port   = 22
    cidrs     = var.allowed_ssh_ipv4_cidrs
  }
}

output "lightsail_instance_name" {
  value = aws_lightsail_instance.app.name
}

output "mysql_database_endpoint" {
  value = aws_lightsail_database.mysql.master_endpoint_address
}

output "mysql_database_port" {
  value = aws_lightsail_database.mysql.master_endpoint_port
}

output "mysql_credentials_secret_arn" {
  value = aws_secretsmanager_secret.mysql_credentials.arn
}

