  map_public_ip_on_launch = true

  tags = {
    Name = "subnet-1"
    Tier = "public"
  }
}

# Subnet 2 - Availability Zone 2
resource "aws_subnet" "subnet_2" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = "${var.aws_region}b"
  map_public_ip_on_launch = true

  tags = {
    Name = "subnet-2"
    Tier = "public"
  }
}

# DB Subnet Group
resource "aws_db_subnet_group" "main" {
  name       = "main-db-subnet-group"
  subnet_ids = [aws_subnet.subnet_1.id, aws_subnet.subnet_2.id]

  tags = {
    Name = "main-db-subnet-group"
  }
}

# Security Group for Database Access
resource "aws_security_group" "db_sg" {
  name        = "database-security-group"
  description = "Allow database access on port 3306"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "MySQL access from allowed CIDR blocks"
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = var.allowed_cidr_blocks
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "database-security-group"
  }
}

# MySQL RDS Instance
resource "aws_db_instance" "mysql" {
  identifier             = "main-mysql-db"
  engine                 = "mysql"
  engine_version         = "8.0"
  instance_class         = "db.t3.micro"
  allocated_storage      = 20
  storage_type           = "gp2"
  storage_encrypted      = true
  username               = var.db_username
  password               = var.db_password
  db_name                = "maindb"
  port                   = 3306
  publicly_accessible    = true
  vpc_security_group_ids = [aws_security_group.db_sg.id]
  db_subnet_group_name   = aws_db_subnet_group.main.name
  skip_final_snapshot    = false
  final_snapshot_identifier = "main-mysql-db-final-snapshot"
  backup_retention_period = 7
  backup_window          = "07:00-09:00"
  maintenance_window     = "sun:09:00-sun:11:00"
  multi_az               = false

  tags = {
    Name        = "main-mysql-db"
    Environment = "production"
    ManagedBy   = "terraform"
  }
}

# Output the database endpoint
output "db_endpoint" {
  description = "RDS MySQL database endpoint"
  value       = aws_db_instance.mysql.endpoint
  sensitive   = false
}

output "db_address" {
  description = "RDS MySQL database address (hostname only)"
  value       = aws_db_instance.mysql.address
}

output "db_port" {
  description = "RDS MySQL database port"
  value       = aws_db_instance.mysql.port
}

output "vpc_id" {
  description = "ID of the main VPC"
  value       = aws_vpc.main.id
}

output "subnet_ids" {
  description = "IDs of the created subnets"
  value       = [aws_subnet.subnet_1.id, aws_subnet.subnet_2.id]
}

output "security_group_id" {
  description = "ID of the database security group"
  value       = aws_security_group.db_sg.id
}

