model_answers:
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.5"
    }
  }
}

variable "name" {
  description = "Name prefix for the Application Load Balancer resources. Use 1-26 alphanumeric or hyphen characters, without leading/trailing hyphens."
  type        = string
  default     = "secure-alb"

  validation {
    condition     = can(regex("^[A-Za-z0-9](?:[A-Za-z0-9-]{0,24}[A-Za-z0-9])?$", var.name))
    error_message = "name must be 1-26 characters, contain only letters, numbers, and hyphens, and cannot start or end with a hyphen."
  }
}

variable "vpc_id" {
  description = "VPC ID where the ALB and target group will be created."
  type        = string
}

variable "subnet_ids" {
  description = "At least two subnet IDs in different Availability Zones for the ALB."
  type        = list(string)

  validation {
    condition     = length(var.subnet_ids) >= 2
    error_message = "At least two subnet IDs are required."
  }
}

variable "certificate_arn" {
  description = "ACM certificate ARN for the HTTPS listener."
  type        = string

  validation {
    condition     = length(var.certificate_arn) > 0
    error_message = "certificate_arn is required for the HTTPS listener."
  }
}

variable "internal" {
  description = "Whether the ALB is internal."
  type        = bool
  default     = false
}

variable "allowed_ingress_cidr_blocks" {
  description = "IPv4 CIDR blocks allowed to access HTTP/HTTPS listeners."
  type        = list(string)
  default     = ["0.0.0.0/0"]
}

variable "allowed_ingress_ipv6_cidr_blocks" {
  description = "IPv6 CIDR blocks allowed to access HTTP/HTTPS listeners."
  type        = list(string)
  default     = []
}

variable "target_port" {
  description = "Port used by the default target group."
  type        = number
  default     = 80
}

variable "target_protocol" {
  description = "Protocol used by the default target group."
  type        = string
  default     = "HTTP"

  validation {
    condition     = contains(["HTTP", "HTTPS"], var.target_protocol)
    error_message = "target_protocol must be either HTTP or HTTPS."
  }
}

variable "target_type" {
  description = "Target type for the default target group."
  type        = string
  default     = "ip"

  validation {
    condition     = contains(["instance", "ip", "lambda"], var.target_type)
    error_message = "target_type must be one of: instance, ip, lambda."
  }
}

variable "health_check_path" {
  description = "Health check path for HTTP/HTTPS target groups."
  type        = string
  default     = "/"
}

variable "enable_deletion_protection" {
  description = "Enable deletion protection for the ALB."
  type        = bool
  default     = true
}

variable "enable_waf" {
  description = "Create and associate an AWS WAFv2 Web ACL with AWS managed rule groups."
  type        = bool
  default     = true
}

variable "access_log_retention_days" {
  description = "Number of days to retain ALB access logs in S3."
  type        = number
  default     = 365
}

variable "tags" {
  description = "Tags to apply to resources."
  type        = map(string)
  default     = {}
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_region" "current" {}

data "aws_vpc" "selected" {
  id = var.vpc_id
}

resource "random_id" "suffix" {
  byte_length = 4
}

locals {
  name_lower       = lower(var.name)
  log_bucket_name  = substr("${local.name_lower}-access-logs-${random_id.suffix.hex}", 0, 63)
  logs_prefix      = "alb/${local.name_lower}"
  waf_metric_name  = replace(var.name, "/[^0-9A-Za-z_]/", "_")
  target_group_name = substr("${var.name}-tg", 0, 32)

  common_tags = merge(
    {
      ManagedBy = "Terraform"
      Service   = "ApplicationLoadBalancer"
    },
    var.tags
  )
}

resource "aws_s3_bucket" "alb_access_logs" {
  bucket        = local.log_bucket_name
  force_destroy = false

  tags = merge(local.common_tags, {
    Name = local.log_bucket_name
  })
}

resource "aws_s3_bucket_public_access_block" "alb_access_logs" {
  bucket = aws_s3_bucket.alb_access_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "alb_access_logs" {
  bucket = aws_s3_bucket.alb_access_logs.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_versioning" "alb_access_logs" {
  bucket = aws_s3_bucket.alb_access_logs.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "alb_access_logs" {
  bucket = aws_s3_bucket.alb_access_logs.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "alb_access_logs" {
  bucket = aws_s3_bucket.alb_access_logs.id

  rule {
    id     = "expire-alb-access-logs"
    status = "Enabled"

    filter {
      prefix = "${local.logs_prefix}/"
    }

    expiration {
      days = var.access_log_retention_days
    }

    noncurrent_version_expiration {
      noncurrent_days = var.access_log_retention_days
    }

    abort_incomplete_multipart_upload {
      days_after_initiation = 7
    }
  }

  depends_on = [aws_s3_bucket_versioning.alb_access_logs]
}

data "aws_iam_policy_document" "alb_access_logs" {
  statement {
    sid    = "DenyInsecureTransport"
    effect = "Deny"

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    actions = ["s3:*"]

    resources = [
      aws_s3_bucket.alb_access_logs.arn,
      "${aws_s3_bucket.alb_access_logs.arn}/*"
    ]

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }

  statement {
    sid    = "AllowElasticLoadBalancingLogDelivery"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["logdelivery.elasticloadbalancing.amazonaws.com"]
    }

    actions = ["s3:PutObject"]

    resources = [
      "${aws_s3_bucket.alb_access_logs.arn}/${local.logs_prefix}/AWSLogs/${data.aws_caller_identity.current.account_id}/*"
    ]
  }
}

resource "aws_s3_bucket_policy" "alb_access_logs" {
  bucket = aws_s3_bucket.alb_access_logs.id
  policy = data.aws_iam_policy_document.alb_access_logs.json

  depends_on = [
    aws_s3_bucket_public_access_block.alb_access_logs,
    aws_s3_bucket_ownership_controls.alb_access_logs
  ]
}

resource "aws_security_group" "alb" {
  name_prefix            = "${var.name}-alb-"
  description            = "Security group for ${var.name} Application Load Balancer"
  vpc_id                 = var.vpc_id
  revoke_rules_on_delete = true

  tags = merge(local.common_tags, {
    Name = "${var.name}-alb-sg"
  })
}

resource "aws_vpc_security_group_ingress_rule" "https_ipv4" {
  for_each = toset(var.allowed_ingress_cidr_blocks)

  security_group_id = aws_security_group.alb.id
  description       = "Allow HTTPS from ${each.value}"
  cidr_ipv4         = each.value
  ip_protocol       = "tcp"
  from_port         = 443
  to_port           = 443
}

resource "aws_vpc_security_group_ingress_rule" "http_ipv4" {
  for_each = toset(var.allowed_ingress_cidr_blocks)

  security_group_id = aws_security_group.alb.id
  description       = "Allow HTTP redirect from ${each.value}"
  cidr_ipv4         = each.value
  ip_protocol       = "tcp"
  from_port         = 80
  to_port           = 80
}

resource "aws_vpc_security_group_ingress_rule" "https_ipv6" {
  for_each = toset(var.allowed_ingress_ipv6_cidr_blocks)

  security_group_id = aws_security_group.alb.id
  description       = "Allow HTTPS from ${each.value}"
  cidr_ipv6         = each.value
  ip_protocol       = "tcp"
  from_port         = 443
  to_port           = 443
}

resource "aws_vpc_security_group_ingress_rule" "http_ipv6" {
  for_each = toset(var.allowed_ingress_ipv6_cidr_blocks)

  security_group_id = aws_security_group.alb.id
  description       = "Allow HTTP redirect from ${each.value}"
  cidr_ipv6         = each.value
  ip_protocol       = "tcp"
  from_port         = 80
  to_port           = 80
}

resource "aws_vpc_security_group_egress_rule" "to_targets" {
  security_group_id = aws_security_group.alb.id
  description       = "Allow ALB traffic to targets in the VPC"
  cidr_ipv4         = data.aws_vpc.selected.cidr_block
  ip_protocol       = "tcp"
  from_port         = var.target_port
  to_port           = var.target_port
}

resource "aws_lb" "this" {
  name                             = var.name
  internal                         = var.internal
  load_balancer_type               = "application"
  security_groups                  = [aws_security_group.alb.id]
  subnets                          = var.subnet_ids
  enable_deletion_protection       = var.enable_deletion_protection
  enable_http2                     = true
  drop_invalid_header_fields       = true
  desync_mitigation_mode           = "strictest"
  idle_timeout                     = 60
  enable_cross_zone_load_balancing = true

  access_logs {
    bucket  = aws_s3_bucket.alb_access_logs.id
    prefix  = local.logs_prefix
    enabled = true
  }

  tags = merge(local.common_tags, {
    Name = var.name
  })

  depends_on = [aws_s3_bucket_policy.alb_access_logs]
}

resource "aws_lb_target_group" "default" {
  name                 = local.target_group_name
  port                 = var.target_port
  protocol             = var.target_protocol
  vpc_id               = var.vpc_id
  target_type          = var.target_type
  deregistration_delay = 30

  health_check {
    enabled             = true
    protocol            = var.target_protocol
    port                = "traffic-port"
    path                = var.health_check_path
    matcher             = "200-399"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 3
    unhealthy_threshold = 3
  }

  tags = merge(local.common_tags, {
    Name = local.target_group_name
  })
}

resource "aws_lb_listener" "http_redirect" {
  load_balancer_arn = aws_lb.this.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type = "redirect"

    redirect {
      protocol    = "HTTPS"
      port        = "443"
      status_code = "HTTP_301"
    }
  }

  tags = local.common_tags
}

resource "aws_lb_listener" "https" {
  load_balancer_arn = aws_lb.this.arn
  port              = 443
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-TLS13-1-2-2021-06"
  certificate_arn   = var.certificate_arn

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.default.arn
  }

  tags = local.common_tags
}

resource "aws_wafv2_web_acl" "this" {
  count = var.enable_waf ? 1 : 0

  name        = "${var.name}-web-acl"
  description = "AWS WAFv2 Web ACL for ${var.name} Application Load Balancer"
  scope       = "REGIONAL"

  default_action {
    allow {}
  }

  rule {
    name     = "AWSManagedRulesAmazonIpReputationList"
    priority = 10

    override_action {
      none {}
    }

    statement {
      managed_rule_group_statement {
        name        = "AWSManagedRulesAmazonIpReputationList"
        vendor_name = "AWS"
      }
    }

    visibility_config {
      cloudwatch_metrics_enabled = true
      metric_name                = "${local.waf_metric_name}_IpReputation"
      sampled_requests_enabled   = true
    }
  }

  rule {
    name     = "AWSManagedRulesKnownBadInputsRuleSet"
    priority = 20

    override_action {
      none {}
    }

    statement {
      managed_rule_group_statement {
        name        = "AWSManagedRulesKnownBadInputsRuleSet"
        vendor_name = "AWS"
      }
    }

    visibility_config {
      cloudwatch_metrics_enabled = true
      metric_name                = "${local.waf_metric_name}_KnownBadInputs"
      sampled_requests_enabled   = true
    }
  }

  rule {
    name     = "AWSManagedRulesCommonRuleSet"
    priority = 30

    override_action {
      none {}
    }

    statement {
      managed_rule_group_statement {
        name        = "AWSManagedRulesCommonRuleSet"
        vendor_name = "AWS"
      }
    }

    visibility_config {
      cloudwatch_metrics_enabled = true
      metric_name                = "${local.waf_metric_name}_Common"
      sampled_requests_enabled   = true
    }
  }

  visibility_config {
    cloudwatch_metrics_enabled = true
    metric_name                = "${local.waf_metric_name}_WebACL"
    sampled_requests_enabled   = true
  }

  tags = merge(local.common_tags, {
    Name = "${var.name}-web-acl"
  })
}

resource "aws_wafv2_web_acl_association" "this" {
  count = var.enable_waf ? 1 : 0

  resource_arn = aws_lb.this.arn
  web_acl_arn  = aws_wafv2_web_acl.this[0].arn
}

output "alb_arn" {
  description = "ARN of the Application Load Balancer."
  value       = aws_lb.this.arn
}

output "alb_dns_name" {
  description = "DNS name of the Application Load Balancer."
  value       = aws_lb.this.dns_name
}

output "alb_zone_id" {
  description = "Route 53 hosted zone ID of the Application Load Balancer."
  value       = aws_lb.this.zone_id
}

output "alb_security_group_id" {
  description = "Security group ID attached to the Application Load Balancer."
  value       = aws_security_group.alb.id
}

output "default_target_group_arn" {
  description = "ARN of the default target group."
  value       = aws_lb_target_group.default.arn
}

output "access_logs_bucket_name" {
  description = "S3 bucket name for ALB access logs."
  value       = aws_s3_bucket.alb_access_logs.id
}

