model_answers:
# Define the KMS key for S3 encryption
resource "aws_kms_key" "s3_key" {
  description             = "KMS key for S3 bucket encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootAccountAccess"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowS3ServiceUsage"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })

  tags = {
    Name        = "s3-bucket-kms-key"
    Environment = "production"
    ManagedBy   = "terraform"
  }
}

# KMS key alias for easier reference
resource "aws_kms_alias" "s3_key_alias" {
  name          = "alias/s3-bucket-encryption-key"
  target_key_id = aws_kms_key.s3_key.key_id
}

# S3 bucket with security best practices
resource "aws_s3_bucket" "main" {
  bucket = "my-secure-encrypted-bucket-${data.aws_caller_identity.current.account_id}"

  tags = {
    Name        = "my-secure-encrypted-bucket"
    Environment = "production"
    ManagedBy   = "terraform"
  }
}

# Block all public access
resource "aws_s3_bucket_public_access_block" "main" {
  bucket = aws_s3_bucket.main.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Enable versioning
resource "aws_s3_bucket_versioning" "main" {
  bucket = aws_s3_bucket.main.id

  versioning_configuration {
    status = "Enabled"
  }
}

# Apply KMS server-side encryption
resource "aws_s3_bucket_server_side_encryption_configuration" "main" {
  bucket = aws_s3_bucket.main.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.s3_key.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

# Enable default encryption
resource "aws_s3_bucket_server_side_encryption_configuration" "default_encryption" {
  bucket = aws_s3_bucket.main.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }

  depends_on = [aws_s3_bucket_server_side_encryption_configuration.main]
}

# Data source for current AWS account ID
data "aws_caller_identity" "current" {}

###############################################################################
# Variables
###############################################################################
variable "vpc_id" {
  description = "VPC ID where ElastiCache will be deployed"
  type        = string
}

variable "private_subnet_ids" {
  description = "List of private subnet IDs for the ElastiCache subnet group"
  type        = list(string)
}

variable "allowed_security_group_ids" {
  description = "Security group IDs allowed to access Redis (e.g., application SG)"
  type        = list(string)
  default     = []
}

variable "redis_auth_token" {
  description = "Auth token for Redis (must be 16-128 chars, alphanumeric + symbols)"
  type        = string
  sensitive   = true
  default     = null
}

variable "environment" {
  description = "Environment name (e.g., prod, staging)"
  type        = string
  default     = "prod"
}

###############################################################################
# Data sources
###############################################################################
data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

###############################################################################
# KMS Key for encryption at rest
###############################################################################
resource "aws_kms_key" "redis" {
  description             = "KMS key for ElastiCache Redis encryption at rest"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = {
    Name        = "${var.environment}-redis-kms"
    Environment = var.environment
  }
}

resource "aws_kms_alias" "redis" {
  name          = "alias/${var.environment}-redis"
  target_key_id = aws_kms_key.redis.key_id
}

###############################################################################
# Security Group - restrictive ingress
###############################################################################
resource "aws_security_group" "redis" {
  name        = "${var.environment}-redis-sg"
  description = "Security group for ElastiCache Redis - restrict to app SG only"
  vpc_id      = var.vpc_id

  # Allow egress for replication and patching
  egress {
    description = "Allow all outbound for replication/patching"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name        = "${var.environment}-redis-sg"
    Environment = var.environment
  }

  lifecycle {
    create_before_destroy = true
  }
}

# Ingress rules - only allow from specified security groups
resource "aws_security_group_rule" "redis_ingress" {
  for_each                 = toset(var.allowed_security_group_ids)
  type                     = "ingress"
  from_port                = 6379
  to_port                  = 6379
  protocol                 = "tcp"
  source_security_group_id = each.value
  security_group_id        = aws_security_group.redis.id
  description              = "Allow Redis access from ${each.value}"
}

###############################################################################
# Subnet Group - private subnets only
###############################################################################
resource "aws_elasticache_subnet_group" "redis" {
  name        = "${var.environment}-redis-subnet-group"
  description = "Subnet group for ElastiCache Redis in private subnets"
  subnet_ids  = var.private_subnet_ids

  tags = {
    Name        = "${var.environment}-redis-subnet-group"
    Environment = var.environment
  }
}

###############################################################################
# Parameter Group - security hardening
###############################################################################
resource "aws_elasticache_parameter_group" "redis" {
  name        = "${var.environment}-redis-params"
  description = "Custom parameter group with security hardening for Redis"
  family      = "redis7"

  # Disable potentially dangerous commands
  parameter {
    name  = "rename-command"
    value = "CONFIG CONFIG_RENAMED"
  }
  parameter {
    name  = "rename-command"
    value = "FLUSHDB FLUSHDB_RENAMED"
  }
  parameter {
    name  = "rename-command"
    value = "FLUSHALL FLUSHALL_RENAMED"
  }
  parameter {
    name  = "rename-command"
    value = "KEYS KEYS_RENAMED"
  }
  parameter {
    name  = "rename-command"
    value = "DEBUG DEBUG_RENAMED"
  }
  parameter {
    name  = "rename-command"
    value = "SHUTDOWN SHUTDOWN_RENAMED"
  }

  # Memory management
  parameter {
    name  = "maxmemory-policy"
    value = "allkeys-lru"
  }

  # Slow log for monitoring
  parameter {
    name  = "slowlog-log-slower-than"
    value = "10000"
  }

  # Disable transparent huge pages issues
  parameter {
    name  = "activedefrag"
    value = "no"
  }

  tags = {
    Name        = "${var.environment}-redis-params"
    Environment = var.environment
  }

  lifecycle {
    create_before_destroy = true
  }
}

###############################################################################
# CloudWatch Log Group
###############################################################################
resource "aws_cloudwatch_log_group" "redis" {
  name              = "/aws/elasticache/${var.environment}/redis"
  retention_in_days = 30
  kms_key_id        = aws_kms_key.redis.arn

  tags = {
    Name        = "${var.environment}-redis-logs"
    Environment = var.environment
  }
}

###############################################################################
# ElastiCache Replication Group (Redis Cluster)
###############################################################################
resource "aws_elasticache_replication_group" "redis" {
  replication_group_id       = "${var.environment}-redis"
  description               = "ElastiCache Redis replication group for ${var.environment}"
  engine                    = "redis"
  engine_version            = "7.1"
  node_type                 = "cache.r7g.large"
  num_cache_clusters        = 3
  port                      = 6379
  parameter_group_name     = aws_elasticache_parameter_group.redis.name
  subnet_group_name         = aws_elasticache_subnet_group.redis.name
  security_group_ids       = [aws_security_group.redis.id]
  kms_key_id                = aws_kms_key.redis.arn
  at_rest_encryption_enabled = true
  transit_encryption_enabled = true
  auth_token                = var.redis_auth_token
  auth_token_update_strategy = "ROTATE"

  # Multi-AZ for high availability
  automatic_failover_enabled = true
  multi_az_enabled           = true

  # Maintenance and backups
  maintenance_window         = "sun:05:00-sun:09:00"
  snapshot_window            = "00:00-03:00"
  snapshot_retention_limit   = 7
  auto_minor_version_upgrade = "true"

  # Notifications
  notification_topic_arn = aws_sns_topic.redis_alerts.arn

  # Logging
  log_delivery_configuration {
    destination      = aws_cloudwatch_log_group.redis.name
    destination_type = "cloudwatch-logs"
    log_format       = "json"
    log_type         = "slow-log"
  }

  log_delivery_configuration {
    destination      = aws_cloudwatch_log_group.redis.name
    destination_type = "cloudwatch-logs"
    log_format       = "json"
    log_type         = "engine-log"
  }

  tags = {
    Name        = "${var.environment}-redis"
    Environment = var.environment
    ManagedBy   = "terraform"
  }

  lifecycle {
    ignore_changes = [num_cache_clusters]
  }
}

###############################################################################
# SNS Topic for alerts
###############################################################################
resource "aws_sns_topic" "redis_alerts" {
  name              = "${var.environment}-redis-alerts"
  kms_master_key_id = aws_kms_key.redis.id

  tags = {
    Name        = "${var.environment}-redis-alerts"
    Environment = var.environment
  }
}

resource "aws_sns_topic_policy" "redis_alerts" {
  arn    = aws_sns_topic.redis_alerts.arn
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowElastiCachePublish"
        Effect = "Allow"
        Principal = {
          Service = "elasticache.amazonaws.com"
        }
        Action   = "SNS:Publish"
        Resource = aws_sns_topic.redis_alerts.arn
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = data.aws_caller_identity.current.account_id
          }
        }
      }
    ]
  })
}

###############################################################################
# CloudWatch Alarms
###############################################################################
resource "aws_cloudwatch_metric_alarm" "redis_cpu" {
  alarm_name          = "${var.environment}-redis-high-cpu"
  alarm_description   = "Redis CPU utilization is high"
  comparison_operator = "GreaterThanThreshold"
  evaluation_periods = 3
  threshold           = 75
  metric_name         = "CPUUtilization"
  namespace           = "AWS/ElastiCache"
  period              = 300
  statistic           = "Average"
  alarm_actions       = [aws_sns_topic.redis_alerts.arn]
  ok_actions          = [aws_sns_topic.redis_alerts.arn]

  dimensions = {
    ReplicationGroup = aws_elasticache_replication_group.redis.replication_group_id
  }

  tags = {
    Name        = "${var.environment}-redis-cpu-alarm"
    Environment = var.environment
  }
}

resource "aws_cloudwatch_metric_alarm" "redis_memory" {
  alarm_name          = "${var.environment}-redis-high-memory"
  alarm_description   = "Redis memory utilization is high"
  comparison_operator = "GreaterThanThreshold"
  evaluation_periods = 3
  threshold           = 80
  metric_name         = "DatabaseMemoryUsagePercentage"
  namespace           = "AWS/ElastiCache"
  period              = 300
  statistic           = "Average"
  alarm_actions       = [aws_sns_topic.redis_alerts.arn]
  ok_actions          = [aws_sns_topic.redis_alerts.arn]

  dimensions = {
    ReplicationGroup = aws_elasticache_replication_group.redis.replication_group_id
  }

  tags = {
    Name        = "${var.environment}-redis-memory-alarm"
    Environment = var.environment
  }
}

resource "aws_cloudwatch_metric_alarm" "redis_evictions" {
  alarm_name          = "${var.environment}-redis-evictions"
  alarm_description   = "Redis evictions detected - may indicate memory pressure"
