}

variable "db_username" {
  description = "Master username for the RDS instance"
  type        = string
  default     = "airbyte_admin"
}

variable "db_password" {
  description = "Master password for the RDS instance (use AWS Secrets Manager in production)"
  type        = string
  sensitive   = true
}

# DB Subnet Group using existing public subnets
resource "aws_db_subnet_group" "airbyte_rds" {
  name       = "airbyte-rds-subnet-group"
  subnet_ids = var.public_subnet_ids

  tags = {
    Name = "airbyte-rds-subnet-group"
  }
}

