model_answers:
# Variables
variable "region" {
  description = "AWS region"
  type        = string
  default     = "us-east-1"
}

variable "stream_name" {
  description = "Name of the Firehose delivery stream"
  type        = string
  default     = "firehose-opensearch-stream"
}

variable "opensearch_collection_name" {
  description = "Name of the OpenSearch Serverless collection"
  type        = string
  default     = "firehose-target-collection"
}

provider "aws" {
  region = var.region
}

# S3 Bucket for Firehose backup
resource "aws_s3_bucket" "firehose_backup" {
  bucket = "${var.stream_name}-backup-${data.aws_caller_identity.current.account_id}"
}

resource "aws_s3_bucket_versioning" "firehose_backup" {
  bucket = aws_s3_bucket.firehose_backup.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "firehose_backup" {
  bucket = aws_s3_bucket.firehose_backup.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "firehose_backup" {
  bucket                  = aws_s3_bucket.firehose_backup.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# IAM Role for Firehose
data "aws_caller_identity" "current" {}

resource "aws_iam_role" "firehose_role" {
  name = "${var.stream_name}-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
        Action = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "sts:ExternalId" = data.aws_caller_identity.current.account_id
          }
        }
      }
    ]
  })
}

# IAM Policy for Firehose - S3 access
resource "aws_iam_role_policy" "firehose_s3_policy" {
  name = "${var.stream_name}-s3-policy"
  role = aws_iam_role.firehose_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:AbortMultipartUpload",
          "s3:GetBucketLocation",
          "s3:GetObject",
          "s3:ListBucket",
          "s3:ListBucketMultipartUploads",
          "s3:PutObject"
        ]
        Resource = [
          aws_s3_bucket.firehose_backup.arn,
          "${aws_s3_bucket.firehose_backup.arn}/*"
        ]
      }
    ]
  })
}

# IAM Policy for Firehose - OpenSearch Serverless access
resource "aws_iam_role_policy" "firehose_opensearch_policy" {
  name = "${var.stream_name}-opensearch-policy"
  role = aws_iam_role.firehose_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "aoss:CreateAccessPolicy",
          "aoss:CreateCollection",
          "aoss:CreateIndex",
          "aoss:CreateSecurityPolicy",
          "aoss:DescribeAccessPolicy",
          "aoss:DescribeCollection",
          "aoss:DescribeIndex",
          "aoss:DescribeSecurityPolicy",
          "aoss:GetAccessPolicy",
          "aoss:GetCollection",
          "aoss:GetIndex",
          "aoss:GetSecurityPolicy",
          "aoss:ListAccessPolicies",
          "aoss:ListCollections",
          "aoss:ListIndices",
          "aoss:ListSecurityPolicies",
          "aoss:UpdateAccessPolicy",
          "aoss:UpdateCollection",
          "aoss:UpdateIndex",
          "aoss:UpdateSecurityPolicy"
        ]
        Resource = aws_opensearchserverless_collection.firehose_target.arn
      }
    ]
  })
}

# OpenSearch Serverless Encryption Security Policy
resource "aws_opensearchserverless_security_policy" "encryption" {
  name = "${var.opensearch_collection_name}-encryption"
  type = "encryption"

  policy = jsonencode({
    Rules = [
      {
        Resource = "collection/${var.opensearch_collection_name}"
        ResourceType = "collection"
        AWSOwnedKey = true
      }
    ]
  })
}

# OpenSearch Serverless Network Security Policy
resource "aws_opensearchserverless_security_policy" "network" {
  name = "${var.opensearch_collection_name}-network"
  type = "network"

  policy = jsonencode([
    {
      Rules = [
        {
          ResourceType = "collection"
          Resource = [
            "collection/${var.opensearch_collection_name}"
          ]
          AllowFromPublic = true
        }
      ]
    }
  ])
}

# OpenSearch Serverless Access Policy
resource "aws_opensearchserverless_access_policy" "firehose_access" {
  name = "${var.opensearch_collection_name}-access"
  type = "data"

  policy = jsonencode([
    {
      Rules = [
        {
          ResourceType = "collection"
          Resource = [
            "collection/${var.opensearch_collection_name}"
          ]
          Permission = [
            "aoss:CreateCollectionItems",
            "aoss:UpdateCollectionItems",
            "aoss:DescribeCollectionItems"
          ]
          Principal = [
            aws_iam_role.firehose_role.arn
          ]
        },
        {
          ResourceType = "index"
          Resource = [
            "index/${var.opensearch_collection_name}/*"
          ]
          Permission = [
            "aoss:CreateIndex",
            "aoss:UpdateIndex",
            "aoss:DescribeIndex",
            "aoss:ReadDocument",
            "aoss:WriteDocument"
          ]
          Principal = [
            aws_iam_role.firehose_role.arn
          ]
        }
      ]
    }
  ])
}

# OpenSearch Serverless Collection
resource "aws_opensearchserverless_collection" "firehose_target" {
  name = var.opensearch_collection_name
  type = "SEARCH"

  depends_on = [
    aws_opensearchserverless_security_policy.encryption,
    aws_opensearchserverless_security_policy.network,
    aws_opensearchserverless_access_policy.firehose_access
  ]
}

# Kinesis Firehose Delivery Stream
resource "aws_kinesis_firehose_delivery_stream" "opensearch_stream" {
  name        = var.stream_name
  destination = "opensearchserverless"

  serverless_configuration {
    collection_arn = aws_opensearchserverless_collection.firehose_target.arn

    s3_configuration {
      bucket_arn = aws_s3_bucket.firehose_backup.arn
      role_arn   = aws_iam_role.firehose_role.arn

      buffering_size = 5
      buffering_interval = 300

      cloudwatch_logging_options {
        enabled         = true
        log_group_name  = aws_cloudwatch_log_group.firehose_logs.name
        log_stream_name = aws_cloudwatch_log_stream.firehose_logs.name
      }
    }
  }

  tags = {
    Environment = "production"
    ManagedBy   = "terraform"
  }
}

# CloudWatch Log Group for Firehose
resource "aws_cloudwatch_log_group" "firehose_logs" {
  name              = "/aws/kinesisfirehose/${var.stream_name}"
  retention_in_days = 30
}

resource "aws_cloudwatch_log_stream" "firehose_logs" {
  name           = "S3Delivery"
  log_group_name = aws_cloudwatch_log_group.firehose_logs.name
}

