model_answers:
# Variables
variable "admin_password" {
  description = "Admin password for Redshift cluster"
  type        = string
  sensitive   = true
}

variable "db_name" {
  description = "Initial database name"
  type        = string
  default     = "mydb"
}

variable "vpc_id" {
  description = "VPC ID where Redshift will be deployed"
  type        = string
}

variable "subnet_ids" {
  description = "List of private subnet IDs for the Redshift cluster"
  type        = list(string)
}

variable "allowed_cidr_blocks" {
  description = "CIDR blocks allowed to access Redshift"
  type        = list(string)
  default     = ["10.0.0.0/16"]
}

# Data sources
data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

# KMS Key for encryption
resource "aws_kms_key" "redshift" {
  description             = "KMS key for Redshift encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
}

resource "aws_kms_alias" "redshift" {
  name          = "alias/redshift-encryption"
  target_key_id = aws_kms_key.redshift.key_id
}

# SNS Topic for event notifications
resource "aws_sns_topic" "redshift_events" {
  name              = "redshift-events"
  kms_master_key_id = aws_kms_key.redshift.id
}

resource "aws_sns_topic_policy" "redshift_events" {
  arn = aws_sns_topic.redshift_events.arn

  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "RedshiftEventsTopicPolicy"
    Statement = [
      {
        Sid    = "AllowRedshiftToPublish"
        Effect = "Allow"
        Principal = {
          Service = "redshift.amazonaws.com"
        }
        Action   = "SNS:Publish"
        Resource = aws_sns_topic.redshift_events.arn
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = data.aws_caller_identity.current.account_id
          }
        }
      }
    ]
  })
}

# S3 bucket for audit logs
resource "aws_s3_bucket" "redshift_logs" {
  bucket = "redshift-audit-logs-${data.aws_caller_identity.current.account_id}-${data.aws_region.current.name}"
}

resource "aws_s3_bucket_public_access_block" "redshift_logs" {
  bucket = aws_s3_bucket.redshift_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "redshift_logs" {
  bucket = aws_s3_bucket.redshift_logs.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "redshift_logs" {
  bucket = aws_s3_bucket.redshift_logs.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.redshift.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "redshift_logs" {
  bucket = aws_s3_bucket.redshift_logs.id

  rule {
    id     = "log-retention"
    status = "Enabled"

    expiration {
      days = 90
    }

    noncurrent_version_expiration {
      noncurrent_days = 30
    }
  }
}

# IAM Role for Redshift to write audit logs to S3
resource "aws_iam_role" "redshift_s3" {
  name = "redshift-s3-audit-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "redshift.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "redshift_s3" {
  name = "redshift-s3-audit-policy"
  role = aws_iam_role.redshift_s3.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:PutObject",
          "s3:GetBucketAcl"
        ]
        Resource = [
          aws_s3_bucket.redshift_logs.arn,
          "${aws_s3_bucket.redshift_logs.arn}/*"
        ]
      }
    ]
  })
}

# Security Group
resource "aws_security_group" "redshift" {
  name        = "redshift-sg"
  description = "Security group for Redshift cluster"
  vpc_id      = var.vpc_id

  ingress {
    description = "Redshift port from allowed CIDRs"
    from_port   = 5439
    to_port     = 5439
    protocol    = "tcp"
    cidr_blocks = var.allowed_cidr_blocks
  }

  egress {
    description = "Allow all outbound"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "redshift-sg"
  }
}

# Subnet Group
resource "aws_redshift_subnet_group" "main" {
  name        = "redshift-subnet-group"
  description = "Redshift subnet group"
  subnet_ids  = var.subnet_ids

  tags = {
    Name = "redshift-subnet-group"
  }
}

# Parameter Group
resource "aws_redshift_parameter_group" "example" {
  name        = "example-redshift-params"
  family      = "redshift-1.0"
  description = "Example Redshift parameter group"

  parameter {
    name  = "require_ssl"
    value = "true"
  }

  parameter {
    name  = "enable_user_activity_logging"
    value = "true"
  }

  parameter {
    name  = "max_connections"
    value = "100"
  }

  parameter {
    name  = "statement_timeout"
    value = "0"
  }

  tags = {
    Name = "example-redshift-params"
  }
}

# Redshift Cluster
resource "aws_redshift_cluster" "example" {
  cluster_identifier                   = "example-redshift-cluster"
  database_name                        = var.db_name
  master_username                      = "admin"
  master_password                      = var.admin_password
  node_type                            = "dc2.large"
  number_of_nodes                      = 2
  cluster_type                         = "multi-node"
  encrypted                            = true
  kms_key_id                           = aws_kms_key.redshift.arn
  enhanced_vpc_routing                 = true
  publicly_accessible                  = false
  apply_immediately                    = false
  automated_snapshot_retention_period = 7
  preferred_maintenance_window        = "Sun:00:00-Sun:01:00"
  cluster_parameter_group_name         = aws_redshift_parameter_group.example.name
  iam_roles                            = [aws_iam_role.redshift_s3.arn]
  vpc_security_group_ids               = [aws_security_group.redshift.id]
  cluster_subnet_group_name            = aws_redshift_subnet_group.main.name

  logging {
    enable        = true
    bucket_name   = aws_s3_bucket.redshift_logs.bucket
    s3_key_prefix = "redshift-audit-logs"
  }

  tags = {
    Name        = "example-redshift-cluster"
    Environment = "production"
  }
}

# Event Subscription
resource "aws_redshift_event_subscription" "example" {
  name          = "redshift-event-subscription"
  description   = "Send Redshift parameter group events to SNS"
  sns_topic_arn = aws_sns_topic.redshift_events.arn

  source_type = "parameter-group"
  source_ids  = [aws_redshift_parameter_group.example.name]

  event_categories = [
    "configuration",
    "management",
    "monitoring",
    "security"
  ]

  severity = "INFO"

  tags = {
    Name = "redshift-event-subscription"
  }

  depends_on = [
    aws_sns_topic_policy.redshift_events
  ]
}

# Outputs
output "redshift_cluster_endpoint" {
  description = "Redshift cluster endpoint"
  value       = aws_redshift_cluster.example.endpoint
}

output "redshift_parameter_group_name" {
  description = "Redshift parameter group name"
  value       = aws_redshift_parameter_group.example.name
}

output "sns_topic_arn" {
  description = "SNS topic ARN for Redshift events"
  value       = aws_sns_topic.redshift_events.arn
}

