# IAM Service Role for Elastic Beanstalk (Enhanced Health monitoring)
resource "aws_iam_role" "eb_service_role_us_west" {
  provider = aws.us_west
  name     = "aws-elasticbeanstalk-service-role-us-west"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "elasticbeanstalk.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role" "eb_service_role_eu_central" {
