model_answers:
# Terraform configuration for AWS Lex Bot - Trip Booking
# Follows AWS security best practices

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# Data sources
data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

# IAM Role for AWS Lex Bot
resource "aws_iam_role" "lex_bot_role" {
  name = "lex-trip-booking-bot-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lex.amazonaws.com"
        }
        Condition = {
          StringEquals = {
            "sts:ExternalId" = "${data.aws_caller_identity.current.account_id}"
          }
        }
      }
    ]
  })

  tags = {
    Name        = "lex-trip-booking-bot-role"
    Environment = "production"
    ManagedBy   = "terraform"
  }
}

# IAM Policy for Lex Bot - Least Privilege
resource "aws_iam_role_policy" "lex_bot_policy" {
  name = "lex-trip-booking-bot-policy"
  role = aws_iam_role.lex_bot_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams"
        ]
        Resource = "arn:aws:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:/aws/lex/*"
      },
      {
        Effect = "Allow"
        Action = [
          "polly:SynthesizeSpeech"
        ]
        Resource = "*"
      }
    ]
  })
}

# CloudWatch Log Group for Lex Bot
resource "aws_cloudwatch_log_group" "lex_bot_logs" {
  name              = "/aws/lex/trip-booking-bot"
  retention_in_days = 30
  kms_key_id        = aws_kms_key.lex_logs.arn

  tags = {
    Name        = "lex-trip-booking-bot-logs"
    Environment = "production"
    ManagedBy   = "terraform"
  }
}

# KMS Key for encrypting Lex logs
resource "aws_kms_key" "lex_logs" {
  description             = "KMS key for Lex Bot CloudWatch logs encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = {
    Name        = "lex-trip-booking-bot-kms"
    Environment = "production"
    ManagedBy   = "terraform"
  }
}

resource "aws_kms_alias" "lex_logs_alias" {
  name          = "alias/lex-trip-booking-bot"
  target_key_id = aws_kms_key.lex_logs.key_id
}

# Custom Slot Type for Trip Destinations
resource "aws_lex_slot_type" "trip_destination" {
  name = "TripDestination"
  description = "Custom slot type for trip destination types"

  enumeration_value {
    value = "beach"
    synonyms = ["seaside", "ocean", "coastal"]
  }

  enumeration_value {
    value = "mountain"
    synonyms = ["alpine", "hills", "summit"]
  }

  enumeration_value {
    value = "city"
    synonyms = ["urban", "metropolitan", "town"]
  }

  enumeration_value {
    value = "countryside"
    synonyms = ["rural", "village", "farm"]
  }

  enumeration_value {
    value = "international"
    synonyms = ["abroad", "overseas", "foreign"]
  }

  value_selection_strategy = "ORIGINAL_VALUE"

  create_version = true
}

# Custom Slot Type for Traveler Count
resource "aws_lex_slot_type" "traveler_count" {
  name = "TravelerCount"
  description = "Custom slot type for number of travelers"

  enumeration_value {
    value = "one"
    synonyms = ["solo", "single", "1"]
  }

  enumeration_value {
    value = "two"
    synonyms = ["couple", "pair", "2"]
  }

  enumeration_value {
    value = "three"
    synonyms = ["3"]
  }

  enumeration_value {
    value = "four"
    synonyms = ["family", "4"]
  }

  enumeration_value {
    value = "five_or_more"
    synonyms = ["group", "many", "5+"]
  }

  value_selection_strategy = "ORIGINAL_VALUE"

  create_version = true
}

# Intent for Booking a Trip
resource "aws_lex_intent" "book_trip" {
  name = "BookTrip"
  description = "Intent to book a trip with various travel preferences"

  fulfillment_activity {
    type = "ReturnIntent"
  }

  sample_utterances = [
    "I want to book a trip",
    "Book me a vacation",
    "I need to plan a trip",
    "Can you help me book a trip",
    "I would like to travel",
    "Book a trip to the beach",
    "I want to go on vacation",
    "Plan a trip for me",
    "Help me book travel",
    "I need to book a holiday"
  ]

  slot {
    name        = "Destination"
    description = "The destination for the trip"
    slot_type   = aws_lex_slot_type.trip_destination.name
    priority    = 1
    value_elicitation_prompt {
      max_attempts = 2
      message {
        content      = "What type of destination would you like? For example, beach, mountain, or city?"
        content_type = "PlainText"
      }
      message {
        content      = "Could you please specify your preferred destination type?"
        content_type = "PlainText"
      }
    }
    priority    = 1
    slot_constraint = "Required"
  }

  slot {
    name        = "DepartureDate"
    description = "The departure date for the trip"
    slot_type   = "AMAZON.DATE"
    priority    = 2
    value_elicitation_prompt {
      max_attempts = 2
      message {
        content      = "When would you like to depart?"
        content_type = "PlainText"
      }
      message {
        content      = "Please provide your preferred departure date."
        content_type = "PlainText"
      }
    }
    priority    = 2
    slot_constraint = "Required"
  }

  slot {
    name        = "ReturnDate"
    description = "The return date for the trip"
    slot_type   = "AMAZON.DATE"
    priority    = 3
    value_elicitation_prompt {
      max_attempts = 2
      message {
        content      = "When would you like to return?"
        content_type = "PlainText"
      }
      message {
        content      = "Please provide your preferred return date."
        content_type = "PlainText"
      }
    }
    priority    = 3
    slot_constraint = "Required"
  }

  slot {
    name        = "Travelers"
    description = "Number of travelers"
    slot_type   = aws_lex_slot_type.traveler_count.name
    priority    = 4
    value_elicitation_prompt {
      max_attempts = 2
      message {
        content      = "How many travelers will be going?"
        content_type = "PlainText"
      }
      message {
        content      = "Please specify the number of travelers."
        content_type = "PlainText"
      }
    }
    priority    = 4
    slot_constraint = "Required"
  }

  slot {
    name        = "Budget"
    description = "Budget for the trip"
    slot_type   = "AMAZON.Number"
    priority    = 5
    value_elicitation_prompt {
      max_attempts = 2
      message {
        content      = "What is your budget for this trip?"
        content_type = "PlainText"
      }
      message {
        content      = "Please provide your budget amount."
        content_type = "PlainText"
      }
    }
    priority    = 5
    slot_constraint = "Optional"
  }

  conclusion_statement {
    message {
      content      = "Great, I have booked your trip. Destination: {Destination}, Departure: {DepartureDate}, Return: {ReturnDate}, Travelers: {Travelers}."
      content_type = "PlainText"
    }
  }

  rejection_statement {
    message {
      content      = "I am sorry, I could not book your trip at this time."
      content_type = "PlainText"
    }
  }
}

# AWS Lex Bot
resource "aws_lex_bot" "trip_booking" {
  name                        = "TripBookingBot"
  description                 = "Lex bot for booking trips and travel arrangements"
  idle_session_ttl_in_seconds = 300
  enable_model_improvements   = true
  nlu_intent_confidence_threshold = 0.70
  voice_id                    = "Joanna"
  process_partial_utterances  = true
  locale                      = "en-US"
  child_directed              = false

  abort_statement {
    message {
      content      = "I am sorry, I could not understand. Please try again."
      content_type = "PlainText"
    }
  }

  clarification_prompt {
    max_attempts = 2
    message {
      content      = "I am sorry, I did not understand. Could you please rephrase your request?"
      content_type = "PlainText"
    }
    message {
      content      = "I did not get that. Please try again with a different phrasing."
      content_type = "PlainText"
    }
  }

  intent {
    intent_name    = aws_lex_intent.book_trip.name
    intent_version = "$LATEST"
  }

  depends_on = [
    aws_iam_role_policy.lex_bot_policy,
    aws_lex_intent.book_trip,
    aws_lex_slot_type.trip_destination,
    aws_lex_slot_type.traveler_count
  ]

  tags = {
    Name        = "TripBookingBot"
    Environment = "production"
    ManagedBy   = "terraform"
    Purpose     = "trip-booking"
  }
}

# Bot Version
resource "aws_lex_bot_version" "trip_booking_v1" {
  bot_name = aws_lex_bot.trip_booking.name
  description = "Initial version of Trip Booking Bot"
}

# Bot Alias
resource "aws_lex_bot_alias" "trip_booking_production" {
  bot_name     = aws_lex_bot.trip_booking.name
  bot_version  = aws_lex_bot_version.trip_booking_v1.bot_version
  description  = "Production alias for Trip Booking Bot"
  bot_version  = aws_lex_bot_version.trip_booking_v1.bot_version

  conversation_logs {
    log_group_name = aws_cloudwatch_log_group.lex_bot_logs.name
    iam_role_arn   = aws_iam_role.lex_bot_role.arn
  }
}

# Outputs
output "lex_bot_name" {
  description = "Name of the Lex Bot"
  value       = aws_lex_bot.trip_booking.name
}

output "lex_bot_arn" {
  description = "ARN of the Lex Bot"
  value       = aws_lex_bot.trip_booking.arn
}

output "lex_bot_alias_arn" {
  description = "ARN of the Lex Bot Alias"
