terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source = "hashicorp/random"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region"
  type        = string
  default     = "us-east-1"
}

variable "db_name" {
  description = "Name of the database"
  type        = string
  default     = "mydatabase"
}

variable "db_username" {
  description = "Master username"
  type        = string
  default     = "admin"
  sensitive   = true
}

# Generate a random master password
resource "random_password" "db_password" {
  length  = 20
  special = true
}

# Store the password securely in Secrets Manager
resource "aws_secretsmanager_secret" "db_password" {
  name                    = "${var.db_name}-master-password"
  description             = "Master password for RDS ${var.db_name}"
  recovery_window_in_days = 7
}

resource "aws_secretsmanager_secret_version" "db_password" {
  secret_id     = aws_secretsmanager_secret.db_password.id
  secret_string = random_password.db_password.result
}

# KMS key for encryption at rest
resource "aws_kms_key" "rds" {
  description             = "KMS key for RDS encryption"
  deletion_window_in_days  = 7
  enable_key_rotation      = true
}

resource "aws_kms_alias" "rds" {
  name          = "alias/${var.db_name}-rds"
  target_key_id = aws_kms_key.rds.key_id
}

# IAM role for Enhanced Monitoring
resource "aws_iam_role" "rds_monitoring" {
  name = "${var.db_name}-rds-monitoring"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action = "sts:AssumeRole"
      Effect = "Allow"
      Principal = {
        Service = "monitoring.rds.amazonaws.com"
      }
    }]
  })
}

resource "aws_iam_role_policy_attachment" "rds_monitoring" {
  role       = aws_iam_role.rds_monitoring.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonRDSEnhancedMonitoringRole"
}

# Use existing default VPC and subnets (replace with your own VPC/subnets in production)
data "aws_vpc" "default" {
  default = true
}

data "aws_subnets" "default" {
  filter {
    name   = "vpc-id"
    values = [data.aws_vpc.default.id]
  }
}

# DB subnet group
resource "aws_db_subnet_group" "main" {
  name       = "${var.db_name}-subnet-group"
  subnet_ids = data.aws_subnets.default.ids

  tags = {
    Name = "${var.db_name}-subnet-group"
  }
}

# Security group for the primary RDS instance
resource "aws_security_group" "rds_primary_sg" {
  name        = "${var.db_name}-primary-sg"
  description = "Security group for primary RDS ${var.db_name}"
  vpc_id      = data.aws_vpc.default.id

  ingress {
    description = "SQL Server access from VPC"
    from_port   = 1433
    to_port     = 1433
    protocol    = "tcp"
    cidr_blocks = [data.aws_vpc.default.cidr_block]
  }

  egress {
    description = "Allow all outbound"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "${var.db_name}-primary-sg"
  }
}

# Security group for the read replica
resource "aws_security_group" "rds_replica_sg" {
  name        = "${var.db_name}-replica-sg"
  description = "Security group for read replica of ${var.db_name}"
  vpc_id      = data.aws_vpc.default.id

  ingress {
    description     = "SQL Server access from primary SG"
    from_port       = 1433
    to_port         = 1433
    protocol        = "tcp"
    security_groups = [aws_security_group.rds_primary_sg.id]
  }

  egress {
    description = "Allow all outbound"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "${var.db_name}-replica-sg"
  }
}

# Parameter group with SSL enforcement
resource "aws_db_parameter_group" "main" {
  name        = "${var.db_name}-params"
  family      = "sqlserver-ex-15.0"
  description = "Parameter group for ${var.db_name}"

  parameter {
    name  = "rds.force_ssl"
    value = "1"
  }

  tags = {
    Name = "${var.db_name}-params"
  }
}

# Primary RDS SQL Server instance
resource "aws_db_instance" "primary" {
  identifier                   = "${var.db_name}-primary"
  engine                       = "sqlserver-ex"
  engine_version               = "15.00.4236.7.v1"
  instance_class               = "db.t3.small"
  allocated_storage            = 20
  max_allocated_storage         = 100
  storage_type                  = "gp3"
  storage_encrypted             = true
  kms_key_id                    = aws_kms_key.rds.arn
  db_name                       = var.db_name
  username                      = var.db_username
  password                      = random_password.db_password.result
  db_subnet_group_name          = aws_db_subnet_group.main.name
  vpc_security_group_ids        = [aws_security_group.rds_primary_sg.id]
  parameter_group_name          = aws_db_parameter_group.main.name
  backup_retention_period       = 7
  backup_window                 = "03:00-04:00"
  maintenance_window            = "Mon:00:00-Mon:01:00"
  multi_az                      = false
  deletion_protection           = true
  skip_final_snapshot           = false
  final_snapshot_identifier     = "${var.db_name}-primary-final"
  enabled_cloudwatch_logs_exports = ["error", "agent"]
  iam_database_authentication_enabled = true
  performance_insights_enabled  = true
  performance_insights_kms_key_id = aws_kms_key.rds.arn
  performance_insights_retention_period = 7
  monitoring_interval           = 60
  monitoring_role_arn           = aws_iam_role.rds_monitoring.arn
  auto_minor_version_upgrade    = false
  publicly_accessible          = false
  copy_tags_to_snapshot         = true

  tags = {
    Name = "${var.db_name}-primary"
    Role = "primary"
  }
}

# Read replica
resource "aws_db_instance" "replica" {
  identifier                   = "${var.db_name}-replica"
  replicate_source_db          = aws_db_instance.primary.identifier
  instance_class               = "db.t3.small"
  storage_type                 = "gp3"
  storage_encrypted            = true
  kms_key_id                   = aws_kms_key.rds.arn
  vpc_security_group_ids       = [aws_security_group.rds_replica_sg.id]
  skip_final_snapshot          = true
  multi_az                     = false
  publicly_accessible          = false
  iam_database_authentication_enabled = true
  performance_insights_enabled = true
  performance_insights_kms_key_id = aws_kms_key.rds.arn
  performance_insights_retention_period = 7
  monitoring_interval          = 60
  monitoring_role_arn          = aws_iam_role.rds_monitoring.arn
  copy_tags_to_snapshot        = true

  tags = {
    Name = "${var.db_name}-replica"
    Role = "replica"
  }
}

# Outputs
output "primary_endpoint" {
  value     = aws_db_instance.primary.endpoint
  sensitive = true
}

output "replica_endpoint" {
  value     = aws_db_instance.replica.endpoint
  sensitive = true
}

output "db_password_secret_arn" {
  value = aws_secretsmanager_secret.db_password.arn
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
