}

variable "aws_region" {
  description = "AWS region for the Lightsail database"
  type        = string
  default     = "us-east-1"
}

variable "database_name" {
  description = "Name of the Lightsail managed database"
  type        = string
  default     = "my-lightsail-db"
}

variable "master_username" {
  description = "Master username for the database"
  type        = string
  default     = "admin"
}

variable "availability_zone" {
  description = "Availability zone for the database"
  type        = string
  default     = "us-east-1a"
}

variable "blueprint_id" {
  description = "Blueprint ID for the database engine (e.g., mysql_8_0, postgres_13)"
  type        = string
  default     = "mysql_8_0"
}

variable "bundle_id" {
  description = "Bundle ID for the database size (e.g., micro_1_0, small_2_0)"
  type        = string
  default     = "micro_1_0"
}

# Generate a secure random password for the master user
resource "random_password" "master" {
  length  = 20
  special = true
}

# Store the master password securely in AWS Secrets Manager
resource "aws_secretsmanager_secret" "db_password" {
  name                    = "${var.database_name}-master-password"
  description             = "Master password for Lightsail database ${var.database_name}"
  recovery_window_in_days = 7
}

resource "aws_secretsmanager_secret_version" "db_password" {
  secret_id     = aws_secretsmanager_secret.db_password.id
  secret_string = random_password.master.result
}

# Create the AWS Lightsail managed database
resource "aws_lightsail_database" "this" {
  name                        = var.database_name
  availability_zone           = var.availability_zone
  blueprint_id                = var.blueprint_id
  bundle_id                   = var.bundle_id
  master_database_name        = var.database_name
  master_username             = var.master_username
  master_password             = random_password.master.result
  publicly_accessible         = false # Security best practice: keep database private
  preferred_backup_window     = "07:00-09:00"
  preferred_maintenance_window = "Tue:09:00-Tue:11:00"
  skip_final_snapshot         = false
  final_snapshot_name         = "${var.database_name}-final-snapshot"

  tags = {
    Name        = var.database_name
    Environment = "production"
    ManagedBy   = "terraform"
  }
}

# Outputs
output "database_arn" {
  description = "ARN of the Lightsail database"
  value       = aws_lightsail_database.this.arn
}

output "database_endpoint" {
  description = "Connection endpoint for the database"
  value       = aws_lightsail_database.this.endpoint
}

output "database_port" {
  description = "Port for the database connection"
  value       = aws_lightsail_database.this.port
}

output "master_password_secret_arn" {
  description = "ARN of the Secrets Manager secret containing the master password"
  value       = aws_secretsmanager_secret.db_password.arn
  sensitive   = true
}

