  region = "us-west-2"
}

variable "table_name" {
  description = "Name of the DynamoDB table"
  type        = string
  default     = "multi-region-table"
}

# DynamoDB table in us-east-1
resource "aws_dynamodb_table" "use1" {
  provider = aws.use1

  name         = var.table_name
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "id"

  attribute {
    name = "id"
    type = "S"
  }

  # Enable server-side encryption using AWS owned key (default, but explicit)
  server_side_encryption {
    enabled = true
  }

  # Enable point-in-time recovery for continuous backups
  point_in_time_recovery {
    enabled = true
  }

  tags = {
    Environment = "production"
    ManagedBy   = "terraform"
  }
}

# DynamoDB table in us-west-1
resource "aws_dynamodb_table" "usw1" {
  provider = aws.usw1

  name         = var.table_name
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "id"

  attribute {
    name = "id"
    type = "S"
  }

  server_side_encryption {
    enabled = true
  }

  point_in_time_recovery {
    enabled = true
  }

  tags = {
    Environment = "production"
    ManagedBy   = "terraform"
  }
}

# DynamoDB table in us-west-2
resource "aws_dynamodb_table" "usw2" {
  provider = aws.usw2

  name         = var.table_name
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "id"

  attribute {
    name = "id"
    type = "S"
  }

  server_side_encryption {
    enabled = true
  }

  point_in_time_recovery {
    enabled = true
  }

  tags = {
    Environment = "production"
    ManagedBy   = "terraform"
  }
}

output "table_arns" {
  description = "ARNs of the DynamoDB tables in each region"
  value = {
    us_east_1 = aws_dynamodb_table.use1.arn
    us_west_1 = aws_dynamodb_table.usw1.arn
    us_west_2 = aws_dynamodb_table.usw2.arn
  }
}

