model_answers:
provider "aws" {
  region = "us-east-1"
}

# KMS key for encryption of Kinesis streams and CloudWatch logs
resource "aws_kms_key" "app_key" {
  description             = "KMS key for Kinesis Analytics application encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow CloudWatch Logs to use the key"
        Effect = "Allow"
        Principal = {
          Service = "logs.amazonaws.com"
        }
        Action = [
          "kms:Encrypt*",
          "kms:Decrypt*",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:Describe*"
        ]
        Resource = "*"
        Condition = {
          ArnLike = {
            "kms:EncryptionContext:aws:logs:arn" = "arn:aws:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:*"
          }
        }
      },
      {
        Sid    = "Allow Kinesis to use the key"
        Effect = "Allow"
        Principal = {
          Service = "kinesis.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:GenerateDataKey*"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "app_key_alias" {
  name          = "alias/kinesis-analytics-app-key"
  target_key_id = aws_kms_key.app_key.key_id
}

data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

# Kinesis Data Streams for input and output
resource "aws_kinesis_stream" "input_stream" {
  name             = "analytics-input-stream"
  shard_count      = 1
  retention_period = 24
  encryption_type  = "KMS"
  kms_key_id       = aws_kms_key.app_key.arn
}

resource "aws_kinesis_stream" "output_stream" {
  name             = "analytics-output-stream"
  shard_count      = 1
  retention_period = 24
  encryption_type  = "KMS"
  kms_key_id       = aws_kms_key.app_key.arn
}

# CloudWatch Log Group and Log Stream
resource "aws_cloudwatch_log_group" "app_log_group" {
  name              = "/aws/kinesis-analytics/app-log-group"
  retention_in_days = 30
  kms_key_id        = aws_kms_key.app_key.arn
}

resource "aws_cloudwatch_log_stream" "app_log_stream" {
  name           = "analytics-app-log-stream"
  log_group_name = aws_cloudwatch_log_group.app_log_group.name
}

# IAM role for Kinesis Analytics application
resource "aws_iam_role" "analytics_role" {
  name = "kinesis-analytics-app-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "kinesisanalytics.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

# IAM policy for the role
resource "aws_iam_policy" "analytics_policy" {
  name        = "kinesis-analytics-app-policy"
  description = "Permissions for Kinesis Analytics application"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "kinesis:DescribeStream",
          "kinesis:GetShardIterator",
          "kinesis:GetRecords",
          "kinesis:ListShards"
        ]
        Resource = aws_kinesis_stream.input_stream.arn
      },
      {
        Effect = "Allow"
        Action = [
          "kinesis:DescribeStream",
          "kinesis:PutRecord",
          "kinesis:PutRecords"
        ]
        Resource = aws_kinesis_stream.output_stream.arn
      },
      {
        Effect = "Allow"
        Action = [
          "logs:PutLogEvents",
          "logs:CreateLogStream",
          "logs:DescribeLogStreams"
        ]
        Resource = "${aws_cloudwatch_log_group.app_log_group.arn}:*"
      },
      {
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey"
        ]
        Resource = aws_kms_key.app_key.arn
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "analytics_attach" {
  role       = aws_iam_role.analytics_role.name
  policy_arn = aws_iam_policy.analytics_policy.arn
}

# Kinesis Analytics V2 Application (SQL)
resource "aws_kinesisanalyticsv2_application" "analytics_app" {
  name                   = "basic-analytics-app"
  runtime_environment    = "SQL-1_0"
  service_execution_role = aws_iam_role.analytics_role.arn

  application_configuration {
    sql_application_configuration {
      input {
        name_prefix = "SOURCE_SQL_STREAM"
        kinesis_streams_input {
          resource_arn = aws_kinesis_stream.input_stream.arn
          role_arn     = aws_iam_role.analytics_role.arn
        }
        input_schema {
          record_format {
            record_format_type = "JSON"
            mapping_parameters {
              json_mapping_parameters {
                record_row_path = "$"
              }
            }
          }
          record_encoding = "UTF-8"
          record_columns {
            name    = "sensor_id"
            sql_type = "VARCHAR(16)"
          }
          record_columns {
            name    = "temperature"
            sql_type = "DOUBLE"
          }
          record_columns {
            name    = "event_time"
            sql_type = "TIMESTAMP"
          }
        }
      }

      output {
        name = "DESTINATION_SQL_STREAM"
        kinesis_streams_output {
          resource_arn = aws_kinesis_stream.output_stream.arn
          role_arn     = aws_iam_role.analytics_role.arn
        }
        destination_schema {
          record_format_type = "JSON"
        }
      }

      # Reference data is optional; omitted for basic setup
    }

    cloudwatch_logging_options {
      log_stream_arn = aws_cloudwatch_log_stream.app_log_stream.arn
    }
  }

  tags = {
    Environment = "development"
    Purpose     = "basic-kinesis-analytics"
  }
}

output "application_arn" {
  value = aws_kinesisanalyticsv2_application.analytics_app.arn
}

output "log_stream_name" {
  value = aws_cloudwatch_log_stream.app_log_stream.name
}

