model_answers:
terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.region
}

variable "region" {
  description = "AWS region"
  type        = string
  default     = "us-east-1"
}

variable "bundle_id" {
  description = "Lightsail bundle ID (e.g., nano_2_0, micro_2_0)"
  type        = string
  default     = "nano_2_0"
}

variable "allowed_ssh_cidr" {
  description = "CIDR block allowed to SSH into the Lightsail instance (restrict to your IP for security)"
  type        = string
  # No default – must be provided to enforce least privilege
}

data "aws_availability_zones" "available" {
  state = "available"
}

# SSH key pair for instance access
resource "aws_lightsail_key_pair" "wp_key" {
  name = "wordpress-key-${random_id.suffix.hex}"
}

resource "random_id" "suffix" {
  byte_length = 4
}

# Lightsail instance with WordPress blueprint
resource "aws_lightsail_instance" "wordpress" {
  name              = "wordpress-${random_id.suffix.hex}"
  availability_zone = data.aws_availability_zones.available.names[0]
  blueprint_id      = "wordpress"
  bundle_id         = var.bundle_id
  key_pair_name     = aws_lightsail_key_pair.wp_key.name

  tags = {
    Name        = "WordPress-Lightsail"
    Environment = "production"
  }
}

# Static public IP
resource "aws_lightsail_static_ip" "wp_ip" {
  name = "wordpress-ip-${random_id.suffix.hex}"
}

resource "aws_lightsail_static_ip_attachment" "wp_ip_attach" {
  static_ip_name = aws_lightsail_static_ip.wp_ip.name
  instance_name  = aws_lightsail_instance.wordpress.name
}

# Firewall rules: HTTP, HTTPS open to world; SSH restricted to allowed CIDR
resource "aws_lightsail_instance_public_ports" "wp_ports" {
  instance_name = aws_lightsail_instance.wordpress.name

  port_info {
    from_port = 80
    to_port   = 80
    protocol  = "tcp"
    cidrs     = ["0.0.0.0/0"]
  }

  port_info {
    from_port = 443
    to_port   = 443
    protocol  = "tcp"
    cidrs     = ["0.0.0.0/0"]
  }

  port_info {
    from_port = 22
    to_port   = 22
    protocol  = "tcp"
    cidrs     = [var.allowed_ssh_cidr]
  }
}

# Outputs
output "static_ip" {
  description = "Public static IP of the WordPress instance"
  value       = aws_lightsail_static_ip.wp_ip.ip_address
}

output "instance_public_ip" {
  description = "Current public IP (may differ before static IP attachment)"
  value       = aws_lightsail_instance.wordpress.public_ip_address
}

output "key_pair_name" {
  description = "Name of the Lightsail key pair"
  value       = aws_lightsail_key_pair.wp_key.name
}

output "private_key" {
  description = "Private key for SSH access (sensitive)"
  value       = aws_lightsail_key_pair.wp_key.private_key
  sensitive   = true
}

output "wordpress_username" {
  description = "Default administrator username for WordPress (Bitnami)"
  value       = "bitnami"
}

output "wordpress_password_instructions" {
  description = "Retrieve the default application password from the Lightsail console or via AWS CLI"
  value       = "Use the Lightsail console or run: aws lightsail get-instance --instance-name ${aws_lightsail_instance.wordpress.name} --query 'instance.passwordData'"
}

