model_answers:
# IAM role for Lex bot service role
resource "aws_iam_role" "lex_bot_role" {
  name = "OrderPizzaBotLexRole"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "lex.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

# IAM policy for Lex bot to access Polly and CloudWatch logs
resource "aws_iam_policy" "lex_bot_policy" {
  name        = "OrderPizzaBotLexPolicy"
  description = "Policy for OrderPizza Lex bot to synthesize speech and write logs"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "polly:SynthesizeSpeech"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "${aws_cloudwatch_log_group.lex_bot_logs.arn}:*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "lex_bot_attach" {
  role       = aws_iam_role.lex_bot_role.name
  policy_arn = aws_iam_policy.lex_bot_policy.arn
}

# CloudWatch Log Group for Lex bot logs
resource "aws_cloudwatch_log_group" "lex_bot_logs" {
  name              = "/aws/lex/OrderPizzaBot"
  retention_in_days = 14
}

# Lex bot
resource "aws_lex_bot" "order_pizza_bot" {
  name           = "OrderPizzaBot"
  description    = "Bot for ordering pizzas"
  child_directed = false
  process_behavior = "BUILD"
  locale         = "en-US"
  voice_id       = "Joanna"
  abort_statement {
    message {
      content      = "Sorry, I could not understand. Goodbye."
      content_type = "PlainText"
    }
  }
  clarification_prompt {
    max_attempts = 2
    message {
      content      = "I didn't understand. Could you please repeat that?"
      content_type = "PlainText"
    }
  }
  idle_session_ttl_in_seconds = 300
  iam_role_arn                = aws_iam_role.lex_bot_role.arn
}

# Intent for ordering pizza
resource "aws_lex_intent" "order_pizza_intent" {
  name              = "OrderPizzaIntent"
  description       = "Intent to order a pizza"
  fulfillment_activity {
    type = "ReturnIntent"
  }
  sample_utterances = [
    "I want to order a pizza",
    "Order a pizza",
    "I'd like a pizza",
    "Can I get a pizza",
    "Pizza please"
  ]
  conclusion_statement {
    message {
      content      = "Your pizza order has been placed. Thank you!"
      content_type = "PlainText"
    }
  }
  rejection_statement {
    message {
      content      = "Okay, I won't place the order."
      content_type = "PlainText"
    }
  }
  confirmation_prompt {
    max_attempts = 2
    message {
      content      = "Would you like to place this order?"
      content_type = "PlainText"
    }
  }
  slot {
    name        = "PizzaType"
    description = "Type of pizza"
    priority    = 1
    slot_constraint = "Required"
    slot_type       = "AMAZON.Food"
    value_elicitation_prompt {
      max_attempts = 2
      message {
        content      = "What type of pizza would you like?"
        content_type = "PlainText"
      }
    }
  }
  slot {
    name        = "PizzaSize"
    description = "Size of pizza"
    priority    = 2
    slot_constraint = "Required"
    slot_type       = "AMAZON.NUMBER"
    value_elicitation_prompt {
      max_attempts = 2
      message {
        content      = "What size pizza (in inches)?"
        content_type = "PlainText"
      }
    }
  }
  slot {
    name        = "CrustType"
    description = "Type of crust"
    priority    = 3
    slot_constraint = "Optional"
    slot_type       = "AMAZON.Food"
    value_elicitation_prompt {
      max_attempts = 2
      message {
        content      = "What type of crust would you like?"
        content_type = "PlainText"
      }
    }
  }
}

# Bot alias to publish the bot
resource "aws_lex_bot_alias" "order_pizza_alias" {
  bot_name    = aws_lex_bot.order_pizza_bot.name
  bot_version = aws_lex_bot.order_pizza_bot.version
  name        = "PROD"
  description = "Production alias for OrderPizzaBot"
}

