model_answers:
terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    archive = {
      source  = "hashicorp/archive"
      version = "~> 2.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region"
  type        = string
  default     = "us-east-1"
}

variable "function_name" {
  description = "Name of the Lambda function"
  type        = string
  default     = "my-lambda-function"
}

# Package the lambda.js file into a zip archive
data "archive_file" "lambda_zip" {
  type        = "zip"
  source_file = "${path.module}/lambda.js"
  output_path = "${path.module}/lambda.zip"
}

# IAM role for Lambda execution
resource "aws_iam_role" "lambda_exec" {
  name = "${var.function_name}-exec-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })

  # Enforce secure transport (optional but recommended)
  inline_policy {}
}

# Attach the AWS managed policy for basic Lambda execution (CloudWatch Logs)
resource "aws_iam_role_policy_attachment" "lambda_basic_execution" {
  role       = aws_iam_role.lambda_exec.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

# Optional: Custom least-privilege policy for CloudWatch Logs (alternative to managed policy)
# Uncomment below and remove the managed policy attachment if you prefer explicit permissions.
# resource "aws_iam_policy" "lambda_logging" {
#   name        = "${var.function_name}-logging-policy"
#   description = "Allow Lambda to write logs to CloudWatch"
#   policy      = jsonencode({
#     Version = "2012-10-17"
#     Statement = [
#       {
#         Effect = "Allow"
#         Action = [
#           "logs:CreateLogGroup",
#           "logs:CreateLogStream",
#           "logs:PutLogEvents"
#         ]
#         Resource = "arn:aws:logs:*:*:*"
#       }
#     ]
#   })
# }
# resource "aws_iam_role_policy_attachment" "lambda_logging_attach" {
#   role       = aws_iam_role.lambda_exec.name
#   policy_arn = aws_iam_policy.lambda_logging.arn
# }

# Lambda function
resource "aws_lambda_function" "this" {
  function_name    = var.function_name
  role             = aws_iam_role.lambda_exec.arn
  handler          = "lambda.handler"   # Assumes lambda.js exports a function named 'handler'
  runtime          = "nodejs18.x"       # Use a supported Node.js runtime
  filename         = data.archive_file.lambda_zip.output_path
  source_code_hash = data.archive_file.lambda_zip.output_base64sha256

  # Security best practices
  publish          = true               # Publish a new version on each update
  reserved_concurrent_executions = -1   # No concurrency limit (adjust as needed)

  environment {
    variables = {
      # Example environment variable; remove or modify as needed
      NODE_OPTIONS = "--enable-source-maps"
    }
  }

  # Enable X-Ray tracing for observability (optional)
  tracing_config {
    mode = "PassThrough"  # Change to "Active" if you want X-Ray tracing
  }

  # Dead letter queue configuration (optional, recommended for production)
  # dead_letter_config {
  #   target_arn = aws_sqs_queue.dlq.arn
  # }

  depends_on = [
    aws_iam_role_policy_attachment.lambda_basic_execution
  ]
}

# Outputs
output "lambda_function_arn" {
  description = "ARN of the Lambda function"
  value       = aws_lambda_function.this.arn
}

output "lambda_function_name" {
  description = "Name of the Lambda function"
  value       = aws_lambda_function.this.function_name
}

output "lambda_role_arn" {
  description = "ARN of the IAM role used by the Lambda function"
  value       = aws_iam_role.lambda_exec.arn
}

