provider "aws" {
  # Region can be set via variable or provider alias
}

variable "environment" {
  description = "Environment name (e.g., dev, staging, prod)"
  type        = string
  default     = "dev"
}

variable "vpc_id" {
  description = "ID of the VPC where the RDS instance will be deployed"
  type        = string
}

variable "subnet_ids" {
  description = "List of private subnet IDs for the DB subnet group"
  type        = list(string)
}

variable "allowed_cidr_blocks" {
  description = "List of CIDR blocks allowed to connect to the database"
  type        = list(string)
  default     = ["10.0.0.0/8"] # Example: restrict to internal VPC range
}

variable "instance_class" {
  description = "RDS instance class"
  type        = string
  default     = "db.t3.micro"
}

variable "allocated_storage" {
  description = "Allocated storage in GB"
  type        = number
  default     = 20
}

variable "max_allocated_storage" {
  description = "Maximum storage autoscaling limit in GB"
  type        = number
  default     = 100
}

variable "engine_version" {
  description = "MySQL engine version"
  type        = string
  default     = "8.0.35"
}

variable "backup_retention_period" {
  description = "Number of days to retain automated backups"
  type        = number
  default     = 7
}

variable "deletion_protection" {
  description = "Enable deletion protection"
  type        = bool
  default     = true
}

variable "multi_az" {
  description = "Enable Multi-AZ deployment for high availability"
  type        = bool
  default     = false
}

variable "db_name" {
  description = "Name of the initial database"
  type        = string
  default     = "appdb"
}

variable "username" {
  description = "Master username for the database"
  type        = string
  default     = "admin"
}

# Generate a secure random password
resource "random_password" "master" {
  length  = 32
  special = true
  override_special = "!#$%&*()-_=+[]{}<>:?"
}

# Store the password in AWS Secrets Manager
resource "aws_secretsmanager_secret" "db_master" {
  name                    = "rds-mysql-${var.environment}-master"
  description             = "Master credentials for MySQL RDS instance"
  recovery_window_in_days = 0 # Immediate deletion for non-prod; adjust for production
}

resource "aws_secretsmanager_secret_version" "db_master" {
  secret_id     = aws_secretsmanager_secret.db_master.id
  secret_string = jsonencode({
    username = var.username
    password = random_password.master.result
    engine   = "mysql"
    host     = aws_db_instance.mysql.address
    port     = aws_db_instance.mysql.port
    dbname   = var.db_name
  })
}

# DB subnet group in private subnets
resource "aws_db_subnet_group" "mysql" {
  name       = "mysql-subnet-group-${var.environment}"
  subnet_ids = var.subnet_ids

  tags = {
    Name        = "mysql-subnet-group-${var.environment}"
    Environment = var.environment
  }
}

# Security group for RDS
resource "aws_security_group" "mysql" {
  name        = "mysql-sg-${var.environment}"
  description = "Security group for MySQL RDS instance"
  vpc_id      = var.vpc_id

  ingress {
    description = "MySQL access from allowed CIDRs"
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = var.allowed_cidr_blocks
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name        = "mysql-sg-${var.environment}"
    Environment = var.environment
  }
}

# Custom parameter group to enforce SSL/TLS connections
resource "aws_db_parameter_group" "mysql" {
  name   = "mysql-params-${var.environment}"
  family = "mysql8.0"

  parameter {
    name  = "require_secure_transport"
    value = "1"
    apply_method = "pending-reboot"
  }

  # Additional security-related parameters
  parameter {
    name  = "log_bin_trust_function_creators"
    value = "0"
    apply_method = "pending-reboot"
  }

  tags = {
    Name        = "mysql-params-${var.environment}"
    Environment = var.environment
  }
}

# RDS MySQL instance
resource "aws_db_instance" "mysql" {
  identifier = "mysql-${var.environment}"

  engine               = "mysql"
  engine_version       = var.engine_version
  instance_class       = var.instance_class
  allocated_storage    = var.allocated_storage
  max_allocated_storage = var.max_allocated_storage
  storage_encrypted    = true
  kms_key_id           = "alias/aws/rds" # Use default RDS KMS key; can be customized

  db_name  = var.db_name
  username = var.username
  password = random_password.master.result

  db_subnet_group_name   = aws_db_subnet_group.mysql.name
  vpc_security_group_ids = [aws_security_group.mysql.id]

  parameter_group_name = aws_db_parameter_group.mysql.name

  backup_retention_period = var.backup_retention_period
  backup_window           = "03:00-04:00" # UTC, adjust as needed
  maintenance_window      = "sun:04:00-sun:05:00"

  multi_az             = var.multi_az
  storage_type         = "gp3"
  iops                 = 3000 # gp3 default, can be adjusted
  publicly_accessible  = false
  deletion_protection  = var.deletion_protection
  skip_final_snapshot  = false
  final_snapshot_identifier = "mysql-${var.environment}-final-${formatdate("YYYY-MM-DD-hhmm", timestamp())}"

  enabled_cloudwatch_logs_exports = ["error", "general", "slowquery"]
  performance_insights_enabled    = true
  performance_insights_retention_period = 7 # days

  auto_minor_version_upgrade = true
  apply_immediately          = false

  tags = {
    Name        = "mysql-${var.environment}"
    Environment = var.environment
  }
}

# Outputs
output "db_instance_endpoint" {
  description = "RDS MySQL endpoint"
  value       = aws_db_instance.mysql.endpoint
}

output "db_instance_address" {
  description = "RDS MySQL hostname"
  value       = aws_db_instance.mysql.address
}

output "db_instance_port" {
  description = "RDS MySQL port"
  value       = aws_db_instance.mysql.port
}

output "db_master_secret_arn" {
  description = "ARN of the Secrets Manager secret containing master credentials"
  value       = aws_secretsmanager_secret.db_master.arn
}

