model_answers:
# Terraform configuration for a SageMaker JupyterServer app with security best practices

# Variables (customize as needed)
variable "region" {
  default = "us-east-1"
}
variable "app_name" {
  default = "example-jupyter-server"
}
variable "domain_name" {
  default = "example-domain"
}
variable "user_profile_name" {
  default = "example-user"
}
variable "vpc_cidr" {
  default = "10.0.0.0/16"
}
variable "private_subnet_cidrs" {
  default = ["10.0.1.0/24", "10.0.2.0/24"]
}
variable "data_bucket_name" {
  default = "example-sagemaker-data-bucket"
}

# Provider
provider "aws" {
  region = var.region
}

# KMS key for encryption at rest
resource "aws_kms_key" "sagemaker" {
  description             = "KMS key for SageMaker domain encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
}

resource "aws_kms_alias" "sagemaker" {
  name          = "alias/sagemaker-domain-key"
  target_key_id = aws_kms_key.sagemaker.key_id
}

# VPC and networking (no internet gateway, private subnets only)
resource "aws_vpc" "sagemaker" {
  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = { Name = "sagemaker-vpc" }
}

resource "aws_subnet" "private" {
  count             = length(var.private_subnet_cidrs)
  vpc_id            = aws_vpc.sagemaker.id
  cidr_block        = var.private_subnet_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = { Name = "sagemaker-private-subnet-${count.index}" }
}

data "aws_availability_zones" "available" {}

# Security group for SageMaker domain (restrictive inbound/outbound)
resource "aws_security_group" "sagemaker" {
  name        = "sagemaker-domain-sg"
  description = "Security group for SageMaker domain"
  vpc_id      = aws_vpc.sagemaker.id

  # No inbound rules required; SageMaker manages connectivity internally
  # Outbound: allow HTTPS to VPC endpoints and necessary AWS services
  egress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"] # Restrict further with VPC endpoints in production
    description = "HTTPS outbound"
  }
}

# VPC endpoints for SageMaker API and Runtime (private access)
resource "aws_vpc_endpoint" "sagemaker_api" {
  vpc_id              = aws_vpc.sagemaker.id
  service_name        = "com.amazonaws.${var.region}.sagemaker.api"
  vpc_endpoint_type   = "Interface"
  private_dns_enabled = true
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.sagemaker.id]
}

resource "aws_vpc_endpoint" "sagemaker_runtime" {
  vpc_id              = aws_vpc.sagemaker.id
  service_name        = "com.amazonaws.${var.region}.sagemaker.runtime"
  vpc_endpoint_type   = "Interface"
  private_dns_enabled = true
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.sagemaker.id]
}

# IAM role for SageMaker execution (least privilege)
resource "aws_iam_role" "sagemaker_execution" {
  name = "sagemaker-execution-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "sagemaker.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "sagemaker_execution" {
  name        = "sagemaker-execution-policy"
  description = "Least privilege policy for SageMaker execution role"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:ListBucket"
        ]
        Resource = [
          "arn:aws:s3:::${var.data_bucket_name}",
          "arn:aws:s3:::${var.data_bucket_name}/*"
        ]
      },
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "arn:aws:logs:*:*:*"
      },
      {
        Effect = "Allow"
        Action = [
          "ecr:GetAuthorizationToken",
          "ecr:BatchCheckLayerAvailability",
          "ecr:GetDownloadUrlForLayer",
          "ecr:BatchGetImage"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "sagemaker:AddTags",
          "sagemaker:Describe*",
          "sagemaker:List*"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "sagemaker_execution" {
  role       = aws_iam_role.sagemaker_execution.name
  policy_arn = aws_iam_policy.sagemaker_execution.arn
}

# SageMaker Domain (VPC only, IAM auth, encryption)
resource "aws_sagemaker_domain" "example" {
  domain_name = var.domain_name
  auth_mode   = "IAM" # IAM authentication (no user/password)
  vpc_id      = aws_vpc.sagemaker.id
  subnet_ids  = aws_subnet.private[*].id
  app_network_access_type = "VpcOnly" # No direct internet access

  default_user_settings {
    execution_role  = aws_iam_role.sagemaker_execution.arn
    security_groups = [aws_security_group.sagemaker.id]

    jupyter_server_app_settings {
      default_resource_spec {
        instance_type = "system" # Use system default (free tier eligible)
      }
    }

    # Encryption for EBS volumes attached to apps
    ebs_volume_settings {
      volume_size_in_gb = 5
      volume_type       = "gp3"
      encrypted         = true
      kms_key_id        = aws_kms_key.sagemaker.arn
    }
  }

  # Encrypt home EFS using KMS
  kms_key_id = aws_kms_key.sagemaker.arn

  tags = {
    Environment = "example"
  }
}

# SageMaker User Profile
resource "aws_sagemaker_user_profile" "example" {
  domain_id         = aws_sagemaker_domain.example.id
  user_profile_name = var.user_profile_name

  user_settings {
    execution_role  = aws_iam_role.sagemaker_execution.arn
    security_groups = [aws_security_group.sagemaker.id]

    jupyter_server_app_settings {
      default_resource_spec {
        instance_type = "system"
      }
    }

    ebs_volume_settings {
      volume_size_in_gb = 5
      volume_type       = "gp3"
      encrypted         = true
      kms_key_id        = aws_kms_key.sagemaker.arn
    }
  }
}

# SageMaker App: JupyterServer
resource "aws_sagemaker_app" "jupyter_server" {
  app_name          = var.app_name
  app_type          = "JupyterServer"
  domain_id         = aws_sagemaker_domain.example.id
  user_profile_name = aws_sagemaker_user_profile.example.user_profile_name

  # Optional: specify instance type and image
  resource_spec {
    instance_type = "system"
    # SageMakerImageArn can be set for custom images
  }

  # Ensure app is created after domain and user profile
  depends_on = [
    aws_sagemaker_domain.example,
    aws_sagemaker_user_profile.example
  ]
}

