terraform {
  required_version = ">= 1.3"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = var.region
}

variable "region" {
  description = "AWS region"
  type        = string
  default     = "us-east-1"
}

variable "cluster_identifier" {
  description = "Redshift cluster identifier"
  type        = string
  default     = "example-redshift-cluster"
}

variable "database_name" {
  description = "Redshift database name"
  type        = string
  default     = "exampledb"
}

variable "master_username" {
  description = "Master user name"
  type        = string
  default     = "admin"
}

variable "node_type" {
  description = "Redshift node type"
  type        = string
  default     = "dc2.large"
}

variable "number_of_nodes" {
  description = "Number of nodes in the cluster"
  type        = number
  default     = 2
}

# Random password for master user
resource "random_password" "master" {
  length  = 32
  special = true
}

# KMS key for encryption
resource "aws_kms_key" "redshift" {
  description             = "KMS key for Redshift cluster encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
}

resource "aws_kms_alias" "redshift" {
  name          = "alias/redshift-${var.cluster_identifier}"
  target_key_id = aws_kms_key.redshift.key_id
}

# VPC and networking
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = "redshift-vpc"
  }
}

resource "aws_subnet" "private_a" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "${var.region}a"

  tags = {
    Name = "redshift-private-a"
  }
}

resource "aws_subnet" "private_b" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "${var.region}b"

  tags = {
    Name = "redshift-private-b"
  }
}

resource "aws_redshift_subnet_group" "main" {
  name       = "redshift-subnet-group"
  subnet_ids = [aws_subnet.private_a.id, aws_subnet.private_b.id]

  tags = {
    Name = "redshift-subnet-group"
  }
}

# Security group for Redshift
resource "aws_security_group" "redshift" {
  name        = "redshift-sg"
  description = "Security group for Redshift cluster"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 5439
    to_port     = 5439
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block] # restrict to VPC
    description = "Allow Redshift access from within VPC"
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
    description = "Allow all outbound traffic"
  }

  tags = {
    Name = "redshift-sg"
  }
}

# IAM role for Redshift
resource "aws_iam_role" "redshift" {
  name = "redshift-cluster-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "redshift.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "redshift_s3_read" {
  role       = aws_iam_role.redshift.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonS3ReadOnlyAccess"
}

# Redshift parameter group
resource "aws_redshift_parameter_group" "example" {
  name   = "example-param-group"
  family = "redshift-1.0"

  parameter {
    name  = "enable_user_activity_logging"
    value = "true"
  }

  parameter {
    name  = "require_ssl"
    value = "true"
  }

  parameter {
    name  = "use_fips_ssl"
    value = "true"
  }

  parameter {
    name  = "max_concurrency_scaling_clusters"
    value = "10"
  }

  description = "Example parameter group with security best practices"
}

# Redshift cluster
resource "aws_redshift_cluster" "example" {
  cluster_identifier = var.cluster_identifier
  database_name      = var.database_name
  master_username    = var.master_username
  master_password    = random_password.master.result
  node_type          = var.node_type
  cluster_type       = "multi-node"
  number_of_nodes    = var.number_of_nodes

  cluster_subnet_group_name = aws_redshift_subnet_group.main.name
  vpc_security_group_ids    = [aws_security_group.redshift.id]
  publicly_accessible       = false

  encrypted                     = true
  kms_key_id                    = aws_kms_key.redshift.arn
  cluster_parameter_group_name  = aws_redshift_parameter_group.example.name
  iam_roles                     = [aws_iam_role.redshift.arn]

  automated_snapshot_retention_period = 7
  allow_version_upgrade               = true
  skip_final_snapshot                 = true

  tags = {
    Name = var.cluster_identifier
  }
}

# SNS topic for event notifications
resource "aws_sns_topic" "redshift_events" {
  name = "redshift-events-topic"
}

# SNS topic policy to allow Redshift to publish
resource "aws_sns_topic_policy" "redshift_events" {
  arn = aws_sns_topic.redshift_events.arn

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "redshift.amazonaws.com"
        }
        Action   = "SNS:Publish"
        Resource = aws_sns_topic.redshift_events.arn
      }
    ]
  })
}

# Redshift event subscription for parameter group events
resource "aws_redshift_event_subscription" "example" {
  name          = "param-group-events"
  sns_topic_arn = aws_sns_topic.redshift_events.arn
  source_type   = "cluster-parameter-group"
  source_ids    = [aws_redshift_parameter_group.example.name]

  event_categories = [
    "configuration",
    "management",
    "monitoring",
    "security"
  ]

  enabled = true

  tags = {
    Name = "param-group-event-subscription"
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

# Variables (to be provided by the caller)
variable "vpc_id" {
  description = "ID of the VPC where the RDS instance will be deployed"
  type        = string
}

variable "subnet_ids" {
  description = "List of private subnet IDs for the DB subnet group (at least two AZs)"
  type        = list(string)
}

variable "allowed_cidr_blocks" {
  description = "List of CIDR blocks allowed to connect to the database (e.g., application subnets)"
  type        = list(string)
  default     = []
}

variable "db_name" {
  description = "Name of the initial database"
  type        = string
  default     = "appdb"
}

variable "master_username" {
  description = "Master username for the database"
  type        = string
  default     = "dbadmin"
}

variable "allocated_storage" {
  description = "Allocated storage in GB"
  type        = number
  default     = 20
}

variable "max_allocated_storage" {
  description = "Maximum storage for autoscaling in GB"
  type        = number
  default     = 100
}

variable "backup_retention_period" {
  description = "Number of days to retain automated backups"
  type        = number
  default     = 7
}

variable "deletion_protection" {
  description = "Enable deletion protection"
  type        = bool
  default     = true
}

variable "skip_final_snapshot" {
  description = "Skip final snapshot when destroying (set to false for production)"
  type        = bool
  default     = false
}

variable "final_snapshot_identifier_prefix" {
  description = "Prefix for the final snapshot identifier"
  type        = string
  default     = "final-snapshot"
}

variable "performance_insights_enabled" {
  description = "Enable Performance Insights"
  type        = bool
  default     = true
}

variable "performance_insights_retention_period" {
  description = "Retention period for Performance Insights in days (7, 31, 62, 93, 124, 155, 186, 217, 248, 279, 310, 341, 372)"
  type        = number
  default     = 7
}

variable "monitoring_interval" {
  description = "Enhanced monitoring interval in seconds (0 to disable)"
  type        = number
  default     = 60
}

variable "tags" {
  description = "Common tags to apply to all resources"
  type        = map(string)
  default     = {}
}

# Random password for master user
resource "random_password" "master" {
  length           = 32
  special          = true
  override_special = "!#$%&*()-_=+[]{}<>:?"
  min_special      = 4
  min_upper        = 2
  min_lower        = 2
  min_numeric      = 2
}

# Store master password in AWS Secrets Manager
resource "aws_secretsmanager_secret" "rds_master" {
  name                    = "rds-postgresql-master-${random_id.suffix.hex}"
  description             = "Master credentials for PostgreSQL RDS instance"
  recovery_window_in_days = 0 # Immediate deletion for demo; set to 7+ for production
  tags                    = var.tags
}

resource "aws_secretsmanager_secret_version" "rds_master" {
  secret_id = aws_secretsmanager_secret.rds_master.id
  secret_string = jsonencode({
    username = var.master_username
    password = random_password.master.result
    engine   = "postgres"
    host     = aws_db_instance.postgresql.address
    port     = aws_db_instance.postgresql.port
    dbname   = var.db_name
  })
}

# Random suffix to ensure globally unique names
resource "random_id" "suffix" {
  byte_length = 4
}

# DB subnet group (private subnets)
resource "aws_db_subnet_group" "postgresql" {
  name        = "postgresql-subnet-group-${random_id.suffix.hex}"
  subnet_ids  = var.subnet_ids
  description = "Subnet group for PostgreSQL RDS instance"
  tags        = var.tags
}

# Security group for RDS
resource "aws_security_group" "postgresql" {
  name        = "postgresql-sg-${random_id.suffix.hex}"
  description = "Security group for PostgreSQL RDS instance"
  vpc_id      = var.vpc_id
  tags        = var.tags

  ingress {
    description = "PostgreSQL access from allowed CIDRs"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = var.allowed_cidr_blocks
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# DB parameter group with SSL enforcement and logging
resource "aws_db_parameter_group" "postgresql" {
  name        = "postgresql-params-${random_id.suffix.hex}"
  family      = "postgres16" # Adjust if using a different major version
  description = "Custom parameter group for PostgreSQL with security best practices"
  tags        = var.tags

  parameter {
    name  = "rds.force_ssl"
    value = "1"
    apply_method = "pending-reboot"
  }

  parameter {
    name  = "log_connections"
    value = "1"
    apply_method = "pending-reboot"
  }

  parameter {
    name  = "log_disconnections"
    value = "1"
    apply_method = "pending-reboot"
  }

  parameter {
    name  = "log_statement"
    value = "ddl" # Logs all DDL statements; adjust as needed
    apply_method = "pending-reboot"
  }

  parameter {
    name  = "shared_preload_libraries"
    value = "pg_stat_statements,auto_explain"
    apply_method = "pending-reboot"
  }
}

# RDS instance
resource "aws_db_instance" "postgresql" {
  identifier = "postgresql-${random_id.suffix.hex}"

  engine         = "postgres"
  engine_version = "16.3" # Latest stable as of writing; supports Graviton2
  instance_class = "db.t4g.large"

  db_name  = var.db_name
  username = var.master_username
  password = random_password.master.result

  port = 5432

  allocated_storage     = var.allocated_storage
  max_allocated_storage = var.max_allocated_storage
  storage_type          = "gp3"
  storage_encrypted     = true
  kms_key_id            = "alias/aws/rds" # Use default RDS KMS key; replace with custom CMK ARN if needed

  db_subnet_group_name   = aws_db_subnet_group.postgresql.name
  vpc_security_group_ids = [aws_security_group.postgresql.id]

  publicly_accessible = false
  multi_az            = true # Enable Multi-AZ for high availability

  backup_retention_period = var.backup_retention_period
  backup_window           = "03:00-04:00" # UTC, adjust to off-peak hours
  maintenance_window      = "sun:04:00-sun:05:00"

  auto_minor_version_upgrade = true
  deletion_protection        = var.deletion_protection
  skip_final_snapshot        = var.skip_final_snapshot
  final_snapshot_identifier  = "${var.final_snapshot_identifier_prefix}-${random_id.suffix.hex}"

  performance_insights_enabled          = var.performance_insights_enabled
  performance_insights_retention_period = var.performance_insights_retention_period
  monitoring_interval                   = var.monitoring_interval
  monitoring_role_arn                   = aws_iam_role.rds_enhanced_monitoring.arn

  parameter_group_name = aws_db_parameter_group.postgresql.name

  enabled_cloudwatch_logs_exports = ["postgresql", "upgrade"] # Export logs to CloudWatch

  copy_tags_to_snapshot = true

  tags = merge(var.tags, {
    Name = "postgresql-${random_id.suffix.hex}"
  })

  depends_on = [
    aws_db_subnet_group.postgresql,
    aws_security_group.postgresql,
    aws_db_parameter_group.postgresql,
    aws_iam_role_policy_attachment.rds_enhanced_monitoring
  ]
}

# IAM role for enhanced monitoring
resource "aws_iam_role" "rds_enhanced_monitoring" {
  name = "rds-enhanced-monitoring-${random_id.suffix.hex}"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "monitoring.rds.amazonaws.com"
        }
      }
    ]
  })
  tags = var.tags
}

resource "aws_iam_role_policy_attachment" "rds_enhanced_monitoring" {
  role       = aws_iam_role.rds_enhanced_monitoring.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonRDSEnhancedMonitoringRole"
}

# Outputs
output "db_instance_endpoint" {
  description = "RDS instance endpoint (hostname)"
  value       = aws_db_instance.postgresql.address
}

output "db_instance_port" {
  description = "RDS instance port"
  value       = aws_db_instance.postgresql.port
}

output "db_instance_arn" {
  description = "RDS instance ARN"
  value       = aws_db_instance.postgresql.arn
}

output "master_secret_arn" {
  description = "ARN of the Secrets Manager secret containing master credentials"
  value       = aws_secretsmanager_secret.rds_master.arn
}

