  tags = {
    Name = "mysql-subnet-group"
  }
}

# Security group for RDS
resource "aws_security_group" "mysql" {
  name        = "mysql-sg"
  description = "Allow MySQL inbound from VPC"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "MySQL from VPC"
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "mysql-sg"
  }
}

# RDS MySQL instance
resource "aws_db_instance" "mysql" {
  identifier             = var.db_instance_identifier
  engine                 = "mysql"
  engine_version         = "8.0"
  instance_class         = "db.t3.micro"
  allocated_storage      = 20
  max_allocated_storage  = 100
  storage_encrypted      = true
  db_name                = var.db_name
  username               = var.db_username
  password               = random_password.master.result
  port                   = 3306
  publicly_accessible    = false
  vpc_security_group_ids = [aws_security_group.mysql.id]
  db_subnet_group_name   = aws_db_subnet_group.mysql.name
  backup_retention_period = 7
  backup_window          = "03:00-04:00"
  maintenance_window     = "sun:05:00-sun:06:00"
  deletion_protection    = true
  skip_final_snapshot    = false
  final_snapshot_identifier = "${var.db_instance_identifier}-final-snapshot"

  tags = {
    Name = var.db_instance_identifier
  }
}

# DB snapshot of the instance
resource "aws_db_snapshot" "mysql" {
  db_instance_identifier = aws_db_instance.mysql.identifier
  db_snapshot_identifier = var.db_snapshot_identifier

  tags = {
    Name = var.db_snapshot_identifier
  }
}

output "db_instance_endpoint" {
  description = "RDS instance endpoint"
  value       = aws_db_instance.mysql.endpoint
}

output "db_snapshot_id" {
  description = "RDS snapshot ID"
  value       = aws_db_snapshot.mysql.id
}

output "secrets_manager_arn" {
  description = "ARN of the Secrets Manager secret holding credentials"
  value       = aws_secretsmanager_secret.rds_credentials.arn
}

