  cidr_block        = cidrsubnet(aws_vpc.eu_central.cidr_block, 8, count.index + 2)
  availability_zone = data.aws_availability_zones.eu_central.names[count.index]
  tags = {
    Name = "eu-central-private-${count.index + 1}"
  }
}

# NAT Gateway
resource "aws_eip" "eu_central_nat" {
  provider = aws.eu_central
  domain   = "vpc"
}

resource "aws_nat_gateway" "eu_central" {
  provider      = aws.eu_central
  allocation_id = aws_eip.eu_central_nat.id
  subnet_id     = aws_subnet.eu_central_public[0].id
  tags = {
    Name = "eu-central-nat"
