  tags = {
    Name = "eu-central-lb-sg"
  }
}

resource "aws_security_group" "eu_central_ec2" {
  provider    = aws.eu_central
  name        = "eu-central-ec2-sg"
  description = "EC2 instances security group"
  vpc_id      = aws_vpc.eu_central.id

  ingress {
    from_port       = 80
    to_port         = 80
    protocol        = "tcp"
    security_groups = [aws_security_group.eu_central_lb.id]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "eu-central-ec2-sg"
  }
