# =============================================================================
# Route53 Geolocation Routing
# =============================================================================

# Hosted zone (global resource, created in default region)
resource "aws_route53_zone" "main" {
  name = var.domain_name
}

# Data sources to fetch ALB details from each environment
data "aws_lb" "us_west" {
  name = aws_elastic_beanstalk_environment.us_west.load_balancers[0]
}

data "aws_lb" "eu_central" {
  provider = aws.eu_central
  name     = aws_elastic_beanstalk_environment.eu_central.load_balancers[0]
}

# Geolocation record for North America -> us-west environment
resource "aws_route53_record" "us_west" {
  zone_id = aws_route53_zone.main.zone_id
  name    = "www.${var.domain_name}"
  type    = "A"

  alias {
    name                   = data.aws_lb.us_west.dns_name
    zone_id                = data.aws_lb.us_west.zone_id
    evaluate_target_health = true
  }

  routing_policy = "geolocation"
  geolocation {
    continent = "North America"
  }
  set_identifier = "us-west"
}

# Geolocation record for Europe -> eu-central environment
resource "aws_route53_record" "eu_central" {
  zone_id = aws_route53_zone.main.zone_id
  name    = "www.${var.domain_name}"
  type    = "A"

  alias {
    name                   = data.aws_lb.eu_central.dns_name
    zone_id                = data.aws_lb.eu_central.zone_id
    evaluate_target_health = true
  }

  routing_policy = "geolocation"
  geolocation {
    continent = "Europe"
  }
  set_identifier = "eu-central"
}

# =============================================================================
# Outputs
# =============================================================================

output "us_west_environment_url" {
  value = aws_elastic_beanstalk_environment.us_west.cname
}

output "eu_central_environment_url" {
  value = aws_elastic_beanstalk_environment.eu_central.cname
}

output "route53_zone_id" {
  value = aws_route53_zone.main.zone_id
}

