model_answers:
terraform {
  required_version = ">= 1.3"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# -----------------------------------------------------------------------------
# Variables
# -----------------------------------------------------------------------------
variable "region" {
  description = "AWS region"
  type        = string
  default     = "us-east-1"
}

variable "vpc_id" {
  description = "ID of the VPC where resources will be deployed"
  type        = string
}

variable "vpc_cidr" {
  description = "CIDR block of the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "private_subnet_ids" {
  description = "List of private subnet IDs for VPC endpoints and Firehose ENIs"
  type        = list(string)
}

variable "collection_name" {
  description = "Name of the OpenSearch Serverless collection"
  type        = string
  default     = "firehose-logs"
}

variable "index_name" {
  description = "Name of the OpenSearch index for Firehose records"
  type        = string
  default     = "firehose-index"
}

variable "backup_bucket_name" {
  description = "Name of the S3 bucket for failed Firehose records"
  type        = string
  default     = "firehose-backup-bucket-unique-suffix" # change to a globally unique name
}

# -----------------------------------------------------------------------------
# KMS Keys
# -----------------------------------------------------------------------------
resource "aws_kms_key" "firehose_sse" {
  description             = "KMS key for Firehose delivery stream server-side encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow Firehose to use the key"
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey*"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "kms:CallerAccount" = data.aws_caller_identity.current.account_id
          }
        }
      }
    ]
  })
}

resource "aws_kms_key" "opensearch_serverless" {
  description             = "KMS key for OpenSearch Serverless collection encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow OpenSearch Serverless to use the key"
        Effect = "Allow"
        Principal = {
          Service = "aoss.amazonaws.com"
        }
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "kms:CallerAccount" = data.aws_caller_identity.current.account_id
          }
        }
      }
    ]
  })
}

resource "aws_kms_alias" "firehose_sse" {
  name          = "alias/firehose-sse-key"
  target_key_id = aws_kms_key.firehose_sse.key_id
}

resource "aws_kms_alias" "opensearch_serverless" {
  name          = "alias/opensearch-serverless-key"
  target_key_id = aws_kms_key.opensearch_serverless.key_id
}

# -----------------------------------------------------------------------------
# Data sources
# -----------------------------------------------------------------------------
data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

# -----------------------------------------------------------------------------
# S3 Backup Bucket
# -----------------------------------------------------------------------------
resource "aws_s3_bucket" "backup" {
  bucket        = var.backup_bucket_name
  force_destroy = true # set to false in production
}

resource "aws_s3_bucket_versioning" "backup" {
  bucket = aws_s3_bucket.backup.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "backup" {
  bucket = aws_s3_bucket.backup.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "backup" {
  bucket                  = aws_s3_bucket.backup.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_lifecycle_configuration" "backup" {
  bucket = aws_s3_bucket.backup.id
  rule {
    id     = "expire-old-backups"
    status = "Enabled"
    expiration {
      days = 30
    }
    noncurrent_version_expiration {
      noncurrent_days = 7
    }
  }
}

# -----------------------------------------------------------------------------
# CloudWatch Log Group for Firehose errors
# -----------------------------------------------------------------------------
resource "aws_cloudwatch_log_group" "firehose_errors" {
  name              = "/aws/kinesisfirehose/${var.collection_name}"
  retention_in_days = 14
}

# -----------------------------------------------------------------------------
# Security Groups
# -----------------------------------------------------------------------------
resource "aws_security_group" "vpc_endpoint" {
  name        = "aoss-endpoint-sg"
  description = "Security group for OpenSearch Serverless VPC endpoint"
  vpc_id      = var.vpc_id

  ingress {
    description = "Allow HTTPS from VPC"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    description = "Allow all outbound"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "aoss-endpoint-sg"
  }
}

resource "aws_security_group" "firehose_eni" {
  name        = "firehose-eni-sg"
  description = "Security group for Firehose ENIs to access OpenSearch Serverless"
  vpc_id      = var.vpc_id

  egress {
    description     = "Allow HTTPS to OpenSearch Serverless endpoint"
    from_port       = 443
    to_port         = 443
    protocol        = "tcp"
    security_groups = [aws_security_group.vpc_endpoint.id]
  }

  tags = {
    Name = "firehose-eni-sg"
  }
}

# -----------------------------------------------------------------------------
# VPC Endpoint for OpenSearch Serverless
# -----------------------------------------------------------------------------
resource "aws_vpc_endpoint" "aoss" {
  vpc_id              = var.vpc_id
  service_name        = "com.amazonaws.${data.aws_region.current.name}.aoss"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = var.private_subnet_ids
  security_group_ids  = [aws_security_group.vpc_endpoint.id]
  private_dns_enabled = true

  tags = {
    Name = "aoss-vpc-endpoint"
  }
}

# -----------------------------------------------------------------------------
# OpenSearch Serverless Collection
# -----------------------------------------------------------------------------
resource "aws_opensearchserverless_collection" "this" {
  name = var.collection_name
  type = "TIMESERIES" # or "SEARCH" depending on use case
  standby_replicas = "ENABLED" # set to "DISABLED" for cost savings in dev

  tags = {
    Environment = "production"
    Purpose     = "Firehose destination"
  }
}

# Encryption policy for the collection
resource "aws_opensearchserverless_security_policy" "encryption" {
  name        = "${var.collection_name}-encryption"
  type        = "encryption"
  description = "Encryption policy for the collection"
  policy = jsonencode({
    Rules = [
      {
        ResourceType = "collection"
        Resource     = ["collection/${var.collection_name}"]
      }
    ],
    AWSOwnedKey = false,
    KmsARN      = aws_kms_key.opensearch_serverless.arn
  })
}

# Network policy – restrict access to VPC endpoint and VPC
resource "aws_opensearchserverless_security_policy" "network" {
  name        = "${var.collection_name}-network"
  type        = "network"
  description = "Network policy for the collection"
  policy = jsonencode([
    {
      Rules = [
        {
          ResourceType = "collection"
          Resource     = ["collection/${var.collection_name}"]
        }
      ],
      AllowFromPublic = false,
      SourceVPCEs     = [aws_vpc_endpoint.aoss.id],
      SourceVPCs      = [var.vpc_id]
    }
  ])
}

# Data access policy – grant Firehose role write access
resource "aws_opensearchserverless_access_policy" "data" {
  name        = "${var.collection_name}-data-access"
  type        = "data"
  description = "Data access policy for Firehose"
  policy = jsonencode([
    {
      Rules = [
        {
          ResourceType = "collection"
          Resource     = ["collection/${var.collection_name}"]
          Permission = [
            "aoss:CreateIndex",
            "aoss:UpdateIndex",
            "aoss:DescribeIndex",
            "aoss:WriteDocument"
          ]
        },
        {
          ResourceType = "index"
          Resource     = ["index/${var.collection_name}/${var.index_name}*"]
          Permission = [
            "aoss:CreateIndex",
            "aoss:UpdateIndex",
            "aoss:DescribeIndex",
            "aoss:WriteDocument"
          ]
        }
      ],
      Principal = [
        aws_iam_role.firehose.arn
      ]
    }
  ])
}

# -----------------------------------------------------------------------------
# IAM Role for Firehose Delivery Stream
# -----------------------------------------------------------------------------
resource "aws_iam_role" "firehose" {
  name = "firehose-to-opensearch-serverless-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

# Inline policy for Firehose role
resource "aws_iam_role_policy" "firehose" {
  name = "firehose-permissions"
  role = aws_iam_role.firehose.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      # S3 backup bucket permissions
      {
        Effect = "Allow"
        Action = [
          "s3:PutObject",
          "s3:GetObject",
          "s3:ListBucket"
        ]
        Resource = [
          aws_s3_bucket.backup.arn,
          "${aws_s3_bucket.backup.arn}/*"
        ]
      },
      # CloudWatch Logs permissions
      {
        Effect = "Allow"
        Action = [
          "logs:PutLogEvents",
          "logs:CreateLogStream",
          "logs:DescribeLogStreams"
        ]
        Resource = "${aws_cloudwatch_log_group.firehose_errors.arn}:*"
      },
      # OpenSearch Serverless permissions (already granted via data access policy,
      # but Firehose also needs aoss:APIAccessAll or specific actions for the endpoint)
      {
        Effect = "Allow"
        Action = [
          "aoss:APIAccessAll"
        ]
        Resource = aws_opensearchserverless_collection.this.arn
      },
      # KMS permissions for delivery stream encryption
      {
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey"
        ]
        Resource = aws_kms_key.firehose_sse.arn
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# Kinesis Firehose Delivery Stream
# -----------------------------------------------------------------------------
resource "aws_kinesis_firehose_delivery_stream" "this" {
  name        = "firehose-to-opensearch-serverless"
  destination = "opensearchserverless"

  opensearchserverless_configuration {
    collection_endpoint = aws_opensearchserverless_collection.this.collection_endpoint
    index_name          = var.index_name

    buffering {
      interval_in_seconds = 60
      size_in_mbs         = 5
    }

    retry_duration = 300

    s3_backup_mode = "FailedDocumentsOnly"

    s3_configuration {
      role_arn           = aws_iam_role.firehose.arn
      bucket_arn         = aws_s3_bucket.backup.arn
      buffering_interval = 300
      buffering_size     = 5
      compression_format = "GZIP"
    }

    cloudwatch_logging_options {
      enabled         = true
      log_group_name  = aws_cloudwatch_log_group.firehose_errors.name
      log_stream_name = "firehose-errors"
    }

    vpc_config {
      subnet_ids         = var.private_subnet_ids
      security_group_ids = [aws_security_group.firehose_eni.id]
      role_arn           = aws_iam_role.firehose.arn
    }
  }

  server_side_encryption {
    enabled  = true
    key_type = "CUSTOMER_MANAGED_CMK"
    key_arn  = aws_kms_key.firehose_sse.arn
  }

  depends_on = [
    aws_opensearchserverless_access_policy.data,
    aws_opensearchserverless_security_policy.network,
    aws_opensearchserverless_security_policy.encryption,
    aws_vpc_endpoint.aoss
  ]
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "collection_endpoint" {
  value       = aws_opensearchserverless_collection.this.collection_endpoint
  description = "OpenSearch Serverless collection endpoint"
}

output "delivery_stream_arn" {
  value       = aws_kinesis_firehose_delivery_stream.this.arn
  description = "ARN of the Firehose delivery stream"
}

output "backup_bucket_name" {
  value       = aws_s3_bucket.backup.id
  description = "Name of the S3 backup bucket"
}

