terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = var.region
}

data "aws_availability_zones" "available" {
  state = "available"
}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = "main-vpc"
  }
}

# Internet Gateway for public subnets (required for publicly accessible RDS)
resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "main-igw"
  }
}

# Public subnets in two different AZs
resource "aws_subnet" "public" {
  count                   = 2
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = true

  tags = {
    Name = "public-subnet-${count.index + 1}"
  }
}

# Route table with default route to Internet Gateway
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name = "public-route-table"
  }
}

# Associate route table with both public subnets
resource "aws_route_table_association" "public" {
  count          = 2
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# DB subnet group spanning both public subnets
resource "aws_db_subnet_group" "database" {
  name       = "database-subnet-group"
  subnet_ids = aws_subnet.public[*].id

  tags = {
    Name = "database-subnet-group"
  }
}

# Security group for RDS PostgreSQL
resource "aws_security_group" "database" {
  name        = "database-sg"
  description = "Allow PostgreSQL inbound traffic"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "PostgreSQL access"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = [var.allowed_cidr] # Restrict this in production
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "database-sg"
  }
}

# Generate a random password for the master user
resource "random_password" "master" {
  length  = 32
  special = true
}

# Store the password in AWS Secrets Manager
resource "aws_secretsmanager_secret" "db_master" {
  name = "rds-postgres-master-password"
}

resource "aws_secretsmanager_secret_version" "db_master" {
  secret_id     = aws_secretsmanager_secret.db_master.id
  secret_string = random_password.master.result
}

# RDS PostgreSQL instance
resource "aws_db_instance" "postgres" {
  identifier = "postgres-db"

  engine         = "postgres"
  engine_version = "15.3"
  instance_class = "db.t4g.micro"

  allocated_storage     = 200
  storage_type          = "gp2"
  storage_encrypted     = true # Encrypt storage at rest

  db_name  = var.db_name
  username = var.db_username
  password = random_password.master.result

  db_subnet_group_name   = aws_db_subnet_group.database.name
  vpc_security_group_ids = [aws_security_group.database.id]

  publicly_accessible    = true
  multi_az               = false
  skip_final_snapshot    = true # Set to false and provide final_snapshot_identifier in production
  deletion_protection    = false # Enable in production
  backup_retention_period = 7
  backup_window           = "03:00-04:00"
  maintenance_window      = "sun:05:00-sun:06:00"
  auto_minor_version_upgrade = true

  tags = {
    Name = "postgres-db"
  }
}

# Outputs
output "db_endpoint" {
  description = "RDS instance endpoint (address:port)"
  value       = "${aws_db_instance.postgres.address}:${aws_db_instance.postgres.port}"
}

output "db_secret_arn" {
  description = "ARN of the Secrets Manager secret containing the master password"
  value       = aws_secretsmanager_secret.db_master.arn
}

