    message {
      content      = "Sorry, I cannot assist you to book the trip right now."
      content_type = "PlainText"
    }
  }

  clarification_prompt {
    max_attempts = 3

    message {
      content      = "I'm sorry, I didn't understand. Could you please repeat that?"
      content_type = "PlainText"
    }
  }

  intent {
    intent_name    = aws_lex_intent.BookTrip.name
    intent_version = aws_lex_intent.BookTrip.version
  }
}

model_answers:
resource "aws_lex_bot" "trip_booking" {
  name           = "TripBookingBot"
  description    = "Bot for booking a trip with destination, dates, and number of guests."
  create_version = true
  child_directed = false

  detect_sentiment          = false
  enable_model_improvements = true
  idle_session_ttl_in_seconds = 300

  locale           = "en-US"
  process_behavior = "BUILD"
  voice_id         = "Joanna"

  clarification_prompt {
    max_attempts = 2
    message {
      content      = "I didn't understand. Could you please provide more details about your trip?"
      content_type = "PlainText"
    }
  }

  abort_statement {
    message {
      content      = "I'm sorry, I couldn't book your trip. Please try again later."
      content_type = "PlainText"
    }
  }

  intent {
    name = "BookTrip"

    sample_utterances = [
      "I want to book a trip",
      "Book a vacation",
      "Plan a trip to {Destination}",
      "I need a trip to {Destination} from {CheckInDate} to {CheckOutDate}",
      "Book a trip for {NumberOfGuests} people to {Destination}",
      "Reserve a trip to {Destination} for {NumberOfGuests} guests",
      "I want to go to {Destination} on {CheckInDate}",
      "Plan a vacation from {CheckInDate} to {CheckOutDate}",
      "Book a trip for {NumberOfGuests}",
    ]

    slot {
      name        = "Destination"
      description = "City or place to visit"
      priority    = 1
      slot_type   = "AMAZON.City"
      slot_constraint = "Required"

      value_elicitation_prompt {
        max_attempts = 2
        message {
          content      = "Which city would you like to visit?"
          content_type = "PlainText"
        }
      }
    }

    slot {
      name        = "CheckInDate"
      description = "Start date of the trip"
      priority    = 2
      slot_type   = "AMAZON.DATE"
      slot_constraint = "Required"

      value_elicitation_prompt {
        max_attempts = 2
        message {
          content      = "What date would you like to check in?"
          content_type = "PlainText"
        }
      }
    }

    slot {
      name        = "CheckOutDate"
      description = "End date of the trip"
      priority    = 3
      slot_type   = "AMAZON.DATE"
      slot_constraint = "Required"

      value_elicitation_prompt {
        max_attempts = 2
        message {
          content      = "What date would you like to check out?"
          content_type = "PlainText"
        }
      }
    }

    slot {
      name        = "NumberOfGuests"
      description = "Number of people traveling"
      priority    = 4
      slot_type   = "AMAZON.NUMBER"
      slot_constraint = "Required"

      value_elicitation_prompt {
        max_attempts = 2
        message {
          content      = "How many guests will be traveling?"
          content_type = "PlainText"
        }
      }
    }

    fulfillment_activity {
      type = "CodeHook"
      code_hook {
        message_version = "1.0"
        uri             = var.lambda_arn
      }
    }
  }
}

variable "lambda_arn" {
  description = "ARN of the Lambda function for fulfillment"
  type        = string
  default     = "arn:aws:lambda:us-east-1:123456789012:function:TripBookingFulfillment"
}

