model_answers:
terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

# Fetch default VPC and subnets (adjust filters for your environment)
data "aws_vpc" "default" {
  default = true
}

data "aws_subnets" "database" {
  filter {
    name   = "vpc-id"
    values = [data.aws_vpc.default.id]
  }
  filter {
    name   = "availability-zone"
    values = ["us-east-1a", "us-east-1b", "us-east-1c"] # adjust to your region
  }
}

# KMS key for RDS encryption
resource "aws_kms_key" "rds" {
  description             = "KMS key for RDS encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
}

resource "aws_kms_alias" "rds" {
  name          = "alias/rds-encryption-key"
  target_key_id = aws_kms_key.rds.key_id
}

# Random password for master user
resource "random_password" "master" {
  length  = 32
  special = true
  override_special = "!#$%&*()-_=+[]{}<>:?"
}

# Store master password in Secrets Manager
resource "aws_secretsmanager_secret" "rds_master" {
  name                    = "rds-primary-master-password"
  recovery_window_in_days = 0 # forces immediate deletion for demo; set to 7 for production
}

resource "aws_secretsmanager_secret_version" "rds_master" {
  secret_id     = aws_secretsmanager_secret.rds_master.id
  secret_string = random_password.master.result
}

# DB subnet group
resource "aws_db_subnet_group" "main" {
  name       = "rds-subnet-group"
  subnet_ids = data.aws_subnets.database.ids

  tags = {
    Name = "RDS Subnet Group"
  }
}

# Security group for RDS
resource "aws_security_group" "rds" {
  name        = "rds-sg"
  description = "Security group for RDS instances"
  vpc_id      = data.aws_vpc.default.id

  ingress {
    description = "MySQL access from application"
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/16"] # restrict to your application CIDR
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "RDS Security Group"
  }
}

# DB parameter group to enforce SSL
resource "aws_db_parameter_group" "mysql_ssl" {
  name   = "mysql-ssl-params"
  family = "mysql8.0"

  parameter {
    name  = "require_secure_transport"
    value = "1"
  }

  tags = {
    Name = "MySQL SSL Parameter Group"
  }
}

# Primary RDS instance (MySQL)
resource "aws_db_instance" "primary" {
  identifier             = "primary-mysql"
  engine                 = "mysql"
  engine_version         = "8.0.35"
  instance_class         = "db.t3.micro" # adjust as needed
  allocated_storage      = 20
  storage_encrypted      = true
  kms_key_id             = aws_kms_key.rds.arn
  db_name                = "appdb"
  username               = "admin"
  password               = random_password.master.result
  port                   = 3306
  publicly_accessible    = false
  vpc_security_group_ids = [aws_security_group.rds.id]
  db_subnet_group_name   = aws_db_subnet_group.main.name
  parameter_group_name   = aws_db_parameter_group.mysql_ssl.name
  backup_retention_period = 7
  backup_window           = "03:00-04:00"
  maintenance_window      = "sun:05:00-sun:06:00"
  deletion_protection     = true
  skip_final_snapshot     = false
  final_snapshot_identifier = "primary-mysql-final-snapshot-${formatdate("YYYY-MM-DD-hhmm", timestamp())}"
  copy_tags_to_snapshot   = true
  enabled_cloudwatch_logs_exports = ["error", "general", "slowquery"]
  performance_insights_enabled    = true
  performance_insights_kms_key_id = aws_kms_key.rds.arn
  monitoring_interval             = 60
  monitoring_role_arn             = aws_iam_role.rds_monitoring.arn

  tags = {
    Name = "Primary MySQL"
  }
}

# IAM role for enhanced monitoring
resource "aws_iam_role" "rds_monitoring" {
  name = "rds-monitoring-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "monitoring.rds.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "rds_monitoring" {
  role       = aws_iam_role.rds_monitoring.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonRDSEnhancedMonitoringRole"
}

# Read replica
resource "aws_db_instance" "replica" {
  identifier             = "replica-mysql"
  replicate_source_db    = aws_db_instance.primary.identifier
  instance_class         = "db.t3.micro"
  storage_encrypted      = true
  kms_key_id             = aws_kms_key.rds.arn
  publicly_accessible    = false
  vpc_security_group_ids = [aws_security_group.rds.id]
  parameter_group_name   = aws_db_parameter_group.mysql_ssl.name
  backup_retention_period = 0 # replicas typically don't need automated backups
  skip_final_snapshot     = true
  copy_tags_to_snapshot   = true
  performance_insights_enabled    = true
  performance_insights_kms_key_id = aws_kms_key.rds.arn
  monitoring_interval             = 60
  monitoring_role_arn             = aws_iam_role.rds_monitoring.arn

  tags = {
    Name = "Read Replica MySQL"
  }
}

# Outputs
output "primary_endpoint" {
  value       = aws_db_instance.primary.endpoint
  description = "Primary RDS endpoint"
}

output "replica_endpoint" {
  value       = aws_db_instance.replica.endpoint
  description = "Read replica endpoint"
}

output "master_password_secret_arn" {
  value       = aws_secretsmanager_secret.rds_master.arn
  description = "ARN of the secret containing the master password"
}

