terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = var.region
}

# Variables with sensible defaults
variable "region" {
  description = "AWS region"
  type        = string
  default     = "us-east-1"
}

variable "db_name" {
  description = "Name of the Lightsail database"
  type        = string
  default     = "mydb"
}

variable "master_username" {
  description = "Master username for the database"
  type        = string
  default     = "dbadmin"
}

variable "blueprint_id" {
  description = "Lightsail database blueprint (engine and version)"
  type        = string
  default     = "mysql_8_0" # e.g., mysql_8_0, postgres_12_8
}

variable "bundle_id" {
  description = "Lightsail database bundle (size and performance)"
  type        = string
  default     = "micro_2_0" # e.g., micro_2_0, small_2_0
}

variable "preferred_backup_window" {
  description = "Daily backup window in UTC (hh24:mi-hh24:mi)"
  type        = string
  default     = "03:00-05:00"
}

variable "preferred_maintenance_window" {
  description = "Weekly maintenance window in UTC (ddd:hh24:mi-ddd:hh24:mi)"
  type        = string
  default     = "sun:05:00-sun:07:00"
}

variable "tags" {
  description = "Tags to apply to resources"
  type        = map(string)
  default = {
    Environment = "production"
    ManagedBy   = "Terraform"
  }
}

# Generate a strong random password for the master user
resource "random_password" "master" {
  length  = 16
  special = true
  # Ensure compatibility with most database engines
  override_special = "!#$%&*()-_=+[]{}<>:?"
}

# Store the password in AWS Secrets Manager
resource "aws_secretsmanager_secret" "db_master" {
  name        = "lightsail/${var.db_name}/master-credentials"
  description = "Master credentials for Lightsail database ${var.db_name}"
  tags        = var.tags
}

resource "aws_secretsmanager_secret_version" "db_master" {
  secret_id = aws_secretsmanager_secret.db_master.id
  secret_string = jsonencode({
    username = var.master_username
    password = random_password.master.result
    engine   = var.blueprint_id
    host     = aws_lightsail_database.main.master_endpoint_address
    port     = aws_lightsail_database.main.master_endpoint_port
  })
}

# Lightsail managed database
resource "aws_lightsail_database" "main" {
  # Use a name that is unique within the region
  relational_database_name = var.db_name

  # Database engine and version
  blueprint_id = var.blueprint_id
  # Instance size / performance bundle
  bundle_id = var.bundle_id

  # Master credentials
  master_database_name = var.db_name
  master_username      = var.master_username
  master_password      = random_password.master.result

  # Security: disable public accessibility (default is false, but explicit is good)
  publicly_accessible = false

  # Backup configuration
  backup_retention_enabled = true
  preferred_backup_window  = var.preferred_backup_window

  # Maintenance window
  preferred_maintenance_window = var.preferred_maintenance_window

  # Snapshot behavior on deletion
  skip_final_snapshot = false
  final_snapshot_name = "final-${var.db_name}-${formatdate("YYYY-MM-DD-hhmm", timestamp())}"

  # Apply changes immediately? Set to false for production to avoid unexpected downtime
  apply_immediately = false

  # Tags
  tags = var.tags
}

# Outputs for easy access
output "database_endpoint" {
  description = "Endpoint address of the Lightsail database"
  value       = aws_lightsail_database.main.master_endpoint_address
}

output "database_port" {
  description = "Port of the Lightsail database"
  value       = aws_lightsail_database.main.master_endpoint_port
}

output "database_arn" {
  description = "ARN of the Lightsail database"
  value       = aws_lightsail_database.main.arn
}

output "secret_arn" {
  description = "ARN of the Secrets Manager secret holding master credentials"
  value       = aws_secretsmanager_secret.db_master.arn
}

