  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region for resources"
  type        = string
  default     = "us-east-1"
}

variable "application_name" {
  description = "Name of the Kinesis Analytics application"
  type        = string
  default     = "kinesis-analytics-app"
}

variable "environment" {
  description = "Environment name"
  type        = string
  default     = "production"
}

# CloudWatch Log Group
resource "aws_cloudwatch_log_group" "kinesis_analytics" {
  name              = "/aws/kinesisanalytics/${var.application_name}"
  retention_in_days = 14

  tags = {
    Name        = var.application_name
    Environment = var.environment
  }
}

# CloudWatch Log Stream
resource "aws_cloudwatch_log_stream" "kinesis_analytics" {
  name           = "application-logs"
  log_group_name = aws_cloudwatch_log_group.kinesis_analytics.name
}

# IAM Role for Kinesis Analytics
resource "aws_iam_role" "kinesis_analytics" {
  name = "${var.application_name}-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "kinesisanalytics.amazonaws.com"
        }
      }
    ]
  })

  tags = {
    Name        = var.application_name
    Environment = var.environment
  }
}

# IAM Policy for CloudWatch Logs (least privilege)
resource "aws_iam_role_policy" "kinesis_analytics_logs" {
  name = "${var.application_name}-logs-policy"
  role = aws_iam_role.kinesis_analytics.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogStreams"
        ]
        Resource = [
          "${aws_cloudwatch_log_group.kinesis_analytics.arn}:*"
        ]
      }
    ]
  })
}

# Kinesis Analytics Application
resource "aws_kinesis_analytics_application" "this" {
  name        = var.application_name
  description = "Basic Kinesis Analytics Application with CloudWatch logging"

  cloudwatch_logging_options {
    log_stream_arn = aws_cloudwatch_log_stream.kinesis_analytics.arn
    role_arn       = aws_iam_role.kinesis_analytics.arn
  }

  tags = {
    Name        = var.application_name
    Environment = var.environment
  }

  depends_on = [
    aws_iam_role_policy.kinesis_analytics_logs
  ]
}

