}

variable "mysql_allowed_cidr" {
  description = "CIDR block allowed to connect to MySQL (e.g., your office IP/32). Restrict for security."
  type        = string
  # Default is intentionally left blank to force explicit input.
  # For testing you may set it to "0.0.0.0/0", but this is NOT recommended for production.
}

resource "aws_lightsail_static_ip" "mysql_ip" {
  name = "mysql-db-static-ip"
}

resource "aws_lightsail_instance" "mysql" {
  name              = "mysql-db-instance"
  availability_zone = "${var.aws_region}a"
  blueprint_id      = "mysql_8_0"
  bundle_id         = "micro_2_0" # smallest bundle suitable for MySQL
  key_pair_name     = aws_lightsail_key_pair.admin.key_pair_name # optional, for SSH access

  tags = {
    Name        = "MySQL-Database-Server"
    Environment = "production"
  }
}

