  name       = "mysql-admin-key"
  public_key = file("~/.ssh/id_rsa.pub") # replace with your public key path or use a variable
}

resource "aws_lightsail_static_ip_attachment" "mysql_attach" {
  static_ip_name = aws_lightsail_static_ip.mysql_ip.name
  instance_name  = aws_lightsail_instance.mysql.name
}

resource "aws_lightsail_instance_public_ports" "mysql_ports" {
  instance_name = aws_lightsail_instance.mysql.name

  port_info {
    protocol  = "tcp"
    from_port = 3306
    to_port   = 3306
    cidrs     = [var.mysql_allowed_cidr]
  }

  # Optional: allow SSH only from a restricted CIDR (add your IP)
  # port_info {
  #   protocol  = "tcp"
  #   from_port = 22
  #   to_port   = 22
  #   cidrs     = ["YOUR_IP/32"]
  # }
}

output "mysql_endpoint" {
  description = "Public IP address of the MySQL Lightsail instance"
  value       = aws_lightsail_static_ip.mysql_ip.ip_address
}

output "mysql_port" {
  description = "MySQL port"
  value       = 3306
}

