resource "aws_lex_bot" "pizza_ordering_bot" {
  name                        = "OrderPizzaBot"
  description                 = "A bot for ordering pizzas"
  child_directed              = false
  idle_session_ttl_in_seconds = 300
  locale                      = "en-US"
  process_behavior            = "BUILD"

  abort_statement {
    message {
      content      = "Sorry, I'm having trouble understanding. Please try again later."
      content_type = "PlainText"
    }
  }

  clarification_prompt {
    max_attempts = 2
    message {
      content      = "I didn't understand that. Would you like to order a pizza?"
      content_type = "PlainText"
    }
  }

  intent {
    name = "OrderPizza"
    sample_utterances = [
      "I want to order a pizza",
      "Order a pizza",
      "I would like a pizza"
    ]

    fulfillment_activity {
      type = "ReturnIntent"
    }

    conclusion_statement {
      message {
        content      = "Your pizza order has been placed successfully. Thank you!"
        content_type = "PlainText"
      }
    }

    slot {
      name            = "PizzaSize"
      slot_type       = "AMAZON.NUMBER"
      slot_constraint = "Required"
      priority       = 1

      value_elicitation_prompt {
        max_attempts = 2
        message {
