terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region for resources"
  type        = string
  default     = "us-east-1"
}

variable "environment" {
  description = "Environment name"
  type        = string
  default     = "production"
}

variable "project_name" {
  description = "Project name used for resource naming"
  type        = string
  default     = "myapp"
}

variable "redis_auth_token" {
  description = "Auth token for Redis (must be 16+ characters)"
  type        = string
  sensitive   = true
}

variable "vpc_cidr" {
  description = "CIDR block for VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "allowed_cidr_blocks" {
  description = "List of CIDR blocks allowed to access Redis"
  type        = list(string)
  default     = ["10.0.0.0/16"]
}

# ============================================================================
# KMS Key for encryption at rest
# ============================================================================

resource "aws_kms_key" "redis" {
  description             = "KMS key for ElastiCache Redis encryption at rest"
  enable_key_rotation     = true
  deletion_window_in_days = 30

  tags = {
    Name        = "${var.project_name}-redis-kms-key"
    Environment = var.environment
  }
}

resource "aws_kms_alias" "redis" {
  name          = "alias/${var.project_name}-redis"
  target_key_id = aws_kms_key.redis.key_id
}

# ============================================================================
# VPC and Networking
# ============================================================================

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name        = "${var.project_name}-vpc"
    Environment = var.environment
  }
}

resource "aws_subnet" "private" {
  count             = 3
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(var.vpc_cidr, 4, count.index + 4)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name        = "${var.project_name}-private-subnet-${count.index + 1}"
    Environment = var.environment
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

# ============================================================================
# Security Group for Redis
# ============================================================================

resource "aws_security_group" "redis" {
  name_prefix = "${var.project_name}-redis-sg-"
  description = "Security group for ElastiCache Redis"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Redis access from allowed CIDR blocks"
    from_port   = 6379
    to_port     = 6379
    protocol    = "tcp"
    cidr_blocks = var.allowed_cidr_blocks
  }

  egress {
    description = "No outbound traffic required for Redis"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name        = "${var.project_name}-redis-sg"
    Environment = var.environment
  }

  lifecycle {
    create_before_destroy = true
  }
}

# ============================================================================
# ElastiCache Subnet Group
# ============================================================================

resource "aws_elasticache_subnet_group" "redis" {
  name        = "${var.project_name}-redis-subnet-group"
  description = "Subnet group for ElastiCache Redis"
  subnet_ids  = aws_subnet.private[*].id

  tags = {
    Name        = "${var.project_name}-redis-subnet-group"
    Environment = var.environment
  }
}

# ============================================================================
# ElastiCache Parameter Group
# ============================================================================

resource "aws_elasticache_parameter_group" "redis" {
  name        = "${var.project_name}-redis-params"
  description = "Parameter group for ElastiCache Redis with security best practices"
  family      = "redis7"

  parameter {
    name  = "notify-keyspace-events"
    value = "KEA"
  }

  parameter {
    name  = "maxmemory-policy"
    value = "allkeys-lru"
  }

  parameter {
    name  = "close-on-slave-write"
    value = "yes"
  }

  tags = {
    Name        = "${var.project_name}-redis-params"
    Environment = var.environment
  }
}

# ============================================================================
# ElastiCache Redis Replication Group
# ============================================================================

resource "random_password" "redis_auth_token" {
  length           = 32
  special          = true
  override_special = "!#$%^&*()-_=+[]{}<>:?"
}

resource "aws_elasticache_replication_group" "redis" {
  replication_group_id          = "${var.project_name}-redis"
  description                   = "Managed Redis replication group for ${var.project_name}"
  node_type                     = "cache.r6g.large"
  num_cache_clusters            = 3
  automatic_failover_enabled    = true
  multi_az_enabled              = true
  engine                        = "redis"
  engine_version                = "7.1"
  parameter_group_name          = aws_elasticache_parameter_group.redis.name
  subnet_group_name             = aws_elasticache_subnet_group.redis.name
  security_group_ids            = [aws_security_group.redis.id]
  port                          = 6379

  # Security: Encryption in transit
  transit_encryption_enabled = true
  transit_encryption_mode   = "required"

  # Security: Encryption at rest with KMS
  at_rest_encryption_enabled = true
  kms_key_id                 = aws_kms_key.redis.arn

  # Security: Auth token
  auth_token            = coalesce(var.redis_auth_token, random_password.redis_auth_token.result)
  auth_token_update_strategy = "ROTATE"

  # Maintenance window
  maintenance_window = "sun:03:00-sun:05:00"

  # Snapshot configuration
  snapshot_window          = "01:00-03:00"
  snapshot_retention_limit = 7
  snapshot_name_prefix    = "${var.project_name}-redis-snapshot"

  # Notifications
  notification_topic_type = "primary"

  # Logging
  log_delivery_configuration {
    destination_type = "cloudwatch-logs"
    destination      = aws_cloudwatch_log_group.redis.name
    log_format       = "text"
    log_type         = "engine-log"
  }

  log_delivery_configuration {
    destination_type = "cloudwatch-logs"
    destination      = aws_cloudwatch_log_group.redis.name
    log_format       = "json"
    log_type         = "slow-log"
  }

  tags = {
    Name        = "${var.project_name}-redis"
    Environment = var.environment
  }

  depends_on = [
    aws_kms_key.redis,
    aws_cloudwatch_log_group.redis,
  ]
}

# ============================================================================
# CloudWatch Log Group for Redis logs
# ============================================================================

resource "aws_cloudwatch_log_group" "redis" {
  name              = "/aws/elasticache/${var.project_name}-redis"
  retention_in_days = 14

  tags = {
    Name        = "${var.project_name}-redis-logs"
    Environment = var.environment
  }
}

# ============================================================================
# CloudWatch Alarms for monitoring
# ============================================================================

resource "aws_cloudwatch_metric_alarm" "redis_cpu" {
  alarm_name          = "${var.project_name}-redis-high-cpu"
  alarm_description   = "Redis CPU utilization above 80%"
  comparison_operator = "GreaterThanThreshold"
  evaluation_periods  = 2
  metric_name         = "CPUUtilization"
  namespace           = "AWS/ElastiCache"
  period              = 300
  statistic           = "Average"
  threshold           = 80
  treat_missing_data  = "notBreaching"

  dimensions = {
    CacheClusterId        = "${var.project_name}-redis"
    CacheNodeId           = "0001"
    ReplicationGroupId    = aws_elasticache_replication_group.redis.id
  }

  tags = {
    Name        = "${var.project_name}-redis-cpu-alarm"
    Environment = var.environment
  }
}

resource "aws_cloudwatch_metric_alarm" "redis_memory" {
  alarm_name          = "${var.project_name}-redis-high-memory"
  alarm_description   = "Redis memory utilization above 80%"
  comparison_operator = "GreaterThanThreshold"
  evaluation_periods  = 2
  metric_name         = "DatabaseMemoryUsagePercentage"
  namespace           = "AWS/ElastiCache"
  period              = 300
  statistic           = "Average"
  threshold           = 80
  treat_missing_data  = "notBreaching"

  dimensions = {
    CacheClusterId     = "${var.project_name}-redis"
    CacheNodeId        = "0001"
    ReplicationGroupId = aws_elasticache_replication_group.redis.id
  }

  tags = {
    Name        = "${var.project_name}-redis-memory-alarm"
    Environment = var.environment
  }
}

# ============================================================================
# Outputs
# ============================================================================

output "redis_primary_endpoint" {
  description = "Primary endpoint for the Redis replication group"
  value       = aws_elasticache_replication_group.redis.primary_endpoint_address
  sensitive   = true
}

output "redis_read_endpoints" {
  description = "Read endpoints for the Redis replication group"
  value       = aws_elasticache_replication_group.redis.reader_endpoint_address
  sensitive   = true
}

output "redis_security_group_id" {
  description = "Security group ID for Redis"
  value       = aws_security_group.redis.id
}

output "redis_kms_key_arn" {
  description = "KMS key ARN for Redis encryption"
  value       = aws_kms_key.redis.arn
}

