model_answers:
data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

variable "opensearch_collection_name" {
  description = "The name of the OpenSearch Serverless collection"
  type        = string
  default     = "my-collection"
}

variable "opensearch_collection_endpoint" {
  description = "The endpoint of the OpenSearch Serverless collection"
  type        = string
  default     = "https://my-collection-id.us-east-1.aoss.amazonaws.com"
}

variable "opensearch_index_name" {
  description = "The name of the OpenSearch index"
  type        = string
  default     = "my-index"
}

# S3 Bucket for Firehose backup
resource "aws_s3_bucket" "firehose_backup" {
  bucket_prefix = "firehose-os-serverless-backup-"
  force_destroy = true
}

resource "aws_s3_bucket_public_access_block" "firehose_backup" {
  bucket                  = aws_s3_bucket.firehose_backup.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "firehose_backup" {
  bucket = aws_s3_bucket.firehose_backup.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

# CloudWatch Log Group for Firehose
resource "aws_cloudwatch_log_group" "firehose_logs" {
  name              = "/aws/kinesisfirehose/firehose-to-os-serverless"
  retention_in_days = 14
}

resource "aws_cloudwatch_log_stream" "firehose_logs_stream" {
  log_group_name = aws_cloudwatch_log_group.firehose_logs.name
  name           = "DestinationDelivery"
}

# IAM Role for Firehose
data "aws_iam_policy_document" "firehose_assume_role" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["firehose.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "firehose_os_serverless_role" {
  name               = "firehose-os-serverless-role"
  assume_role_policy = data.aws_iam_policy_document.firehose_assume_role.json
}

data "aws_iam_policy_document" "firehose_os_serverless_policy" {
  statement {
    sid    = "S3BackupPermissions"
    effect = "Allow"
    actions = [
      "s3:AbortMultipartUpload",
      "s3:GetBucketLocation",
      "s3:GetObject",
      "s3:ListBucket",
      "s3:ListBucketMultipartUploads",
      "s3:PutObject"
    ]
    resources = [
      aws_s3_bucket.firehose_backup.arn,
      "${aws_s3_bucket.firehose_backup.arn}/*"
    ]
  }

  statement {
    sid    = "OpenSearchServerlessPermissions"
    effect = "Allow"
    actions = [
      "aoss:APIAccessAll"
    ]
    resources = [
      "arn:aws:aoss:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:collection/${var.opensearch_collection_name}"
    ]
  }

  statement {
    sid    = "CloudWatchLogsPermissions"
    effect = "Allow"
    actions = [
      "logs:PutLogEvents"
    ]
    resources = [
      "${aws_cloudwatch_log_group.firehose_logs.arn}:*"
    ]
  }
}

resource "aws_iam_policy" "firehose_os_serverless_policy" {
  name   = "firehose-os-serverless-policy"
  policy = data.aws_iam_policy_document.firehose_os_serverless_policy.json
}

resource "aws_iam_role_policy_attachment" "firehose_os_serverless_policy_attach" {
  role       = aws_iam_role.firehose_os_serverless_role.name
  policy_arn = aws_iam_policy.firehose_os_serverless_policy.arn
}

# Kinesis Firehose Delivery Stream
resource "aws_kinesis_firehose_delivery_stream" "this" {
  name = "firehose-to-os-serverless"

  opensearchserverless_configuration {
    collection_endpoint = var.opensearch_collection_endpoint
    index_name          = var.opensearch_index_name
    role_arn            = aws_iam_role.firehose_os_serverless_role.arn
    s3_backup_mode      = "FailedDocumentsOnly"

    s3_configuration {
      role_arn           = aws_iam_role.firehose_os_serverless_role.arn
      bucket_arn         = aws_s3_bucket.firehose_backup.arn
      buffer_size        = 5
      buffer_interval    = 300
      compression_format = "GZIP"
    }

