terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# KMS Key for RDS encryption at rest
resource "aws_kms_key" "rds" {
  description             = "KMS key for RDS MySQL encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 10
}

# Secrets Manager for DB credentials (avoids hardcoding passwords)
resource "random_password" "db_password" {
  length           = 32
  special          = true
  override_special = "!#$%&*()-_=+[]{}<>:?"
}

resource "aws_secretsmanager_secret" "db_credentials" {
  name                    = "mysql-db-credentials"
  description             = "Credentials for the MySQL RDS instance"
  kms_key_id              = aws_kms_key.rds.arn
  recovery_window_in_days = 0
}

resource "aws_secretsmanager_secret_version" "db_credentials" {
  secret_id     = aws_secretsmanager_secret.db_credentials.id
  secret_string = jsonencode({ username = "admin", password = random_password.db_password.result })
}

# IAM Role for RDS Enhanced Monitoring
resource "aws_iam_role" "rds_monitoring" {
  name = "rds-enhanced-monitoring-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action = "sts:AssumeRole"
      Effect = "Allow"
      Principal = { Service = "monitoring.rds.amazonaws.com" }
    }]
  })
}

resource "aws_iam_role_policy_attachment" "rds_monitoring" {
  role       = aws_iam_role.rds_monitoring.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonRDSEnhancedMonitoringRole"
}

# VPC and Networking (Private subnets for security)
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
}

resource "aws_subnet" "private_a" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-east-1a"
}

resource "aws_subnet" "private_b" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-east-1b"
}

resource "aws_db_subnet_group" "mysql" {
  name       = "mysql-subnet-group"
  subnet_ids = [aws_subnet.private_a.id, aws_subnet.private_b.id]
}

# Security Group for RDS (Restrict inbound to VPC CIDR, no outbound rules defined = default deny egress)
resource "aws_security_group" "rds" {
  name        = "mysql-rds-sg"
  description = "Allow inbound MySQL traffic from internal network only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "MySQL from VPC"
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }
}

# RDS Instance
resource "aws_db_instance" "mysql" {
  engine                          = "mysql"
  engine_version                  = "8.0"
  instance_class                  = "db.t3.small"
  allocated_storage               = 20
  storage_type                    = "gp2"
  storage_encrypted               = true
  kms_key_id                      = aws_kms_key.rds.arn

  db_name                         = "appdb"
  username                        = jsondecode(aws_secretsmanager_secret_version.db_credentials.secret_string).username
  password                        = jsondecode(aws_secretsmanager_secret_version.db_credentials.secret_string).password

  db_subnet_group_name            = aws_db_subnet_group.mysql.name
  vpc_security_group_ids          = [aws_security_group.rds.id]
  publicly_accessible             = false

  multi_az                        = true
  backup_retention_period         = 7
  backup_window                   = "03:00-04:00"
  maintenance_window              = "sun:04:00-sun:05:00"

  auto_minor_version_upgrade      = true
  deletion_protection             = true
  skip_final_snapshot             = false
  final_snapshot_identifier       = "mysql-final-snapshot"

  monitoring_interval             = 30
  monitoring_role_arn             = aws_iam_role.rds_monitoring.arn

  performance_insights_enabled    = true
  performance_insights_kms_key_id = aws_kms_key.rds.arn

  enabled_cloudwatch_logs_exports = ["error", "general", "slowquery"]

  depends_on = [aws_iam_role_policy_attachment.rds_monitoring]
}

variable "vpc_id" {
  description = "The ID of the VPC where the RDS instance will be deployed"
  type        = string
}

variable "private_subnet_ids" {
  description = "A list of private subnet IDs for the DB subnet group"
  type        = list(string)
}

variable "allowed_security_group_id" {
  description = "The security group ID allowed to access the RDS instance (e.g., app servers)"
  type        = string
}

variable "db_name" {
  description = "The name of the database to create"
  type        = string
  default     = "appdb"
}

# KMS Key for encrypting RDS storage and performance insights
resource "aws_kms_key" "rds" {
  description             = "KMS key for RDS PostgreSQL encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 30
}

# Security Group for the RDS instance
resource "aws_security_group" "rds" {
  name_prefix = "rds-postgres-sg-"
  description = "Allow inbound PostgreSQL traffic from the application"
  vpc_id      = var.vpc_id

  ingress {
    description     = "PostgreSQL access from allowed SG"
    from_port       = 5432
    to_port         = 5432
    protocol        = "tcp"
    security_groups = [var.allowed_security_group_id]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# DB Subnet Group using private subnets
resource "aws_db_subnet_group" "rds" {
  name       = "rds-postgres-subnet-group"
  subnet_ids = var.private_subnet_ids

  tags = {
    Name = "rds-postgres-subnet-group"
  }
}

# Parameter Group enforcing SSL connections
resource "aws_db_parameter_group" "postgres" {
  name   = "postgres-ssl-enforced"
  family = "postgres15"

  parameter {
    name         = "rds.force_ssl"
    value        = "1"
    apply_method = "pending-reboot"
  }
}

# RDS Instance
resource "aws_db_instance" "postgres" {
  engine                          = "postgres"
  engine_version                  = "15.5"
  instance_class                  = "db.t4g.large"
  allocated_storage               = 100
  storage_type                    = "gp3"
  storage_encrypted               = true
  kms_key_id                      = aws_kms_key.rds.arn

  db_name                         = var.db_name
  username                        = "db_admin"
  manage_master_user_password     = true

  db_subnet_group_name            = aws_db_subnet_group.rds.name
  vpc_security_group_ids          = [aws_security_group.rds.id]
  publicly_accessible             = false

  parameter_group_name            = aws_db_parameter_group.postgres.name

  multi_az                        = true
  backup_retention_period         = 7
  deletion_protection             = true
  auto_minor_version_upgrade      = true
  copy_tags_to_snapshot           = true

  monitoring_interval             = 60
  performance_insights_enabled    = true
  performance_insights_kms_key_id = aws_kms_key.rds.arn

  tags = {
    Name        = "postgres-db-t4g-large"
    Environment = "production"
  }
}

