  description             = "KMS key for RDS MySQL encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 30
}

# Parameter Group enforcing SSL/TLS for Encryption in Transit
resource "aws_db_parameter_group" "mysql_secure" {
  name   = "mysql-secure-pg"
  family = "mysql8.0"

  parameter {
    name         = "require_secure_transport"
    value        = "1"
    apply_method = "pending-reboot"
  }
}

# RDS MySQL Instance
resource "aws_db_instance" "mysql" {
  allocated_storage           = 20
  max_allocated_storage       = 50
  db_name                     = "appdb"
  engine                      = "mysql"
  engine_version              = "8.0"
  instance_class              = "db.t3.micro"
  username                    = "dbadmin"
  manage_master_user_password = true # Utilizes AWS Secrets Manager
  parameter_group_name        = aws_db_parameter_group.mysql_secure.name
  db_subnet_group_name        = aws_db_subnet_group.main.name
  vpc_security_group_ids      = [aws_security_group.rds.id]

  storage_encrypted           = true
  kms_key_id                  = aws_kms_key.rds.arn
  multi_az                    = true
  publicly_accessible         = false

  backup_retention_period     = 7
  deletion_protection         = true
  skip_final_snapshot         = false
  final_snapshot_identifier   = "mysql-final-snapshot"
  ca_cert_identifier          = "rds-ca-rsa2048-g1"
}

# Manual Snapshot of the RDS Instance
resource "aws_db_snapshot" "mysql_snapshot" {
  db_instance_identifier = aws_db_instance.mysql.id
  db_snapshot_identifier = "mysql-instance-manual-snapshot"
}

