model_answers:
# ----------------------------------------------------------------------------
# IAM: Assume-role policy for Lambda service principal
# ----------------------------------------------------------------------------
data "aws_iam_policy_document" "lambda_assume_role" {
  statement {
    sid     = "AllowLambdaAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }
  }
}

# ----------------------------------------------------------------------------
# IAM Role for the Lambda function (least privilege)
# ----------------------------------------------------------------------------
resource "aws_iam_role" "lambda_exec" {
  name               = "lambda-exec-role"
  assume_role_policy = data.aws_iam_policy_document.lambda_assume_role.json
  description        = "Execution role for the Lambda function (least privilege)"
}

# ----------------------------------------------------------------------------
# IAM Policy: Only CloudWatch Logs permissions required for basic execution
# ----------------------------------------------------------------------------
data "aws_iam_policy_document" "lambda_logs" {
  statement {
    sid    = "AllowCloudWatchLogs"
    effect = "Allow"
    actions = [
      "logs:CreateLogStream",
      "logs:PutLogEvents",
    ]
    resources = [
      "${aws_cloudwatch_log_group.lambda_logs.arn}:*",
    ]
  }

  statement {
    sid       = "AllowCreateLogGroup"
    effect    = "Allow"
    actions   = ["logs:CreateLogGroup"]
    resources = ["arn:aws:logs:*:*:log-group:/aws/lambda/*"]
  }
}

resource "aws_iam_policy" "lambda_logs" {
  name        = "lambda-logs-policy"
  description = "Least-privilege CloudWatch Logs permissions for Lambda"
  policy      = data.aws_iam_policy_document.lambda_logs.json
}

resource "aws_iam_role_policy_attachment" "lambda_logs" {
  role       = aws_iam_role.lambda_exec.name
  policy_arn = aws_iam_policy.lambda_logs.arn
}

# ----------------------------------------------------------------------------
# CloudWatch Log Group with retention (avoid indefinite log storage)
# ----------------------------------------------------------------------------
resource "aws_cloudwatch_log_group" "lambda_logs" {
  name              = "/aws/lambda/lambda-function"
  retention_in_days = 14
}

# ----------------------------------------------------------------------------
# KMS key to encrypt Lambda environment variables at rest
# ----------------------------------------------------------------------------
resource "aws_kms_key" "lambda_env" {
  description             = "KMS key for Lambda environment variables"
  deletion_window_in_days = 7
  enable_key_rotation     = true
}

# ----------------------------------------------------------------------------
# Package lambda.js into a zip archive
# ----------------------------------------------------------------------------
data "archive_file" "lambda_source" {
  type        = "zip"
  source_file = "lambda.js"
  output_path = "${path.module}/build/lambda.zip"
}

# ----------------------------------------------------------------------------
# Lambda function
# ----------------------------------------------------------------------------
resource "aws_lambda_function" "this" {
  function_name = "lambda-function"
  description   = "Lambda function running lambda.js"

  role = aws_iam_role.lambda_exec.arn

  filename         = data.archive_file.lambda_source.output_path
  source_code_hash = data.archive_file.lambda_source.output_base64sha256

  handler = "lambda.handler"
  runtime = "nodejs20.x"

  # Encrypt environment variables with a customer-managed KMS key
  kms_key_arn = aws_kms_key.lambda_env.arn

  environment {
    variables = {
      NODE_ENV = "production"
    }
  }

  # Enable AWS X-Ray active tracing
  tracing_config {
    mode = "Active"
  }

  # Limit concurrency to avoid runaway scaling
  reserved_concurrent_executions = 100

  depends_on = [
    aws_iam_role_policy_attachment.lambda_logs,
    aws_cloudwatch_log_group.lambda_logs,
  ]
}

