model_answers:
terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# -------------------------------------------------------------------
# Variables
# -------------------------------------------------------------------
variable "db_master_username" {
  description = "Master username for the RDS PostgreSQL instance"
  type        = string
  default     = "postgres"
  sensitive   = true
}

variable "allowed_db_cidr_blocks" {
  description = "List of CIDR blocks allowed to access the database on port 5432"
  type        = list(string)
  default     = ["0.0.0.0/0"]
}

# -------------------------------------------------------------------
# VPC
# -------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name        = "main-vpc"
    Environment = "production"
  }
}

# -------------------------------------------------------------------
# Subnets across different Availability Zones
# -------------------------------------------------------------------
resource "aws_subnet" "subnet_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = "us-east-1a"
  map_public_ip_on_launch = true

  tags = {
    Name = "subnet-a"
  }
}

resource "aws_subnet" "subnet_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = "us-east-1b"
  map_public_ip_on_launch = true

  tags = {
    Name = "subnet-b"
  }
}

# -------------------------------------------------------------------
# Internet Gateway + Public Route Table (required for public accessibility)
# -------------------------------------------------------------------
resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "main-igw"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name = "public-rt"
  }
}

resource "aws_route_table_association" "a" {
  subnet_id      = aws_subnet.subnet_a.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "b" {
  subnet_id      = aws_subnet.subnet_b.id
  route_table_id = aws_route_table.public.id
}

# -------------------------------------------------------------------
# DB Subnet Group
# -------------------------------------------------------------------
resource "aws_db_subnet_group" "db_subnet_group" {
  name       = "main-db-subnet-group"
  subnet_ids = [aws_subnet.subnet_a.id, aws_subnet.subnet_b.id]

  tags = {
    Name = "main-db-subnet-group"
  }
}

# -------------------------------------------------------------------
# Security Group for PostgreSQL access (port 5432)
# -------------------------------------------------------------------
resource "aws_security_group" "db_sg" {
  name        = "database-security-group"
  description = "Allow PostgreSQL database access"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "PostgreSQL access"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = var.allowed_db_cidr_blocks
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "database-security-group"
  }
}

# -------------------------------------------------------------------
# Random password for the RDS master user
# -------------------------------------------------------------------
resource "random_password" "db_password" {
  length           = 32
  special          = true
  override_special = "!#$%&*()-_=+[]{}<>:?"
}

# -------------------------------------------------------------------
# RDS PostgreSQL 15.3 instance
# -------------------------------------------------------------------
resource "aws_db_instance" "postgres" {
  engine                       = "postgres"
  engine_version               = "15.3"
  instance_class               = "db.t4g.micro"
  allocated_storage            = 200
  storage_type                 = "gp2"
  storage_encrypted            = true
  kms_key_id                   = aws_kms_key.rds.arn

  db_name                      = "appdb"
  username                     = var.db_master_username
  password                     = random_password.db_password.result
  manage_master_user_password  = false

  db_subnet_group_name         = aws_db_subnet_group.db_subnet_group.name
  vpc_security_group_ids       = [aws_security_group.db_sg.id]

  publicly_accessible          = true
  multi_az                     = false

  backup_retention_period      = 7
  backup_window                = "03:00-04:00"
  maintenance_window           = "sun:04:30-sun:05:30"
  auto_minor_version_upgrade   = true

  copy_tags_to_snapshot        = true
  skip_final_snapshot          = false
  final_snapshot_id            = "postgres-final-snapshot-${formatdate("YYYYMMDDhhmmss", timestamp())}"
  deletion_protection          = false

  tags = {
    Name        = "postgres-instance"
    Environment = "production"
  }

  depends_on = [aws_internet_gateway.igw]
}

# -------------------------------------------------------------------
# KMS key for storage encryption
# -------------------------------------------------------------------
resource "aws_kms_key" "rds" {
  description             = "KMS key for RDS PostgreSQL storage encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 30

  tags = {
    Name = "rds-kms-key"
  }
}

resource "aws_kms_alias" "rds" {
  name          = "alias/rds-postgres-key"
  target_key_id = aws_kms_key.rds.key_id
}

# -------------------------------------------------------------------
# Outputs
# -------------------------------------------------------------------
output "db_endpoint" {
  description = "The connection endpoint for the RDS PostgreSQL instance"
  value       = aws_db_instance.postgres.endpoint
}

output "db_address" {
  description = "The hostname of the RDS instance"
  value       = aws_db_instance.postgres.address
}

output "db_port" {
  description = "The port the RDS instance is listening on"
  value       = aws_db_instance.postgres.port
}

output "db_name" {
  description = "The name of the default database"
  value       = aws_db_instance.postgres.db_name
}

output "db_master_username" {
  description = "The master username for the RDS instance"
  value       = aws_db_instance.postgres.username
  sensitive   = true
}

output "db_master_password" {
  description = "The master password for the RDS instance"
  value       = random_password.db_password.result
  sensitive   = true
}

