# CloudWatch alarms for RDS health monitoring
resource "aws_cloudwatch_metric_alarm" "replica_1" {
  alarm_name          = "replica-1-failed-health"
  comparison_operator = "GreaterThanThreshold"
  evaluation_periods  = 1
  metric_name         = "StatusCheckFailed"
  namespace           = "AWS/RDS"
  period              = 60
  statistic           = "Average"
  threshold           = 0
  dimensions = {
    DBInstanceIdentifier = aws_db_instance.replica_1.identifier
  }
}

resource "aws_cloudwatch_metric_alarm" "replica_2" {
  alarm_name          = "replica-2-failed-health"
  comparison_operator = "GreaterThanThreshold"
  evaluation_periods  = 1
  metric_name         = "StatusCheckFailed"
  namespace           = "AWS/RDS"
  period              = 60
  statistic           = "Average"
  threshold           = 0
  dimensions = {
    DBInstanceIdentifier = aws_db_instance.replica_2.identifier
  }
}

# Route 53 health checks based on CloudWatch alarms (for private RDS instances)
resource "aws_route53_health_check" "replica_1" {
  type                            = "CLOUDWATCH_METRIC"
  cloudwatch_alarm_name           = aws_cloudwatch_metric_alarm.replica_1.alarm_name
  cloudwatch_alarm_region         = "us-east-1"
  insufficient_data_health_status = "LastKnownStatus"
}

resource "aws_route53_health_check" "replica_2" {
  type                            = "CLOUDWATCH_METRIC"
  cloudwatch_alarm_name           = aws_cloudwatch_metric_alarm.replica_2.alarm_name
  cloudwatch_alarm_region         = "us-east-1"
  insufficient_data_health_status = "LastKnownStatus"
}

# Weighted routing records - 50/50 split between replicas
resource "aws_route53_record" "replica_1" {
  zone_id         = aws_route53_zone.main.zone_id
  name            = "replicas"
  type            = "CNAME"
  ttl             = 60
  set_identifier  = "replica-1"
  records         = [aws_db_instance.replica_1.address]
  health_check_id = aws_route53_health_check.replica_1.id

  weighted_routing_policy {
    weight = 50
  }
}

resource "aws_route53_record" "replica_2" {
  zone_id         = aws_route53_zone.main.zone_id
  name            = "replicas"
  type            = "CNAME"
  ttl             = 60
  set_identifier  = "replica-2"
  records         = [aws_db_instance.replica_2.address]
  health_check_id = aws_route53_health_check.replica_2.id

  weighted_routing_policy {
    weight = 50
  }
}

