provider "aws" {
  region = "us-east-1"
}

# -----------------------------------------------------------------------------
# Data Sources
# -----------------------------------------------------------------------------

data "aws_caller_identity" "current" {}

data "aws_availability_zones" "available" {
  state = "available"
}

# -----------------------------------------------------------------------------
# KMS Keys
# -----------------------------------------------------------------------------

# KMS Key for SNS topic encryption
resource "aws_kms_key" "sns" {
  description             = "KMS key for Redshift events SNS topic"
  enable_key_rotation     = true
  deletion_window_in_days = 7
}

resource "aws_kms_key_policy" "sns" {
  key_id = aws_kms_key.sns.key_id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow Redshift Service to use the key"
        Effect = "Allow"
        Principal = {
          Service = "redshift.amazonaws.com"
        }
        Action = [
          "kms:GenerateDataKey*",
          "kms:Decrypt",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
}

# KMS Key for Redshift cluster encryption
resource "aws_kms_key" "redshift" {
  description             = "KMS key for Redshift cluster encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 7
}

# -----------------------------------------------------------------------------
# SNS Topic for Redshift Events
# -----------------------------------------------------------------------------

resource "aws_sns_topic" "redshift_events" {
  name              = "redshift-events-topic"
  kms_master_key_id = aws_kms_key.sns.arn
}

resource "aws_sns_topic_policy" "redshift_events" {
  arn = aws_sns_topic.redshift_events.arn

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "redshift.amazonaws.com"
        }
        Action   = "sns:Publish"
        Resource = aws_sns_topic.redshift_events.arn
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# Redshift Parameter Group
# -----------------------------------------------------------------------------

resource "aws_redshift_parameter_group" "example" {
  name   = "example-redshift-parameter-group"
  family = "redshift-1.0"

  parameter {
    name  = "require_ssl"
    value = "true"
  }

  parameter {
    name  = "enable_user_activity_logging"
    value = "true"
  }

  parameter {
    name  = "max_query_execution_time"
    value = "300000"
  }

  parameter {
    name  = "statement_timeout"
    value = "300000"
  }

  tags = {
    Environment = "production"
  }
}

# -----------------------------------------------------------------------------
# Redshift Event Subscription
# -----------------------------------------------------------------------------

resource "aws_redshift_event_subscription" "example" {
  name          = "example-redshift-event-subscription"
  sns_topic_arn = aws_sns_topic.redshift_events.arn
  source_type   = "parameter-group"
  source_ids    = [aws_redshift_parameter_group.example.name]
  severity      = "INFO"

  tags = {
    Environment = "production"
  }
}

# -----------------------------------------------------------------------------
# Networking Resources
# -----------------------------------------------------------------------------

resource "aws_vpc" "example" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
}

resource "aws_subnet" "redshift" {
  count                   = 2
  vpc_id                  = aws_vpc.example.id
  cidr_block              = "10.0.${count.index + 1}.0/24"
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false
}

resource "aws_redshift_subnet_group" "example" {
  name        = "example-redshift-subnet-group"
  subnet_ids  = aws_subnet.redshift[*].id
  description = "Redshift subnet group for private subnets"
}

resource "aws_security_group" "redshift" {
  name        = "example-redshift-sg"
  description = "Security group for Redshift cluster"
  vpc_id      = aws_vpc.example.id

  ingress {
    description = "Redshift access from VPC"
    from_port   = 5439
    to_port     = 5439
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.example.cidr_block]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# -----------------------------------------------------------------------------
# Redshift Cluster
# -----------------------------------------------------------------------------

resource "random_password" "redshift_master" {
  length           = 32
  special          = true
  override_special = "!#$%&*()-_=+[]{}<>:?"
}

resource "aws_redshift_cluster" "example" {
  cluster_identifier                  = "example-redshift-cluster"
  database_name                        = "exampledb"
  master_username                      = "adminuser"
  master_password                      = random_password.redshift_master.result
  node_type                            = "dc2.large"
  cluster_type                         = "single-node"
  cluster_subnet_group_name            = aws_redshift_subnet_group.example.name
  vpc_security_group_ids               = [aws_security_group.redshift.id]
  parameter_group_name                 = aws_redshift_parameter_group.example.name
  publicly_accessible                  = false
  encrypted                            = true
  cluster_encryption_kms_key_id        = aws_kms_key.redshift.arn
  enhanced_vpc_routing                 = true
  allow_version_upgrade                = true
  automated_snapshot_retention_period  = 7
  skip_final_snapshot                  = false
  final_snapshot_identifier            = "example-redshift-final-snapshot"

  tags = {
    Environment = "production"
  }
}

