# Terraform does not provide a dedicated association resource for ElastiCache users and user groups.
# To associate an existing user with an existing user group, the user group must be imported into Terraform state
# (e.g., `terraform import aws_elasticache_user_group.association <user_group_id>`) and updated to include the user in the `user_ids` list.
resource "aws_elasticache_user_group" "association" {
  user_group_id = data.aws_elasticache_user_group.existing.user_group_id
  engine        = data.aws_elasticache_user_group.existing.engine

  user_ids = distinct(concat(
    data.aws_elasticache_user_group.existing.user_ids,
    [data.aws_elasticache_user.existing.user_id]
  ))
}

