# Intent: BookTrip
resource "aws_lex_intent" "book_trip" {
  name              = "BookTrip"
  description       = "Intent to book a trip with destination, dates, number of travelers, and preferences"
  create_version    = true
  sample_utterances = [
    "I want to book a trip",
    "Book a trip",
    "I need to book a vacation",
    "Help me book a trip to {Destination}",
    "I want to go on a trip to {Destination}",
    "Book a trip from {DepartureCity} to {Destination}",
    "I want to travel to {Destination} on {DepartureDate}",
    "Plan a trip to {Destination}",
    "I'd like to book a trip to {Destination} departing {DepartureDate} and returning {ReturnDate}",
    "Book a vacation to {Destination}",
    "I want to visit {Destination}",
    "Plan a vacation to {Destination} from {DepartureDate} to {ReturnDate}",
  ]

  slot {
    name              = "Destination"
    description       = "The destination city for the trip"
    slot_type         = "AMAZON.City"
    slot_constraint   = "Required"
    priority          = 1
    sample_utterances = [
      "I want to go to {Destination}",
      "Take me to {Destination}",
      "My destination is {Destination}",
    ]
    value_elicitation_prompt {
      max_attempts = 2
      message {
        content      = "Where would you like to go for your trip?"
        content_type = "PlainText"
      }
      message {
        content      = "What is your destination city?"
        content_type = "PlainText"
        group_number = 1
      }
      response_card = jsonencode({
        version     = 1
        contentType = "application/vnd.amazonaws.card.generic"
        genericAttachments = [
          {
            title    = "Popular Destinations"
            subtitle = "Choose a destination or type your own"
            buttons = [
              { text = "Paris",    value = "Paris" },
              { text = "Tokyo",    value = "Tokyo" },
              { text = "New York", value = "New York" },
              { text = "London",   value = "London" },
            ]
          }
        ]
      })
    }
  }

  slot {
    name              = "DepartureCity"
    description       = "The departure city for the trip"
    slot_type         = "AMAZON.City"
    slot_constraint   = "Optional"
    priority          = 2
    sample_utterances = [
      "I'm departing from {DepartureCity}",
      "From {DepartureCity}",
      "Leave from {DepartureCity}",
    ]
    value_elicitation_prompt {
      max_attempts = 2
      message {
        content      = "Where will you be departing from?"
        content_type = "PlainText"
      }
    }
  }

  slot {
    name              = "DepartureDate"
    description       = "The departure date for the trip"
    slot_type         = "AMAZON.DATE"
    slot_constraint   = "Required"
    priority          = 3
    sample_utterances = [
      "I want to leave on {DepartureDate}",
      "Departing {DepartureDate}",
      "On {DepartureDate}",
    ]
    value_elicitation_prompt {
      max_attempts = 2
      message {
        content      = "When would you like to depart?"
        content_type = "PlainText"
      }
      message {
        content      = "What is your departure date?"
        content_type = "PlainText"
        group_number = 1
      }
    }
  }

  slot {
    name              = "ReturnDate"
    description       = "The return date for the trip"
    slot_type         = "AMAZON.DATE"
    slot_constraint   = "Required"
    priority          = 4
    sample_utterances = [
      "I want to return on {ReturnDate}",
      "Returning {ReturnDate}",
      "Come back on {ReturnDate}",
    ]
    value_elicitation_prompt {
      max_attempts = 2
      message {
        content      = "When would you like to return?"
        content_type = "PlainText"
      }
    }
  }

  slot {
    name              = "NumberOfTravelers"
    description       = "The number of travelers for the trip"
    slot_type         = "AMAZON.NUMBER"
    slot_constraint   = "Required"
    priority          = 5
    sample_utterances = [
      "{NumberOfTravelers} travelers",
      "{NumberOfTravelers} people",
      "There will be {NumberOfTravelers} of us",
    ]
    value_elicitation_prompt {
      max_attempts = 2
      message {
        content      = "How many travelers will be going on this trip?"
        content_type = "PlainText"
      }
    }
  }

  slot {
    name              = "TravelClass"
    description       = "The travel class preference (Economy, Business, First)"
    slot_type         = aws_lex_slot_type.travel_class.name
    slot_constraint   = "Optional"
    priority          = 6
    sample_utterances = [
      "I want {TravelClass} class",
      "{TravelClass} please",
      "In {TravelClass}",
    ]
    value_elicitation_prompt {
      max_attempts = 2
      message {
        content      = "What travel class would you prefer? Economy, Business, or First?"
        content_type = "PlainText"
      }
      response_card = jsonencode({
        version     = 1
        contentType = "application/vnd.amazonaws.card.generic"
        genericAttachments = [
          {
            title    = "Travel Class"
            subtitle = "Select your preferred travel class"
            buttons = [
              { text = "Economy",  value = "Economy" },
              { text = "Business", value = "Business" },
              { text = "First",    value = "First" },
            ]
          }
        ]
      })
    }
  }

  slot {
    name              = "AccommodationType"
    description       = "The type of accommodation (Hotel, Resort, Hostel, Apartment)"
    slot_type         = aws_lex_slot_type.accommodation_type.name
    slot_constraint   = "Optional"
    priority          = 7
    sample_utterances = [
      "I want a {AccommodationType}",
      "Stay in a {AccommodationType}",
      "{AccommodationType} accommodation",
    ]
    value_elicitation_prompt {
      max_attempts = 2
      message {
        content      = "What type of accommodation would you prefer? Hotel, Resort, Hostel, or Apartment?"
        content_type = "PlainText"
      }
      response_card = jsonencode({
        version     = 1
        contentType = "application/vnd.amazonaws.card.generic"
        genericAttachments = [
          {
            title    = "Accommodation Type"
            subtitle = "Select your preferred accommodation"
            buttons = [
              { text = "Hotel",     value = "Hotel" },
              { text = "Resort",    value = "Resort" },
              { text = "Hostel",    value = "Hostel" },
              { text = "Apartment", value = "Apartment" },
            ]
          }
        ]
      })
    }
  }

  confirmation_prompt {
    max_attempts = 2
    message {
      content      = "I'd like to confirm your trip booking. You want to travel to {Destination}, departing on {DepartureDate} and returning on {ReturnDate}, for {NumberOfTravelers} traveler(s) in {TravelClass} class with {AccommodationType} accommodation. Is this correct?"
      content_type = "PlainText"
    }
    message {
      content      = "Please confirm: Trip to {Destination} from {DepartureDate} to {ReturnDate} for {NumberOfTravelers} person(s). Is this correct?"
      content_type = "PlainText"
      group_number = 1
    }
  }

  rejection_statement {
    message {
      content      = "Okay, I've cancelled your trip booking. Let me know if you'd like to try again."
      content_type = "PlainText"
    }
  }

  conclusion_statement {
    message {
      content      = "Your trip has been booked! You're going to {Destination} from {DepartureDate} to {ReturnDate} for {NumberOfTravelers} traveler(s). Have a great trip!"
      content_type = "PlainText"
    }
    message {
      content      = "Great! Your trip to {Destination} is confirmed. Departing {DepartureDate}, returning {ReturnDate}. Enjoy your journey!"
      content_type = "PlainText"
      group_number = 1
    }
  }

  follow_up_prompt {
    prompt {
      max_attempts = 2
      message {
        content      = "Is there anything else I can help you with regarding your trip?"
        content_type = "PlainText"
      }
    }
    rejection_statement {
      message {
        content      = "Alright, have a wonderful trip to {Destination}! Safe travels!"
        content_type = "PlainText"
      }
    }
  }

  fulfillment_activity {
    type = "ReturnIntent"
  }
}

# Intent: Greeting
