      content      = "I can help you book a trip! Just say something like 'I want to book a trip to Paris' or 'Book a trip'. I'll ask you for your destination, departure date, return date, and number of travelers. You can also specify your departure city, travel class, and accommodation type."
      content_type = "PlainText"
    }
    message {
      content      = "Here's how to use me: 1) Say 'Book a trip' to start booking. 2) I'll ask for your destination, dates, and number of travelers. 3) Confirm your booking details. 4) You can also cancel a booking by saying 'Cancel my booking'."
      content_type = "PlainText"
      group_number = 1
    }
  }

  fulfillment_activity {
    type = "ReturnIntent"
  }
}

# Intent: CancelBooking
resource "aws_lex_intent" "cancel_booking" {
  name              = "CancelBooking"
  description       = "Intent to cancel a trip booking"
  create_version    = true
  sample_utterances = [
    "Cancel my booking",
    "I want to cancel my trip",
    "Cancel the trip",
    "I need to cancel",
    "Cancel",
    "Never mind",
    "I changed my mind",
    "Cancel booking {BookingId}",
    "I want to cancel my reservation",
  ]

  slot {
    name              = "BookingId"
    description       = "The booking ID to cancel"
    slot_type         = "AMAZON.AlphaNumeric"
    slot_constraint   = "Required"
    priority          = 1
    sample_utterances = [
      "Booking {BookingId}",
      "Reservation {BookingId}",
      "Confirmation number {BookingId}",
    ]
    value_elicitation_prompt {
      max_attempts = 2
      message {
        content      = "What is your booking ID?"
        content_type = "PlainText"
      }
    }
  }

  confirmation_prompt {
    max_attempts = 2
    message {
      content      = "Are you sure you want to cancel booking {BookingId}?"
      content_type = "PlainText"
    }
  }

  rejection_statement {
    message {
      content      = "Okay, I've kept your booking active. Is there anything else I can help you with?"
      content_type = "PlainText"
    }
  }

  conclusion_statement {
    message {
      content      = "Your booking {BookingId} has been cancelled. Is there anything else I can help you with?"
      content_type = "PlainText"
    }
  }

  fulfillment_activity {
    type = "ReturnIntent"
  }
}

