#########################
# CloudWatch Log Group  #
#########################
resource "aws_cloudwatch_log_group" "kda_log_group" {
  name              = "/aws/kinesis-analytics/application"
  retention_in_days = 30
  kms_key_id        = aws_kms_key.log_group_key.arn
  tags = {
    Name = "kda-log-group"
  }
}

resource "aws_cloudwatch_log_stream" "kda_log_stream" {
  name           = "kda-log-stream"
  log_group_name = aws_cloudwatch_log_group.kda_log_group.name
}

#########################
# KMS Key for Log Group #
#########################
resource "aws_kms_key" "log_group_key" {
  description         = "KMS key for encrypting CloudWatch log group"
  deletion_window_in_days = 30
  enable_key_rotation = true
  policy = <<EOF
{
  "Version": "2012-10-17",
  "Id": "key-default-1",
  "Statement": [
    {
      "Sid": "Allow administration of the key",
      "Effect": "Allow",
      "Principal": {
        "AWS": "${data.aws_caller_identity.current.arn}"
      },
      "Action": [
        "kms:*"
      ],
      "Resource": "*"
    },
    {
      "Sid": "Allow CloudWatch Logs to use the key",
      "Effect": "Allow",
      "Principal": {
        "Service": "logs.${data.aws_region.current.name}.amazonaws.com"
      },
      "Action": [
        "kms:GenerateDataKey*",
        "kms:Decrypt"
      ],
      "Resource": "*",
      "Condition": {
        "StringEquals": {
          "kms:EncryptionContext:aws:logs:arn": "${aws_cloudwatch_log_group.kda_log_group.arn}"
        }
      }
    }
  ]
}
EOF
}

