#########################
# IAM Role for KDA      #
#########################
data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

resource "aws_iam_role" "kda_service_role" {
  name = "kda-service-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
        Service = "kinesisanalytics.amazonaws.com"
      }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_policy" "kda_logging_policy" {
  name        = "KDA-CloudWatch-Logging"
  description = "Allows KDA to write logs to CloudWatch"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = [
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogStreams"
        ]
        Resource = "${aws_cloudwatch_log_group.kda_log_group.arn}:*"
      },
      {
        Effect   = "Allow"
        Action   = [
          "logs:CreateLogGroup"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "kda_logging_attach" {
  role       = aws_iam_role.kda_service_role.name
  policy_arn = aws_iam_policy.kda_logging_policy.arn
}

