# Kinesis Analytics App #
#########################
resource "aws_kinesisanalyticsv2_application" "basic_sql_app" {
  name                = "basic-sql-application"
  runtime_environment = "SQL-1_0"
  service_execution_role = aws_iam_role.kda_service_role.arn

  application_configuration {
    sql_application_configuration {
      inputs {
        name_prefix = "example-input"
        kinesis_streams_input {
          resource_arn = aws_kinesis_stream.example.arn
          role_arn    = aws_iam_role.kda_service_role.arn
        }
        input_schema {
          record_format {
            record_format_type = "JSON"
            mapping_parameters {
              json_mapping_parameters {
                record_row_path = "$"
              }
            }
          }
          record_encoding = "UTF-8"
          record_columns = [
            {
              name     = "data"
              mapping  = "$.data"
              sql_type = "VARCHAR(64)"
            }
          ]
        }
        input_parallelism {
          count = 1
        }
      }

      outputs {
        name = "example-output"
        kinesis_streams_output {
          resource_arn = aws_kinesis_stream.example.arn
          role_arn    = aws_iam_role.kda_service_role.arn
        }
        destination_schema {
          record_format_type = "JSON"
        }
      }

      cloudwatch_logging_options {
        log_group_name  = aws_cloudwatch_log_group.kda_log_group.name
        log_stream_name = aws_cloudwatch_log_stream.kda_log_stream.name
      }
    }
  }

  tags = {
    Environment = "dev"
    Owner       = "infra-team"
  }
}

