model_answers:
#########################
# Provider Configuration #
#########################
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

#################
# Input Variables #
#################
variable "aws_region" {
  description = "AWS region to deploy resources"
  type        = string
  default     = "us-east-1"
}

variable "domain_name" {
  description = "Root domain for the video streaming site (e.g., example.com)"
  type        = string
}

variable "instance_count" {
  description = "Number of EC2 instances behind the load balancer"
  type        = number
  default     = 3
}

variable "instance_type" {
  description = "EC2 instance type"
  type        = string
  default     = "t3.micro"
}

variable "allowed_ssh_cidr" {
  description = "CIDR block allowed to SSH into EC2 instances (use with caution)"
  type        = string
  default     = "203.0.113.0/24"
}

#########################
# VPC Module (public & private subnets) #
#########################
module "vpc" {
  source  = "terraform-aws-modules/vpc/aws"
  version = "~> 5.0"

  name = "video-streaming-vpc"
  cidr = "10.0.0.0/16"

  azs             = data.aws_availability_zones.available.names
  public_subnets  = ["10.0.1.0/24", "10.0.2.0/24", "10.0.3.0/24"]
  private_subnets = ["10.0.101.0/24", "10.0.102.0/24", "10.0.103.0/24"]

  enable_nat_gateway = true
  single_nat_gateway = true

  tags = {
    Terraform   = "true"
    Environment = "prod"
  }
}

data "aws_availability_zones" "available" {}

#########################
# Security Groups #
#########################
# ALB security group – allow inbound HTTP/HTTPS from anywhere
resource "aws_security_group" "alb_sg" {
  name        = "alb-sg"
  description = "Security group for the Application Load Balancer"
  vpc_id      = module.vpc.vpc_id

  ingress {
    description = "Allow HTTP"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "Allow HTTPS"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "alb-sg"
  }
}

# EC2 instances security group – only allow traffic from ALB SG on app port (8080) and SSH from limited CIDR
resource "aws_security_group" "ec2_sg" {
  name        = "ec2-sg"
  description = "Security group for video streaming EC2 instances"
  vpc_id      = module.vpc.vpc_id

  ingress {
    description = "Allow traffic from ALB on application port"
    from_port   = 8080
    to_port     = 8080
    protocol    = "tcp"
    security_groups = [aws_security_group.alb_sg.id]
  }

  ingress {
    description = "Allow SSH from trusted network"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [var.allowed_ssh_cidr]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "ec2-sg"
  }
}

#########################
# IAM Role for EC2 (SSM) #
#########################
resource "aws_iam_role" "ec2_role" {
  name = "video-streaming-ec2-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action    = "sts:AssumeRole"
      Effect    = "Allow"
      Principal = {
        Service = "ec2.amazonaws.com"
      }
    }]
  })
}

resource "aws_iam_role_policy_attachment" "ssm_managed" {
  role       = aws_iam_role.ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_instance_profile" "ec2_profile" {
  name = "video-streaming-ec2-profile"
  role = aws_iam_role.ec2_role.name
}

#########################
# AMI Data Source #
#########################
data "aws_ami" "amazon_linux_2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }
}

#########################
# EC2 Instances #
#########################
resource "aws_instance" "web" {
  count                     = var.instance_count
  ami                       = data.aws_ami.amazon_linux_2.id
  instance_type             = var.instance_type
  subnet_id                 = element(module.vpc.private_subnets, count.index % length(module.vpc.private_subnets))
  vpc_security_group_ids    = [aws_security_group.ec2_sg.id]
  iam_instance_profile      = aws_iam_instance_profile.ec2_profile.name
  associate_public_ip_address = false
  key_name                  = var.key_pair_name

  root_block_device {
    encrypted = true
    volume_size = 30
  }

  tags = {
    Name        = "video-streaming-web-${count.index + 1}"
    Environment = "prod"
  }

  # Simple user data to run a placeholder web server on port 8080
  user_data = <<-EOF
              #!/bin/bash
              yum install -y httpd
              echo "<h1>Video Streaming Instance ${count.index + 1}</h1>" > /var/www/html/index.html
              systemctl enable httpd
              systemctl start httpd
              # Redirect port 8080 to Apache
              iptables -t nat -A PREROUTING -p tcp --dport 8080 -j REDIRECT --to-port 80
              EOF
}

#########################
# Load Balancer (ALB) #
#########################
resource "aws_lb" "app_alb" {
  name               = "video-streaming-alb"
  internal           = false
  load_balancer_type = "application"
  subnets            = module.vpc.public_subnets
  security_groups    = [aws_security_group.alb_sg.id]

  enable_deletion_protection = false

  tags = {
    Name        = "video-streaming-alb"
    Environment = "prod"
  }
}

#########################
# Target Group #
#########################
resource "aws_lb_target_group" "app_tg" {
  name        = "video-streaming-tg"
  port        = 8080
  protocol    = "HTTP"
  vpc_id      = module.vpc.vpc_id
  target_type = "instance"

  health_check {
    path                = "/"
    protocol            = "HTTP"
    matcher             = "200-399"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 3
    unhealthy_threshold = 2
  }

  tags = {
    Name        = "video-streaming-tg"
    Environment = "prod"
  }
}

#########################
# Register EC2 instances with Target Group #
#########################
resource "aws_lb_target_group_attachment" "web_instances" {
  count            = var.instance_count
  target_group_arn = aws_lb_target_group.app_tg.arn
  target_id        = aws_instance.web[count.index].id
  port             = 8080
}

#########################
# Listener (HTTP) #
#########################
resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.app_alb.arn
  port              = "80"
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.app_tg.arn
  }
}

#########################
# Route53 Hosted Zone #
#########################
resource "aws_route53_zone" "primary" {
  name = var.domain_name

  tags = {
    Name        = "video-streaming-zone"
    Environment = "prod"
  }
}

#########################
# DNS Record (Alias to ALB) #
#########################
resource "aws_route53_record" "app_alias" {
  zone_id = aws_route53_zone.primary.zone_id
  name    = "www.${var.domain_name}"
  type    = "A"

  alias {
    name                   = aws_lb.app_alb.dns_name
    zone_id                = aws_lb.app_alb.zone_id
    evaluate_target_health = true
  }

  ttl = 300
}

#########################
# Key Pair (imported) #
#########################
variable "key_pair_name" {
  description = "Name of an existing EC2 key pair to associate with instances"
  type        = string
}

#########################
# Outputs #
#########################
output "alb_dns_name" {
  description = "DNS name of the Application Load Balancer"
  value       = aws_lb.app_alb.dns_name
}

output "instance_ids" {
  description = "IDs of the EC2 instances"
  value       = aws_instance.web[*].id
}

