provider "aws" {
  region = "us-east-1"
}

data "aws_caller_identity" "current" {}

#########################
# Source bucket (inventory source)
#########################
resource "aws_s3_bucket" "source" {
  bucket = "my-source-bucket-${data.aws_caller_identity.current.account_id}"
  force_destroy = false

  tags = {
    Name = "source-bucket"
  }
}

resource "aws_s3_bucket_versioning" "source" {
  bucket = aws_s3_bucket.source.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "source" {
  bucket = aws_s3_bucket.source.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "source" {
  bucket = aws_s3_bucket.source.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

#########################
# Destination bucket (inventory reports)
#########################
resource "aws_s3_bucket" "inventory_destination" {
  bucket = "my-inventory-destination-${data.aws_caller_identity.current.account_id}"
  force_destroy = false

  tags = {
    Name = "inventory-destination"
  }
}

resource "aws_s3_bucket_public_access_block" "inventory_destination" {
  bucket = aws_s3_bucket.inventory_destination.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "inventory_destination" {
  bucket = aws_s3_bucket.inventory_destination.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

# Allow the source bucket's inventory to write reports into the destination bucket
resource "aws_s3_bucket_policy" "inventory_destination" {
  bucket = aws_s3_bucket.inventory_destination.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowInventoryDelivery"
        Effect    = "Allow"
        Principal = {
          AWS = data.aws_caller_identity.current.arn
        }
        Action    = "s3:PutObject"
        Resource  = "${aws_s3_bucket.inventory_destination.arn}/*"
        Condition = {
          StringEquals = {
            "s3:x-amz-acl" = "bucket-owner-full-control"
          }
        }
      }
    ]
  })
}

#########################
# Inventory configuration on source bucket
#########################
resource "aws_s3_bucket_inventory" "source_inventory" {
  bucket = aws_s3_bucket.source.id
  name   = "weekly-csv-inventory"

  schedule {
    frequency = "Weekly"
  }

  destination {
    bucket = aws_s3_bucket.inventory_destination.arn
    format = "CSV"
    prefix = "inventory-reports/"
    account_id = data.aws_caller_identity.current.account_id
    encryption {
      sse_s3 {}
    }
  }

  included_object_versions = "All"
  optional_fields = [
    "Size",
    "LastModifiedDate",
    "ETag",
    "StorageClass",
    "IsMultipartUploaded",
    "ReplicationStatus",
    "EncryptionStatus"
  ]

  filter {
    # empty filter means include all objects
  }
}

