provider "aws" {
  region = "us-east-1"
}

#########################
# IAM role for Lex bot  #
#########################
resource "aws_iam_role" "lex_bot_role" {
  name = "lex-bot-execution-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Principal = {
        Service = "lex.amazonaws.com"
      }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy" "lex_bot_policy" {
  name = "lex-bot-policy"
  role = aws_iam_role.lex_bot_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "arn:${data.aws_partition.current.partition}:logs:*:*:*"
      },
      {
        Effect   = "Allow"
        Action   = [
          "kms:Decrypt",
          "kms:GenerateDataKey"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "kms:ViaService" = "lex.${var.aws_region}.amazonaws.com"
          }
        }
      }
    ]
  })
}

#########################
# Slot Types            #
#########################
resource "aws_lex_slot_type" "pizza_size" {
  name        = "PizzaSize"
  description = "Size of the pizza"
  enumeration_values = [
    { value = "small" },
    { value = "medium" },
    { value = "large" },
    { value = "extra large" }
  ]
}

resource "aws_lex_slot_type" "pizza_crust" {
  name        = "PizzaCrust"
  description = "Crust type"
  enumeration_values = [
    { value = "thin" },
    { value = "regular" },
    { value = "deep dish" }
  ]
}

resource "aws_lex_slot_type" "pizza_topping" {
  name        = "PizzaTopping"
  description = "Topping choice"
  enumeration_values = [
    { value = "pepperoni" },
    { value = "mushrooms" },
    { value = "onions" },
    { value = "sausage" },
    { value = "bacon" },
    { value = "extra cheese" },
    { value = "black olives" },
    { value = "green peppers" },
    { value = "pineapple" },
    { value = "spinach" }
  ]
}

#########################
# Intent                #
#########################
resource "aws_lex_intent" "order_pizza" {
  name        = "OrderPizza"
  description = "Intent to order a pizza"

  sample_utterances = [
    "I want to order a pizza",
    "Order pizza",
    "Get me a pizza",
    "Can I have a pizza"
  ]

  slot {
    name                 = "Size"
    slot_type            = aws_lex_slot_type.pizza_size.name
    slot_constraint      = "Required"
    value_elicitation_prompt {
      max_attempts = 2
      messages = [{
        content      = "What size pizza would you like? (small, medium, large, extra large)"
        content_type = "PlainText"
      }]
    }
    priority = 1
  }

  slot {
    name                 = "Crust"
    slot_type            = aws_lex_slot_type.pizza_crust.name
    slot_constraint      = "Required"
    value_elicitation_prompt {
      max_attempts = 2
      messages = [{
        content      = "Which crust do you prefer? (thin, regular, deep dish)"
        content_type = "PlainText"
      }]
    }
    priority = 2
  }

  slot {
    name                 = "Topping"
    slot_type            = aws_lex_slot_type.pizza_topping.name
    slot_constraint      = "Optional"
    value_elicitation_prompt {
      max_attempts = 2
      messages = [{
        content      = "Any toppings? (e.g., pepperoni, mushrooms, etc.)"
        content_type = "PlainText"
      }]
    }
    priority = 3
  }

  conclusion_statement {
    messages = [{
      content      = "Your {{Size}} {{Crust}} crust pizza with {{Topping}} has been placed. Thank you for ordering!"
      content_type = "PlainText"
    }]
  }

  fulfillment_activity {
    type = "ReturnIntent"
  }
}

#########################
# Lex Bot               #
#########################
resource "aws_lex_bot" "pizza_bot" {
  name                     = "PizzaOrderBot"
  description              = "Bot that helps users order pizza"
  locale                   = "en_US"
  child_directed           = false
  idle_session_ttl_in_seconds = 300
  voice_id                 = "Joanna"
  process_behavior         = "BUILD"
  role_arn                 = aws_iam_role.lex_bot_role.arn

  abort_statement {
    messages = [{
      content      = "Sorry, I couldn't understand. Please try again later."
      content_type = "PlainText"
    }]
  }

  clarification_prompt {
    max_attempts = 2
    messages = [{
      content      = "I didn't catch that. Could you rephrase?"
      content_type = "PlainText"
    }]
  }

  intent {
    intent_name = aws_lex_intent.order_pizza.name
    intent_version = "$LATEST"
  }

  tags = {
    Environment = "Production"
    Owner       = "InfraTeam"
  }
}

