provider "aws" {
  region = var.region
}

variable "region" {
  description = "AWS region to deploy resources"
  type        = string
  default     = "us-east-1"
}

# Generate a unique, human‑readable name for the Lightsail resources
resource "random_pet" "instance_name" {
  length    = 2
  separator = "-"
}

# Generate an SSH key pair for secure access
resource "tls_private_key" "ssh_key" {
  algorithm = "RSA"
  rsa_bits  = 4096
}

resource "aws_lightsail_key_pair" "ssh_key_pair" {
  name       = "${random_pet.instance_name.id}-key"
  public_key = tls_private_key.ssh_key.public_key_openssh
}

# Lightsail instance running the WordPress blueprint
resource "aws_lightsail_instance" "wordpress" {
  name              = random_pet.instance_name.id
  availability_zone = "${var.region}a"
  blueprint_id      = "wordpress"
  bundle_id         = "nano_2_0" # smallest production‑grade bundle
  key_pair_name     = aws_lightsail_key_pair.ssh_key_pair.name

  # Enable daily automatic snapshots at 03:00 UTC
  auto_snapshot_time_of_day = "03:00"
}

# Allocate a static public IP and attach it to the instance
resource "aws_lightsail_static_ip" "static_ip" {
  name = "${random_pet.instance_name.id}-ip"
}

resource "aws_lightsail_static_ip_attachment" "static_ip_attach" {
  static_ip_name = aws_lightsail_static_ip.static_ip.name
  instance_name  = aws_lightsail_instance.wordpress.name
}

# Open only the required ports (HTTP & HTTPS) – least‑privilege firewall
resource "aws_lightsail_instance_public_ports" "web_ports" {
  instance_name = aws_lightsail_instance.wordpress.name

  port_info {
    from_port = 80
    to_port   = 80
    protocol  = "tcp"
  }

  port_info {
    from_port = 443
    to_port   = 443
    protocol  = "tcp"
  }
}

# Output useful information
output "instance_name" {
  description = "Name of the Lightsail WordPress instance"
  value       = aws_lightsail_instance.wordpress.name
}

output "public_ip_address" {
  description = "Static public IP attached to the instance"
  value       = aws_lightsail_static_ip.static_ip.ip_address
}

output "ssh_private_key_pem" {
  description = "Private SSH key (PEM) for connecting to the instance"
  value       = tls_private_key.ssh_key.private_key_pem
  sensitive   = true
}

