#####################
resource "aws_vpc" "redis_vpc" {
  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = "redis-vpc"
  }
}

resource "aws_subnet" "redis_private" {
  for_each = toset(var.private_subnet_cidrs)

  vpc_id                  = aws_vpc.redis_vpc.id
  cidr_block              = each.value
  map_public_ip_on_launch = false
  availability_zone       = data.aws_availability_zones.available.names[lookup(var.private_subnet_cidrs, each.key)]

  tags = {
    Name = "redis-private-${each.key}"
  }
}

