    Name = "redis-subnet-group"
  }
}

resource "random_password" "redis_auth_token" {
  length  = 32
  special = false
  override_characters = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789"
}

resource "aws_elasticache_replication_group" "redis" {
  replication_group_id          = "redis-cluster"
  description                   = "Redis replication group with HA"
  engine                        = "redis"
  engine_version                = var.redis_engine_version
  node_type                     = var.redis_node_type
  number_cache_clusters         = 2
  automatic_failover_enabled    = true
  multi_az_enabled              = true
  at_rest_encryption_enabled    = true
  transit_encryption_enabled    = true
  auth_token                    = random_password.redis_auth_token.result
  port                          = 6379
  subnet_group_name             = aws_elasticache_subnet_group.redis_subnet_group.name
  security_group_ids            = [aws_security_group.redis_sg.id]
  snapshot_retention_limit      = 7
  snapshot_window               = "03:00-04:00"
  maintenance_window            = "sun:05:00-sun:06:00"
  apply_immediately             = false

  tags = {
    Name = "redis-replication-group"
  }

  lifecycle {
    ignore_changes = [auth_token] # Prevents replacement on token change
  }
}

#####################
# Outputs           #
#####################
output "redis_primary_endpoint_address" {
  description = "Primary endpoint address of the Redis cluster"
  value       = aws_elasticache_replication_group.redis.primary_endpoint_address
}

output "redis_reader_endpoint_address" {
  description = "Reader endpoint address of the Redis cluster"
  value       = aws_elasticache_replication_group.redis.reader_endpoint_address
}

output "redis_port" {
  description = "Port on which Redis is listening"
  value       = aws_elasticache_replication_group.redis.port
}

