model_answers:
provider "aws" {
  region = "us-east-1"
}

# Generate a unique bucket name
resource "random_pet" "bucket_name" {
  length = 2
}

# KMS key for S3 server‑side encryption
resource "aws_kms_key" "s3" {
  description         = "KMS key for S3 bucket encryption"
  enable_key_rotation = true
}

resource "aws_kms_alias" "s3" {
  name          = "alias/s3-bucket-key"
  target_key_id = aws_kms_key.s3.id
}

# Secure S3 bucket
resource "aws_s3_bucket" "secure" {
  bucket = "secure-${random_pet.bucket_name.id}"
  force_destroy = false

  tags = {
    Name = "SecureBucket"
  }
}

# Enable versioning (best practice)
resource "aws_s3_bucket_versioning" "secure" {
  bucket = aws_s3_bucket.secure.id

  versioning_configuration {
    status = "Enabled"
  }
}

# Block all public access
resource "aws_s3_bucket_public_access_block" "secure" {
  bucket                  = aws_s3_bucket.secure.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Server‑side encryption using the KMS key
resource "aws_s3_bucket_server_side_encryption_configuration" "secure" {
  bucket = aws_s3_bucket.secure.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.s3.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

# Enforce encryption on all object uploads
resource "aws_s3_bucket_policy" "secure" {
  bucket = aws_s3_bucket.secure.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyUnencryptedObjectUploads"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:PutObject"
        Resource  = "${aws_s3_bucket.secure.arn}/*"
        Condition = {
          StringNotEquals = {
            "s3:x-amz-server-side-encryption" = "aws:kms"
          }
        }
      }
    ]
  })
}

