provider "aws" {
  region = "us-east-1"
}

# Security best practice: Generate a strong, random password for the database master user
# Avoid hardcoding credentials in your Terraform configuration
resource "random_password" "db_master_password" {
  length           = 16
  special          = true
  override_special = "!#$%&*()-_=+[]{}<>:?"
}

# Create an AWS Lightsail Database Instance running MySQL.
# Using a managed database instance is an AWS security best practice over self-managing 
# MySQL on a compute instance, as it handles patching, backups, and secure credential management.
resource "aws_lightsail_database" "mysql_database" {
  relational_database_name = "app-mysql-db"
  availability_zone        = "us-east-1a"
  blueprint_id             = "mysql_8_0"
  bundle_id                = "medium_2_0"

  master_database_name     = "appdb"
  master_username          = "appadmin"
  master_password          = random_password.db_master_password.result

  # Security best practice: Keep the database private (not publicly accessible over the internet)
  # It can be accessed by other Lightsail instances in the same Region via private networking
  publicly_accessible = false

  # Security best practice: Define maintenance and backup windows to ensure reliability and security patching
  preferred_backup_window      = "07:00-08:00"
  preferred_maintenance_window = "Mon:08:00-Mon:09:00"

  tags = {
    Environment = "Production"
    ManagedBy   = "Terraform"
  }
}

# Output the database endpoint (do not output the password to maintain security)
output "database_endpoint" {
  value       = aws_lightsail_database.mysql_database.master_endpoint_address
  description = "The connection endpoint for the Lightsail MySQL database"
}

