model_answers:
#########################
# Variables
#########################
variable "stream_name" {
  description = "Name of the Kinesis Firehose delivery stream"
  type        = string
}

variable "opensearch_collection_arn" {
  description = "ARN of the OpenSearch Serverless collection"
  type        = string
}

variable "opensearch_index_name" {
  description = "OpenSearch index name where records will be delivered"
  type        = string
}

variable "opensearch_type_name" {
  description = "OpenSearch type name (required for compatibility, can be set to _doc)"
  type        = string
  default     = "_doc"
}

#########################
# KMS Key for Encryption
#########################
resource "aws_kms_key" "firehose" {
  description = "KMS key used to encrypt data at rest for the Firehose delivery stream"
  deletion_window_in_days = 30
  enable_key_rotation     = true
}

#########################
# IAM Role & Policy for Firehose
#########################
resource "aws_iam_role" "firehose_role" {
  name = "${var.stream_name}-firehose-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_policy" "firehose_policy" {
  name   = "${var.stream_name}-firehose-policy"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = [
          "es:ESHttpPost",
          "es:ESHttpPut",
          "es:ESHttpGet"
        ]
        Resource = "${var.opensearch_collection_arn}/*"
      },
      {
        Effect   = "Allow"
        Action   = [
          "kms:GenerateDataKey",
          "kms:Decrypt",
          "kms:Encrypt",
          "kms:ReEncrypt*",
          "kms:DescribeKey"
        ]
        Resource = aws_kms_key.firehose.arn
      },
      {
        Effect   = "Allow"
        Action   = [
          "s3:PutObject",
          "s3:PutObjectAcl",
          "s3:GetBucketLocation"
        ]
        Resource = "${aws_s3_bucket.backup.arn}/*"
      },
      {
        Effect   = "Allow"
        Action   = [
          "logs:PutLogEvents",
          "logs:CreateLogStream",
          "logs:CreateLogGroup"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "firehose_attach" {
  role       = aws_iam_role.firehose_role.name
  policy_arn = aws_iam_policy.firehose_policy.arn
}

#########################
# S3 Bucket for Backup
#########################
resource "aws_s3_bucket" "backup" {
  bucket = "${var.stream_name}-backup"
  acl    = "private"

  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm = "AES256"
      }
    }
  }

  tags = {
    Name = "${var.stream_name}-backup"
  }
}

#########################
# CloudWatch Log Group
#########################
resource "aws_cloudwatch_log_group" "firehose_log" {
  name              = "/aws/kinesisfirehose/${var.stream_name}"
  retention_in_days = 30
}

#########################
# Firehose Delivery Stream
#########################
resource "aws_kinesis_firehose_delivery_stream" "opensearch_stream" {
  name        = var.stream_name
  destination = "opensearch_serverless"

  opensearch_serverless_destination_configuration {
    collection_arn = var.opensearch_collection_arn
    role_arn      = aws_iam_role.firehose_role.arn
    index_name    = var.opensearch_index_name
    type_name     = var.opensearch_type_name

    # S3 backup for failed documents
    s3_backup_mode = "FailedDocumentsOnly"

    s3_configuration {
      role_arn           = aws_iam_role.firehose_role.arn
      bucket_arn         = aws_s3_bucket.backup.arn
      buffering_size     = 5
      buffering_interval = 300
      compression_format = "UNCOMPRESSED"
    }

    # Optional processing (disabled)
    processing_configuration {
      enabled = false
    }

    # CloudWatch logging
    cloudwatch_logging_options {
      enabled         = true
      log_group_name  = aws_cloudwatch_log_group.firehose_log.name
      log_stream_name = "FirehoseDelivery"
    }

    # Buffering hints
    buffering_hints {
      interval_in_seconds = 300
      size_in_mBs         = 5
    }

    # Server-side encryption
    encryption_configuration {
      kms_key_arn = aws_kms_key.firehose.arn
    }
  }

  tags = {
    Name = var.stream_name
  }

  depends_on = [
    aws_iam_role_policy_attachment.firehose_attach,
    aws_s3_bucket.backup,
    aws_cloudwatch_log_group.firehose_log
  ]
}

