terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

#########################
# Variables
#########################
variable "aws_region" {
  description = "AWS region to deploy resources"
  type        = string
  default     = "us-east-1"
}

#########################
# Data sources
#########################
# Use the default VPC (replace with a specific VPC if needed)
data "aws_vpc" "default" {
  default = true
}

# Private subnets tagged with Tier = private (adjust filter as needed)
data "aws_subnet_ids" "private" {
  vpc_id = data.aws_vpc.default.id

  filter {
    name   = "tag:Tier"
    values = ["private"]
  }
}

#########################
# Security Group
#########################
resource "aws_security_group" "db" {
  name        = "mysql-db-sg"
  description = "Security group for MySQL RDS instance"
  vpc_id      = data.aws_vpc.default.id

  # Allow MySQL traffic only from within the VPC (adjust CIDR or source SG as needed)
  ingress {
    description = "MySQL access from VPC"
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = [data.aws_vpc.default.cidr_block]
  }

  # Allow all outbound traffic (required for RDS)
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "mysql-db-sg"
  }
}

#########################
# DB Subnet Group
#########################
resource "aws_db_subnet_group" "mysql" {
  name        = "mysql-subnet-group"
  description = "Subnet group for MySQL RDS"
  subnet_ids  = data.aws_subnet_ids.private.ids

  tags = {
    Name = "mysql-subnet-group"
  }
}

#########################
# MySQL RDS Instance
#########################
resource "aws_db_instance" "mysql" {
  identifier                 = "my-mysql-db"
  engine                     = "mysql"
  engine_version             = "8.0"
  instance_class             = "db.t3.micro"
  allocated_storage          = 20
  storage_type               = "gp2"
  storage_encrypted          = true
  copy_tags_to_snapshot      = true
  multi_az                   = true
  publicly_accessible        = false
  deletion_protection        = true
  backup_retention_period    = 7
  backup_window              = "03:00-04:00"
  maintenance_window         = "Sun:05:00-Sun:06:00"
  performance_insights_enabled = true

  db_subnet_group_name       = aws_db_subnet_group.mysql.name
  vpc_security_group_ids     = [aws_security_group.db.id]

  username                   = "admin"
  manage_master_user_password = true   # AWS Secrets Manager will store the password

  skip_final_snapshot        = false
  final_snapshot_identifier  = "my-mysql-db-final-${timestamp()}"

  tags = {
    Name = "my-mysql-db"
  }
}

