#########################
# Providers per region  #
#########################
provider "aws" {
  region = var.default_region
}

provider "aws" {
  alias  = "us_west"
  region = "us-west-2"
}

provider "aws" {
  alias  = "eu_central"
  region = "eu-central-1"
}

#########################
# Variables & Data      #
#########################
variable "default_region" {
  description = "Default AWS region for global resources"
  type        = string
  default     = "us-east-1"
}

variable "domain_name" {
  description = "The domain name managed in Route53 (e.g., example.com.)"
  type        = string
}

data "aws_route53_zone" "main" {
  name = var.domain_name
}

#########################
# IAM for ElasticBeanstalk #
#########################
resource "aws_iam_role" "eb_ec2_role" {
  name = "eb-ec2-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Principal = { Service = "ec2.amazonaws.com" }
      Action    = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "eb_ec2_webtier" {
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkWebTier"
}

resource "aws_iam_role_policy_attachment" "eb_ec2_service" {
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkMulticontainerDocker"
}

resource "aws_iam_instance_profile" "eb_instance_profile" {
  name = "eb-instance-profile"
  role = aws_iam_role.eb_ec2_role.name
}

#########################
# Elastic Beanstalk US West #
#########################
resource "aws_elastic_beanstalk_application" "us_west" {
  name        = "myapp-us-west"
  description = "Elastic Beanstalk application for US West region"
  provider    = aws.us_west
}

resource "aws_elastic_beanstalk_environment" "us_west" {
  name                = "us_west"
  application         = aws_elastic_beanstalk_application.us_west.name
  solution_stack_name = "64bit Amazon Linux 2 v5.8.0 running Node.js 14"
  provider            = aws.us_west

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "IamInstanceProfile"
    value     = aws_iam_instance_profile.eb_instance_profile.arn
  }

  # Enable enhanced health reporting (best‑practice)
  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "EnvironmentHealth"
    value     = "Enhanced"
  }
}

#########################
# Elastic Beanstalk EU Central #
#########################
resource "aws_elastic_beanstalk_application" "eu_central" {
  name        = "myapp-eu-central"
  description = "Elastic Beanstalk application for EU Central region"
  provider    = aws.eu_central
}

resource "aws_elastic_beanstalk_environment" "eu_central" {
  name                = "eu_central"
  application         = aws_elastic_beanstalk_application.eu_central.name
  solution_stack_name = "64bit Amazon Linux 2 v5.8.0 running Node.js 14"
  provider            = aws.eu_central

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "IamInstanceProfile"
    value     = aws_iam_instance_profile.eb_instance_profile.arn
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "EnvironmentHealth"
    value     = "Enhanced"
  }
}

#########################
# Route53 Geolocation Records #
#########################
# US traffic → US West environment
resource "aws_route53_record" "us_west_geo" {
  zone_id = data.aws_route53_zone.main.zone_id
  name    = var.domain_name
  type    = "CNAME"
  ttl     = 300

  set_identifier = "us_west"
  geolocation_routing_policy {
    country = "US"
  }

  records = [aws_elastic_beanstalk_environment.us_west.endpoint_url]
}

# EU traffic → EU Central environment
resource "aws_route53_record" "eu_central_geo" {
  zone_id = data.aws_route53_zone.main.zone_id
  name    = var.domain_name
  type    = "CNAME"
  ttl     = 300

  set_identifier = "eu_central"
  geolocation_routing_policy {
    continent = "EU"
  }

  records = [aws_elastic_beanstalk_environment.eu_central.endpoint_url]
}

# Default fallback (any other location) → US West
resource "aws_route53_record" "default_fallback" {
  zone_id = data.aws_route53_zone.main.zone_id
  name    = var.domain_name
  type    = "CNAME"
  ttl     = 300

  set_identifier = "default"
  # No geolocation block makes this the default record
  records = [aws_elastic_beanstalk_environment.us_west.endpoint_url]
}

