#####################
resource "random_password" "db_master_password" {
  length  = 16
  special = true
  override_characters = "!@#$%&*()-_=+[]{}<>?"
}

#####################
# Parameter Group (optional)
#####################
resource "aws_db_parameter_group" "postgres_params" {
  name        = "postgres-params"
  family      = "postgres15"
  description = "Custom parameter group for PostgreSQL 15"

  # Example parameter – adjust as needed
  parameter {
    name  = "log_min_duration_statement"
    value = "1000"
  }

  tags = {
    Name = "postgres-params"
  }
}

#####################
# RDS Instance
#####################
resource "aws_db_instance" "postgres" {
  identifier              = "custom-postgres-db"
  engine                  = "postgres"
  engine_version          = var.engine_version
  instance_class          = var.instance_class
  allocated_storage       = var.allocated_storage
  storage_type            = "gp2"
  name                    = var.db_name
  username                = var.db_username
  password                = random_password.db_master_password.result
  db_subnet_group_name    = aws_db_subnet_group.postgres_subnet_group.name
  vpc_security_group_ids  = [aws_security_group.rds_sg.id]

  multi_az                = true
  publicly_accessible     = false
  storage_encrypted       = true
  deletion_protection     = true
  backup_retention_period = 5
  backup_window           = "03:00-06:00"
  skip_final_snapshot     = false
  final_snapshot_identifier = "${aws_db_instance.postgres.identifier}-final-snapshot"

  parameter_group_name    = aws_db_parameter_group.postgres_params.name

  apply_immediately       = false

  tags = {
    Name = "custom-postgres-db"
  }
}

