provider "aws" {
  region = "us-east-1"
}

# Use the default VPC and its subnets (replace with a dedicated VPC in production)
data "aws_vpc" "default" {
  default = true
}

data "aws_subnet_ids" "default" {
  vpc_id = data.aws_vpc.default.id
}

# Security group allowing Redshift traffic only from the VPC CIDR
resource "aws_security_group" "redshift_sg" {
  name        = "redshift-sg"
  description = "Security group for Redshift cluster"
  vpc_id      = data.aws_vpc.default.id

  ingress {
    from_port   = 5439
    to_port     = 5439
    protocol    = "tcp"
    cidr_blocks = [data.aws_vpc.default.cidr_block]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# Redshift subnet group
resource "aws_redshift_subnet_group" "example" {
  name        = "example-subnet-group"
  description = "Subnet group for Redshift cluster"
  subnet_ids  = data.aws_subnet_ids.default.ids
}

# Example Redshift parameter group
resource "aws_redshift_parameter_group" "example" {
  name   = "example-parameter-group"
  family = "redshift-1.0"
  description = "Example Redshift parameter group"

  parameter {
    name  = "require_ssl"
    value = "true"
  }
}

# Random password for the master user (store securely, e.g., in Secrets Manager)
resource "random_password" "master" {
  length           = 16
  special          = true
  override_characters = "_@%"
}

# Redshift cluster
resource "aws_redshift_cluster" "example" {
  cluster_identifier          = "example-cluster"
  database_name               = "dev"
  master_username             = "masteruser"
  master_password             = random_password.master.result
  node_type                   = "dc2.large"
  cluster_type                = "single-node"
  encrypted                   = true
  enhanced_vpc_routing        = true
  publicly_accessible         = false
  skip_final_snapshot         = true
  vpc_security_group_ids      = [aws_security_group.redshift_sg.id]
  cluster_subnet_group_name   = aws_redshift_subnet_group.example.name
  parameter_group_name        = aws_redshift_parameter_group.example.name
}

# SNS topic for Redshift events
resource "aws_sns_topic" "redshift_events" {
  name = "redshift-events-topic"
}

# Allow Redshift to publish to the SNS topic
resource "aws_sns_topic_policy" "redshift_events_policy" {
  arn    = aws_sns_topic.redshift_events.arn
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = {
          Service = "redshift.amazonaws.com"
        }
        Action    = "SNS:Publish"
        Resource  = aws_sns_topic.redshift_events.arn
        Condition = {
          ArnEquals = {
            "aws:SourceArn" = aws_redshift_cluster.example.arn
          }
        }
      }
    ]
  })
}

# Event subscription for parameter‑group events
resource "aws_redshift_event_subscription" "parameter_group_events" {
  name           = "parameter-group-events"
  sns_topic_arn  = aws_sns_topic.redshift_events.arn
  source_type    = "cluster-parameter-group"
  source_ids     = [aws_redshift_parameter_group.example.name]
  enabled        = true
  event_categories = ["configuration"]
}

