terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

#########################
# Variables
#########################
variable "aws_region" {
  description = "AWS region to deploy resources"
  type        = string
  default     = "us-east-1"
}

variable "vpc_id" {
  description = "VPC ID where the RDS instance will be placed"
  type        = string
  default     = data.aws_vpc.default.id
}

variable "allowed_cidr_blocks" {
  description = "CIDR blocks allowed to connect to MySQL"
  type        = list(string)
  default     = ["10.0.0.0/16"]
}

#########################
# Data sources
#########################
data "aws_vpc" "default" {
  default = true
}

data "aws_subnets" "available" {
  filter {
    name   = "vpc-id"
    values = [var.vpc_id]
  }
}

#########################
# Random password for DB master user
#########################
resource "random_password" "db_master" {
  length  = 16
  special = true
  override_characters = "!@#$%&*()-_=+[]{}<>?"
}

#########################
# Security Group for RDS
#########################
resource "aws_security_group" "rds_mysql_sg" {
  name        = "rds-mysql-sg"
  description = "Allow MySQL inbound from trusted CIDRs"
  vpc_id      = var.vpc_id

  ingress {
    description = "MySQL from trusted networks"
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = var.allowed_cidr_blocks
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "rds-mysql-sg"
  }
}

#########################
# Subnet Group for RDS (private subnets only)
#########################
resource "aws_db_subnet_group" "rds_mysql_subnet" {
  name       = "rds-mysql-subnet-group"
  subnet_ids = data.aws_subnets.available.ids

  tags = {
    Name = "rds-mysql-subnet-group"
  }
}

#########################
# RDS MySQL Instance
#########################
resource "aws_db_instance" "mysql" {
  identifier               = "my-mysql-instance"
  engine                   = "mysql"
  engine_version           = "8.0"
  instance_class           = "db.t3.medium"
  allocated_storage        = 20
  storage_type             = "gp3"
  storage_encrypted        = true
  multi_az                 = true
  publicly_accessible      = false
  db_subnet_group_name     = aws_db_subnet_group.rds_mysql_subnet.name
  vpc_security_group_ids   = [aws_security_group.rds_mysql_sg.id]
  username                 = "admin"
  password                 = random_password.db_master.result
  backup_retention_period  = 7
  backup_window            = "03:00-04:00"
  maintenance_window       = "Mon:05:00-Mon:06:00"
  deletion_protection      = true
  skip_final_snapshot      = false
  final_snapshot_identifier = "${aws_db_instance.mysql.identifier}-final-snapshot"

  # Enable IAM DB authentication (optional but recommended)
  iam_database_authentication_enabled = true

  # Monitoring (enhanced)
  monitoring_interval = 60
  monitoring_role_arn = aws_iam_role.rds_monitoring.arn

  tags = {
    Environment = "dev"
    ManagedBy   = "terraform"
  }
}

#########################
# IAM Role for Enhanced Monitoring
#########################
resource "aws_iam_role" "rds_monitoring" {
  name = "rds-monitoring-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
        Service = "monitoring.rds.amazonaws.com"
      }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "rds_monitoring_attach" {
  role       = aws_iam_role.rds_monitoring.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonRDSEnhancedMonitoringRole"
}

#########################
# Snapshot of the RDS instance
#########################
resource "aws_db_snapshot" "mysql_snapshot" {
  db_instance_identifier = aws_db_instance.mysql.id
  db_snapshot_identifier = "${aws_db_instance.mysql.identifier}-snapshot-${formatdate("YYYYMMDDHHmmss", timestamp())}"

  # Ensure snapshot is taken after the DB is fully provisioned
  depends_on = [aws_db_instance.mysql]
}

