model_answers:
provider "aws" {
  region = "us-east-1"
}

#########################
# VPC & Networking
#########################
data "aws_availability_zones" "available" {}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
  tags = {
    Name = "msk-vpc"
  }
}

resource "aws_subnet" "private" {
  count                   = 3
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 1)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false
  tags = {
    Name = "msk-private-${count.index}"
  }
}

resource "aws_security_group" "msk" {
  name        = "msk-sg"
  description = "Security group for MSK brokers"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Kafka broker port"
    from_port   = 9092
    to_port     = 9092
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "msk-sg"
  }
}

#########################
# KMS Key for Encryption
#########################
resource "aws_kms_key" "msk" {
  description = "KMS key for MSK encryption at rest"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  tags = {
    Name = "msk-encryption-key"
  }
}

#########################
# CloudWatch Log Group
#########################
resource "aws_cloudwatch_log_group" "msk" {
  name              = "/aws/msk/cluster-logs"
  retention_in_days = 30
  tags = {
    Name = "msk-log-group"
  }
}

resource "aws_iam_role" "msk_logging" {
  name = "msk-logging-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17",
    Statement = [{
      Effect    = "Allow",
      Principal = { Service = "kafka.amazonaws.com" },
      Action    = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy" "msk_logging" {
  name = "msk-logging-policy"
  role = aws_iam_role.msk_logging.id

  policy = jsonencode({
    Version = "2012-10-17",
    Statement = [{
      Effect   = "Allow",
      Action   = [
        "logs:CreateLogGroup",
        "logs:CreateLogStream",
        "logs:PutLogEvents"
      ],
      Resource = "${aws_cloudwatch_log_group.msk.arn}:*"
    }]
  })
}

#########################
# S3 Bucket for Data
#########################
resource "random_id" "suffix" {
  byte_length = 4
}

resource "aws_s3_bucket" "msk_data" {
  bucket = "msk-data-${random_id.suffix.hex}"
  force_destroy = true

  tags = {
    Name = "msk-data-bucket"
  }
}

#########################
# IAM Role for Firehose
#########################
resource "aws_iam_role" "firehose_role" {
  name = "msk-firehose-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17",
    Statement = [{
      Effect    = "Allow",
      Principal = { Service = "firehose.amazonaws.com" },
      Action    = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy" "firehose_policy" {
  name = "msk-firehose-policy"
  role = aws_iam_role.firehose_role.id

  policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Effect   = "Allow",
        Action   = [
          "s3:PutObject",
          "s3:PutObjectAcl",
          "s3:GetBucketLocation",
          "s3:ListBucket"
        ],
        Resource = [
          "${aws_s3_bucket.msk_data.arn}",
          "${aws_s3_bucket.msk_data.arn}/*"
        ]
      },
      {
        Effect   = "Allow",
        Action   = [
          "logs:PutLogEvents"
        ],
        Resource = "*"
      }
    ]
  })
}

#########################
# Kinesis Firehose Delivery Stream
#########################
resource "aws_kinesis_firehose_delivery_stream" "msk_to_s3" {
  name        = "msk-firehose-${random_id.suffix.hex}"
  destination = "s3"

  s3_configuration {
    role_arn        = aws_iam_role.firehose_role.arn
    bucket_arn      = aws_s3_bucket.msk_data.arn
    buffer_interval = 300
    buffer_size     = 5
    compression_format = "UNCOMPRESSED"
  }

  tags = {
    Name = "msk-firehose"
  }
}

#########################
# MSK Cluster
#########################
resource "aws_msk_cluster" "example" {
  cluster_name           = "example-msk-cluster"
  kafka_version          = "3.5.0"
  number_of_broker_nodes = 3

  broker_node_group_info {
    instance_type   = "kafka.m5.large"
    client_subnets  = aws_subnet.private[*].id
    security_groups = [aws_security_group.msk.id]

    storage_info {
      ebs_storage_info {
        volume_size = 1000
      }
    }
  }

  encryption_info {
    encryption_at_rest_kms_key_arn = aws_kms_key.msk.arn
  }

  client_authentication {
    tls {
      enabled = true
    }
  }

  open_monitoring {
    prometheus {
      jmx_exporter {
        enabled_in_broker = true
      }
      node_exporter {
        enabled_in_broker = true
      }
    }
  }

  logging_info {
    broker_logs {
      cloudwatch_logs {
        enabled   = true
        log_group = aws_cloudwatch_log_group.msk.name
      }
    }
  }

  tags = {
    Environment = "dev"
    Name        = "example-msk-cluster"
  }
}

#########################
# Outputs
#########################
output "msk_cluster_arn" {
  description = "ARN of the MSK cluster"
  value       = aws_msk_cluster.example.arn
}

output "cloudwatch_log_group_name" {
  description = "Name of the CloudWatch log group for MSK"
  value       = aws_cloudwatch_log_group.msk.name
}

output "s3_bucket_name" {
  description = "Name of the S3 bucket for MSK data"
  value       = aws_s3_bucket.msk_data.id
}

output "firehose_name" {
  description = "Name of the Kinesis Firehose delivery stream"
  value       = aws_kinesis_firehose_delivery_stream.msk_to_s3.name
}

