}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "private_subnet_cidrs" {
  description = "List of CIDR blocks for private subnets"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

#########################
# Networking
#########################
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = "rds-vpc"
  }
}

resource "aws_subnet" "private" {
  count                   = length(var.private_subnet_cidrs)
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.private_subnet_cidrs[count.index]
  map_public_ip_on_launch = false
  availability_zone       = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "rds-private-${count.index}"
  }
}

data "aws_availability_zones" "available" {}

resource "aws_db_subnet_group" "rds" {
  name       = "rds-subnet-group"
  subnet_ids = aws_subnet.private[*].id

  tags = {
    Name = "RDS subnet group"
  }
}

resource "aws_security_group" "rds" {
  name        = "rds-sg"
  description = "Security group for RDS instances"
  vpc_id      = aws_vpc.main.id

  # Inbound: allow only from within the VPC (example: app servers)
  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "RDS SG"
  }
}

#########################
# KMS Key for Encryption
#########################
resource "aws_kms_key" "rds" {
  description         = "KMS key for RDS encryption"
  deletion_window_in_days = 30
  enable_key_rotation = true

  tags = {
    Name = "rds-kms-key"
  }
}

resource "aws_kms_alias" "rds" {
  name          = "alias/rds-key"
  target_key_id = aws_kms_key.rds.id
}

#########################
# Random Password
#########################
resource "random_password" "master" {
  length  = 16
  special = true
  override_characters = "!@#%^&*()-_=+[]{}<>?"
}

#########################
# Primary RDS Instance
#########################
resource "aws_db_instance" "primary" {
  identifier               = "primary-db"
  engine                   = "postgres"
  engine_version          = "15"
  instance_class           = "db.t3.micro"
  allocated_storage        = 20
  storage_type             = "gp2"
  storage_encrypted        = true
  kms_key_id               = aws_kms_key.rds.arn

  username                 = "dbadmin"
  password                 = random_password.master.result
  db_name                  = "appdb"

  vpc_security_group_ids   = [aws_security_group.rds.id]
  db_subnet_group_name     = aws_db_subnet_group.rds.name
  publicly_accessible      = false
  multi_az                 = false
  backup_retention_period  = 7
  deletion_protection      = true
  skip_final_snapshot      = false
  final_snapshot_identifier = "primary-db-final-${timestamp()}"
  apply_immediately        = false

  tags = {
    Name = "Primary RDS"
  }
}

#########################
# Read Replica
#########################
resource "aws_db_instance" "replica" {
  identifier               = "replica-db"
  engine                   = aws_db_instance.primary.engine
  engine_version          = aws_db_instance.primary.engine_version
  instance_class           = "db.t3.micro"
  storage_type             = "gp2"
  allocated_storage        = 20
  storage_encrypted        = true
  kms_key_id               = aws_kms_key.rds.arn

  replicate_source_db      = aws_db_instance.primary.id

  vpc_security_group_ids   = [aws_security_group.rds.id]
  db_subnet_group_name     = aws_db_subnet_group.rds.name
  publicly_accessible      = false
  backup_retention_period  = 7
  deletion_protection      = true
  skip_final_snapshot      = false
  final_snapshot_identifier = "replica-db-final-${timestamp()}"
  apply_immediately        = false

  tags = {
    Name = "RDS Read Replica"
  }

  depends_on = [aws_db_instance.primary]
}

