  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

resource "aws_lambda_permission" "allow_lex_invoke" {
  statement_id  = "AllowLexInvoke"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.trip_fulfillment.function_name
  principal     = "lex.amazonaws.com"
  source_arn    = aws_lex_bot.trip_booking_bot.arn
}

#########################
# Lex Intent
#########################
resource "aws_lex_intent" "book_trip_intent" {
  name        = "BookTripIntent"
  description = "Intent to book a trip"

  sample_utterances = [
    "I want to book a flight to {Destination} on {TravelDate}",
    "Book me a trip to {Destination} for {TravelDate}",
    "Reserve a flight to {Destination} on {TravelDate}"
  ]

  # Slots definition
  slot {
    name                 = "Destination"
    slot_type            = "AMAZON.City"
    slot_constraint      = "Required"
    value_elicitation_prompt {
      max_attempts = 2
      messages = [
        {
          content_type = "PlainText"
          content      = "Which city would you like to travel to?"
        }
      ]
    }
    priority = 1
  }

  slot {
    name                 = "TravelDate"
    slot_type            = "AMAZON.Date"
    slot_constraint      = "Required"
    value_elicitation_prompt {
      max_attempts = 2
      messages = [
        {
          content_type = "PlainText"
          content      = "When would you like to travel?"
        }
      ]
    }
    priority = 2
  }

  # Confirmation prompt
  confirmation_prompt {
    max_attempts = 2
    messages = [
      {
        content_type = "PlainText"
        content      = "You want to travel to {Destination} on {TravelDate}, is that correct?"
      }
    ]
  }

  # Rejection statement
  rejection_statement {
    messages = [
      {
        content_type = "PlainText"
        content      = "Okay, let me know if you need anything else."
      }
    ]
  }

  # Fulfillment via Lambda
  fulfillment_activity {
    type = "CodeHook"
    code_hook {
      uri          = aws_lambda_function.trip_fulfillment.arn
      message_version = "1.0"
    }
  }

  # Dialog code hook (optional, can be same as fulfillment)
  dialog_code_hook {
    uri          = aws_lambda_function.trip_fulfillment.arn
    message_version = "1.0"
  }

  # Intent version
  create_version = true
}

#########################
# Lex Bot
#########################
resource "aws_lex_bot" "trip_booking_bot" {
  name                     = "TripBookingBot"
  description              = "Lex bot for booking trips"
  locale                   = "en_US"
  voice_id                 = "Joanna"
  child_directed           = false
  idle_session_ttl_in_seconds = 300
  process_behavior         = "BUILD"
  role_arn                 = aws_iam_role.lex_bot_role.arn
  encryption_key_arn       = aws_kms_key.lex_bot_key.arn

  # Abort statement
  abort_statement {
    messages = [
      {
        content_type = "PlainText"
        content      = "Sorry, I couldn't understand. Let's try again later."
      }
    ]
  }

  # Clarification prompt
  clarification_prompt {
    max_attempts = 2
    messages = [
      {
        content_type = "PlainText"
        content      = "I didn't catch that. Could you please repeat?"
      }
    ]
  }

  # Intent association
  intent {
    intent_name    = aws_lex_intent.book_trip_intent.name
    intent_version = "$LATEST"
  }

  # Enable automatic versioning
  create_version = true

  # Tags for cost allocation and security
  tags = {
    Environment = "Production"
    Owner       = "InfrastructureTeam"
  }
}

