  description = "Name of the Lightsail managed database."
  type        = string
  default     = "my-lightsail-db"
}

variable "db_username" {
  description = "Master username for the database."
  type        = string
  default     = "admin"
}

variable "db_password_length" {
  description = "Length of the generated master password."
  type        = number
  default     = 16
}

#####################
# Generate secure password
#####################
resource "random_password" "db_password" {
  length           = var.db_password_length
  override_characters = "!@#$%&*()-_=+[]{}<>?"
  keepers = {
    # Force regeneration only if the length changes
    length = var.db_password_length
  }
}

#####################
# Store credentials in Secrets Manager (best practice)
#####################
resource "aws_secretsmanager_secret" "db_credentials" {
  name = "${var.db_name}-credentials"
  description = "Credentials for Lightsail managed database ${var.db_name}"
  tags = {
    Environment = "production"
    ManagedBy   = "terraform"
  }
}

resource "aws_secretsmanager_secret_version" "db_credentials_version" {
  secret_id     = aws_secretsmanager_secret.db_credentials.id
  secret_string = jsonencode({
    username = var.db_username
    password = random_password.db_password.result
  })
  depends_on = [aws_lightsail_database.this]
}

#####################
# Lightsail Managed Database
#####################
resource "aws_lightsail_database" "this" {
  name                 = var.db_name
  blueprint_id         = "mysql_8_0"          # MySQL 8.0; adjust as needed
  bundle_id            = "micro_2_0"          # Smallest bundle; adjust for capacity
  availability_zone    = "${var.region}a"     # Choose an AZ in the selected region
  master_database_name = "appdb"
  master_username      = var.db_username
  master_password      = random_password.db_password.result

  # Security best practice: do not expose publicly
  publicly_accessible = false

  tags = {
    Environment = "production"
    ManagedBy   = "terraform"
  }

  # Ensure password is stored before deletion to avoid orphaned secret
  lifecycle {
    prevent_destroy = false
  }
}

#####################
# Outputs
#####################
output "lightsail_database_endpoint" {
  description = "Endpoint address for the Lightsail managed database."
  value       = aws_lightsail_database.this.endpoint
}

output "lightsail_database_port" {
  description = "Port for the Lightsail managed database."
  value       = aws_lightsail_database.this.port
}

output "db_credentials_secret_arn" {
  description = "ARN of the Secrets Manager secret containing DB credentials."
  value       = aws_secretsmanager_secret.db_credentials.arn
}

