}

#########################
# Random ID for bucket name
#########################
resource "random_id" "bucket_id" {
  byte_length = 4
}

#########################
# S3 bucket for CodeBuild artifacts
#########################
resource "aws_s3_bucket" "codebuild_output" {
  bucket = "codebuild-output-${random_id.bucket_id.hex}"
  force_destroy = true

  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm = "AES256"
      }
    }
  }

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true

  tags = {
    Name = "codebuild-output"
  }
}

#########################
# VPC and Subnet
#########################
data "aws_availability_zones" "available" {}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = "codebuild-vpc"
  }
}

resource "aws_subnet" "main" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.0.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = {
    Name = "codebuild-subnet"
  }
}

#########################
# Security Group with no ingress/egress (blocks internet)
#########################
resource "aws_security_group" "codebuild_sg" {
  name        = "codebuild-sg"
  description = "Security group with no internet access"
  vpc_id      = aws_vpc.main.id

  ingress = []
  egress  = []
}

#########################
# IAM Role for CodeBuild
#########################
resource "aws_iam_role" "codebuild_role" {
  name = "codebuild-service-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
        Service = "codebuild.amazonaws.com"
      }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_policy" "codebuild_policy" {
  name        = "codebuild-policy"
  description = "Policy for CodeBuild to access S3, VPC and CloudWatch Logs"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:PutObject",
          "s3:GetObject",
          "s3:GetObjectVersion",
          "s3:ListBucket"
        ]
        Resource = [
          aws_s3_bucket.codebuild_output.arn,
          "${aws_s3_bucket.codebuild_output.arn}/*"
        ]
      },
      {
        Effect = "Allow"
        Action = [
          "ec2:CreateNetworkInterface",
          "ec2:DescribeNetworkInterfaces",
          "ec2:DeleteNetworkInterface",
          "ec2:DescribeSubnets",
          "ec2:DescribeSecurityGroups",
          "ec2:DescribeVpcs"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "codebuild_attach" {
  role       = aws_iam_role.codebuild_role.name
  policy_arn = aws_iam_policy.codebuild_policy.arn
}

#########################
# CodeBuild Project
#########################
resource "aws_codebuild_project" "project" {
  name          = "student-codebuild"
  description   = "CodeBuild project for student builds"
  service_role  = aws_iam_role.codebuild_role.arn

  artifacts {
    type                = "S3"
    location            = aws_s3_bucket.codebuild_output.bucket
    packaging           = "ZIP"
    name_prefix         = "build-output"
    encryption_disabled = false
  }

  environment {
    compute_type = "BUILD_GENERAL1_SMALL"
    image        = "aws/codebuild/alpine:latest"
    type         = "LINUX_CONTAINER"
    privileged_mode = false
  }

  source {
    type            = "GITHUB"
    location        = "github.com/source-location"
    git_clone_depth = 1
  }

  vpc_config {
    vpc_id            = aws_vpc.main.id
    subnets           = [aws_subnet.main.id]
    security_group_ids = [aws_security_group.codebuild_sg.id]
  }

  tags = {
    Environment = "dev"
  }
}

