provider "aws" {
  region = "us-east-1"
}

# -------------------------------------------------
# VPC and networking (3 AZs, private subnets only)
# -------------------------------------------------
data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "msk_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = "msk-vpc"
  }
}

resource "aws_subnet" "msk_subnet" {
  count                   = 3
  vpc_id                  = aws_vpc.msk_vpc.id
  cidr_block              = cidrsubnet(aws_vpc.msk_vpc.cidr_block, 8, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "msk-subnet-${count.index}"
  }
}

resource "aws_security_group" "msk_sg" {
  name        = "msk-sg"
  description = "Security group for MSK brokers"
  vpc_id      = aws_vpc.msk_vpc.id

  # Allow Kafka client traffic only from within the VPC
  ingress {
    description = "Kafka client traffic"
    from_port   = 9092
    to_port     = 9092
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.msk_vpc.cidr_block]
  }

  # Allow inter‑broker communication
  ingress {
    description = "Inter‑broker traffic"
    from_port   = 9094
    to_port     = 9094
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.msk_vpc.cidr_block]
  }

  egress {
    description = "Allow all outbound"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "msk-sg"
  }
}

# -------------------------------------------------
# KMS key for encryption at rest
# -------------------------------------------------
data "aws_iam_policy_document" "kms_key_policy" {
  statement {
    sid    = "AllowMSKService"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["kafka.amazonaws.com"]
    }

    actions = [
      "kms:GenerateDataKey*",
      "kms:Decrypt",
      "kms:Encrypt",
      "kms:ReEncrypt*",
      "kms:DescribeKey"
    ]

    resources = ["*"]
  }
}

resource "aws_kms_key" "msk_key" {
  description         = "KMS key for MSK encryption at rest"
  policy              = data.aws_iam_policy_document.kms_key_policy.json
  deletion_window_in_days = 30

  tags = {
    Name = "msk-at-rest-key"
  }
}

# -------------------------------------------------
# CloudWatch Log Group for broker logs
# -------------------------------------------------
resource "aws_cloudwatch_log_group" "msk_logs" {
  name              = "/aws/msk/example"
  retention_in_days = 30

  tags = {
    Name = "msk-log-group"
  }
}

# -------------------------------------------------
# MSK Configuration (optional but recommended)
# -------------------------------------------------
resource "aws_msk_configuration" "example" {
  name            = "example-msk-config"
  kafka_versions  = ["3.5.1"]
  server_properties = <<PROPERTIES
auto.create.topics.enable = false
log.retention.hours = 168
delete.topic.enable = true
PROPERTIES

  tags = {
    Name = "example-msk-config"
  }
}

# -------------------------------------------------
# Managed Streaming for Kafka (MSK) Cluster
# -------------------------------------------------
resource "aws_msk_cluster" "example" {
  cluster_name           = "example-msk-cluster"
  kafka_version          = "3.5.1"
  number_of_broker_nodes = 3

  broker_node_group_info {
    instance_type   = "kafka.m5.large"
    client_subnets  = aws_subnet.msk_subnet[*].id
    security_groups = [aws_security_group.msk_sg.id]

    storage_info {
      ebs_storage_info {
        volume_size = 1000 # GB
      }
    }
  }

  encryption_info {
    encryption_at_rest_kms_key_arn = aws_kms_key.msk_key.arn

    encryption_in_transit {
      client_broker = "TLS"
      in_cluster    = true
    }
  }

  logging_info {
    broker_logs {
      cloudwatch_logs {
        enabled   = true
        log_group = aws_cloudwatch_log_group.msk_logs.name
      }
    }
  }

  configuration_info {
    arn      = aws_msk_configuration.example.arn
    revision = aws_msk_configuration.example.latest_revision
  }

  tags = {
    Environment = "dev"
    Owner       = "infra-team"
  }
}

