# Variables for flexibility and reuse
variable "vpc_id" {
  description = "The VPC ID where EFS will be deployed"
  type        = string
}

variable "subnet_ids" {
  description = "List of subnet IDs for EFS mount targets"
  type        = list(string)
}

variable "common_tags" {
  description = "Common tags to apply to all resources"
  type        = map(string)
  default = {
    Project     = "Infrastructure"
    Environment = "Production"
    ManagedBy   = "Terraform"
  }
}

# Security Group to restrict access to EFS (Security Best Practice)
resource "aws_security_group" "efs_sg" {
  name        = "efs-mount-sg"
  description = "Allow NFS traffic from within the VPC"
  vpc_id      = var.vpc_id

  ingress {
    description = "Allow NFS port 2049 from VPC CIDR"
    from_port   = 2049
    to_port     = 2049
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/8"] # Replace with your specific VPC CIDR
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = var.common_tags
}

# EFS File System
resource "aws_efs_file_system" "this" {
  creation_token = "efs-filesystem-token"

  # Security Best Practices
  encrypted            = true
  performance_mode     = "generalPurpose"
  throughput_mode      = "bursting"
  lifecycle_policy     = "after_30_days"

  tags = merge(var.common_tags, {
    Name = "secure-efs-filesystem"
  })
}

# Mount Targets for each subnet provided
resource "aws_efs_mount_target" "this" {
  count = length(var.subnet_ids)

  file_system_id  = aws_efs_file_system.this.id
  subnet_id       = var.subnet_ids[count.index]
  security_groups = [aws_security_group.efs_sg.id]

  tags = merge(var.common_tags, {
    Name = "efs-mount-target-${count.index}"
  })
}

