      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "source" {
  bucket = aws_s3_bucket.source.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Destination Bucket for Inventory Reports
resource "aws_s3_bucket" "destination" {
  bucket = "inventory-reports-bucket-${random_id.suffix.hex}"
}

resource "aws_s3_bucket_server_side_encryption_configuration" "destination" {
  bucket = aws_s3_bucket.destination.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "destination" {
  bucket = aws_s3_bucket.destination.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Bucket Policy to allow S3 Inventory to write to the destination bucket
resource "aws_s3_bucket_policy" "destination_policy" {
  bucket = aws_s3_bucket.destination.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowS3InventoryWrite"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action   = "s3:PutObject"
        Resource = "${aws_s3_bucket.destination.arn}/*"
        Condition = {
          StringEquals = {
            "s3:x-amz-acl" = "bucket-owner-full-control"
          }
        }
      }
    ]
  })
}

# S3 Inventory Configuration
resource "aws_s3_bucket_inventory" "weekly_inventory" {
  bucket = aws_s3_bucket.source.id
  id     = "weekly-object-version-inventory"

  schedule {
    frequency = "Weekly"
  }

  included_object_versions {
    all = true
  }

  destination {
    s3 {
      bucket = aws_s3_bucket.destination.id
      format = "CSV"
    }
  }

  depends_on = [aws_s3_bucket_policy.destination_policy]
}

