resource "aws_subnet" "redis_subnet_2" {
  vpc_id            = aws_vpc.redis_vpc.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-east-1b"
  tags              = { Name = "redis-subnet-2" }
}

# ElastiCache Subnet Group
resource "aws_elasticache_subnet_group" "redis_subnet_group" {
  name       = "redis-subnet-group"
  subnet_ids = [aws_subnet.redis_subnet_1.id, aws_subnet.redis_subnet_2.id]
}

# Security Group: Restrict access to port 6379 from within the VPC
resource "aws_security_group" "redis_sg" {
  name        = "redis-security-group"
  description = "Allow Redis traffic from within VPC"
  vpc_id      = aws_vpc.redis_vpc.id

  ingress {
    from_port   = 6379
    to_port     = 6379
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.redis_vpc.cidr_block]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = { Name = "redis-sg" }
}

# Redis Replication Group (Best practice over aws_elasticache_cluster for production)
resource "aws_elasticache_replication_group" "redis" {
  replication_group_id          = "redis-cluster"
  description                   = "Secure Redis Instance"
  node_type                     = "cache.t3.micro"
  num_cache_clusters            = 2 # Enable Multi-AZ for high availability
  parameter_group_name          = "default.redis7"
  port                          = 6379
  subnet_group_name             = aws_elasticache_subnet_group.redis_subnet_group.name
  security_group_ids            = [aws_security_group.redis_sg.id]

  # Security Best Practices
  at_rest_encryption_enabled    = true
  transit_encryption_enabled     = true
  auth_token                    = "StrongPassword123!" # In production, use a secret manager or variable

  automatic_failover_enabled     = true
  multi_az_enabled              = true

  tags = {
    Environment = "Production"
    Service     = "Cache"
  }
}

output "redis_endpoint" {
  value       = aws_elasticache_replication_group.redis.primary_endpoint_address
  description = "The endpoint of the primary Redis node"
}

