provider "aws" {
  region = "us-east-1"
}

# Variables for sensitive data and configuration
variable "db_password" {
  description = "Password for the Redshift administrator"
  type        = string
  sensitive   = true
}

variable "vpc_id" {
  description = "The VPC ID where resources will be deployed"
  type        = string
  default     = "vpc-xxxxxxxx"
}

variable "subnet_ids" {
  description = "List of subnet IDs for the Redshift cluster"
  type        = list(string)
  default     = ["subnet-xxxxxxxx", "subnet-yyyyyyyy"]
}

# SNS Topic for Redshift Event Notifications
resource "aws_sns_topic" "redshift_events" {
  name = "redshift-cluster-events-topic"
}

# Redshift Parameter Group
resource "aws_redshift_parameter_group" "example" {
  name   = "redshift-example-pg"
  family = "redshift-ql2.0.0"

  parameter {
    name  = "require_ssl"
    value = "true" # Security best practice: enforce SSL
  }
}

# Redshift Subnet Group
resource "aws_redshift_subnet_group" "main" {
  name       = "redshift-subnet-group"
  subnet_ids = var.subnet_ids
}

# Security Group for Redshift (Restrict access to port 5439)
resource "aws_security_group" "redshift_sg" {
  name        = "redshift-sg"
  description = "Allow Redshift access"
  vpc_id      = var.vpc_id

  ingress {
    from_port   = 5439
    to_port     = 5439
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/8"] # Replace with your actual internal network CIDR
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# Redshift Cluster
resource "aws_redshift_cluster" "example" {
  cluster_identifier = "redshift-cluster-example"
  database_name      = "exampledb"
  master_username    = "awsuser"
  master_password    = var.db_password
  node_type          = "dc2.large"
  cluster_type       = "single-node"

  # Attach the parameter group
  parameter_group_name = aws_redshift_parameter_group.example.name

  # Network and Security
  cluster_subnet_group_name = aws_redshift_subnet_group.main.name
  vpc_security_group_ids    = [aws_security_group.redshift_sg.id]
  publicly_accessible      = false # Security best practice: keep cluster private

  # Encryption
  encrypted = true # Security best practice: encrypt data at rest

  skip_final_snapshot = true
}

# Redshift Event Subscription
# This resource sends events associated with the cluster and its configuration (including parameter groups) to SNS
resource "aws_redshift_event_subscription" "example" {
  event_categories = ["cluster"] # 'cluster' category covers parameter group changes and cluster state changes
  sns_topic_arn    = aws_sns_topic.redshift_events.arn
}

