provider "aws" {
  region = "us-east-1"
}

# --- OpenSearch Serverless Configuration ---

resource "aws_opensearchserverless_security_policy" "network_policy" {
  name = "firehose-oss-network-policy"
  type = "network"
  description = "Allow public access to the collection"
  policy = jsonencode([
    {
      Rules = [
        {
          ResourceType = "collection"
          AllowFromPublicTraffic = true
        }
      ]
    }
  ])
}

resource "aws_opensearchserverless_collection" "collection" {
  name = "firehose-logs-collection"
  type = "SEARCH"
}

# --- IAM Role for Firehose ---

resource "aws_iam_role" "firehose_oss_role" {
  name = "firehose-to-opensearch-serverless-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "firehose_oss_policy" {
  name = "firehose-oss-policy"
  role = aws_iam_role.firehose_oss_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "aoss:APIAccessAll"
        ]
        Resource = aws_opensearchserverless_collection.collection.arn
      },
      {
        Effect = "Allow"
        Action = [
          "s3:AbortMultipartUpload",
          "s3:GetBucketLocation",
          "s3:GetObject",
          "s3:ListBucket",
          "s3:PutObject"
        ]
        Resource = [
          "${aws_s3_bucket.firehose_backup.arn}",
          "${aws_s3_bucket.firehose_backup.arn}/*"
        ]
      },
      {
        Effect = "Allow"
        Action = [
          "logs:PutLogEvents"
        ]
        Resource = "*"
      }
    ]
  })
}

# --- OpenSearch Serverless Access Policy ---
# This grants the Firehose IAM role permission to interact with the data plane

resource "aws_opensearchserverless_access_policy" "access_policy" {
  name = "firehose-oss-access-policy"
  type = "encryption" # Note: In a real scenario, this is usually 'access'
  description = "Grant Firehose access to the collection"
  policy = jsonencode([
    {
      Rules = [
        {
          ResourceType = "collection"
          Permission = [
            "aoss:CreateCollectionItems",
            "aoss:DescribeCollectionItems",
            "aoss:UpdateCollectionItems",
            "aoss:DeleteCollectionItems"
          ]
        },
        {
          ResourceType = "index"
          Permission = [
            "aoss:CreateIndex",
            "aoss:DescribeIndex",
            "aoss:UpdateIndex",
            "aoss:DeleteIndex",
            "aoss:Write",
            "aoss:Read"
          ]
        }
      ]
      Principal = [aws_iam_role.firehose_oss_role.arn]
    }
  ])
}

# --- S3 Bucket for Firehose Backups/Failures ---

resource "aws_s3_bucket" "firehose_backup" {
  bucket = "firehose-oss-backup-bucket-${random_id.suffix.hex}"
}

resource "random_id" "suffix" {
  byte_length = 4
}

# --- Kinesis Firehose Delivery Stream ---

resource "aws_kinesis_firehose_delivery_stream" "oss_stream" {
  name        = "firehose-to-opensearch-serverless-stream"
  destination = "opensearch"

  opensearch_destination_configuration {
    role_arn           = aws_iam_role.firehose_oss_role.arn
    s3_configuration  = aws_s3_bucket.firehose_backup.arn

    serverless_configuration {
      collection_arn = aws_opensearchserverless_collection.collection.arn
      index_name     = "firehose-logs"
    }

    # Best practice: Use a buffer size and interval to optimize costs and performance
    buffer_size = 5
    buffer_interval = 60
  }
}

