provider "aws" {
  region = "us-east-1"
}

# --- Networking ---
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_hostnames  = true
  enable_dns_support   = true
}

resource "aws_subnet" "msk_subnet" {
  count             = 3
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.${count.index}.0/24"
  availability_zone = data.aws_availability_zones.available.names[count.index]
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_security_group" "msk_sg" {
  name        = "msk-security-group"
  description = "Allow Kafka traffic"
  vpc_id      = aws_vpc.main.id

  # Kafka Plaintext
  ingress {
    from_port   = 9092
    to_port     = 9092
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/16"]
  }

  # Kafka TLS
  ingress {
    from_port   = 9094
    to_port     = 9094
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/16"]
  }

  # Zookeeper
  ingress {
    from_port   = 2181
    to_port     = 2181
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/16"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# --- Encryption ---
resource "aws_kms_key" "msk_key" {
  description             = "KMS key for MSK encryption at rest"
  deletion_window_in_days = 7
  enable_key_rotation     = true
}

# --- Storage & Delivery ---
resource "aws_s3_bucket" "msk_storage" {
  bucket = "msk-data-lake-bucket-${random_id.id.hex}"
}

resource "aws_s3_bucket_public_access_block" "msk_storage_block" {
  bucket = aws_s3_bucket.msk_storage.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_cloudwatch_log_group" "msk_logs" {
  name              = "/aws/msk/cluster-logs"
  retention_in_days = 30
}

resource "aws_iam_role" "firehose_role" {
  name = "msk-firehose-delivery-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action = "sts:AssumeRole"
      Effect = "Allow"
      Principal = { Service = "firehose.amazonaws.com" }
    }]
  })
}

resource "aws_iam_role_policy" "firehose_s3_policy" {
  name = "firehose-s3-access"
  role = aws_iam_role.firehose_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect   = "Allow"
      Action   = ["s3:PutObject", "s3:GetBucketLocation"]
      Resource = ["${aws_s3_bucket.msk_storage.arn}", "${aws_s3_bucket.msk_storage.arn}/*"]
    }]
  })
}

resource "aws_kinesis_firehose_delivery_stream" "msk_stream" {
  name        = "msk-delivery-stream"
  destination = "extended_s3"

  extended_s3_configuration {
    role_arn   = aws_iam_role.firehose_role.arn
    bucket_arn = aws_s3_bucket.msk_storage.arn
  }
}

# --- MSK Cluster ---
resource "aws_msk_cluster" "main" {
  cluster_name           = "msk-cluster"
  kafka_version           = "3.5.1"
  number_of_broker_nodes  = 3

  broker_node_group_info {
    instance_type = "kafka.m5.large"
    client_subnets = [
      aws_subnet.msk_subnet[0].id,
      aws_subnet.msk_subnet[1].id,
      aws_subnet.msk_subnet[2].id
    ]
    security_groups = [aws_security_group.msk_sg.id]
    storage_info {
      ebs_storage_volume_size = 100
    }
  }

  encryption_info {
    encryption_at_rest {
      data_volume_kms_key_id = aws_kms_key.msk_key.arn
      encryption_in_transit {
        client_broker = "TLS"
        broker_inter_broker = "TLS"
      }
    }
  }

  monitoring {
    open_monitoring {
      prometheus {
        section {
          enabled = true
        }
      }
    }
  }

  logging_info {
    broker_logs {
      cloudwatch_logs {
        enabled   = true
        log_group = aws_cloudwatch_log_group.msk_logs.name
      }
    }
  }
}

resource "random_id" "id" {
  byte_length = 4
}

output "bootstrap_brokers" {
  value = aws_msk_cluster.main.bootstrap_brokers_tls
}

output "firehose_stream_arn" {
  value = aws_kinesis_firehose_delivery_stream.msk_stream.arn
}

output "s3_bucket_name" {
  value = aws_s3_bucket.msk_storage.id
}

provider "aws" {
  region = "us-east-1"
}

# Random password for the database
resource "random_password" "db_password" {
