resource "aws_s3_bucket_public_access_block" "build_output_access" {
  bucket = aws_s3_bucket.build_output.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# VPC Configuration
