    Name = "codebuild-vpc"
  }
}

# Subnet Configuration
resource "aws_subnet" "main" {
  vpc_id     = aws_vpc.main.id
  cidr_block = "10.0.0.0/24"

  tags = {
    Name = "codebuild-subnet"
  }
}

# Security Group - No ingress or egress rules to block internet access
resource "aws_security_group" "main" {
  name        = "codebuild-sg"
  description = "Block all internet access"
  vpc_id      = aws_vpc.main.id

  # By omitting ingress and egress blocks, we ensure no rules are added.
  # Note: AWS default security groups allow all outbound; 
  # creating a new SG without egress rules effectively blocks all outbound traffic.
}

# IAM Role for CodeBuild to execute and access S3
resource "aws_iam_role" "codebuild_role" {
  name = "codebuild-project-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
      },
    ]
  })
}

resource "aws_iam_role_policy" "codebuild_s3_policy" {
  name = "codebuild-s3-policy"
  role = aws_iam_role.codebuild_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:GetBucketLocation"
        ]
        Effect   = "Allow"
        Resource = [
          aws_s3_bucket.build_output.arn,
          "${aws_s3_bucket.build_output.arn}/*"
        ]
      },
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

