provider "aws" {
  region = "us-east-1"
}

# VPC and Networking
resource "aws_vpc" "msk_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = "msk-vpc"
  }
}

# Create 3 subnets in 3 different AZs for high availability
data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_subnet" "msk_subnet" {
  count             = 3
  vpc_id            = aws_vpc.msk_vpc.id
  cidr_block        = "10.0.${count.index}.0/24"
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "msk-subnet-${count.index}"
  }
}

# Security Group for MSK Brokers
resource "aws_security_group" "msk_sg" {
  name        = "msk-cluster-sg"
  description = "Allow Kafka traffic"
  vpc_id      = aws_vpc.msk_vpc.id

  # TLS Port
  ingress {
    from_port   = 9094
    to_port     = 9094
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/16"] # Restrict to VPC CIDR
  }

  # ZooKeeper Port (if using non-IAM auth)
  ingress {
    from_port   = 2181
    to_port     = 2181
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/16"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "msk-security-group"
  }
}

# MSK Cluster Configuration
resource "aws_msk_configuration" "msk_config" {
  kafka_versions = ["3.6.0"]
  server_properties = <<PROPERTIES
auto.create.topics.enable = false
delete.topic.enable = true
PROPERTIES
}

# MSK Cluster
resource "aws_msk_cluster" "msk_cluster" {
  cluster_name           = "managed-kafka-cluster"
  kafka_version          = "3.6.0"
  configuration_info {
    arn = aws_msk_configuration.msk_config.arn
  }

  number_of_broker_nodes = 3

  broker_node_group_info {
    instance_type   = "kafka.m5.large"
    client_subnets  = aws_subnet.msk_subnet[*].id
    security_groups = [aws_security_group.msk_sg.id]
    storage_info {
      ebs_storage_volume_size = 100
    }
  }

  encryption_info {
    encryption_in_transit {
      client_broker = "TLS"
      in_cluster    = true
    }
  }

  tags = {
    Environment = "Production"
    ManagedBy   = "Terraform"
  }
}

