# Variables to avoid hardcoding and ensure reusability
variable "vpc_id" {
  type        = string
  description = "The ID of the VPC to associate with the Route 53 Resolver rule"
}

variable "domain_name" {
  type        = string
  description = "The domain name for the resolver rule"
  default     = "internal.example.com"
}

variable "target_ip_addresses" {
  type        = list(string)
  description = "The IP addresses of the DNS servers to forward requests to"
  default     = ["10.0.0.10", "10.0.0.11"]
}

# Create a Route 53 Resolver Rule (Forwarding rule)
# This defines how DNS queries for a specific domain should be handled
resource "aws_route53_resolver_rule" "forwarding_rule" {
  domain_name = var.domain_name
  rule_type   = "forward"

  target_ip {
    ip = var.target_ip_addresses[0]
  }

  target_ip {
    ip = var.target_ip_addresses[1]
  }
}

# The Route 53 Resolver Rule Association resource
# This associates the defined rule with a specific VPC
resource "aws_route53_resolver_rule_association" "vpc_association" {
  resolver_rule_id = aws_route53_resolver_rule.forwarding_rule.id
  vpc_id           = var.vpc_id
}

