model_answers:
provider "aws" {
  region = "us-east-1"
}

resource "aws_kms_key" "firehose" {
  description             = "KMS key for Firehose and OpenSearch Serverless"
  deletion_window_in_days = 7
  enable_key_rotation     = true
}

resource "aws_s3_bucket" "backup" {
  bucket_prefix = "firehose-opensearch-backup-"
}

resource "aws_s3_bucket_ownership_controls" "backup" {
  bucket = aws_s3_bucket.backup.id
  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_public_access_block" "backup" {
  bucket = aws_s3_bucket.backup.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "backup" {
  bucket = aws_s3_bucket.backup.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.firehose.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_cloudwatch_log_group" "firehose" {
  name              = "/aws/kinesisfirehose/opensearch-serverless"
  retention_in_days = 7
}

resource "aws_opensearchserverless_security_policy" "encryption" {
  name = "firehose-encryption"
  type = "encryption"
  policy = jsonencode({
    Rules = [{
      ResourceType = "collection"
      Resource      = ["collection/${aws_opensearchserverless_collection.this.name}"]
    }]
    AWSOwnedKey = false
    KMSKeyARN   = aws_kms_key.firehose.arn
  })
}

resource "aws_opensearchserverless_security_policy" "network" {
  name = "firehose-network"
  type = "network"
  policy = jsonencode([{
    Rules = [{
      ResourceType = "collection"
      Resource      = ["collection/${aws_opensearchserverless_collection.this.name}"]
    }]
    AllowFromPublic = true
  }])
}

resource "aws_opensearchserverless_collection" "this" {
  name                 = "firehose-logs"
  type                 = "SEARCH"
  standby_replicas     = "ENABLED"
  depends_on           = [aws_opensearchserverless_security_policy.encryption, aws_opensearchserverless_security_policy.network]
}

resource "aws_opensearchserverless_access_policy" "this" {
  name = "firehose-access"
  type = "data"
  policy = jsonencode([{
    Rules = [
      {
        ResourceType = "collection"
        Resource      = ["collection/${aws_opensearchserverless_collection.this.name}"]
        Permission    = ["aoss:CreateCollectionItems", "aoss:DeleteCollectionItems", "aoss:UpdateCollectionItems", "aoss:DescribeCollectionItems"]
      },
      {
        ResourceType = "index"
        Resource      = ["index/${aws_opensearchserverless_collection.this.name}/*"]
        Permission    = ["aoss:CreateIndex", "aoss:DeleteIndex", "aoss:UpdateIndex", "aoss:DescribeIndex", "aoss:ReadDocument", "aoss:WriteDocument"]
      }
    ]
    Principal = [aws_iam_role.firehose.arn]
  }])
}

resource "aws_iam_role" "firehose" {
  name = "firehose-opensearch-serverless-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action    = "sts:AssumeRole"
      Effect    = "Allow"
      Principal = { Service = "firehose.amazonaws.com" }
    }]
  })
}

resource "aws_iam_role_policy" "firehose" {
  name = "firehose-opensearch-serverless-policy"
  role = aws_iam_role.firehose.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["aoss:APIAccessAll"]
        Resource = [aws_opensearchserverless_collection.this.arn, "${aws_opensearchserverless_collection.this.arn}/*"]
      },
      {
        Effect = "Allow"
        Action = [
          "s3:AbortMultipartUpload",
          "s3:GetBucketLocation",
          "s3:GetObject",
          "s3:ListBucket",
          "s3:ListBucketMultipartUploads",
          "s3:PutObject"
        ]
        Resource = [aws_s3_bucket.backup.arn, "${aws_s3_bucket.backup.arn}/*"]
      },
      {
        Effect   = "Allow"
        Action   = ["logs:PutLogEvents"]
        Resource = ["${aws_cloudwatch_log_group.firehose.arn}:*"]
      },
      {
        Effect = "Allow"
        Action = [
          "kms:GenerateDataKey*",
          "kms:Decrypt"
        ]
        Resource = aws_kms_key.firehose.arn
      }
    ]
  })
}

resource "aws_kinesis_firehose_delivery_stream" "this" {
  name        = "opensearch-serverless-stream"
  destination = "opensearchserverless"

  opensearchserverless_configuration {
    role_arn             = aws_iam_role.firehose.arn
    collection_endpoint  = aws_opensearchserverless_collection.this.collection_endpoint
    index_name           = "firehose-logs"
    s3_backup_mode       = "FailedDataOnly"
    buffering_interval   = 60
    buffering_size       = 5

    s3_configuration {
      role_arn             = aws_iam_role.firehose.arn
      bucket_arn           = aws_s3_bucket.backup.arn
      prefix               = "firehose/"
      error_output_prefix  = "errors/!{firehose:error-output-type}/year=!{timestamp:yyyy}/month=!{timestamp:MM}/day=!{timestamp:dd}/"
      buffering_size       = 5
