    name   = "vpc-id"
    values = [data.aws_vpc.default.id]
  }
}

resource "aws_db_subnet_group" "this" {
  name       = "sql-db-subnet-group"
  subnet_ids = data.aws_subnets.default.ids
  tags = {
    Name = "sql-db-subnet-group"
  }
}

resource "aws_security_group" "db" {
  name        = "sql-db-sg"
  description = "Security group for RDS SQL instances"
  vpc_id      = data.aws_vpc.default.id

  ingress {
    description = "SQL access from VPC"
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = [data.aws_vpc.default.cidr_block]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "sql-db-sg"
  }
}

resource "aws_db_instance" "primary" {
  identifier                  = "primary-sql-db"
  engine                       = "mysql"
  engine_version               = "8.0"
  instance_class               = "db.t3.micro"
  allocated_storage            = 20
  max_allocated_storage        = 100
  storage_encrypted            = true
  db_subnet_group_name         = aws_db_subnet_group.this.name
  vpc_security_group_ids       = [aws_security_group.db.id]
  publicly_accessible          = false
  multi_az                     = false
  master_username              = "dbadmin"
  manage_master_user_password  = true
  backup_retention_period      = 7
  skip_final_snapshot          = false
  final_snapshot_identifier    = "primary-sql-final-snapshot"
  deletion_protection          = true

  tags = {
    Name = "primary-sql-db"
  }
}

resource "aws_db_instance" "replica" {
  identifier                  = "replica-sql-db"
  replicate_source_db          = aws_db_instance.primary.identifier
  instance_class               = "db.t3.micro"
  publicly_accessible          = false
  storage_encrypted            = true
  db_subnet_group_name         = aws_db_subnet_group.this.name
  vpc_security_group_ids       = [aws_security_group.db.id]
  skip_final_snapshot          = false
  final_snapshot_identifier    = "replica-sql-final-snapshot"
  deletion_protection          = true
  backup_retention_period      = 0

  tags = {
    Name = "replica-sql-db"
  }
}

