model_answers:
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Provider configurations for each target region
provider "aws" {
  alias  = "us_east_1"
  region = "us-east-1"
}

provider "aws" {
  alias  = "us_west_1"
  region = "us-west-1"
}

provider "aws" {
  alias  = "us_west_2"
  region = "us-west-2"
}

# Map regions to their respective provider aliases for iteration
locals {
  region_providers = {
    "us-east-1"  = aws.us_east_1
    "us-west-1"  = aws.us_west_1
    "us-west-2"  = aws.us_west_2
  }

  table_name = "global-application-data"
}

resource "aws_dynamodb_table" "global_table" {
  # Iterate over the map, creating one table per region with the correct provider
  for_each = local.region_providers

  # Meta-argument to select the aliased provider for this instance
  provider = each.value

  name           = local.table_name
  billing_mode   = "PAY_PER_REQUEST"
  hash_key       = "pk"
  range_key      = "sk"
  deletion_protection_enabled = true

  attribute {
    name = "pk"
    type = "S"
  }

  attribute {
    name = "sk"
    type = "S"
  }

  # Global Secondary Index Example (Optional but common pattern)
  global_secondary_index {
    name            = "gsi-1"
    hash_key        = "gsi1pk"
    range_key       = "gsi1sk"
    projection_type = "ALL"
  }

  attribute {
    name = "gsi1pk"
    type = "S"
  }

  attribute {
    name = "gsi1sk"
    type = "S"
  }

  # Security Best Practice: Encryption at Rest (AWS Owned Key by default, specify KMS key for Customer Managed Key)
  server_side_encryption {
    enabled     = true
    # kms_key_arn = aws_kms_key.dynamodb.arn # Uncomment and define KMS resource for CMK
  }

  # Security Best Practice: Point-in-Time Recovery for backup/restore
  point_in_time_recovery {
    enabled = true
  }

  # Security Best Practice: TTL for automatic cleanup of expired items
  ttl {
    attribute_name = "ttl"
    enabled        = true
  }

  tags = {
    Environment = "production"
    ManagedBy   = "terraform"
    Region      = each.key
  }
}

# Output table ARNs for reference
output "dynamodb_table_arns" {
  description = "Map of region to DynamoDB Table ARN"
  value       = { for k, v in aws_dynamodb_table.global_table : k => v.arn }
}

