model_answers:
# ---------------------------------------------------------
# KMS Key for Encryption (Best Practice: Encrypt at Rest)
# ---------------------------------------------------------
resource "aws_kms_key" "kinesis_analytics" {
  description             = "KMS key for Kinesis Analytics and CloudWatch Logs encryption"
  deletion_window_in_days = 10
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "Allow root account full access"
        Effect    = "Allow"
        Principal = { AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root" }
        Action    = "kms:*"
        Resource  = "*"
      },
      {
        Sid       = "Allow Kinesis Analytics service to use the key"
        Effect    = "Allow"
        Principal = { Service = "kinesisanalytics.amazonaws.com" }
        Action    = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource  = "*"
      },
      {
        Sid       = "Allow CloudWatch Logs to use the key"
        Effect    = "Allow"
        Principal = { Service = "logs.amazonaws.com" }
        Action    = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource  = "*"
        Condition = {
          StringEquals = {
            "kms:EncryptionContext:aws:logs:arn" = "arn:aws:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:/aws/kinesis-analytics/${aws_kinesisanalyticsv2_application.basic.name}:*"
          }
        }
      }
    ]
  })
}

# ---------------------------------------------------------
# CloudWatch Log Group & Stream
# ---------------------------------------------------------
resource "aws_cloudwatch_log_group" "kinesis_analytics" {
  name              = "/aws/kinesis-analytics/${aws_kinesisanalyticsv2_application.basic.name}"
  retention_in_days = 30
  kms_key_id        = aws_kms_key.kinesis_analytics.arn
}

resource "aws_cloudwatch_log_stream" "kinesis_analytics" {
  name           = "application-logs"
  log_group_name = aws_cloudwatch_log_group.kinesis_analytics.name
  # KMS key for log stream is inherited from Log Group
}

# ---------------------------------------------------------
# IAM Role for Kinesis Analytics Service Execution
# ---------------------------------------------------------
resource "aws_iam_role" "kinesis_analytics_exec" {
  name = "${aws_kinesisanalyticsv2_application.basic.name}-exec-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action    = "sts:AssumeRole"
      Effect    = "Allow"
      Principal = { Service = "kinesisanalytics.amazonaws.com" }
    }]
  })

  inline_policy {
    name = "cloudwatch-logs-write"
    policy = jsonencode({
      Version = "2012-10-17"
      Statement = [{
        Effect   = "Allow"
        Action   = ["logs:PutLogEvents", "logs:DescribeLogStreams"]
        Resource = aws_cloudwatch_log_stream.kinesis_analytics.arn
      }]
    })
  }

  inline_policy {
    name = "kms-decrypt-logs"
    policy = jsonencode({
      Version = "2012-10-17"
      Statement = [{
        Effect   = "Allow"
        Action   = ["kms:Decrypt", "kms:GenerateDataKey"]
        Resource = aws_kms_key.kinesis_analytics.arn
      }]
    })
  }
}

# ---------------------------------------------------------
# Source Kinesis Stream (Required for valid Application Input)
# ---------------------------------------------------------
resource "aws_kinesis_stream" "source" {
  name             = "${aws_kinesisanalyticsv2_application.basic.name}-source"
  shard_count      = 1
  retention_period = 24
  encryption_type  = "KMS"
  kms_key_id       = aws_kms_key.kinesis_analytics.arn
}

# ---------------------------------------------------------
# Kinesis Analytics V2 Application (SQL-1_0 for self-contained basic example)
# ---------------------------------------------------------
resource "aws_kinesisanalyticsv2_application" "basic" {
  name                 = "basic-kinesis-analytics-app"
  runtime_environment  = "SQL-1_0"
  service_execution_role = aws_iam_role.kinesis_analytics_exec.arn

  application_configuration {
    sql_application_configuration {
      inputs {
        name_prefix           = "SOURCE_SQL_STREAM"
        input_processing_configuration {
          input_lambda_processor {
            resource_arn = "" # Optional: Lambda processor ARN
          }
        }
        kinesis_streams_input {
          resource_arn = aws_kinesis_stream.source.arn
        }
        input_schema {
          record_format {
            mapping_parameters {
              json_mapping_parameters {
                record_row_path = "$"
              }
            }
          }
          record_encoding = "UTF-8"
          record_columns = [
            {
              name        = "event_time",
              mapping     = "$.event_time",
              sql_type    = "TIMESTAMP"
            },
            {
              name        = "payload",
              mapping     = "$.payload",
              sql_type    = "VARCHAR(1024)"
            }
          ]
        }
      }
    }

    application_code_configuration {
      code_content {
        text_content = <<-SQL
          CREATE OR REPLACE STREAM "DESTINATION_SQL_STREAM" (event_time TIMESTAMP, payload VARCHAR(1024));
          CREATE OR REPLACE PUMP "STREAM_PUMP" AS INSERT INTO "DESTINATION_SQL_STREAM"
          SELECT STREAM event_time, payload FROM "SOURCE_SQL_STREAM_001";
        SQL
      }
      code_content_type = "PLAINTEXT"
    }

    environment_properties {
      property_groups = [{
        property_group_id = "ApplicationProperties"
        property_map = {
          "log.level" = "INFO"
        }
      }]
    }
  }

  cloudwatch_logging_options {
    log_stream_arn = aws_cloudwatch_log_stream.kinesis_analytics.arn
  }

  # Required for SQL apps to define output/error handling minimally
  application_snapshot_configuration {
    snapshots_enabled = false
  }
}

