model_answers:
variable "efs_tags" {
  description = "A map of tags to assign to the EFS file system."
  type        = map(string)
  default     = {}
}

variable "performance_mode" {
  description = "The performance mode of the file system. Valid values: 'generalPurpose', 'maxIO'."
  type        = string
  default     = "generalPurpose"
  validation {
    condition     = contains(["generalPurpose", "maxIO"], var.performance_mode)
    error_message = "Performance mode must be 'generalPurpose' or 'maxIO'."
  }
}

variable "throughput_mode" {
  description = "The throughput mode of the file system. Valid values: 'bursting', 'provisioned', 'elastic'."
  type        = string
  default     = "bursting"
  validation {
    condition     = contains(["bursting", "provisioned", "elastic"], var.throughput_mode)
    error_message = "Throughput mode must be 'bursting', 'provisioned', or 'elastic'."
  }
}

variable "provisioned_throughput_in_mibps" {
  description = "The provisioned throughput in MiB/s (required if throughput_mode is 'provisioned')."
  type        = number
  default     = null
  validation {
    condition     = var.throughput_mode != "provisioned" || (var.provisioned_throughput_in_mibps != null && var.provisioned_throughput_in_mibps >= 1)
    error_message = "Provisioned throughput must be at least 1 MiB/s when throughput_mode is 'provisioned'."
  }
}

variable "kms_key_id" {
  description = "The ARN of the KMS key to use for encryption at rest. If omitted, the AWS managed key for EFS is used."
  type        = string
  default     = null
}

variable "lifecycle_transition_days" {
  description = "Number of days after which to move files to Infrequent Access (IA) storage. Set to null to disable."
  type        = number
  default     = 30
}

