  throughput_mode  = var.throughput_mode

  provisioned_throughput_in_mibps = var.throughput_mode == "provisioned" ? var.provisioned_throughput_in_mibps : null

  lifecycle_policy {
    transition_to_ia = var.lifecycle_transition_days != null ? "AFTER_${var.lifecycle_transition_days}_DAYS" : "NONE"
  }

  backup_policy {
    status = "ENABLED"
  }

  tags = merge({
    "Name"        = "efs-${random_id.efs_token.hex}"
    "ManagedBy"   = "Terraform"
    "Environment" = "production"
  }, var.efs_tags)
}

