      }
    ]
  }

  checksum = filebase64sha256("${path.module}/bot_checksum.json")
}

resource "aws_lex_intent" "order_pizza" {
  name               = "OrderPizza"
  description        = "Intent to order a customized pizza"
  fulfillment_activity {
    type = "ReturnIntent"
  }

  sample_utterances = [
    "I want to order a pizza",
    "Can I get a {Crust} crust pizza with {Toppings}?",
    "I'd like a {Size} pizza please",
    "Order a pizza for me"
  ]

  slots = [
    {
      name             = "Size"
      description      = "Size of the pizza"
      slot_constraint  = "Required"
      slot_type        = "AMAZON.Number"
      slot_type_version = "$LATEST"
      value_elicitation_prompt {
        max_attempts = 2
        messages = [
          {
            content_type = "PlainText"
            content      = "What size pizza would you like? Small, medium, or large?"
          }
        ]
      }
      priority = 1
    },
    {
      name             = "Crust"
      description      = "Type of crust"
      slot_constraint  = "Required"
      slot_type        = "PizzaCrustType"
      slot_type_version = "$LATEST"
      value_elicitation_prompt {
        max_attempts = 2
        messages = [
          {
            content_type = "PlainText"
            content      = "What type of crust would you prefer? Thin, thick, or stuffed?"
          }
        ]
      }
      priority = 2
    },
    {
      name             = "Toppings"
      description      = "Pizza toppings"
      slot_constraint  = "Required"
      slot_type        = "PizzaToppings"
      slot_type_version = "$LATEST"
      value_elicitation_prompt {
        max_attempts = 3
        messages = [
          {
            content_type = "PlainText"
            content      = "What toppings would you like on your pizza?"
          },
          {
            content_type = "PlainText"
            content      = "Any specific toppings you'd like to add?"
          }
        ]
      }
      priority = 3
    },
    {
      name             = "Quantity"
      description      = "Number of pizzas"
      slot_constraint  = "Optional"
      slot_type        = "AMAZON.Number"
      slot_type_version = "$LATEST"
      value_elicitation_prompt {
        max_attempts = 1
        messages = [
          {
            content_type = "PlainText"
            content      = "How many pizzas would you like to order?"
          }
        ]
      }
      priority = 4
      default_value_spec {
        default_value_list = [{ default_value = "1" }]
      }
    }
  ]

  confirmation_prompt {
    max_attempts = 2
    messages = [
      {
        content_type = "PlainText"
        content      = "So you want a {Quantity} {Size} inch {Crust} crust pizza with {Toppings}. Is that correct?"
      }
    ]
  }

  rejection_statement {
    messages = [
      {
        content_type = "PlainText"
        content      = "Okay, let's start over. What would you like to order?"
      }
    ]
  }

  conclusion_statement {
    messages = [
      {
        content_type = "PlainText"
        content      = "Perfect! Your {Quantity} {Size} inch {Crust} crust pizza with {Toppings} has been ordered. It will be ready for pickup in 20 minutes. Thank you for choosing our pizzeria!"
      },
      {
        content_type = "PlainText"
        content      = "Great! Your order for {Quantity} {Size} inch {Crust} crust pizza with {Toppings} is confirmed. Expected ready time: 20 minutes. Enjoy your meal!"
      }
    ]
    response_card = "Your pizza order has been placed successfully!"
  }

  follow_up_prompt {
    prompt {
      max_attempts = 1
      messages = [
        {
          content_type = "PlainText"
          content      = "Would you like to order anything else today?"
        }
      ]
    }
    rejection_statement {
      messages = [
        {
          content_type = "PlainText"
          content      = "No problem! Your order is confirmed. Have a great day!"
        }
      ]
    }
  }
}

