model_answers:
terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS Region to deploy resources."
  type        = string
  default     = "us-east-1"
}

variable "instance_name" {
  description = "Name for the Lightsail instance."
  type        = string
  default     = "wp-lightsail-instance"
}

variable "availability_zone" {
  description = "Availability Zone for the instance."
  type        = string
  default     = "us-east-1a"
}

variable "bundle_id" {
  description = "Bundle ID (instance size). e.g., nano_2_0, micro_2_0, small_2_0, medium_2_0"
  type        = string
  default     = "small_2_0"
}

variable "blueprint_id" {
  description = "Blueprint ID for WordPress."
  type        = string
  default     = "wordpress"
}

variable "key_pair_name" {
  description = "Name of the Lightsail Key Pair to associate with the instance for SSH access. Must be created separately or imported."
  type        = string
  validation {
    condition     = length(var.key_pair_name) > 0
    error_message = "Key pair name must be provided for secure SSH access."
  }
}

variable "allowed_ssh_cidrs" {
  description = "List of CIDR blocks allowed to access SSH (port 22). Restrict this to your IP for security."
  type        = list(string)
  default     = ["10.0.0.0/8"] # Example restrictive default, CHANGE THIS
}

variable "allowed_http_cidrs" {
  description = "List of CIDR blocks allowed to access HTTP (port 80)."
  type        = list(string)
  default     = ["0.0.0.0/0"]
}

variable "allowed_https_cidrs" {
  description = "List of CIDR blocks allowed to access HTTPS (port 443)."
  type        = list(string)
  default     = ["0.0.0.0/0"]
}

variable "tags" {
  description = "Map of tags to apply to all resources."
  type        = map(string)
  default     = {
    Environment = "production"
    ManagedBy   = "terraform"
    Application = "wordpress"
  }
}

resource "aws_lightsail_key_pair" "wp_key" {
  # This resource manages the key pair *in* Lightsail.
  # If you have an existing key pair name in var.key_pair_name, you can remove this resource
  # and use the name directly in the instance resource.
  # Best practice: Generate locally and import public key, or let AWS generate and save private key securely.
  key_pair_name = "${var.instance_name}-keypair"
  # public_key    = file("~/.ssh/id_rsa.pub") # Uncomment to import your own public key
}

resource "aws_lightsail_instance" "wp" {
  name              = var.instance_name
  availability_zone = var.availability_zone
  blueprint_id      = var.blueprint_id
  bundle_id         = var.bundle_id
  key_pair_name     = aws_lightsail_key_pair.wp.key_pair_name # Use managed key pair

  # Security Best Practice: Disable source/destination check not applicable to Lightsail directly,
  # but we control ports via aws_lightsail_instance_public_ports.

  # User data for additional hardening or configuration (optional)
  # WordPress blueprint auto-configures on first boot.
  user_data = <<-EOF
    #!/bin/bash
    # Example: Update packages on first boot
    apt-get update && apt-get upgrade -y
    # Ensure WordPress permissions are correct (blueprint usually handles this)
    # chown -R bitnami:daemon /opt/bitnami/wordpress
    # find /opt/bitnami/wordpress -type d -exec chmod 775 {} \;
    # find /opt/bitnami/wordpress -type f -exec chmod 664 {} \;
  EOF

  tags = var.tags
}

# Security Best Practice: Explicitly define allowed public ports (Firewall)
# By default, Lightsail opens 22, 80, 443. We restrict SSH to specific IPs.
resource "aws_lightsail_instance_public_ports" "wp_ports" {
  instance_name = aws_lightsail_instance.wp.name

  port_info {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidrs       = var.allowed_ssh_cidrs
    ipv6_cidrs  = [] # Add IPv6 ranges if needed
  }

  port_info {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidrs       = var.allowed_http_cidrs
    ipv6_cidrs  = ["::/0"]
  }

  port_info {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidrs       = var.allowed_https_cidrs
    ipv6_cidrs  = ["::/0"]
  }
}

# Security Best Practice: Enable Automatic Snapshots (Backups)
resource "aws_lightsail_instance_add_on" "auto_snapshot" {
  instance_name = aws_lightsail_instance.wp.name
  add_on_type   = "AutoSnapshot"

  auto_snapshot_add_on_request {
    snapshot_time_of_day = "03:00" # UTC time for daily snapshot
  }
}

# Outputs
output "instance_public_ip" {
  description = "Public IP address of the WordPress instance."
  value       = aws_lightsail_instance.wp.public_ip_address
}

output "instance_private_ip" {
  description = "Private IP address of the WordPress instance."
  value       = aws_lightsail_instance.wp.private_ip_address
}

output "ssh_command" {
  description = "SSH command to connect to the instance (using the generated private key)."
  value       = "ssh -i ${aws_lightsail_key_pair.wp.key_pair_name}.pem bitnami@${aws_lightsail_instance.wp.public_ip_address}"
  sensitive   = true
}

output "wordpress_admin_url" {
  description = "URL to access WordPress admin panel (credentials retrieved via console/logs)."
  value       = "http://${aws_lightsail_instance.wp.public_ip_address}/wp-admin"
}

output "key_pair_private_key" {
  description = "Private key for SSH access. SAVE THIS SECURELY. It is only available on creation."
