model_answers:
resource "aws_kms_key" "s3_bucket_key" {
  description             = "KMS key for S3 bucket encryption"
  deletion_window_in_days = 10
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "key-default-1"
    Statement = [
      {
        Sid       = "Allow administration of the key"
        Effect    = "Allow"
        Principal = { AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root" }
        Action    = ["kms:*"]
        Resource  = "*"
      },
      {
        Sid       = "Allow S3 service to use the key for bucket encryption"
        Effect    = "Allow"
        Principal = { Service = "s3.amazonaws.com" }
        Action    = [
          "kms:GenerateDataKey",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:DescribeKey"
        ]
        Resource  = "*"
        Condition = {
          StringEquals = {
            "kms:EncryptionContext:aws:s3:arn" = "arn:aws:s3:::${aws_s3_bucket.secure_bucket.bucket}"
          }
          StringLike = {
            "kms:EncryptionContext:aws:s3:arn" = "arn:aws:s3:::${aws_s3_bucket.secure_bucket.bucket}/*"
          }
        }
      }
    ]
  })
}

resource "aws_kms_alias" "s3_bucket_key_alias" {
  name          = "alias/s3-bucket-encryption-key"
  target_key_id = aws_kms_key.s3_bucket_key.key_id
}

resource "aws_s3_bucket" "secure_bucket" {
  bucket = "my-secure-encrypted-bucket-${data.aws_caller_identity.current.account_id}-${data.aws_region.current.name}"

  # Prevent accidental deletion
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "secure_bucket_versioning" {
  bucket = aws_s3_bucket.secure_bucket.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "secure_bucket_public_access" {
  bucket = aws_s3_bucket.secure_bucket.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "secure_bucket_encryption" {
  bucket = aws_s3_bucket.secure_bucket.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.s3_bucket_key.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true # Reduces KMS request costs
  }
}

resource "aws_s3_bucket_policy" "secure_bucket_policy" {
  bucket = aws_s3_bucket.secure_bucket.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyInsecureConnections"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource  = [
          aws_s3_bucket.secure_bucket.arn,
          "${aws_s3_bucket.secure_bucket.arn}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      },
      {
        Sid       = "DenyUnencryptedObjectUploads"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:PutObject"
        Resource  = "${aws_s3_bucket.secure_bucket.arn}/*"
        Condition = {
          StringNotEquals = {
            "s3:x-amz-server-side-encryption" = "aws:kms"
          }
        }
      },
      {
        Sid       = "DenyIncorrectKMSKey"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:PutObject"
        Resource  = "${aws_s3_bucket.secure_bucket.arn}/*"
        Condition = {
          StringNotEquals = {
            "s3:x-amz-server-side-encryption-aws-kms-key-id" = aws_kms_key.s3_bucket_key.arn
          }
        }
      }
    ]
  })
}

data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

provider "aws" {
  default_tags {
    tags = {
      Environment = var.environment
      ManagedBy   = "Terraform"
      Owner       = var.owner
    }
  }
}

variable "environment" {
  description = "Environment name (e.g., prod, staging, dev)"
  type        = string
  default     = "prod"
}

variable "owner" {
  description = "Team or individual responsible for the resource"
  type        = string
  default     = "platform-team"
}

variable "vpc_id" {
  description = "VPC ID where the Redis cluster will be deployed"
  type        = string
}

variable "private_subnet_ids" {
  description = "List of private subnet IDs for the Redis subnet group (minimum 2 for Multi-AZ)"
  type        = list(string)
  validation {
    condition     = length(var.private_subnet_ids) >= 2
    error_message = "At least 2 private subnets are required for Multi-AZ deployment."
  }
}

variable "allowed_security_group_ids" {
  description = "List of Security Group IDs allowed to connect to Redis (e.g., App Server SGs)"
  type        = list(string)
  default     = []
}

variable "engine_version" {
  description = "Redis engine version"
  type        = string
  default     = "7.2"
}

variable "node_type" {
  description = "Redis node instance type"
  type        = string
  default     = "cache.r7g.large"
}

variable "num_cache_clusters" {
  description = "Number of node groups (shards). For cluster mode disabled, this is replica count + 1."
  type        = number
  default     = 2
}

variable "automatic_failover_enabled" {
  description = "Enable Multi-AZ with automatic failover"
  type        = bool
  default     = true
}

variable "multi_az_enabled" {
  description = "Enable Multi-AZ (required for automatic failover)"
  type        = bool
  default     = true
}

variable "backup_retention_limit" {
  description = "Number of days to retain backups"
  type        = number
  default     = 14
}

variable "preferred_maintenance_window" {
  description = "Weekly maintenance window (UTC)"
  type        = string
  default     = "sun:03:00-sun:05:00"
}

variable "snapshot_window" {
  description = "Daily snapshot window (UTC)"
  type        = string
  default     = "02:00-04:00"
}

variable "parameter_group_family" {
  description = "Parameter group family matching engine version"
  type        = string
  default     = "redis7"
}

variable "auth_token_secret_arn" {
  description = "ARN of existing Secrets Manager secret containing the auth token. If null, a new secret is generated."
  type        = string
  default     = null
}

variable "kms_key_id" {
  description = "KMS Key ID for encryption at rest. If null, AWS managed key (aws/elasticache) is used."
  type        = string
  default     = null
}

variable "deletion_protection" {
  description = "Enable deletion protection"
  type        = bool
  default     = true
}

# --- Random Password Generation (Fallback if no secret ARN provided) ---
resource "random_password" "redis_auth" {
  length  = 32
  special = false
  override_special = "_"
  keepers = {
    # Regenerate only if engine version changes significantly or forced
    engine_version = var.engine_version
  }
}

# --- Secrets Manager for Auth Token ---
resource "aws_secretsmanager_secret" "redis_auth" {
  count = var.auth_token_secret_arn == null ? 1 : 0
  name  = "/${var.environment}/redis/${random_id.suffix.hex}/auth-token"
  description = "Redis AUTH token for ${var.environment} environment"
  kms_key_id  = var.kms_key_id
  tags = {
    Name = "${var.environment}-redis-auth-token"
  }
}

resource "aws_secretsmanager_secret_version" "redis_auth" {
  count = var.auth_token_secret_arn == null ? 1 : 0
  secret_id     = aws_secretsmanager_secret.redis_auth[0].id
  secret_string = random_password.redis_auth.result
}

data "aws_secretsmanager_secret_version" "existing_auth" {
  count = var.auth_token_secret_arn != null ? 1 : 0
  secret_id = var.auth_token_secret_arn
}

locals {
  auth_token = var.auth_token_secret_arn != null ? data.aws_secretsmanager_secret_version.existing_auth[0].secret_string : random_password.redis_auth.result
  auth_token_secret_arn = var.auth_token_secret_arn != null ? var.auth_token_secret_arn : aws_secretsmanager_secret.redis_auth[0].arn
}

# --- Random Suffix for unique naming ---
resource "random_id" "suffix" {
  byte_length = 4
}

# --- KMS Key (Optional Customer Managed Key) ---
resource "aws_kms_key" "redis" {
  count = var.kms_key_id == null ? 1 : 0
  description             = "KMS Key for ElastiCache Redis (${var.environment})"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowRootAccess"
        Effect    = "Allow"
        Principal = { AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root" }
        Action    = "kms:*"
        Resource  = "*"
      },
      {
        Sid       = "AllowElastiCacheService"
        Effect    = "Allow"
        Principal = { Service = "elasticache.amazonaws.com" }
        Action    = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource  = "*"
        Condition = {
          StringEquals = {
            "kms:ViaService" = "elasticache.${data.aws_region.current.name}.amazonaws.com"
          }
        }
      }
    ]
  })
}

data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

locals {
  kms_key_id = var.kms_key_id != null ? var.kms_key_id : aws_kms_key.redis[0].arn
}

# --- ElastiCache Subnet Group ---
resource "aws_elasticache_subnet_group" "redis" {
  name       = "${var.environment}-redis-subnet-group"
  subnet_ids = var.private_subnet_ids
}

# --- ElastiCache Parameter Group ---
resource "aws_elasticache_parameter_group" "redis" {
  name        = "${var.environment}-redis-params"
  family      = var.parameter_group_family
  description = "Custom Redis parameters for ${var.environment}"

  parameter {
    name  = "timeout"
    value = "300" # Close idle connections after 300s
  }

  parameter {
    name  = "maxmemory-policy"
    value = "allkeys-lru" # Eviction policy
  }

  parameter {
    name  = "slowlog-log-slower-than"
    value = "10000" # Log queries > 10ms
  }

  parameter {
    name  = "slowlog-max-len"
    value = "128"
  }

  # TLS/SSL Configuration (Enforced by transit_encryption_enabled = true on replication group)
  # Note: redis7 requires 'tls-port' parameter if non-standard, but standard is 6379.
}

# --- Security Group ---
resource "aws_security_group" "redis" {
  name        = "${var.environment}-redis-sg"
  description = "Security Group for ElastiCache Redis"
  vpc_id      = var.vpc_id

  ingress {
    description     = "Redis TLS from allowed SGs"
    from_port       = 6379
    to_port         = 6379
    protocol        = "tcp"
    security_groups = var.allowed_security_group_ids
  }

  # Allow self-referencing for replication traffic if needed (cluster mode)
  ingress {
    description     = "Redis Cluster Bus / Replication"
    from_port       = 16379
    to_port         = 16379
    protocol        = "tcp"
    self            = true
  }

  egress {
    description = "Allow all outbound (required for KMS/SecretsManager if VPC endpoints not used)"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  lifecycle {
    create_before_destroy = true
  }
}

# --- ElastiCache Replication Group (Primary Resource) ---
resource "aws_elasticache_replication_group" "redis" {
  replication_group_id          = "${var.environment}-redis"
  replication_group_description = "Redis Replication Group for ${var.environment}"

  engine               = "redis"
  engine_version       = var.engine_version
  node_type            = var.node_type
  port                 = 6379
  parameter_group_name = aws_elasticache_parameter_group.redis.name

  # Network & Security
  subnet_group_name  = aws_elasticache_subnet_group.redis.name
  security_group_ids = [aws_security_group.redis.id]

  # High Availability
  automatic_failover_enabled = var.automatic_failover_enabled
  multi_az_enabled           = var.multi_az_enabled
  num_cache_clusters         = var.num_cache_clusters # Primary + Replicas

  # Encryption
  at_rest_encryption_enabled = true
  kms_key_id                 = local.kms_key_id
  transit_encryption_enabled = true
  auth_token                 = local.auth_token

  # Backups & Maintenance
  snapshot_retention_limit = var.backup_retention_limit
  snapshot_window          = var.snapshot_window
  preferred_maintenance_window = var.preferred_maintenance_window

  # Operational
  deletion_protection = var.deletion_protection

  # Log Delivery (CloudWatch Logs)
  log_delivery_configuration {
    destination_type = "cloudwatch-logs"
    log_format       = "json"
    log_type         = "slow-log"
    destination_details {
      cloudwatch_logs {
        log_group = aws_cloudwatch_log_group.redis_slow.name
      }
    }
  }

  log_delivery_configuration {
    destination_type = "cloudwatch-logs"
    log_format       = "json"
    log_type         = "engine-log"
    destination_details {
      cloudwatch_logs {
        log_group = aws_cloudwatch_log_group.redis_engine.name
      }
    }
  }

  lifecycle {
    ignore_changes = [
      auth_token, # Managed via Secrets Manager rotation externally or manual apply
    ]
  }
}

# --- CloudWatch Log Groups ---
resource "aws_cloudwatch_log_group" "redis_slow" {
  name              = "/aws/elasticache/${var.environment}/redis/slowlog"
  retention_in_days = 30
  kms_key_id        = local.kms_key_id
}

resource "aws_cloudwatch_log_group" "redis_engine" {
  name              = "/aws/elasticache/${var.environment}/redis/engine"
  retention_in_days = 30
  kms_key_id        = local.kms_key_id
}

# --- Outputs ---
output "redis_primary_endpoint" {
  description = "Primary endpoint for read/write operations"
  value       = aws_elasticache_replication_group.redis.primary_endpoint_address
  sensitive   = false
}

output "redis_reader_endpoint" {
  description = "Reader endpoint for read-only operations (load balances replicas)"
  value       = aws_elasticache_replication_group.redis.reader_endpoint_address
  sensitive   = false
}

output "redis_port" {
  description = "Redis port"
  value       = aws_elasticache_replication_group.redis.port
}

output "redis_auth_token_secret_arn" {
  description = "ARN of the Secrets Manager secret containing the AUTH token"
  value       = local.auth_token_secret_arn
  sensitive   = true
}

output "redis_security_group_id" {
  description = "Security Group ID attached to Redis"
  value       = aws_security_group.redis.id
}

output "redis_replication_group_id" {
  description = "Replication Group ID"
  value       = aws_elasticache_replication_group.redis.replication_group_id
}

