model_answers:
variable "domain_id" {
  type        = string
  description = "The ID of the SageMaker Domain."
}

variable "user_profile_name" {
  type        = string
  description = "The name of the User Profile to attach the app to."
}

variable "vpc_subnet_ids" {
  type        = list(string)
  description = "List of private subnet IDs for the SageMaker App VPC configuration."
}

variable "security_group_ids" {
  type        = list(string)
  description = "List of Security Group IDs allowing necessary egress (e.g., S3, ECR, CloudWatch) and no ingress from 0.0.0.0/0."
}

variable "kms_key_id" {
  type        = string
  description = "ARN of the KMS Key for encrypting the EBS volume attached to the app instance."
}

variable "instance_type" {
  type        = string
  default     = "ml.t3.medium"
  description = "Instance type for the JupyterServer. Choose based on workload requirements."
}

variable "sagemaker_image_arn" {
  type        = string
  description = "ARN of the SageMaker Image (e.g., AWS provided JupyterServer image or custom hardened image)."
}

variable "sagemaker_image_version_arn" {
  type        = string
  description = "ARN of the specific SageMaker Image Version to ensure immutability."
}

variable "lifecycle_config_arn" {
  type        = string
  default     = null
  description = "ARN of a Studio Lifecycle Configuration for security hardening (e.g., disabling terminal, restricting kernels). Optional."
}

resource "aws_sagemaker_app" "jupyter_server" {
  domain_id           = var.domain_id
  user_profile_name   = var.user_profile_name
  app_type            = "JupyterServer"
  app_name            = "default" # JupyterServer app name is typically 'default' per user profile

  resource_spec {
    instance_type                = var.instance_type
    sage_maker_image_arn         = var.sagemaker_image_arn
    sage_maker_image_version_arn = var.sagemaker_image_version_arn
    lifecycle_config_arn         = var.lifecycle_config_arn
  }

  # Security Best Practice: Deploy inside VPC with Private Subnets
  space_name = null # Explicitly null as we use user_profile_name

  # Security Best Practice: Encrypt storage volume with Customer Managed KMS Key
  # Note: KMS Key policy must allow SageMaker service principal and the execution role to use it.
  # This is configured via the Domain or UserProfile settings usually, but can be overridden here if supported by API.
  # As of current provider versions, KMS key for App storage is typically inherited from Domain/UserProfile defaults.
  # Explicit volume_kms_key_id is not a direct argument on aws_sagemaker_app resource in provider v5+, 
  # it is configured at Domain/UserProfile level. 
  # We ensure the Domain/UserProfile was created with `kms_key_id`.

  # Security Best Practice: Network Isolation
  # VPC config is inherited from Domain/UserProfile. 
  # If Domain/UserProfile has VPC config, this app uses it. 
  # If not, you cannot attach VPC config directly to this specific App resource via Terraform AWS Provider currently.
  # Ensure the referenced Domain/UserProfile has `vpc_id`, `subnet_ids`, `security_group_ids` set.

  tags = {
    Name        = "jupyter-server-${var.user_profile_name}"
    Environment = "production"
    ManagedBy   = "terraform"
    Security    = "high"
  }

  # Security Best Practice: Explicitly depend on User Profile to ensure VPC/KMS settings are propagated
  # depends_on = [aws_sagemaker_user_profile.example] # Uncomment and reference if defining User Profile in same config
}

