model_answers:
provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  type    = string
  default = "us-east-1"
}

variable "cluster_identifier" {
  type    = string
  default = "example-redshift-cluster"
}

variable "master_username" {
  type    = string
  default = "adminuser"
}

variable "master_password" {
  type      = string
  sensitive = true
  default   = "ChangeMe123!"
}

variable "database_name" {
  type    = string
  default = "dev"
}

variable "node_type" {
  type    = string
  default = "dc2.large"
}

variable "number_of_nodes" {
  type    = number
  default = 2
}

variable "allowed_cidr_blocks" {
  type    = list(string)
  default = ["10.0.0.0/8"]
}

# VPC and Networking
resource "aws_vpc" "redshift_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = "redshift-vpc"
  }
}

resource "aws_subnet" "redshift_subnet_a" {
  vpc_id                  = aws_vpc.redshift_vpc.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = "${var.aws_region}a"
  map_public_ip_on_launch = false

  tags = {
    Name = "redshift-subnet-a"
  }
}

resource "aws_subnet" "redshift_subnet_b" {
  vpc_id                  = aws_vpc.redshift_vpc.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = "${var.aws_region}b"
  map_public_ip_on_launch = false

  tags = {
    Name = "redshift-subnet-b"
  }
}

resource "aws_security_group" "redshift_sg" {
  name        = "redshift-cluster-sg"
  description = "Security group for Redshift cluster"
  vpc_id      = aws_vpc.redshift_vpc.id

  ingress {
    from_port   = 5439
    to_port     = 5439
    protocol    = "tcp"
    cidr_blocks = var.allowed_cidr_blocks
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "redshift-cluster-sg"
  }
}

resource "aws_redshift_subnet_group" "redshift_subnet_group" {
  name       = "redshift-subnet-group"
  subnet_ids = [aws_subnet.redshift_subnet_a.id, aws_subnet.redshift_subnet_b.id]

  tags = {
    Name = "redshift-subnet-group"
  }
}

# KMS Key for Encryption
resource "aws_kms_key" "redshift_kms_key" {
  description             = "KMS key for Redshift cluster encryption"
  deletion_window_in_days = 10
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Allow root access"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow Redshift service"
        Effect = "Allow"
        Principal = {
          Service = "redshift.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
}

data "aws_caller_identity" "current" {}

# IAM Role for Redshift (if needed for S3, etc.)
resource "aws_iam_role" "redshift_role" {
  name = "redshift-cluster-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "redshift.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "redshift_s3_readonly" {
  role       = aws_iam_role.redshift_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonS3ReadOnlyAccess"
}

# Redshift Parameter Group
resource "aws_redshift_parameter_group" "example" {
  name        = "example-redshift-pg"
  family      = "redshift-1.0"
  description = "Example Redshift parameter group"

  parameter {
    name         = "enable_user_activity_logging"
    value        = "true"
    apply_method = "immediate"
  }

  parameter {
    name         = "require_ssl"
    value        = "true"
    apply_method = "immediate"
  }

  tags = {
    Name = "example-redshift-pg"
  }
}

# SNS Topic for Event Notifications
resource "aws_sns_topic" "redshift_events" {
  name = "redshift-event-notifications"

  tags = {
    Name = "redshift-event-notifications"
  }
}

resource "aws_sns_topic_policy" "redshift_events_policy" {
  arn    = aws_sns_topic.redshift_events.arn
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Allow Redshift to publish"
        Effect = "Allow"
        Principal = {
          Service = "redshift.amazonaws.com"
        }
        Action   = "SNS:Publish"
        Resource = aws_sns_topic.redshift_events.arn
      }
    ]
  })
}

# Redshift Cluster
resource "aws_redshift_cluster" "example" {
  cluster_identifier      = var.cluster_identifier
  database_name           = var.database_name
  master_username         = var.master_username
  master_password         = var.master_password
  node_type               = var.node_type
  number_of_nodes         = var.number_of_nodes
  cluster_subnet_group_name = aws_redshift_subnet_group.redshift_subnet_group.name
  vpc_security_group_ids  = [aws_security_group.redshift_sg.id]
  parameter_group_name    = aws_redshift_parameter_group.example.name
  iam_roles               = [aws_iam_role.redshift_role.arn]
  encrypted               = true
  kms_key_id              = aws_kms_key.redshift_kms_key.arn
  publicly_accessible     = false
  skip_final_snapshot     = true
  automated_snapshot_retention_period = 7

  tags = {
    Name = "example-redshift-cluster"
  }
}

# Redshift Event Subscription for Parameter Group
resource "aws_redshift_event_subscription" "parameter_group_events" {
  name                 = "redshift-parameter-group-events"
  sns_topic_arn        = aws_sns_topic.redshift_events.arn
  source_type          = "parameter-group"
  source_ids           = [aws_redshift_parameter_group.example.name]
  event_categories     = ["configuration-change"]
  severity             = "INFO"
  enabled              = true

  tags = {
    Name = "redshift-parameter-group-events"
  }
}

# Outputs
output "redshift_cluster_endpoint" {
  value     = aws_redshift_cluster.example.endpoint
  sensitive = false
}

output "redshift_parameter_group_name" {
  value = aws_redshift_parameter_group.example.name
}

output "sns_topic_arn" {
  value = aws_sns_topic.redshift_events.arn
}

