model_answers:
variable "name" {
  description = "Prefix name for all resources"
  type        = string
}

variable "region" {
  description = "AWS Region"
  type        = string
  default     = "us-east-1"
}

variable "vpc_id" {
  description = "VPC ID for private Firehose delivery and OpenSearch Serverless VPC Endpoint"
  type        = string
}

variable "subnet_ids" {
  description = "Subnet IDs for Firehose ENIs and OpenSearch Serverless VPC Endpoint (must be private subnets)"
  type        = list(string)
}

variable "security_group_ids" {
  description = "Security Group IDs for Firehose ENIs and OpenSearch Serverless VPC Endpoint"
  type        = list(string)
}

variable "opensearch_collection_name" {
  description = "Name of the OpenSearch Serverless Collection"
  type        = string
  default     = "firehose-logs"
}

variable "index_name" {
  description = "OpenSearch index name pattern"
  type        = string
  default     = "firehose-logs-%Y-%m-%d"
}

variable "s3_bucket_name" {
  description = "S3 Bucket name for Firehose backup (must be globally unique). If null, a bucket will be created with a generated name."
  type        = string
  default     = null
}

variable "buffer_size_mb" {
  description = "Buffer size in MB before delivering to destination"
  type        = number
  default     = 128
}

variable "buffer_interval_seconds" {
  description = "Buffer interval in seconds before delivering to destination"
  type        = number
  default     = 300
}

locals {
  tags = {
    Name        = var.name
    Environment = "production"
    ManagedBy   = "Terraform"
  }

  s3_bucket_id = var.s3_bucket_name != null ? var.s3_bucket_name : "${var.name}-firehose-backup-${random_id.suffix.hex}"
}

resource "random_id" "suffix" {
  byte_length = 8
}

# ---------------------------------------------------------
# KMS Key for Encryption (S3, Firehose, OpenSearch Serverless)
# ---------------------------------------------------------
resource "aws_kms_key" "firehose" {
  description             = "KMS Key for ${var.name} Firehose and OpenSearch Serverless"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_key.json
  tags                    = local.tags
}

resource "aws_kms_alias" "firehose" {
  name          = "alias/${var.name}-firehose"
  target_key_id = aws_kms_key.firehose.key_id
}

data "aws_iam_policy_document" "kms_key" {
  statement {
    sid    = "AllowRoot"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowFirehoseRole"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = [aws_iam_role.firehose_delivery.arn]
    }
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "AllowOpenSearchServerless"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["aoss.amazonaws.com"]
    }
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey"
    ]
    resources = ["*"]
    condition {
      test     = "StringEquals"
      variable = "kms:ViaService"
      values   = ["aoss.${var.region}.amazonaws.com"]
    }
  }

  statement {
    sid    = "AllowS3"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey"
    ]
    resources = ["*"]
    condition {
      test     = "StringEquals"
      variable = "kms:ViaService"
      values   = ["s3.${var.region}.amazonaws.com"]
    }
  }
}

data "aws_caller_identity" "current" {}

# ---------------------------------------------------------
# S3 Bucket for Backup (Failed Documents)
# ---------------------------------------------------------
resource "aws_s3_bucket" "firehose_backup" {
  bucket = local.s3_bucket_id
  tags   = local.tags
}

resource "aws_s3_bucket_versioning" "firehose_backup" {
  bucket = aws_s3_bucket.firehose_backup.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "firehose_backup" {
  bucket = aws_s3_bucket.firehose_backup.id
  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.firehose.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "firehose_backup" {
  bucket = aws_s3_bucket.firehose_backup.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_lifecycle_configuration" "firehose_backup" {
  bucket = aws_s3_bucket.firehose_backup.id
  rule {
    id     = "expire-old-versions"
    status = "Enabled"
    noncurrent_version_expiration {
      noncurrent_days = 90
    }
  }
}

# ---------------------------------------------------------
# CloudWatch Log Group for Firehose Delivery Errors
# ---------------------------------------------------------
resource "aws_cloudwatch_log_group" "firehose" {
  name              = "/aws/kinesisfirehose/${var.name}"
  retention_in_days = 30
  kms_key_id        = aws_kms_key.firehose.arn
  tags              = local.tags
}

resource "aws_cloudwatch_log_stream" "firehose_delivery" {
  name           = "delivery-stream"
  log_group_name = aws_cloudwatch_log_group.firehose.name
}

# ---------------------------------------------------------
# IAM Role for Firehose Delivery Stream
# ---------------------------------------------------------
resource "aws_iam_role" "firehose_delivery" {
  name = "${var.name}-firehose-delivery-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action = "sts:AssumeRole"
      Effect = "Allow"
      Principal = {
        Service = "firehose.amazonaws.com"
      }
      Condition = {
        StringEquals = {
          "aws:SourceAccount" = data.aws_caller_identity.current.account_id
        }
        ArnLike = {
          "aws:SourceArn" = "arn:aws:firehose:${var.region}:${data.aws_caller_identity.current.account_id}:deliverystream/${var.name}*"
        }
      }
    }]
  })
  tags = local.tags
}

resource "aws_iam_role_policy" "firehose_delivery" {
  name = "${var.name}-firehose-delivery-policy"
  role = aws_iam_role.firehose_delivery.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "S3BackupAccess"
        Effect = "Allow"
        Action = [
          "s3:AbortMultipartUpload",
          "s3:GetBucketLocation",
          "s3:GetObject",
          "s3:ListBucket",
          "s3:ListBucketMultipartUploads",
          "s3:PutObject"
        ]
        Resource = [
          aws_s3_bucket.firehose_backup.arn,
          "${aws_s3_bucket.firehose_backup.arn}/*"
        ]
      },
      {
        Sid    = "KMSAccess"
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey"
        ]
        Resource = aws_kms_key.firehose.arn
      },
      {
        Sid    = "OpenSearchServerlessAccess"
        Effect = "Allow"
        Action = [
          "aoss:APIAccessAll"
        ]
        Resource = aws_opensearchserverless_collection.main.arn
      },
      {
        Sid    = "CloudWatchLogsAccess"
        Effect = "Allow"
        Action = [
          "logs:PutLogEvents"
        ]
        Resource = [
          "${aws_cloudwatch_log_group.firehose.arn}:log-stream:*"
        ]
      },
      {
        Sid    = "EC2NetworkInterfaceManagement"
        Effect = "Allow"
        Action = [
          "ec2:CreateNetworkInterface",
          "ec2:DeleteNetworkInterface",
          "ec2:DescribeNetworkInterfaces",
          "ec2:DescribeSubnets",
          "ec2:DescribeSecurityGroups",
          "ec2:DescribeVpcs"
        ]
        Resource = "*"
      }
    ]
  })
}

# ---------------------------------------------------------
# OpenSearch Serverless Collection & Policies
# ---------------------------------------------------------
resource "aws_opensearchserverless_collection" "main" {
  name        = var.opensearch_collection_name
  type        = "SEARCH"
  description = "Collection for ${var.name} Firehose Delivery Stream"
  tags        = local.tags
}

resource "aws_opensearchserverless_security_policy" "encryption" {
  name = "${var.name}-encryption-policy"
  type = "encryption"
  policy = jsonencode({
    Rules = [{
      ResourceType = "collection"
      Resource     = ["collection/${var.opensearch_collection_name}"]
    }],
    AWSOwnedKey = false,
    KmsARN      = aws_kms_key.firehose.arn
  })
}

resource "aws_opensearchserverless_vpc_endpoint" "main" {
  name           = "${var.name}-vpc-endpoint"
  vpc_id         = var.vpc_id
  subnet_ids     = var.subnet_ids
  security_group_ids = var.security_group_ids
  tags           = local.tags
}

resource "aws_opensearchserverless_security_policy" "network" {
  name = "${var.name}-network-policy"
  type = "network"
  policy = jsonencode([{
    Rules = [
      {
        ResourceType = "collection"
        Resource     = ["collection/${var.opensearch_collection_name}"]
      },
      {
        ResourceType = "dashboard"
        Resource     = ["collection/${var.opensearch_collection_name}"]
      }
    ],
    AllowFromPublic = false
    SourceVPCEs     = [aws_opensearchserverless_vpc_endpoint.main.id]
  }])
}

resource "aws_opensearchserverless_security_policy" "data_access" {
  name = "${var.name}-data-access-policy"
  type = "data"
  policy = jsonencode([{
    Rules = [
      {
        ResourceType = "collection"
        Resource     = ["collection/${var.opensearch_collection_name}"]
        Permission   = [
          "aoss:CreateCollectionItems",
          "aoss:DeleteCollectionItems",
          "aoss:UpdateCollectionItems",
          "aoss:DescribeCollectionItems"
        ]
      },
      {
        ResourceType = "index"
        Resource     = ["index/${var.opensearch_collection_name}/*"]
        Permission   = [
          "aoss:CreateIndex",
          "aoss:DeleteIndex",
          "aoss:UpdateIndex",
          "aoss:DescribeIndex",
          "aoss:ReadDocument",
          "aoss:WriteDocument"
        ]
      }
    ],
    Principal = [aws_iam_role.firehose_delivery.arn]
  }])
}

# ---------------------------------------------------------
# Kinesis Firehose Delivery Stream
# ---------------------------------------------------------
resource "aws_kinesis_firehose_delivery_stream" "main" {
  name        = var.name
  destination = "opensearch_serverless"

  opensearch_serverless_destination {
    role_arn            = aws_iam_role.firehose_delivery.arn
    collection_arn      = aws_opensearchserverless_collection.main.arn
    index_name          = var.index_name
    s3_backup_mode      = "FailedDocumentsOnly"

    s3_configuration {
      role_arn           = aws_iam_role.firehose_delivery.arn
      bucket_arn         = aws_s3_bucket.firehose_backup.arn
      buffer_size        = var.buffer_size_mb
      buffer_interval    = var.buffer_interval_seconds
      compression_format = "GZIP"
      encryption_configuration {
        kms_encryption_context = "firehose-delivery-stream"
        key_type               = "AWS_KMS"
        key_arn                = aws_kms_key.firehose.arn
      }
      cloudwatch_logging_options {
        enabled        = true
        log_group_name = aws_cloudwatch_log_group.firehose.name
        log_stream_name = aws_cloudwatch_log_stream.firehose_delivery.name
      }
    }

    buffering_hints {
      interval_in_seconds = var.buffer_interval_seconds
      size_in_mbs         = var.buffer_size_mb
    }

    retry_options {
      duration_in_seconds = 300
    }

    cloudwatch_logging_options {
      enabled        = true
      log_group_name = aws_cloudwatch_log_group.firehose.name
      log_stream_name = aws_cloudwatch_log_stream.firehose_delivery.name
    }

    vpc_configuration {
      subnet_ids        = var.subnet_ids
      security_group_ids = var.security_group_ids
      role_arn          = aws_iam_role.firehose_delivery.arn
    }
  }

  tags = local.tags
}

# ---------------------------------------------------------
# Outputs
# ---------------------------------------------------------
output "firehose_delivery_stream_name" {
  value = aws_kinesis_firehose_delivery_stream.main.name
}

output "firehose_delivery_stream_arn" {
  value = aws_kinesis_firehose_delivery_stream.main.arn
}

output "opensearch_collection_endpoint" {
  value = aws_opensearchserverless_collection.main.collection_endpoint
}

output "opensearch_dashboard_endpoint" {
  value = aws_opensearchserverless_collection.main.dashboard_endpoint
}

output "s3_backup_bucket_name" {
  value = aws_s3_bucket.firehose_backup.bucket
}

output "firehose_role_arn" {
  value = aws_iam_role.firehose_delivery.arn
}

