model_answers:
terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS Region to deploy resources."
  type        = string
  default     = "us-east-1"
}

variable "vpc_id" {
  description = "ID of the VPC where the RDS instance will reside (must have private subnets)."
  type        = string
}

variable "private_subnet_ids" {
  description = "List of Private Subnet IDs for the DB Subnet Group. Must be in at least 2 AZs."
  type        = list(string)
  validation {
    condition     = length(var.private_subnet_ids) >= 2
    error_message = "At least 2 private subnets in different AZs are required for Multi-AZ deployment."
  }
}

variable "allowed_security_group_ids" {
  description = "List of Security Group IDs allowed to connect to the database (e.g., Application Server SGs)."
  type        = list(string)
  default     = []
}

variable "allowed_cidr_blocks" {
  description = "List of CIDR blocks allowed to connect to the database (use SGs instead where possible)."
  type        = list(string)
  default     = []
}

variable "db_identifier" {
  description = "Unique identifier for the DB instance."
  type        = string
  default     = "prod-mysql-instance"
}

variable "db_instance_class" {
  description = "Instance type for the DB."
  type        = string
  default     = "db.t3.medium"
}

variable "allocated_storage" {
  description = "Initial allocated storage in GB."
  type        = number
  default     = 100
}

variable "max_allocated_storage" {
  description = "Maximum storage threshold for autoscaling (0 to disable)."
  type        = number
  default     = 500
}

variable "engine_version" {
  description = "MySQL Engine Version."
  type        = string
  default     = "8.0.36"
}

variable "backup_retention_period" {
  description = "Days to retain backups (0 disables automated backups)."
  type        = number
  default     = 30
}

variable "backup_window" {
  description = "Daily time range (UTC) for automated backups."
  type        = string
  default     = "03:00-04:00"
}

variable "maintenance_window" {
  description = "Weekly time range (UTC) for system maintenance."
  type        = string
  default     = "sun:04:00-sun:05:00"
}

variable "deletion_protection" {
  description = "Enable deletion protection."
  type        = bool
  default     = true
}

variable "performance_insights_enabled" {
  description = "Enable Performance Insights."
  type        = bool
  default     = true
}

variable "monitoring_interval" {
  description = "Interval (seconds) for Enhanced Monitoring. 0 to disable."
  type        = number
  default     = 60
}

variable "iam_database_authentication_enabled" {
  description = "Enable IAM Database Authentication."
  type        = bool
  default     = true
}

# --- Random Password Generation (Best Practice: Never hardcode passwords) ---
resource "random_password" "db_master_password" {
  length  = 32
  special = true
  override_special = "!#$%&*()-_=+[]{}<>:?"
  keepers = {
    # Rotate password only if identifier changes
    db_identifier = var.db_identifier
  }
}

# --- DB Subnet Group ---
resource "aws_db_subnet_group" "main" {
  name       = "${var.db_identifier}-subnet-group"
  subnet_ids = var.private_subnet_ids
  tags = {
    Name        = "${var.db_identifier}-subnet-group"
    Environment = "production"
    ManagedBy   = "terraform"
  }
}

# --- DB Parameter Group (Enforce TLS & Security Settings) ---
resource "aws_db_parameter_group" "mysql_secure" {
  family = "mysql8.0"
  name   = "${var.db_identifier}-params"

  parameter {
    name  = "require_secure_transport"
    value = "ON" # Enforces TLS/SSL connections
  }

  parameter {
    name  = "sql_mode"
    value = "STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION,NO_ZERO_DATE,NO_ZERO_IN_DATE,ERROR_FOR_DIVISION_BY_ZERO"
  }

  parameter {
    name  = "local_infile"
    value = "OFF" # Disable loading local files
  }

  parameter {
    name  = "log_bin_trust_function_creators"
    value = "OFF"
  }

  lifecycle {
    create_before_destroy = true
  }
}

# --- Security Group for RDS ---
resource "aws_security_group" "rds" {
  name        = "${var.db_identifier}-sg"
  description = "Security Group for MySQL RDS Instance"
  vpc_id      = var.vpc_id

  # Ingress from Application Security Groups
  dynamic "ingress" {
    for_each = var.allowed_security_group_ids
    content {
      description = "MySQL from Application SG"
      from_port   = 3306
      to_port     = 3306
      protocol    = "tcp"
      security_groups = [ingress.value]
    }
  }

  # Ingress from CIDR Blocks (Fallback/Exception)
  dynamic "ingress" {
    for_each = var.allowed_cidr_blocks
    content {
      description = "MySQL from CIDR"
      from_port   = 3306
      to_port     = 3306
      protocol    = "tcp"
      cidr_blocks = [ingress.value]
    }
  }

  # Egress: Restrict to minimal required (e.g., S3 for backups/logs, KMS, CloudWatch)
  # Using AWS Managed Prefix Lists for S3/CloudWatch in the region is best practice.
  egress {
    description = "Allow HTTPS to AWS Services (S3, CloudWatch, KMS) via VPC Endpoints or NAT"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"] # Restrict to VPC CIDR or Prefix List IDs in production
  }

  tags = {
    Name        = "${var.db_identifier}-sg"
    Environment = "production"
    ManagedBy   = "terraform"
  }
}

# --- KMS Key for Encryption (Customer Managed Key - Best Practice) ---
resource "aws_kms_key" "rds" {
  description             = "KMS Key for ${var.db_identifier} RDS Encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "key-default-1"
    Statement = [
      {
        Sid       = "Allow root account full access"
        Effect    = "Allow"
        Principal = { AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root" }
        Action    = "kms:*"
        Resource  = "*"
      },
      {
        Sid       = "Allow RDS service to use key"
        Effect    = "Allow"
        Principal = { Service = "rds.amazonaws.com" }
        Action    = [
          "kms:Encrypt", "kms:Decrypt", "kms:ReEncrypt*", "kms:GenerateDataKey*",
          "kms:DescribeKey", "kms:CreateGrant", "kms:RetireGrant"
        ]
        Resource  = "*"
        Condition = {
          StringEquals = {
            "kms:ViaService" = "rds.${var.aws_region}.amazonaws.com"
            "kms:CallerAccount" = data.aws_caller_identity.current.account_id
          }
        }
      }
    ]
  })
}

data "aws_caller_identity" "current" {}

resource "aws_kms_alias" "rds" {
  name          = "alias/${var.db_identifier}-rds-key"
  target_key_id = aws_kms_key.rds.key_id
}

# --- CloudWatch Log Group for RDS Logs ---
resource "aws_cloudwatch_log_group" "rds_logs" {
  name              = "/aws/rds/instance/${var.db_identifier}"
  retention_in_days = 90
  kms_key_id        = aws_kms_key.rds.arn
}

# --- IAM Role for Enhanced Monitoring / RDS Enhanced Monitoring ---
resource "aws_iam_role" "rds_monitoring" {
  name = "${var.db_identifier}-monitoring-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action = "sts:AssumeRole"
      Effect = "Allow"
      Principal = { Service = "monitoring.rds.amazonaws.com" }
    }]
  })
}

resource "aws_iam_role_policy_attachment" "rds_monitoring" {
  role       = aws_iam_role.rds_monitoring.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonRDSEnhancedMonitoringRole"
}

# --- RDS Instance ---
resource "aws_db_instance" "mysql" {
  identifier              = var.db_identifier
  engine                  = "mysql"
  engine_version          = var.engine_version
  instance_class          = var.db_instance_class
  allocated_storage       = var.allocated_storage
  max_allocated_storage   = var.max_allocated_storage
  storage_type            = "gp3"
  storage_encrypted       = true
  kms_key_id              = aws_kms_key.rds.arn

  db_subnet_group_name    = aws_db_subnet_group.main.name
  vpc_security_group_ids  = [aws_security_group.rds.id]
  parameter_group_name    = aws_db_parameter_group.mysql_secure.name

  username                = "admin" # Avoid 'root', 'admin' is standard for AWS RDS
  password                = random_password.db_master_password.result
  port                    = 3306

  # High Availability & Durability
  multi_az                = true
  deletion_protection     = var.deletion_protection

  # Backups
  backup_retention_period = var.backup_retention_period
  backup_window           = var.backup_window
  copy_tags_to_snapshot   = true

  # Maintenance
  maintenance_window      = var.maintenance_window

  # Monitoring & Logging
  monitoring_interval           = var.monitoring_interval
  monitoring_role_arn           = var.monitoring_interval > 0 ? aws_iam_role.rds_monitoring.arn : null
  performance_insights_enabled  = var.performance_insights_enabled
  performance_insights_kms_key_id = var.performance_insights_enabled ? aws_kms_key.rds.arn : null
  enabled_cloudwatch_logs_exports = ["audit", "error", "general", "slowquery"]

  # Security
  publicly_accessible     = false
  iam_database_authentication_enabled = var.iam_database_authentication_enabled

  # Network
  # Note: RDS creates a Network Interface in the subnets provided in the Subnet Group.

  lifecycle {
    ignore_changes = [
      password, # Password managed by random_password rotation logic via keepers
    ]
  }

  tags = {
    Name                 = var.db_identifier
    Environment          = "production"
    ManagedBy            = "terraform"
    BackupRequired       = "true"
    EncryptionRequired   = "true"
  }
}

# --- Outputs ---
output "db_endpoint" {
  description = "RDS Instance Endpoint (Writer)"
  value       = aws_db_instance.mysql.endpoint
}

output "db_port" {
  description = "RDS Instance Port"
  value       = aws_db_instance.mysql.port
}

output "db_arn" {
  description = "RDS Instance ARN"
  value       = aws_db_instance.mysql.arn
}

output "db_security_group_id" {
  description = "Security Group ID attached to RDS"
  value       = aws_security_group.rds.id
}

output "kms_key_arn" {
  description = "KMS Key ARN used for encryption"
  value       = aws_kms_key.rds.arn
}

# Note: The master password is stored in AWS Secrets Manager or SSM Parameter Store automatically
# if using the AWS Console, but with Terraform it is in state.
# BEST PRACTICE: Use `aws_secretsmanager_secret` + `aws_secretsmanager_secret_version` to store
# the generated password and reference it in application code, rather than reading from TF state.

