provider "aws" {
  alias  = "eu_central"
  region = "eu-central-1"
  default_tags {
    tags = {
      Project     = "multi-region-eb"
      ManagedBy   = "terraform"
      Environment = "production"
      Region      = "eu-central-1"
    }
  }
}

# ============================================================
# Global Resources: Route53 Hosted Zone
# ============================================================
resource "aws_route53_zone" "main" {
  name = "eb-example.com" # Replace with your registered domain
}

# ============================================================
# Reusable Module: Regional Foundation (VPC, IAM, EB App)
# ============================================================
module "us_west_foundation" {
  source  = "./modules/regional_foundation"
  providers = {
    aws = aws.us_west
  }
  region_name      = "us-west-2"
  environment_name = "us_west"
  domain_name      = aws_route53_zone.main.name
}

module "eu_central_foundation" {
  source  = "./modules/regional_foundation"
  providers = {
    aws = aws.eu_central
  }
  region_name      = "eu-central-1"
  environment_name = "eu_central"
  domain_name      = aws_route53_zone.main.name
}

# ============================================================
# Global Resources: Route53 Geolocation Records
# ============================================================
resource "aws_route53_record" "geo_us" {
  zone_id = aws_route53_zone.main.zone_id
  name    = "app.${aws_route53_zone.main.name}"
  type    = "CNAME"
  ttl     = 60
  records = [module.us_west_foundation.eb_environment_url]

  geolocation_routing_policy {
    location_name = "US"
  }

  set_identifier = "us-west-2-geo"
}

resource "aws_route53_record" "geo_eu" {
  zone_id = aws_route53_zone.main.zone_id
  name    = "app.${aws_route53_zone.main.name}"
  type    = "CNAME"
  ttl     = 60
  records = [module.eu_central_foundation.eb_environment_url]

  geolocation_routing_policy {
    location_name = "EU"
  }

  set_identifier = "eu-central-1-geo"
}

resource "aws_route53_record" "geo_default" {
  zone_id = aws_route53_zone.main.zone_id
  name    = "app.${aws_route53_zone.main.name}"
  type    = "CNAME"
  ttl     = 60
  records = [module.us_west_foundation.eb_environment_url] # Fallback to US

  geolocation_routing_policy {
    location_name = "*"
  }

  set_identifier = "default-fallback"
}

# ============================================================
# Module Definition: ./modules/regional_foundation/main.tf
# (Inlined here for single-file requirement, normally separate directory)
# ============================================================

# --- Module Variables ---
variable "region_name"      { type = string }
variable "environment_name" { type = string }
variable "domain_name"      { type = string }

# --- Module Locals ---
locals {
  # Latest Amazon Linux 2023 Docker Platform ARN pattern
  solution_stack_name = "64bit Amazon Linux 2023 v4.1.0 running Docker"
}

# --- Data Sources ---
data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_elastic_beanstalk_solution_stack" "docker" {
  most_recent = true
  name_regex  = "^64bit Amazon Linux 2023.*running Docker"
}

# --- VPC & Networking (Security Best Practice: Private Instances, Public ALB) ---
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support   = true
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id
  depends_on    = [aws_internet_gateway.main]
}

resource "aws_eip" "nat" {
  domain = "vpc"
}

resource "aws_subnet" "public" {
  count                   = 2
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 4, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = true
}

resource "aws_subnet" "private" {
  count             = 2
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 4, count.index + 10)
  availability_zone = data.aws_availability_zones.available.names[count.index]
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id
  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id
  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }
}

resource "aws_route_table_association" "public" {
  count          = length(aws_subnet.public)
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "private" {
  count          = length(aws_subnet.private)
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# --- Security Groups ---
resource "aws_security_group" "alb" {
  name        = "${var.environment_name}-alb-sg"
  description = "Allow HTTP/HTTPS inbound to ALB"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_security_group" "instances" {
  name        = "${var.environment_name}-instance-sg"
  description = "Allow traffic from ALB only"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port       = 80
    to_port         = 80
    protocol        = "tcp"
    security_groups = [aws_security_group.alb.id]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# --- IAM Roles (Least Privilege) ---
resource "aws_iam_role" "service_role" {
  name = "${var.environment_name}-eb-service-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action = "sts:AssumeRole"
      Effect = "Allow"
      Principal = { Service = "elasticbeanstalk.amazonaws.com" }
    }]
  })
}

resource "aws_iam_role_policy_attachment" "service_managed" {
  role       = aws_iam_role.service_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSElasticBeanstalkEnhancedHealth"
}

resource "aws_iam_role_policy_attachment" "service_core" {
  role       = aws_iam_role.service_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSElasticBeanstalkService"
}

resource "aws_iam_role" "instance_role" {
  name = "${var.environment_name}-eb-instance-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action = "sts:AssumeRole"
      Effect = "Allow"
      Principal = { Service = "ec2.amazonaws.com" }
    }]
  })
}

resource "aws_iam_role_policy_attachment" "instance_ecr" {
  role       = aws_iam_role.instance_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEC2ContainerRegistryReadOnly"
}

resource "aws_iam_role_policy_attachment" "instance_ssm" {
  role       = aws_iam_role.instance_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_role_policy_attachment" "instance_cw" {
  role       = aws_iam_role.instance_role.name
  policy_arn = "arn:aws:iam::aws:policy/CloudWatchAgentServerPolicy"
}

resource "aws_iam_instance_profile" "instance_profile" {
  name = "${var.environment_name}-eb-instance-profile"
  role = aws_iam_role.instance_role.name
}

# --- Elastic Beanstalk Application ---
resource "aws_elastic_beanstalk_application" "main" {
  name        = var.environment_name
  description = "EB App for ${var.region_name}"
}

# --- Elastic Beanstalk Environment ---
resource "aws_elastic_beanstalk_environment" "main" {
  name                  = var.environment_name
  application           = aws_elastic_beanstalk_application.main.name
  solution_stack_name   = data.aws_elastic_beanstalk_solution_stack.docker.name
  platform_arn          = data.aws_elastic_beanstalk_solution_stack.docker.arn

  # Network Configuration (Security: Private Instances)
  setting {
    namespace = "aws:ec2:vpc"
    name      = "VPCId"
    value     = aws_vpc.main.id
  }
  setting {
    namespace = "aws:ec2:vpc"
    name      = "Subnets"
    value     = join(",", aws_subnet.private[*].id)
  }
  setting {
    namespace = "aws:ec2:vpc"
    name      = "ELBSubnets"
    value     = join(",", aws_subnet.public[*].id)
  }
  setting {
    namespace = "aws:ec2:vpc"
    name      = "ELBScheme"
    value     = "public"
  }

  # Security Groups
  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "SecurityGroups"
    value     = aws_security_group.instances.id
  }
  setting {
    namespace = "aws:elbv2:loadbalancer"
    name      = "SecurityGroups"
    value     = aws_security_group.alb.id
  }

  # IAM Roles
  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "ServiceRole"
    value     = aws_iam_role.service_role.arn
  }
  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "IamInstanceProfile"
    value     = aws_iam_instance_profile.instance_profile.name
  }

  # Instance Configuration (Security: IMDSv2, Encryption, Latest AMI)
  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "InstanceType"
    value     = "t3.micro" # Adjust for production
  }
  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "RootVolumeType"
    value     = "gp3"
  }
  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "RootVolumeSize"
    value     = "20"
  }
  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "BlockDeviceMappings"
    value     = "/dev/xvda=:20:true:gp3:encrypted"
  }
  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "MetadataHttpTokens"
    value     = "required" # Enforce IMDSv2
  }

  # Managed Platform Updates (Security: Auto-patch)
  setting {
    namespace = "aws:elasticbeanstalk:managedactions"
    name      = "ManagedActionsEnabled"
    value     = "true"
  }
  setting {
    namespace = "aws:elasticbeanstalk:managedactions:platformupdate"
    name      = "UpdateLevel"
    value     = "minor"
  }
  setting {
    namespace = "aws:elasticbeanstalk:managedactions:platformupdate"
    name      = "InstanceRefreshEnabled"
    value     = "true"
  }

  # Health & Monitoring
  setting {
    namespace = "aws:elasticbeanstalk:healthreporting:system"
    name      = "SystemType"
    value     = "enhanced"
  }
  setting {
    namespace = "aws:elasticbeanstalk:cloudwatch:logs"
    name      = "HealthStreamingEnabled"
    value     = "true"
  }

  # ASG Sizing
  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MinSize"
    value     = "1"
  }
  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MaxSize"
    value     = "3"
  }

  # Tags propagated to resources
  tags = {
    Name = var.environment_name
  }
}

# --- Module Outputs ---
output "eb_environment_url" {
  value       = aws_elastic_beanstalk_environment.main.cname
  description = "The CNAME URL of the Elastic Beanstalk Environment"
}

output "eb_environment_id" {
  value = aws_elastic_beanstalk_environment.main.id
}

