model_answers:
terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

provider "aws" {
  default_tags {
    tags = {
      Project     = "msk-logging-demo"
      Environment = "prod"
      ManagedBy   = "terraform"
    }
  }
}

# ---------------------------------------------------------
# Random Suffix for Unique Naming
# ---------------------------------------------------------
resource "random_string" "suffix" {
  length  = 6
  special = false
  upper   = false
}

# ---------------------------------------------------------
# Network (Minimal Best Practice: Private Subnets, No NAT GW for brokers)
# ---------------------------------------------------------
resource "aws_vpc" "msk" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support   = true
}

resource "aws_subnet" "msk_private" {
  count                   = 3
  vpc_id                  = aws_vpc.msk.id
  cidr_block              = cidrsubnet(aws_vpc.msk.cidr_block, 4, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_security_group" "msk_broker" {
  name        = "msk-broker-sg-${random_string.suffix.result}"
  description = "Security Group for MSK Broker Nodes"
  vpc_id      = aws_vpc.msk.id

  # Allow TLS (9094) and Plaintext (9092) from within VPC (adjust CIDR as needed)
  ingress {
    from_port   = 9092
    to_port     = 9094
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.msk.cidr_block]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_security_group" "msk_client" {
  name        = "msk-client-sg-${random_string.suffix.result}"
  description = "Security Group for MSK Clients"
  vpc_id      = aws_vpc.msk.id

  ingress {
    from_port   = 9092
    to_port     = 9094
    protocol    = "tcp"
    security_groups = [aws_security_group.msk_broker.id]
  }
}

# ---------------------------------------------------------
# KMS Key for Encryption at Rest (and S3/Firehose)
# ---------------------------------------------------------
resource "aws_kms_key" "msk" {
  description             = "KMS Key for MSK Encryption at Rest and S3/Firehose"
  deletion_window_in_days = 10
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "key-default-1"
    Statement = [
      {
        Sid       = "Allow root account full access"
        Effect    = "Allow"
        Principal = { AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root" }
        Action    = "kms:*"
        Resource  = "*"
      },
      {
        Sid       = "Allow MSK Service to use key"
        Effect    = "Allow"
        Principal = { Service = "kafka.amazonaws.com" }
        Action    = [
          "kms:Encrypt", "kms:Decrypt", "kms:ReEncrypt*", "kms:GenerateDataKey*",
          "kms:DescribeKey", "kms:CreateGrant", "kms:RetireGrant"
        ]
        Resource  = "*"
        Condition = {
          StringEquals = { "kms:ViaService" = "kafka.${data.aws_region.current.name}.amazonaws.com" }
        }
      },
      {
        Sid       = "Allow Firehose to use key"
        Effect    = "Allow"
        Principal = { Service = "firehose.amazonaws.com" }
        Action    = [
          "kms:Encrypt", "kms:Decrypt", "kms:ReEncrypt*", "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource  = "*"
      }
    ]
  })
}

data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

# ---------------------------------------------------------
# S3 Bucket for Firehose Destination
# ---------------------------------------------------------
resource "aws_s3_bucket" "msk_logs" {
  bucket = "msk-logs-${data.aws_caller_identity.current.account_id}-${random_string.suffix.result}"
  force_destroy = false # Set true for dev cleanup only
}

resource "aws_s3_bucket_versioning" "msk_logs" {
  bucket = aws_s3_bucket.msk_logs.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "msk_logs" {
  bucket = aws_s3_bucket.msk_logs.id
  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.msk.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "msk_logs" {
  bucket = aws_s3_bucket.msk_logs.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# ---------------------------------------------------------
# CloudWatch Log Group
# ---------------------------------------------------------
resource "aws_cloudwatch_log_group" "msk_broker_logs" {
  name              = "/aws/msk/${aws_msk_cluster.main.cluster_name}/broker-logs"
  retention_in_days = 30
  kms_key_id        = aws_kms_key.msk.arn
}

# ---------------------------------------------------------
# Kinesis Firehose Delivery Stream -> S3
# ---------------------------------------------------------
resource "aws_iam_role" "firehose" {
  name = "msk-firehose-role-${random_string.suffix.result}"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action = "sts:AssumeRole"
      Effect = "Allow"
      Principal = { Service = "firehose.amazonaws.com" }
      Condition = { StringEquals = { "sts:ExternalId" = data.aws_caller_identity.current.account_id } }
    }]
  })
}

resource "aws_iam_policy" "firehose_s3" {
  name = "msk-firehose-s3-policy-${random_string.suffix.result}"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["s3:AbortMultipartUpload", "s3:GetBucketLocation", "s3:GetObject", "s3:ListBucket", "s3:ListBucketMultipartUploads", "s3:PutObject"]
        Resource = [aws_s3_bucket.msk_logs.arn, "${aws_s3_bucket.msk_logs.arn}/*"]
      },
      {
        Effect   = "Allow"
        Action   = ["kms:Decrypt", "kms:GenerateDataKey"]
        Resource = [aws_kms_key.msk.arn]
      },
      {
        Effect   = "Allow"
        Action   = ["logs:PutLogEvents"]
        Resource = [aws_cloudwatch_log_group.msk_broker_logs.arn]
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "firehose_s3" {
  role       = aws_iam_role.firehose.name
  policy_arn = aws_iam_policy.firehose_s3.arn
}

resource "aws_kinesis_firehose_delivery_stream" "msk_logs" {
  name        = "msk-broker-logs-${random_string.suffix.result}"
  destination = "extended_s3"

  extended_s3_configuration {
    role_arn            = aws_iam_role.firehose.arn
    bucket_arn          = aws_s3_bucket.msk_logs.arn
    prefix              = "msk-broker-logs/year=!{timestamp:YYYY}/month=!{timestamp:MM}/day=!{timestamp:DD}/hour=!{timestamp:HH}/"
    error_output_prefix = "msk-broker-logs/errors/!{firehose:error-output-type}/year=!{timestamp:YYYY}/month=!{timestamp:MM}/day=!{timestamp:DD}/hour=!{timestamp:HH}/"

    buffering_hints {
      interval_in_seconds = 60
      size_in_mbs         = 50
    }
    compression_format = "GZIP"
    encryption_configuration {
      kms_encryption_context = "msk-broker-logs"
      key_arn                = aws_kms_key.msk.arn
    }
    cloudwatch_logging_options {
      enabled = true
      log_group_name = aws_cloudwatch_log_group.msk_broker_logs.name
      log_stream_name = "firehose-delivery"
    }
  }
}

# ---------------------------------------------------------
# MSK Cluster
# ---------------------------------------------------------
resource "aws_msk_cluster" "main" {
  cluster_name           = "msk-cluster-${random_string.suffix.result}"
  kafka_version          = "3.7.x" # Latest stable LTS as of writing
  number_of_broker_nodes = 3

  broker_node_group_info {
    instance_type   = "kafka.m7g.large" # Graviton3, cost-effective
    client_subnets  = aws_subnet.msk_private[*].id
    security_groups = [aws_security_group.msk_broker.id]

    storage_info {
      ebs_storage_info {
        volume_size = 100 # GiB
      }
    }

    connectivity_info {
      public_access {
        type = "DISABLED" # Security Best Practice: No Public Access
      }
    }
  }

  # Encryption at Rest (KMS) and In Transit (TLS)
  encryption_info {
    encryption_at_rest_kms_key_arn = aws_kms_key.msk.arn
    encryption_in_transit {
      client_broker = "TLS" # Enforce TLS for client-broker
      in_cluster    = true  # Enforce TLS for inter-broker
    }
  }

  # Open Monitoring (Prometheus)
  open_monitoring {
    prometheus {
      jmx_exporter {
        enabled_in_broker = true
      }
      node_exporter {
        enabled_in_broker = true
      }
    }
  }

  # Logging Configuration: CloudWatch, S3, Firehose
  logging_info {
    broker_logs {
      cloudwatch_logs {
        enabled   = true
        log_group = aws_cloudwatch_log_group.msk_broker_logs.name
      }
      s3 {
        enabled = true
        bucket  = aws_s3_bucket.msk_logs.id
        prefix  = "msk-broker-logs-direct/"
      }
      firehose {
        enabled             = true
        delivery_stream_arn = aws_kinesis_firehose_delivery_stream.msk_logs.arn
      }
    }
  }

  # Client Authentication (Best Practice: SASL/SCRAM or IAM)
  client_authentication {
    sasl {
      iam = true # Enable IAM Auth
    }
    unauthenticated = false
  }

  # Configuration for Auto Scaling / Best Practices (Optional but recommended)
  # configuration_info {
  #   arn      = aws_msk_configuration.main.arn
  #   revision = 1
  # }
}

# ---------------------------------------------------------
# Outputs
# ---------------------------------------------------------
output "msk_cluster_arn" {
  value = aws_msk_cluster.main.arn
}

output "msk_bootstrap_brokers_tls" {
  value     = aws_msk_cluster.main.bootstrap_brokers_tls
  sensitive = true
}

output "s3_bucket_name" {
  value = aws_s3_bucket.msk_logs.id
}

output "firehose_stream_name" {
  value = aws_kinesis_firehose_delivery_stream.msk_logs.name
}

output "cloudwatch_log_group_name" {
  value = aws_cloudwatch_log_group.msk_broker_logs.name
}

