model_answers:
terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS Region to deploy resources"
  type        = string
  default     = "us-east-1"
}

variable "allowed_cidr_blocks" {
  description = "List of CIDR blocks allowed to access the MySQL instance on port 3306"
  type        = list(string)
  default     = ["10.0.0.0/8"] # Example: Restrict to private RFC1918 space. CHANGE FOR PRODUCTION.
}

variable "db_name" {
  description = "Name of the initial database to create"
  type        = string
  default     = "appdb"
}

variable "instance_class" {
  description = "RDS Instance Class"
  type        = string
  default     = "db.t3.micro"
}

variable "engine_version" {
  description = "MySQL Engine Version"
  type        = string
  default     = "8.0.36"
}

# ---------------------------------------------------------
# Networking (Assumes Default VPC for simplicity; replace with dedicated VPC/Subnets in production)
# ---------------------------------------------------------
data "aws_vpc" "default" {
  default = true
}

data "aws_subnet_ids" "private" {
  vpc_id = data.aws_vpc.default.id
  filter {
    name   = "tag:aws:subnet-type"
    values = ["Private"]
  }
  # Fallback to any subnet if tags missing (e.g. default VPC)
  filter {
    name   = "map-public-ip-on-launch"
    values = ["false"]
  }
}

# ---------------------------------------------------------
# Security
# ---------------------------------------------------------
resource "random_password" "db_master_password" {
  length  = 32
  special = true
  override_special = "!#$%&*()-_=+[]{}<>:?"
}

resource "aws_security_group" "rds_sg" {
  name        = "sg-rds-mysql-secure"
  description = "Security Group for Private MySQL RDS Instance"
  vpc_id      = data.aws_vpc.default.id

  ingress {
    description     = "MySQL Access from Allowed CIDRs"
    from_port       = 3306
    to_port         = 3306
    protocol        = "tcp"
    cidr_blocks     = var.allowed_cidr_blocks
  }

  egress {
    description = "Allow all outbound (required for RDS managed services/updates)"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "sg-rds-mysql-secure"
  }
}

# ---------------------------------------------------------
# KMS Key for Encryption (Customer Managed Key - Best Practice)
# ---------------------------------------------------------
resource "aws_kms_key" "rds_key" {
  description             = "KMS Key for RDS MySQL Encryption"
  deletion_window_in_days = 10 # Minimum allowed
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "key-default-1"
    Statement = [
      {
        Sid       = "Allow administration of the key"
        Effect    = "Allow"
        Principal = { AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root" }
        Action    = ["kms:*"]
        Resource  = "*"
      },
      {
        Sid       = "Allow RDS service to use the key"
        Effect    = "Allow"
        Principal = { Service = "rds.amazonaws.com" }
        Action    = [
          "kms:Encrypt", "kms:Decrypt", "kms:ReEncrypt*", "kms:GenerateDataKey*",
          "kms:DescribeKey", "kms:CreateGrant", "kms:RetireGrant"
        ]
        Resource  = "*"
        Condition = {
          StringEquals = {
            "kms:ViaService" = "rds.${var.aws_region}.amazonaws.com"
            "kms:CallerAccount" = data.aws_caller_identity.current.account_id
          }
        }
      }
    ]
  })
}

data "aws_caller_identity" "current" {}

# ---------------------------------------------------------
# IAM Role for Enhanced Monitoring
# ---------------------------------------------------------
resource "aws_iam_role" "rds_monitoring_role" {
  name = "rds-monitoring-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action    = "sts:AssumeRole"
      Effect    = "Allow"
      Principal = { Service = "monitoring.rds.amazonaws.com" }
    }]
  })
}

resource "aws_iam_role_policy_attachment" "rds_monitoring_policy" {
  role       = aws_iam_role.rds_monitoring_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonRDSEnhancedMonitoringRole"
}

# ---------------------------------------------------------
# DB Subnet Group
# ---------------------------------------------------------
resource "aws_db_subnet_group" "private_subnets" {
  name       = "rds-private-subnet-group"
  description = "Subnet group for private RDS instances"
  subnet_ids = data.aws_subnet_ids.private.ids

  tags = {
    Name = "rds-private-subnet-group"
  }
}

# ---------------------------------------------------------
# Parameter Group (Enforce TLS/SSL)
# ---------------------------------------------------------
resource "aws_db_parameter_group" "mysql_secure_params" {
  family = "mysql8.0"
  name   = "mysql-8-secure-params"

  parameter {
    name  = "require_secure_transport"
    value = "ON"
  }

  parameter {
    name  = "log_bin_trust_function_creators"
    value = "ON"
  }
}

# ---------------------------------------------------------
# RDS Instance
# ---------------------------------------------------------
resource "aws_db_instance" "mysql" {
  identifier             = "mysql-secure-instance"
  engine                 = "mysql"
  engine_version         = var.engine_version
  instance_class         = var.instance_class
  allocated_storage      = 20
  max_allocated_storage  = 100
  storage_type           = "gp3"
  storage_encrypted      = true
  kms_key_id             = aws_kms_key.rds_key.arn

  db_name  = var.db_name
  username = "admin"
  password = random_password.db_master_password.result
  port     = 3306

  db_subnet_group_name   = aws_db_subnet_group.private_subnets.name
  vpc_security_group_ids = [aws_security_group.rds_sg.id]

  parameter_group_name = aws_db_parameter_group.mysql_secure_params.name

  # High Availability & Durability
  multi_az               = true
  deletion_protection    = true
  backup_retention_period = 7
  backup_window          = "03:00-04:00"
  maintenance_window     = "mon:04:00-mon:05:00"

  # Security & Compliance
  copy_tags_to_snapshot  = true
  iam_database_authentication_enabled = true
  publicly_accessible    = false
  ca_cert_identifier     = "rds-ca-rsa2048-g1"

  # Monitoring
  monitoring_interval    = 60
  monitoring_role_arn    = aws_iam_role.rds_monitoring_role.arn
  performance_insights_enabled = true
  performance_insights_kms_key_id = aws_kms_key.rds_key.arn
  performance_insights_retention_period = 7

  # Logging
  enabled_cloudwatch_logs_exports = ["audit", "error", "general", "slowquery"]

  tags = {
    Name        = "mysql-secure-instance"
    Environment = "production"
    ManagedBy   = "terraform"
  }

  # Ensure SG and KMS key are ready
  depends_on = [
    aws_security_group.rds_sg,
    aws_kms_key.rds_key,
    aws_iam_role_policy_attachment.rds_monitoring_policy
  ]
}

# ---------------------------------------------------------
# Manual Snapshot
# ---------------------------------------------------------
resource "aws_db_snapshot" "initial_snapshot" {
  db_instance_identifier = aws_db_instance.mysql.id
  db_snapshot_identifier = "mysql-initial-snapshot-${formatdate("YYYYMMDDHHmmss", timestamp())}"
  tags = {
    Name        = "Initial Manual Snapshot"
    Environment = "production"
    SourceInstance = aws_db_instance.mysql.identifier
  }

  # Wait for instance to be available before snapshotting
  depends_on = [aws_db_instance.mysql]
}

# ---------------------------------------------------------
# Outputs (Sensitive values marked)
# ---------------------------------------------------------
output "db_endpoint" {
  description = "RDS Instance Endpoint"
  value       = aws_db_instance.mysql.endpoint
}

output "db_port" {
  description = "RDS Instance Port"
  value       = aws_db_instance.mysql.port
}

output "db_master_username" {
  description = "Master Username"
  value       = aws_db_instance.mysql.username
}

output "db_master_password" {
  description = "Master Password (Generated)"
  value       = random_password.db_master_password.result
  sensitive   = true
}

output "snapshot_id" {
  description = "Manual Snapshot Identifier"
  value       = aws_db_snapshot.initial_snapshot.id
}

output "snapshot_arn" {
  description = "Manual Snapshot ARN"
  value       = aws_db_snapshot.initial_snapshot.arn
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
