# ---------------------------------------------------------
resource "aws_kms_key" "rds" {
  description             = "KMS key for RDS PostgreSQL encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "key-default-1"
    Statement = [
      {
        Sid       = "Allow administration of the key"
        Effect    = "Allow"
        Principal = { AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root" }
        Action    = ["kms:*"]
        Resource  = "*"
      },
      {
        Sid       = "Allow RDS service to use the key"
        Effect    = "Allow"
        Principal = { Service = "rds.amazonaws.com" }
        Action    = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource  = "*"
        Condition = {
          StringEquals = {
            "kms:ViaService" = "rds.${var.aws_region}.amazonaws.com"
          }
          StringLike = {
            "kms:EncryptionContext:aws:rds:db-id" = "${var.db_name}-*"
          }
        }
      }
    ]
  })
}

resource "aws_kms_alias" "rds" {
  name          = "alias/${var.db_name}-rds-key"
  target_key_id = aws_kms_key.rds.key_id
}

# ---------------------------------------------------------
# Random Password for Master User
# ---------------------------------------------------------
resource "random_password" "master" {
  length  = 32
  special = false
  override_special = "_"
}

resource "aws_secretsmanager_secret" "rds_credentials" {
  name        = "${var.db_name}/rds/master_credentials"
  description = "Master credentials for RDS PostgreSQL instance"
  kms_key_id  = aws_kms_key.rds.arn

  rotation_rules {
    automatically_after = "30d"
  }
}

resource "aws_secretsmanager_secret_version" "rds_credentials" {
  secret_id = aws_secretsmanager_secret.rds_credentials.id
  secret_string = jsonencode({
    username = "admin"
    password = random_password.master.result
    engine   = "postgres"
    host     = "" # Populated after creation via rotation lambda or manually
    port     = 5432
    dbname   = var.db_name
  })
}

# ---------------------------------------------------------
# DB Subnet Group
# ---------------------------------------------------------
resource "aws_db_subnet_group" "main" {
  name       = "${var.db_name}-subnet-group"
  subnet_ids = var.private_subnet_ids
  tags = {
    Name = "${var.db_name}-subnet-group"
  }
}

# ---------------------------------------------------------
# Security Group
# ---------------------------------------------------------
resource "aws_security_group" "rds" {
  name        = "${var.db_name}-rds-sg"
  description = "Security group for RDS PostgreSQL instance"
  vpc_id      = var.vpc_id

  ingress {
    description = "PostgreSQL from allowed CIDRs"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = var.allowed_cidr_blocks
  }

  egress {
    description = "Allow all outbound (required for RDS managed services)"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "${var.db_name}-rds-sg"
  }
}

# ---------------------------------------------------------
# DB Parameter Group (Security Hardening)
# ---------------------------------------------------------
resource "aws_db_parameter_group" "pg16" {
  family = "postgres16"
  name   = "${var.db_name}-pg16-params"

  parameter {
    name  = "rds.force_ssl"
    value = "1"
  }

  parameter {
    name  = "log_connections"
    value = "1"
  }

  parameter {
    name  = "log_disconnections"
    value = "1"
  }

  parameter {
    name  = "log_statement"
    value = "ddl"
  }

  parameter {
    name  = "pgaudit.log"
    value = "ddl, role"
  }

  tags = {
    Name = "${var.db_name}-pg16-params"
  }
}

# ---------------------------------------------------------
# RDS Instance
# ---------------------------------------------------------
resource "aws_db_instance" "postgres" {
  identifier             = "${var.db_name}-pg"
  engine                 = "postgres"
  engine_version         = var.engine_version
  instance_class         = var.instance_class
  allocated_storage      = var.allocated_storage
  max_allocated_storage  = var.max_allocated_storage
  storage_type           = "gp3"
  storage_encrypted      = true
  kms_key_id             = aws_kms_key.rds.arn

  db_name           = var.db_name
  username          = "admin"
  password          = random_password.master.result
  manage_master_user_password = false # We manage via Secrets Manager explicitly

  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.rds.id]

  parameter_group_name = aws_db_parameter_group.pg16.name

  backup_retention_period = var.backup_retention_period
  backup_window           = "03:00-04:00"
  maintenance_window      = "mon:04:00-mon:05:00"

  deletion_protection         = var.deletion_protection
  skip_final_snapshot         = false
  final_snapshot_identifier   = "${var.db_name}-final-snapshot-${formatdate("YYYYMMDDHHmmss", timestamp())}"

  multi_az               = true
  publicly_accessible    = false
  copy_tags_to_snapshot  = true

  monitoring_interval = 60
  monitoring_role_arn = aws_iam_role.rds_monitoring.arn

  performance_insights_enabled          = true
  performance_insights_kms_key_id       = aws_kms_key.rds.arn
  performance_insights_retention_period = 7

  enabled_cloudwatch_logs_exports = ["postgresql", "upgrade"]

  iam_database_authentication_enabled = true

  apply_immediately = false

  tags = {
    Name        = "${var.db_name}-pg"
    Environment = "production"
    ManagedBy   = "terraform"
  }
}

# ---------------------------------------------------------
# IAM Role for Enhanced Monitoring
# ---------------------------------------------------------
resource "aws_iam_role" "rds_monitoring" {
  name = "${var.db_name}-rds-monitoring-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action    = "sts:AssumeRole"
      Effect    = "Allow"
      Principal = { Service = "monitoring.rds.amazonaws.com" }
    }]
  })
}

resource "aws_iam_role_policy_attachment" "rds_monitoring" {
  role       = aws_iam_role.rds_monitoring.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonRDSEnhancedMonitoringRole"
}

# ---------------------------------------------------------
# Data Sources
# ---------------------------------------------------------
data "aws_caller_identity" "current" {}

