    init_query                   = "SET x=1, y=2"
    max_connections_percent      = 100
    max_idle_connections_percent = 50
    session_pinning_filters      = ["EXCLUDE_VARIABLE_SETS"]
  }
}

resource "aws_db_proxy_target" "example" {
  db_cluster_identifier = aws_rds_cluster.example.cluster_identifier
  db_proxy_name          = aws_db_proxy.example.name
  target_group_name      = aws_db_proxy_default_target_group.example.name
}

model_answers:
terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  default_tags {
    tags = {
      Environment = "production"
      ManagedBy   = "terraform"
      Project     = "aurora-mysql-cluster"
    }
  }
}

# Random suffix for unique resource names
resource "random_string" "suffix" {
  length  = 8
  special = false
  upper   = false
}

# KMS Key for RDS encryption
resource "aws_kms_key" "rds" {
  description             = "KMS key for Aurora MySQL encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "Allow root access"
        Effect    = "Allow"
        Principal = { AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root" }
        Action    = "kms:*"
        Resource  = "*"
      },
      {
        Sid       = "Allow RDS service"
        Effect    = "Allow"
        Principal = { Service = "rds.amazonaws.com" }
        Action    = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
}

# VPC with DNS support
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support   = true
  instance_tenancy     = "default"
}

# Private subnets for RDS (multi-AZ)
resource "aws_subnet" "private" {
  count                   = 3
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 4, count.index + 4)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false
}

# DB Subnet Group
resource "aws_db_subnet_group" "aurora" {
  name       = "aurora-mysql-subnet-group-${random_string.suffix.result}"
  subnet_ids = aws_subnet.private[*].id
  description = "Subnet group for Aurora MySQL cluster"
}

# Security Group for Aurora Cluster
resource "aws_security_group" "aurora" {
  name        = "aurora-mysql-sg-${random_string.suffix.result}"
  description = "Security group for Aurora MySQL cluster"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port       = 3306
    to_port         = 3306
    protocol        = "tcp"
    security_groups = [aws_security_group.proxy.id]
    description     = "MySQL from RDS Proxy only"
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
    description = "Allow all outbound"
  }
}

# Security Group for RDS Proxy
resource "aws_security_group" "proxy" {
  name        = "rds-proxy-sg-${random_string.suffix.result}"
  description = "Security group for RDS Proxy"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/16"]
    description = "MySQL from VPC CIDR"
  }

  egress {
    from_port       = 3306
    to_port         = 3306
    protocol        = "tcp"
    security_groups = [aws_security_group.aurora.id]
    description     = "MySQL to Aurora cluster"
  }
}

# IAM Role for RDS Enhanced Monitoring
resource "aws_iam_role" "rds_monitoring" {
  name = "rds-enhanced-monitoring-role-${random_string.suffix.result}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action    = "sts:AssumeRole"
      Effect    = "Allow"
      Principal = { Service = "monitoring.rds.amazonaws.com" }
    }]
  })
}

resource "aws_iam_role_policy_attachment" "rds_monitoring" {
  role       = aws_iam_role.rds_monitoring.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonRDSEnhancedMonitoringRole"
}

# IAM Role for RDS Proxy
resource "aws_iam_role" "rds_proxy" {
  name = "rds-proxy-role-${random_string.suffix.result}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action    = "sts:AssumeRole"
      Effect    = "Allow"
      Principal = { Service = "rds.amazonaws.com" }
    }]
  })
}

resource "aws_iam_policy" "rds_proxy_secrets" {
  name = "rds-proxy-secrets-policy-${random_string.suffix.result}"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect   = "Allow"
      Action   = ["secretsmanager:GetSecretValue", "kms:Decrypt"]
      Resource = [aws_secretsmanager_secret.db_credentials.arn, aws_kms_key.rds.arn]
    }]
  })
}

resource "aws_iam_role_policy_attachment" "rds_proxy_secrets" {
  role       = aws_iam_role.rds_proxy.name
  policy_arn = aws_iam_policy.rds_proxy_secrets.arn
}

# Secrets Manager for DB Credentials
resource "aws_secretsmanager_secret" "db_credentials" {
  name                    = "aurora-mysql/credentials/${random_string.suffix.result}"
  description             = "Aurora MySQL master credentials"
  kms_key_id              = aws_kms_key.rds.arn
  recovery_window_in_days = 30
}

resource "random_password" "db_password" {
  length  = 32
  special = true
  override_special = "!@#$%^&*()-_=+"
}

resource "aws_secretsmanager_secret_version" "db_credentials" {
  secret_id = aws_secretsmanager_secret.db_credentials.id
  secret_string = jsonencode({
    username = "admin"
    password = random_password.db_password.result
    engine   = "mysql"
    host     = "" # Will be populated after cluster creation
    port     = 3306
    dbname   = "appdb"
  })
}

# Aurora MySQL Cluster
resource "aws_rds_cluster" "aurora" {
  cluster_identifier      = "aurora-mysql-cluster-${random_string.suffix.result}"
  engine                  = "aurora-mysql"
  engine_version          = "8.0.mysql_aurora.3.05.2"
  engine_mode             = "provisioned"
  database_name           = "appdb"
  master_username         = "admin"
  manage_master_user_password = true
  master_user_secret_kms_key_id = aws_kms_key.rds.arn

  db_subnet_group_name    = aws_db_subnet_group.aurora.name
  vpc_security_group_ids  = [aws_security_group.aurora.id]

  # Instance configuration
  instance_class          = "db.r6g.xlarge"
  availability_zones      = data.aws_availability_zones.available.names[0:2]

  # Storage encryption
  storage_encrypted       = true
  kms_key_id              = aws_kms_key.rds.arn

  # Backup configuration
  backup_retention_period = 7
  preferred_backup_window = "03:00-04:00"
  preferred_maintenance_window = "sun:04:00-sun:05:00"

  # Deletion protection and final snapshot
  deletion_protection     = true
  skip_final_snapshot     = false
  final_snapshot_identifier = "snapshot"

  # Monitoring
  monitoring_interval     = 60
  monitoring_role_arn     = aws_iam_role.rds_monitoring.arn
  performance_insights_enabled = true
  performance_insights_kms_key_id = aws_kms_key.rds.arn
  performance_insights_retention_period = 7

  # Network
  port                    = 3306

  # Parameter group
  db_cluster_parameter_group_name = aws_rds_cluster_parameter_group.aurora.name

  # Enable IAM authentication
  iam_database_authentication_enabled = true

  # Enable CloudWatch logs exports
  enabled_cloudwatch_logs_exports = ["audit", "error", "general", "slowquery"]

  # Serverless v2 scaling configuration (optional)
  serverlessv2_scaling_configuration {
    min_capacity = 0.5
    max_capacity = 128
  }

  lifecycle {
    prevent_destroy = true
    ignore_changes  = [master_user_secret]
  }
}

# Cluster Parameter Group
resource "aws_rds_cluster_parameter_group" "aurora" {
  name        = "aurora-mysql-params-${random_string.suffix.result}"
  family      = "aurora-mysql8.0"
  description = "Parameter group for Aurora MySQL 8.0"

  parameter {
    name  = "slow_query_log"
    value = "1"
  }

  parameter {
    name  = "long_query_time"
    value = "2"
  }

  parameter {
    name  = "log_queries_not_using_indexes"
    value = "1"
  }
}

# DB Instances (2 for HA)
resource "aws_rds_cluster_instance" "aurora" {
  count               = 2
  identifier          = "aurora-mysql-instance-${count.index + 1}-${random_string.suffix.result}"
  cluster_identifier  = aws_rds_cluster.aurora.id
  instance_class      = "db.r6g.xlarge"
  engine              = aws_rds_cluster.aurora.engine
  engine_version      = aws_rds_cluster.aurora.engine_version
  publicly_accessible = false
  monitoring_interval = 60
  monitoring_role_arn = aws_iam_role.rds_monitoring.arn
  performance_insights_enabled = true
  performance_insights_kms_key_id = aws_kms_key.rds.arn

  lifecycle {
    prevent_destroy = true
  }
}

# RDS Proxy
resource "aws_db_proxy" "aurora_proxy" {
  name                   = "aurora-mysql-proxy-${random_string.suffix.result}"
  engine_family          = "MYSQL"
  auth                   = [{
    auth_scheme                = "SECRETS"
    description                = "Aurora MySQL proxy authentication"
    iam_auth                   = "DISABLED"
    secret_arn                 = aws_secretsmanager_secret.db_credentials.arn
    client_password_auth_type  = "MYSQL_NATIVE_PASSWORD"
  }]
  role_arn               = aws_iam_role.rds_proxy.arn
  vpc_subnet_ids         = aws_subnet.private[*].id
  vpc_security_group_ids = [aws_security_group.proxy.id]
  require_tls            = true
  idle_client_timeout    = 1800
  max_connections_percent = 95
  max_idle_connections_percent = 50
  debug_logging          = false
}

# Proxy Target Group
resource "aws_db_proxy_target_group" "aurora_proxy_target" {
  db_proxy_name          = aws_db_proxy.aurora_proxy.name
  target_group_name      = "aurora-mysql-target-group-${random_string.suffix.result}"
  db_cluster_identifiers = [aws_rds_cluster.aurora.cluster_identifier]
  connection_pool_config = {
    max_connections_percent  = 95
    max_idle_connections_percent = 50
    connection_borrow_timeout = 120
    session_pinning_filters  = ["EXCLUDE_VARIABLE_SETTINGS"]
  }
}

# Proxy Default Target Group Association
resource "aws_db_proxy_default_target_group" "aurora_proxy_default" {
  db_proxy_name = aws_db_proxy.aurora_proxy.name
  connection_pool_config = {
    max_connections_percent  = 95
    max_idle_connections_percent = 50
    connection_borrow_timeout = 120
  }
}

# Data sources
data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

# Outputs
output "cluster_endpoint" {
  description = "Aurora cluster writer endpoint"
  value       = aws_rds_cluster.aurora.endpoint
}

output "cluster_reader_endpoint" {
  description = "Aurora cluster reader endpoint"
  value       = aws_rds_cluster.aurora.reader_endpoint
}

output "proxy_endpoint" {
  description = "RDS Proxy endpoint"
  value       = aws_db_proxy.aurora_proxy.endpoint
}

output "secrets_manager_arn" {
  description = "Secrets Manager secret ARN for DB credentials"
  value       = aws_secretsmanager_secret.db_credentials.arn
}

output "kms_key_arn" {
  description = "KMS key ARN for encryption"
  value       = aws_kms_key.rds.arn
}

output "vpc_id" {
  description = "VPC ID"
  value       = aws_vpc.main.id
}

output "private_subnet_ids" {
  description = "Private subnet IDs"
  value       = aws_subnet.private[*].id
}

