terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS Region to deploy resources"
  type        = string
  default     = "us-east-1"
}

variable "vpc_id" {
  description = "VPC ID where RDS will be deployed (must have private subnets in at least 2 AZs)"
  type        = string
}

variable "allowed_cidr_blocks" {
  description = "List of CIDR blocks allowed to access the database on port 5432"
  type        = list(string)
  default     = ["10.0.0.0/8"]
}

variable "db_instance_class" {
  description = "Instance class for the primary DB instance"
  type        = string
  default     = "db.t3.medium"
}

variable "replica_instance_class" {
  description = "Instance class for the read replica"
  type        = string
  default     = "db.t3.medium"
}

variable "db_name" {
  description = "Name of the initial database"
  type        = string
  default     = "appdb"
}

variable "master_username" {
  description = "Master username for the database"
  type        = string
  default     = "admin"
}

# ---------------------------------------------------------
# Secrets & Encryption
# ---------------------------------------------------------
resource "random_password" "master_password" {
  length  = 32
  special = true
  override_special = "!#$%&*()-_=+[]{}<>:?"
}

resource "aws_kms_key" "rds" {
  description             = "KMS key for RDS encryption"
  deletion_window_in_days = 10
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowRootAccess"
        Effect    = "Allow"
        Principal = { AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root" }
        Action    = "kms:*"
        Resource  = "*"
      },
      {
        Sid       = "AllowRDSService"
        Effect    = "Allow"
        Principal = { Service = "rds.amazonaws.com" }
        Action    = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
}

data "aws_caller_identity" "current" {}

# ---------------------------------------------------------
# Network
# ---------------------------------------------------------
data "aws_subnet_ids" "private" {
  vpc_id = var.vpc_id
  filter {
    name   = "tag:aws:subnet-type"
    values = ["private"]
  }
}

resource "aws_db_subnet_group" "main" {
  name       = "rds-private-subnet-group"
  subnet_ids = data.aws_subnet_ids.private.ids
  tags = {
    Name = "rds-private-subnet-group"
  }
}

resource "aws_security_group" "rds" {
  name        = "sg-rds-postgresql"
  description = "Security group for RDS PostgreSQL instances"
  vpc_id      = var.vpc_id

  ingress {
    description     = "PostgreSQL from allowed CIDRs"
    from_port       = 5432
    to_port         = 5432
    protocol        = "tcp"
    cidr_blocks     = var.allowed_cidr_blocks
  }

  egress {
    description = "Allow all outbound"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "sg-rds-postgresql"
  }
}

# ---------------------------------------------------------
# Parameter Group (Enforce SSL/TLS)
# ---------------------------------------------------------
resource "aws_db_parameter_group" "pg15" {
  family = "postgres15"
  name   = "pg15-require-ssl"

  parameter {
    name  = "rds.force_ssl"
    value = "1"
  }

  parameter {
    name  = "log_connections"
    value = "1"
  }

  parameter {
    name  = "log_disconnections"
    value = "1"
  }
}

# ---------------------------------------------------------
# Primary RDS Instance
# ---------------------------------------------------------
resource "aws_db_instance" "primary" {
  identifier             = "primary-pg-db"
  engine                 = "postgres"
  engine_version         = "15.7"
  instance_class         = var.db_instance_class
  allocated_storage      = 100
  max_allocated_storage  = 500
  storage_type           = "gp3"
  storage_encrypted      = true
  kms_key_id             = aws_kms_key.rds.arn

  db_name           = var.db_name
  username          = var.master_username
  password          = random_password.master_password.result
  parameter_group_name = aws_db_parameter_group.pg15.name
  db_subnet_group_name = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.rds.id]

  backup_retention_period = 7
  backup_window           = "03:00-04:00"
  maintenance_window      = "sun:04:00-sun:05:00"

  deletion_protection     = true
  skip_final_snapshot     = false
  final_snapshot_identifier = "primary-pg-db-final-snapshot-${formatdate("YYYYMMDDHHmmss", timestamp())}"

  publicly_accessible     = false
  copy_tags_to_snapshot   = true

  monitoring_interval     = 60
  monitoring_role_arn     = aws_iam_role.rds_monitoring.arn
  performance_insights_enabled = true
  performance_insights_kms_key_id = aws_kms_key.rds.arn
  performance_insights_retention_period = 7

  enabled_cloudwatch_logs_exports = ["postgresql", "upgrade"]

  iam_database_authentication_enabled = true

  tags = {
    Name        = "primary-pg-db"
    Environment = "production"
    Role        = "primary"
  }
}

# ---------------------------------------------------------
# Read Replica
# ---------------------------------------------------------
resource "aws_db_instance" "replica" {
  identifier             = "replica-pg-db"
  replicate_source_db    = aws_db_instance.primary.identifier
  instance_class         = var.replica_instance_class
  storage_type           = "gp3"
  monitoring_interval    = 60
  monitoring_role_arn    = aws_iam_role.rds_monitoring.arn
  performance_insights_enabled = true
  performance_insights_kms_key_id = aws_kms_key.rds.arn

  publicly_accessible    = false
  deletion_protection    = true
  copy_tags_to_snapshot  = true

  # Replica inherits encryption, parameter group, subnet group, security groups from primary
  # but we can override specific settings if needed.

  tags = {
    Name        = "replica-pg-db"
    Environment = "production"
    Role        = "replica"
  }

  # Ensure replica is created after primary is fully available
  depends_on = [aws_db_instance.primary]
}

# ---------------------------------------------------------
# IAM Role for Enhanced Monitoring
# ---------------------------------------------------------
resource "aws_iam_role" "rds_monitoring" {
  name = "rds-monitoring-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action = "sts:AssumeRole"
      Effect = "Allow"
      Principal = {
        Service = "monitoring.rds.amazonaws.com"
      }
    }]
  })
}

resource "aws_iam_role_policy_attachment" "rds_monitoring" {
  role       = aws_iam_role.rds_monitoring.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonRDSEnhancedMonitoringRole"
}

