variable "aws_region" {
  description = "AWS Region for Lightsail resources."
  type        = string
  default     = "us-east-1"
}

variable "db_identifier" {
  description = "Unique identifier for the Lightsail database."
  type        = string
  default     = "tf-lightsail-db"
  validation {
    condition     = length(var.db_identifier) <= 255 && can(regex("^[a-zA-Z0-9_-]+$", var.db_identifier))
    error_message = "Database identifier must be alphanumeric, hyphens, or underscores, max 255 chars."
  }
}

variable "engine" {
  description = "Database engine (e.g., mysql, postgres)."
  type        = string
  default     = "postgres"
  validation {
    condition     = contains(["mysql", "postgres"], var.engine)
    error_message = "Engine must be 'mysql' or 'postgres'."
  }
}

variable "engine_version" {
  description = "Database engine version."
  type        = string
  default     = "15"
}

variable "bundle_id" {
  description = "Lightsail bundle ID (pricing tier). Use 'micro_2_0' for dev/test."
  type        = string
  default     = "micro_2_0"
}

variable "master_username" {
  description = "Master username for the database."
  type        = string
  default     = "dbadmin"
  validation {
    condition     = length(var.master_username) <= 16 && can(regex("^[a-zA-Z][a-zA-Z0-9_]*$", var.master_username))
    error_message = "Username must start with a letter, contain only alphanumeric/underscore, max 16 chars."
  }
}

variable "backup_retention_enabled" {
  description = "Enable automated backups."
  type        = bool
  default     = true
}

variable "preferred_backup_window" {
  description = "Daily time range (UTC) for automated backups (e.g., '03:00-04:00')."
  type        = string
  default     = "03:00-04:00"
}

variable "preferred_maintenance_window" {
  description = "Weekly time range (UTC) for system maintenance (e.g., 'mon:04:00-mon:05:00')."
  type        = string
  default     = "mon:04:00-mon:05:00"
}

variable "publicly_accessible" {
  description = "Whether the database has a public endpoint. Best practice: false (use VPC peering)."
  type        = bool
  default     = false
}

variable "tags" {
  description = "Map of tags to apply to all resources."
  type        = map(string)
  default     = {
    Environment = "production"
    ManagedBy   = "terraform"
  }
}

resource "random_password" "db_master_password" {
  length  = 32
  special = true
  override_special = "!@#$%^&*()_+-="
  keepers = {
    db_identifier = var.db_identifier
  }
}

resource "aws_lightsail_database" "managed_db" {
  name                    = var.db_identifier
