# ---------------------------------------------------------
# Random Suffix for unique resource naming
# ---------------------------------------------------------
resource "random_id" "suffix" {
  byte_length = 4
}

# ---------------------------------------------------------
# KMS Key for Encryption (Security Best Practice)
# ---------------------------------------------------------
resource "aws_kms_key" "lex_bot_key" {
  description             = "KMS Key for Lex Bot encryption"
  deletion_window_in_days = 10
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "key-default-1"
    Statement = [
      {
        Sid       = "Allow administration of the key"
        Effect    = "Allow"
        Principal = { AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root" }
        Action    = ["kms:*"]
        Resource  = "*"
      },
      {
        Sid       = "Allow Lex service to use the key"
        Effect    = "Allow"
        Principal = { Service = "lex.amazonaws.com" }
        Action    = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource  = "*"
        Condition = {
          StringEquals = {
            "kms:ViaService" = "lex.${var.aws_region}.amazonaws.com"
          }
          StringEquals = {
            "aws:SourceAccount" = data.aws_caller_identity.current.account_id
          }
        }
      }
    ]
  })
}

resource "aws_kms_alias" "lex_bot_key_alias" {
  name          = "alias/lex-bot-${var.bot_name}-${random_id.suffix.hex}"
  target_key_id = aws_kms_key.lex_bot_key.key_id
}

# ---------------------------------------------------------
# IAM Role for Lex Bot (Least Privilege)
# ---------------------------------------------------------
data "aws_caller_identity" "current" {}

resource "aws_iam_role" "lex_bot_role" {
  name = "LexBotExecutionRole-${var.bot_name}-${random_id.suffix.hex}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action    = "sts:AssumeRole"
      Effect    = "Allow"
      Principal = { Service = "lex.amazonaws.com" }
    }]
  })

  inline_policy {
    name = "LexBotPermissions"
    policy = jsonencode({
      Version = "2012-10-17"
      Statement = [
        {
          Sid       = "AllowPolly"
          Effect    = "Allow"
          Action    = ["polly:SynthesizeSpeech"]
          Resource  = "*"
        },
        {
          Sid       = "AllowComprehend"
          Effect    = "Allow"
          Action    = [
            "comprehend:DetectDominantLanguage",
            "comprehend:DetectSentiment"
          ]
          Resource  = "*"
        },
        {
          Sid       = "AllowKMS"
          Effect    = "Allow"
          Action    = [
            "kms:Encrypt",
            "kms:Decrypt",
            "kms:ReEncrypt*",
            "kms:GenerateDataKey*",
            "kms:DescribeKey"
          ]
          Resource  = aws_kms_key.lex_bot_key.arn
        },
        {
          Sid       = "AllowCloudWatchLogs"
          Effect    = "Allow"
          Action    = [
            "logs:CreateLogGroup",
            "logs:CreateLogStream",
            "logs:PutLogEvents"
          ]
          Resource  = "arn:aws:logs:${var.aws_region}:${data.aws_caller_identity.current.account_id}:log-group:/aws/lex/${var.bot_name}*"
        }
      ]
    })
  }
}

# ---------------------------------------------------------
# Lex Bot V2 Resource
# ---------------------------------------------------------
resource "aws_lex_bot" "book_trip_bot" {
  name                     = var.bot_name
  description              = var.bot_description
  role_arn                 = aws_iam_role.lex_bot_role.arn
  data_privacy             = { child_directed = false }
  idle_session_ttl_in_seconds = 300
  auto_build_bot_locales   = true

  # Encryption Configuration
  encryption_setting {
    kms_key_arn = aws_kms_key.lex_bot_key.arn
    bot_locale_export_password = "ExportPass${random_id.suffix.hex}!" # In production, use SSM Parameter Store
    bot_locale_import_password = "ImportPass${random_id.suffix.hex}!"
  }

  # ---------------------------------------------------------
  # Locale: en_US
  # ---------------------------------------------------------
  bot_locale {
    locale_id            = "en_US"
    nlu_intent_confidence_threshold = 0.40
    voice_settings {
      voice_id = "Joanna"
      engine   = "neural"
    }

    # ---------------------------------------------------------
    # Custom Slot Types
    # ---------------------------------------------------------
    custom_slot_type {
      name = "TravelDestinationType"
      description = "List of supported travel destinations"
      slot_type_values = [
        { sample_value = { value = "New York" } },
        { sample_value = { value = "Los Angeles" } },
        { sample_value = { value = "Las Vegas" } },
        { sample_value = { value = "Miami" } },
        { sample_value = { value = "Chicago" } },
        { sample_value = { value = "Seattle" } },
        { sample_value = { value = "San Francisco" } },
        { sample_value = { value = "Orlando" } }
      ]
      value_selection_setting {
        resolution_strategy = "TopResolution"
        regex_filter {
          pattern = "^[A-Za-z\\s]+$"
        }
      }
    }

    custom_slot_type {
      name = "ConfirmationType"
      description = "Yes/No confirmation slot type"
      slot_type_values = [
        { sample_value = { value = "yes" } },
        { sample_value = { value = "no" } },
        { sample_value = { value = "yeah" } },
        { sample_value = { value = "nope" } },
        { sample_value = { value = "confirm" } },
        { sample_value = { value = "cancel" } }
      ]
      value_selection_setting {
        resolution_strategy = "TopResolution"
      }
    }

    # ---------------------------------------------------------
    # Intent: BookTrip
    # ---------------------------------------------------------
    intent {
      name = "BookTrip"
      description = "Intent to book a round trip flight and hotel"
      parent_intent_signature = "AMAZON.FallbackIntent" # Not a real parent, just placeholder for structure, usually omitted for root intents. Removing to avoid validation error.
      # parent_intent_signature omitted for root intent.

      sample_utterances = [
        { utterance = "I want to book a trip to {Destination}" },
        { utterance = "Book a flight to {Destination} for {StartDate}" },
        { utterance = "Plan a vacation to {Destination} from {StartDate} to {EndDate}" },
        { utterance = "I need a trip to {Destination} with a budget of {Budget}" },
        { utterance = "Book me a trip" }
      ]

      # ---------------------------------------------------------
      # Slots
      # ---------------------------------------------------------
      slot {
        name = "Destination"
        description = "The city or location to travel to"
        slot_type_name = "TravelDestinationType"
        value_elicitation_setting {
          slot_constraint = "Required"
          prompt_specification {
            message_groups = [
              { message = { plain_text_message = { value = "Where would you like to travel to?" } } },
              { message = { plain_text_message = { value = "What is your destination?" } } }
            ]
            max_retries = 2
            allow_interrupt = true
          }
          sample_utterances = [
            { utterance = "I want to go to {Destination}" },
            { utterance = "{Destination}" },
            { utterance = "My destination is {Destination}" }
          ]
          wait_and_continue_specification {
            waiting_response {
              message_groups = [{ message = { plain_text_message = { value = "Let me check available destinations..." } } }]
              allow_interrupt = true
            }
            continue_response {
              message_groups = [{ message = { plain_text_message = { value = "Great, I found options for {Destination}." } } }]
              allow_interrupt = true
            }
            still_waiting_response {
              message_groups = [{ message = { plain_text_message = { value = "Still looking for options..." } } }]
              frequency_in_seconds = 15
              timeout_in_seconds = 60
              allow_interrupt = true
            }
          }
        }
      }

      slot {
        name = "StartDate"
        description = "Trip start date"
        slot_type_name = "AMAZON.Date"
        value_elicitation_setting {
          slot_constraint = "Required"
          prompt_specification {
            message_groups = [
              { message = { plain_text_message = { value = "When would you like to start your trip?" } } },
              { message = { plain_text_message = { value = "What is the departure date?" } } }
            ]
            max_retries = 2
            allow_interrupt = true
          }
          sample_utterances = [
            { utterance = "I want to leave on {StartDate}" },
            { utterance = "Departing {StartDate}" },
            { utterance = "{StartDate}" }
          ]
        }
      }

      slot {
        name = "EndDate"
        description = "Trip end date"
        slot_type_name = "AMAZON.Date"
        value_elicitation_setting {
          slot_constraint = "Required"
          prompt_specification {
            message_groups = [
              { message = { plain_text_message = { value = "When would you like to return?" } } },
              { message = { plain_text_message = { value = "What is the return date?" } } }
            ]
            max_retries = 2
            allow_interrupt = true
          }
          sample_utterances = [
            { utterance = "I will return on {EndDate}" },
            { utterance = "Returning {EndDate}" },
            { utterance = "{EndDate}" }
          ]
        }
      }

      slot {
        name = "Budget"
        description = "Maximum budget for the trip in USD"
        slot_type_name = "AMAZON.Number"
        value_elicitation_setting {
          slot_constraint = "Optional" # Optional slot
          prompt_specification {
            message_groups = [
              { message = { plain_text_message = { value = "What is your budget for this trip in dollars?" } } }
            ]
            max_retries = 1
            allow_interrupt = true
          }
          sample_utterances = [
            { utterance = "My budget is {Budget} dollars" },
            { utterance = "{Budget}" }
          ]
          default_value_specification {
            default_value_list = [{ default_value = "1000" }]
          }
        }
      }

      slot {
        name = "ConfirmBooking"
        description = "Final confirmation before booking"
        slot_type_name = "ConfirmationType"
        value_elicitation_setting {
          slot_constraint = "Required"
          prompt_specification {
            message_groups = [
              { message = { plain_text_message = { value = "Shall I book a trip to {Destination} from {StartDate} to {EndDate} with a budget of {Budget} dollars? Please say yes or no." } } }
            ]
            max_retries = 2
            allow_interrupt = true
          }
          sample_utterances = [
            { utterance = "{ConfirmBooking}" },
            { utterance = "Yes please" },
            { utterance = "No, cancel" }
          ]
          slot_constraint = "Required"
        }
      }

      # ---------------------------------------------------------
      # Initial Response (Welcome/Confirmation start)
      # ---------------------------------------------------------
      initial_response_setting {
        message_groups = [
          {
            message = {
              plain_text_message = { value = "Sure, I can help you book a trip. Where would you like to go?" }
            }
          }
        ]
        allow_interrupt = true
      }

      # ---------------------------------------------------------
      # Confirmation Prompt (Before Fulfillment)
      # ---------------------------------------------------------
      intent_confirmation_setting {
        prompt_specification {
          message_groups = [
            {
              message = {
