model_answers:
terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS Region to deploy resources"
  type        = string
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidr" {
  description = "CIDR block for the single public subnet"
  type        = string
  default     = "10.0.1.0/24"
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for the two private subnets (must be 2 for HA)"
  type        = list(string)
  default     = ["10.0.10.0/24", "10.0.20.0/24"]
}

variable "allowed_ssh_cidr" {
  description = "CIDR block allowed to SSH into instances (Restrict in production)"
  type        = string
  default     = "10.0.0.0/8" # Example: Restrict to corporate VPN/CIDR
}

variable "environment" {
  description = "Environment name for tagging"
  type        = string
  default     = "prod"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  # Use first two AZs for private subnets, first AZ for public subnet
  azs = slice(data.aws_availability_zones.available.names, 0, 2)
  common_tags = {
    Environment = var.environment
    ManagedBy   = "Terraform"
  }
}

# --- VPC & Core Networking ---

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true
  tags = merge(local.common_tags, { Name = "${var.environment}-vpc" })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id
  tags   = merge(local.common_tags, { Name = "${var.environment}-igw" })
}

# --- Public Subnet (Single AZ) ---
# Note: Best Practice for Production ALB/HA requires 2 public subnets.
# This configuration follows the explicit request for ONE public subnet.

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.public_subnet_cidr
  availability_zone       = local.azs[0]
  map_public_ip_on_launch = true
  tags = merge(local.common_tags, {
    Name = "${var.environment}-public-subnet"
    Type = "public"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id
  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }
  tags = merge(local.common_tags, { Name = "${var.environment}-public-rt" })
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

# --- NAT Gateway (Single AZ - Cost Optimized / Request Constrained) ---
# Warning: Single NAT Gateway is a Single Point of Failure for private subnet egress.
# Best Practice: One NAT Gateway per AZ (requires 2 public subnets).

resource "aws_eip" "nat" {
  domain = "vpc"
  tags   = merge(local.common_tags, { Name = "${var.environment}-nat-eip" })
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public.id
  tags          = merge(local.common_tags, { Name = "${var.environment}-nat-gw" })
  depends_on    = [aws_internet_gateway.main]
}

# --- Private Subnets (Two AZs for HA) ---

resource "aws_subnet" "private" {
  count                   = 2
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.private_subnet_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false
  tags = merge(local.common_tags, {
    Name = "${var.environment}-private-subnet-${count.index + 1}"
    Type = "private"
    Role = count.index == 0 ? "app" : "db"
  })
}

resource "aws_route_table" "private" {
  count  = 2
  vpc_id = aws_vpc.main.id
  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }
  tags = merge(local.common_tags, { Name = "${var.environment}-private-rt-${count.index + 1}" })
}

resource "aws_route_table_association" "private" {
  count          = 2
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

# --- Security Groups (Least Privilege) ---

resource "aws_security_group" "web" {
  name        = "${var.environment}-web-sg"
  description = "Allow HTTP/HTTPS inbound, Restricted SSH"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from Internet"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from Internet"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "SSH from Admin CIDR"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [var.allowed_ssh_cidr]
  }

  egress {
    description = "All outbound (Required for patching/updates via NAT)"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, { Name = "${var.environment}-web-sg" })
}

resource "aws_security_group" "app" {
  name        = "${var.environment}-app-sg"
  description = "Allow traffic from Web SG only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "App Port from Web Tier"
    from_port   = 8080
    to_port     = 8080
    protocol    = "tcp"
    security_groups = [aws_security_group.web.id]
  }

  ingress {
    description = "SSH from Admin CIDR (Bastion/SSM preferred)"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [var.allowed_ssh_cidr]
  }

  egress {
    description = "All outbound via NAT"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, { Name = "${var.environment}-app-sg" })
}

resource "aws_security_group" "db" {
  name        = "${var.environment}-db-sg"
  description = "Allow traffic from App SG only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "PostgreSQL/MySQL from App Tier"
    from_port   = 5432 # Change to 3306 for MySQL
    to_port     = 5432
    protocol    = "tcp"
    security_groups = [aws_security_group.app.id]
  }

  # No direct SSH access from internet. Use Session Manager / Bastion in private subnet if needed.
  egress {
    description = "No direct internet egress for DB (Security Best Practice)"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [] # Empty blocks effectively denies all egress unless specific rules added
    # Note: If DB needs patches, add specific egress to S3/Repos endpoints or use VPC Endpoints.
  }

  tags = merge(local.common_tags, { Name = "${var.environment}-db-sg" })
}

# --- VPC Flow Logs (Security Best Practice) ---

resource "aws_cloudwatch_log_group" "vpc_flow_logs" {
  name              = "/aws/vpc/flowlogs/${var.environment}"
  retention_in_days = 30
  tags              = local.common_tags
}

resource "aws_iam_role" "flow_log_role" {
  name = "${var.environment}-vpc-flowlog-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action = "sts:AssumeRole"
      Effect = "Allow"
      Principal = { Service = "vpc-flow-logs.amazonaws.com" }
    }]
  })
}

resource "aws_iam_role_policy" "flow_log_policy" {
  name = "${var.environment}-vpc-flowlog-policy"
  role = aws_iam_role.flow_log_role.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action = [
        "logs:CreateLogGroup",
        "logs:CreateLogStream",
        "logs:PutLogEvents",
        "logs:DescribeLogGroups",
        "logs:DescribeLogStreams"
      ]
      Effect   = "Allow"
      Resource = aws_cloudwatch_log_group.vpc_flow_logs.arn
    }]
  })
}

resource "aws_flow_log" "vpc_flow_log" {
  iam_role_arn     = aws_iam_role.flow_log_role.arn
  log_destination  = aws_cloudwatch_log_group.vpc_flow_logs.arn
  traffic_type     = "ALL"
  vpc_id           = aws_vpc.main.id
  log_format       = "${version} ${account-id} ${interface-id} ${srcaddr} ${dstaddr} ${srcport} ${dstport} ${protocol} ${packets} ${bytes} ${start} ${end} ${action} ${log-status} ${vpc-id} ${subnet-id} ${instance-id} ${tcp-flags} ${type} ${pkt-srcaddr} ${pkt-dstaddr} ${region} ${az-id} ${sublocation-type} ${sublocation-id} ${tcp-flags}"
  tags             = local.common_tags
}

# --- Outputs ---

output "vpc_id" {
  value = aws_vpc.main.id
}

output "public_subnet_id" {
  value = aws_subnet.public.id
}

output "private_subnet_ids" {
  value = aws_subnet.private[*].id
}

output "security_group_ids" {
  value = {
    web = aws_security_group.web.id
    app = aws_security_group.app.id
    db  = aws_security_group.db.id
  }
}

output "nat_gateway_id" {
  value = aws_nat_gateway.main.id
}

