model_answers:
variable "name" {
  description = "Name prefix for the ALB and related resources."
  type        = string
}

variable "vpc_id" {
  description = "ID of the VPC where the ALB will be deployed."
  type        = string
}

variable "subnet_ids" {
  description = "List of public subnet IDs (minimum 2 in different AZs)."
  type        = list(string)
}

variable "certificate_arn" {
  description = "ARN of the ACM certificate for HTTPS termination."
  type        = string
}

variable "access_logs_bucket_arn" {
  description = "ARN of the S3 bucket for ALB access logs. Bucket must have appropriate policy."
  type        = string
}

variable "tags" {
  description = "Map of tags to apply to all resources."
  type        = map(string)
  default     = {}
}

# Security Group for the ALB
resource "aws_security_group" "alb" {
  name        = "${var.name}-alb-sg"
  description = "Security group for ${var.name} Application Load Balancer"
  vpc_id      = var.vpc_id

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
    ipv6_cidr_blocks = ["::/0"]
  }

  ingress {
    description = "HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
    ipv6_cidr_blocks = ["::/0"]
  }

  egress {
    description = "Allow all outbound traffic to targets"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
    ipv6_cidr_blocks = ["::/0"]
  }

  tags = merge(var.tags, { Name = "${var.name}-alb-sg" })
}

# S3 Bucket Policy for Access Logs (Assumes bucket exists, ensures policy allows ALB logging)
resource "aws_s3_bucket_policy" "alb_logs" {
  count = length(var.access_logs_bucket_arn) > 0 ? 1 : 0
  bucket = split("/", var.access_logs_bucket_arn)[0]

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "delivery.logs.amazonaws.com" }
        Action    = "s3:PutObject"
        Resource  = "${var.access_logs_bucket_arn}/*"
        Condition = {
          StringEquals = {
            "s3:x-amz-acl" = "bucket-owner-full-control"
          }
        }
      },
      {
        Effect    = "Allow"
        Principal = { Service = "delivery.logs.amazonaws.com" }
        Action    = "s3:GetBucketAcl"
        Resource  = var.access_logs_bucket_arn
      }
    ]
  })
}

# Application Load Balancer
resource "aws_lb" "main" {
  name               = var.name
  internal           = false
  load_balancer_type = "application"
  security_groups    = [aws_security_group.alb.id]
  subnets            = var.subnet_ids
  ip_address_type    = "dualstack"
  enable_deletion_protection = true
  enable_http2       = true
  enable_waf_fail_open = false

  access_logs {
    bucket  = split("/", var.access_logs_bucket_arn)[0]
    prefix  = "${var.name}/alb-logs"
    enabled = true
  }

  # Desync mitigation (AWS Best Practice)
  drop_invalid_header_fields = true

  tags = merge(var.tags, { Name = var.name })
}

# HTTP to HTTPS Redirect Listener (Port 80)
resource "aws_lb_listener" "http_redirect" {
  load_balancer_arn = aws_lb.main.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type = "redirect"
    redirect {
      port        = "443"
      protocol    = "HTTPS"
      status_code = "HTTP_301"
    }
  }
}

# HTTPS Listener (Port 443) - Default action returns 404 until target groups attached
resource "aws_lb_listener" "https" {
  load_balancer_arn = aws_lb.main.arn
  port              = 443
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-TLS13-1-2-2021-06" # Modern TLS policy
  certificate_arn   = var.certificate_arn

  default_action {
    type = "fixed-response"
    fixed_response {
      content_type = "text/plain"
      message_body = "No target group configured. Please attach a target group to this listener."
      status_code  = "404"
    }
  }
}

# Outputs
output "alb_arn" {
  description = "ARN of the Application Load Balancer"
  value       = aws_lb.main.arn
}

output "alb_dns_name" {
  description = "DNS name of the Application Load Balancer"
  value       = aws_lb.main.dns_name
}

output "alb_zone_id" {
  description = "Zone ID of the Application Load Balancer (for Route53 Alias)"
  value       = aws_lb.main.zone_id
}

output "https_listener_arn" {
  description = "ARN of the HTTPS Listener (attach target groups to this)"
  value       = aws_lb_listener.https.arn
}

output "alb_security_group_id" {
  description = "Security Group ID attached to the ALB"
  value       = aws_security_group.alb.id
}

