model_answers:
terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# --- Networking (Best Practice: Private Subnets across 3 AZs) ---
resource "aws_vpc" "msk_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = "msk-vpc"
  }
}

resource "aws_subnet" "msk_private" {
  count                   = 3
  vpc_id                  = aws_vpc.msk_vpc.id
  cidr_block              = cidrsubnet(aws_vpc.msk_vpc.cidr_block, 4, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "msk-private-${data.aws_availability_zones.available.names[count.index]}"
    # Required for MSK to identify subnets for broker placement
    "kubernetes.io/role/internal-elb" = "1"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

# --- Security Group (Best Practice: Least Privilege) ---
resource "aws_security_group" "msk_sg" {
  name        = "msk-cluster-sg"
  description = "Security group for MSK Cluster - Restricted to VPC CIDR on Kafka ports"
  vpc_id      = aws_vpc.msk_vpc.id

  # Inbound: Allow TLS (9094) and Plaintext (9092) from within VPC only
  # Best Practice: Restrict source to specific client SGs or VPC CIDR in production
  ingress {
    from_port   = 9092
    to_port     = 9094
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.msk_vpc.cidr_block]
  }

  # Outbound: Allow all (required for broker-to-broker communication and client responses)
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "msk-cluster-sg"
  }
}

# --- Encryption (Best Practice: Customer Managed KMS Key) ---
resource "aws_kms_key" "msk_key" {
  description             = "KMS Key for MSK Encryption at Rest"
  deletion_window_in_days = 10
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "key-default-1"
    Statement = [
      {
        Sid       = "Allow administration of the key"
        Effect    = "Allow"
        Principal = { AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root" }
        Action    = ["kms:*"]
        Resource  = "*"
      },
      {
        Sid       = "Allow MSK service to use the key"
        Effect    = "Allow"
        Principal = { Service = "kafka.amazonaws.com" }
        Action    = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
}

data "aws_caller_identity" "current" {}

resource "aws_kms_alias" "msk_alias" {
  name          = "alias/msk-cluster-key"
  target_key_id = aws_kms_key.msk_key.key_id
}

# --- MSK Cluster Configuration (Best Practice: TLS + IAM Auth + Enhanced Monitoring) ---
resource "aws_msk_cluster" "main" {
  cluster_name           = "managed-msk-cluster"
  kafka_version          = "3.7.x" # Use latest stable LTS
  number_of_broker_nodes = 3

  # Network Configuration: Private Subnets Only
  broker_node_group_info {
    instance_type   = "kafka.m7g.large" # Graviton3 - Cost/Performance optimized
    client_subnets  = aws_subnet.msk_private[*].id
    security_groups = [aws_security_group.msk_sg.id]

    # Storage Configuration
    storage_info {
      ebs_storage_info {
        volume_size = 100 # GiB
      }
    }

    # Best Practice: Enable AZ Distribution for HA
    az_distribution = "DEFAULT"
  }

  # Encryption Configuration
  encryption_info {
    encryption_at_rest {
      kms_key_arn = aws_kms_key.msk_key.arn
    }
    encryption_in_transit {
      client_broker = "TLS"            # Enforce TLS for clients
      in_cluster    = true             # Enforce TLS for inter-broker communication
    }
  }

  # Authentication Configuration (Best Practice: IAM + TLS)
  client_authentication {
    sasl {
      iam = true # Enable IAM Access Control
    }
    tls {
      enabled = true # Enable Mutual TLS (Optional: requires cert management)
    }
  }

  # Monitoring Configuration (Best Practice: Enhanced Monitoring)
  logging_info {
    broker_logs {
      cloudwatch_logs {
        enabled   = true
        log_group = aws_cloudwatch_log_group.msk_broker_logs.name
      }
      s3 {
        enabled = false # Enable and provide bucket ARN for long-term retention
      }
    }
  }

  # Open Monitoring (Prometheus)
  open_monitoring {
    prometheus {
      jmx_exporter {
        enabled_in_broker = true
      }
      node_exporter {
        enabled_in_broker = true
      }
    }
  }

  # Configuration for Auto Scaling / Maintenance (Optional but recommended)
  # maintenance_window_start_time {
  #   day_of_week = "MON"
  #   time_of_day = "03:00"
  #   time_zone   = "UTC"
  # }

  tags = {
    Environment = "production"
    ManagedBy   = "terraform"
  }
}

# CloudWatch Log Group for Broker Logs
resource "aws_cloudwatch_log_group" "msk_broker_logs" {
  name              = "/aws/msk/${aws_msk_cluster.main.cluster_name}/broker-logs"
  retention_in_days = 30
  kms_key_id        = aws_kms_key.msk_key.arn # Encrypt logs with same key
}

# --- Outputs ---
output "msk_bootstrap_brokers_tls" {
  description = "Bootstrap brokers for TLS connection"
  value       = aws_msk_cluster.main.bootstrap_brokers_tls
}

output "msk_bootstrap_brokers_iam" {
  description = "Bootstrap brokers for IAM (SASL_SCRAM) connection"
  value       = aws_msk_cluster.main.bootstrap_brokers_sasl_iam
}

output "msk_arn" {
  description = "ARN of the MSK Cluster"
  value       = aws_msk_cluster.main.arn
}

output "msk_zookeeper_connect" {
  description = "Zookeeper connection string (TLS)"
  value       = aws_msk_cluster.main.zookeeper_connect_tls
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS Region for Lightsail resources."
  type        = string
  default     = "us-east-1"
}

variable "allowed_ssh_cidr" {
  description = "CIDR block allowed to access SSH (Port 22). Restrict this to your IP for security."
  type        = string
  default     = "0.0.0.0/0" # CHANGE THIS IN PRODUCTION
  validation {
    condition     = can(cidrhost(var.allowed_ssh_cidr, 0))
    error_message = "allowed_ssh_cidr must be a valid CIDR block."
  }
}

variable "allowed_mysql_cidr" {
  description = "CIDR block allowed to access MySQL (Port 3306). Restrict to application servers or specific IPs."
  type        = string
  default     = "0.0.0.0/0" # CHANGE THIS IN PRODUCTION
  validation {
    condition     = can(cidrhost(var.allowed_mysql_cidr, 0))
    error_message = "allowed_mysql_cidr must be a valid CIDR block."
  }
}

variable "instance_name" {
  description = "Name for the Lightsail instance."
  type        = string
  default     = "mysql-server"
}

variable "availability_zone" {
  description = "Availability Zone for the instance."
  type        = string
  default     = "us-east-1a"
}

# --- Security: Generate Strong Passwords & Keys ---
resource "random_password" "mysql_root_password" {
  length  = 32
  special = true
  override_special = "!#$%&*()-_=+[]{}<>:?"
}

resource "random_password" "mysql_app_password" {
  length  = 32
  special = true
  override_special = "!#$%&*()-_=+[]{}<>:?"
}

resource "tls_private_key" "ssh_key" {
  algorithm = "RSA"
  rsa_bits  = 4096
}

resource "aws_lightsail_key_pair" "generated" {
  key_pair_name = "${var.instance_name}-key-${random_id.suffix.hex}"
  public_key    = tls_private_key.ssh_key.public_key_openssh
}

resource "random_id" "suffix" {
  byte_length = 4
}

# --- Networking: Static IP for Stable Endpoint ---
resource "aws_lightsail_static_ip" "static_ip" {
  name = "${var.instance_name}-static-ip"
}

resource "aws_lightsail_static_ip_attachment" "attachment" {
  static_ip_name = aws_lightsail_static_ip.static_ip.name
  instance_name  = aws_lightsail_instance.mysql_server.name
}

# --- Compute: Lightsail Instance (Amazon Linux 2023) ---
resource "aws_lightsail_instance" "mysql_server" {
  name              = var.instance_name
  availability_zone = var.availability_zone
  blueprint_id      = "amazon_linux_2023" # Latest LTS Amazon Linux
  bundle_id         = "nano_3_0"          # 1 vCPU, 1 GB RAM, 40 GB SSD (Adjust as needed)
  key_pair_name     = aws_lightsail_key_pair.generated.key_pair_name

  # Security Best Practice: User Data to Harden OS & Install MySQL
  user_data = templatefile("${path.module}/user_data.sh.tpl", {
    mysql_root_password = random_password.mysql_root_password.result
    mysql_app_user      = "app_user"
    mysql_app_password  = random_password.mysql_app_password.result
    mysql_app_db        = "app_db"
  })

  tags = {
    Name        = var.instance_name
    Environment = "production"
    ManagedBy   = "terraform"
  }
}

# --- Security: Firewall Rules (Instance Level) ---
# Lightsail uses instance-level firewalls. We restrict ports explicitly.
resource "aws_lightsail_instance_public_ports" "ssh" {
  instance_name = aws_lightsail_instance.mysql_server.name
  port_info {
    from_port = 22
    to_port   = 22
    protocol  = "tcp"
    cidrs     = [var.allowed_ssh_cidr]
  }
}

resource "aws_lightsail_instance_public_ports" "mysql" {
  instance_name = aws_lightsail_instance.mysql_server.name
  port_info {
    from_port = 3306
    to_port   = 3306
    protocol  = "tcp"
    cidrs     = [var.allowed_mysql_cidr]
  }
}

# --- Outputs ---
output "instance_public_ip" {
  description = "Public IP address of the Lightsail instance."
  value       = aws_lightsail_static_ip.static_ip.ip_address
}

output "ssh_private_key_pem" {
  description = "Private key for SSH access (PEM format). Store securely!"
  value       = tls_private_key.ssh_key.private_key_pem
  sensitive   = true
}

output "mysql_root_password" {
  description = "Generated MySQL root password."
  value       = random_password.mysql_root_password.result
  sensitive   = true
}

output "mysql_app_credentials" {
  description = "Application database credentials."
  value = {
    host     = aws_lightsail_static_ip.static_ip.ip_address
    port     = 3306
    database = "app_db"
    username = "app_user"
    password = random_password.mysql_app_password.result
  }
  sensitive = true
}

output "mysql_connection_command" {
  description = "Command to connect to MySQL from the instance via SSH."
  value       = "ssh -i <private_key_file> ec2-user@${aws_lightsail_static_ip.static_ip.ip_address} -t 'mysql -u root -p'"
}
